#[derive(Debug, Default)]
struct CypherCompileContext {
    variable_function_arguments: BTreeMap<(usize, usize), VariableFunctionArgument>,
    function_argument_sources: BTreeMap<(usize, usize), FunctionArgumentSources>,
    collection_filter_calls: BTreeMap<(usize, usize), CollectionFilterCall>,
    list_comprehension_sources: BTreeMap<(usize, usize), ListComprehensionSource>,
    static_reduce_sources: BTreeMap<(usize, usize), StaticReduceSource>,
    unwind_expression_sources: BTreeMap<(usize, usize), String>,
    inline_property_value_sources: BTreeMap<usize, InlinePropertyValueSource>,
    compact_exists_pattern_queries: BTreeMap<(usize, usize), String>,
    order_null_placements: BTreeMap<(usize, usize), NullOrder>,
    parameters: BTreeMap<String, CypherParameterValue>,
    graph: Option<Declaration>,
}

impl CypherCompileContext {
    fn from_source_with_parameters_and_graph(
        cypher: &str,
        parameters: BTreeMap<String, CypherParameterValue>,
        graph: Option<Declaration>,
        order_null_placements: BTreeMap<(usize, usize), NullOrder>,
    ) -> Self {
        Self {
            variable_function_arguments: collect_variable_function_arguments(cypher),
            function_argument_sources: collect_function_argument_sources(cypher),
            collection_filter_calls: collect_collection_filter_calls(cypher),
            list_comprehension_sources: collect_list_comprehension_sources(cypher),
            static_reduce_sources: collect_static_reduce_sources(cypher),
            unwind_expression_sources: collect_unwind_expression_sources(cypher),
            inline_property_value_sources: collect_inline_property_value_sources(cypher),
            compact_exists_pattern_queries: collect_compact_exists_pattern_queries(cypher),
            order_null_placements,
            parameters,
            graph,
        }
    }

    fn variable_function_argument(&self, function: &FunctionInvocation) -> Option<&str> {
        self.variable_function_argument_info(function)
            .map(|argument| argument.variable.as_str())
    }

    fn variable_function_argument_info(
        &self,
        function: &FunctionInvocation,
    ) -> Option<&VariableFunctionArgument> {
        self.variable_function_arguments
            .get(&(function.span.start, function.span.end))
    }

    fn function_argument_sources(
        &self,
        function: &FunctionInvocation,
    ) -> Option<&FunctionArgumentSources> {
        self.function_argument_sources
            .get(&(function.span.start, function.span.end))
    }

    fn collection_filter_call(
        &self,
        function: &FunctionInvocation,
    ) -> Option<&CollectionFilterCall> {
        self.collection_filter_calls
            .get(&(function.span.start, function.span.end))
    }

    fn list_comprehension_source(
        &self,
        comprehension: &ListComprehension,
    ) -> Option<&ListComprehensionSource> {
        self.list_comprehension_sources
            .get(&(comprehension.span.start, comprehension.span.end))
    }

    fn static_reduce_source(&self, function: &FunctionInvocation) -> Option<&StaticReduceSource> {
        self.static_reduce_sources
            .get(&(function.span.start, function.span.end))
    }

    fn unwind_expression_source(&self, unwind: &Unwind) -> Option<&str> {
        self.unwind_expression_sources
            .get(&(unwind.span.start, unwind.span.end))
            .map(String::as_str)
    }

    fn truncated_inline_property_value_source(
        &self,
        expression: &Expression,
    ) -> Option<&InlinePropertyValueSource> {
        let span = expression_span(expression)?;
        self.inline_property_value_sources
            .get(&span.start)
            .filter(|source| source.end > span.end)
    }

    fn compact_exists_pattern_query(&self, exists: &ExistsExpression) -> Option<&str> {
        self.compact_exists_pattern_queries
            .get(&(exists.span.start, exists.span.end))
            .map(String::as_str)
    }

    fn order_null_placement(&self, item: &SortItem) -> Option<NullOrder> {
        let span = expression_span(&item.expression)?;
        self.order_null_placements
            .get(&(span.start, span.end))
            .copied()
    }

    fn parameter_value(
        &self,
        parameter: &CypherParameter,
        path: impl Into<String>,
    ) -> Result<&CypherParameterValue, CoreError> {
        let path = path.into();
        let name = parameter.name.name.as_str();
        self.parameters.get(name).ok_or_else(|| {
            Diagnostic::new(
                "MISSING_PARAMETER",
                path,
                format!("Cypher parameter '${name}' was not provided"),
            )
            .into_core_error()
        })
    }

    fn graph_declaration(&self, path: impl Into<String>) -> Result<&Declaration, CoreError> {
        let path = path.into();
        self.graph.as_ref().ok_or_else(|| {
            unsupported(
                path,
                "graph-variable expansion requires a graph declaration so Coral can expand mapped properties",
            )
        })
    }
}

#[derive(Clone, Copy)]
enum PredicateCompileMode<'a> {
    Graph {
        plan: &'a GraphPlan,
        path_state: Option<&'a CypherCompileState>,
    },
    CaseWhen {
        plan: Option<&'a GraphPlan>,
    },
}

impl<'a> PredicateCompileMode<'a> {
    fn graph_plan(self) -> Option<&'a GraphPlan> {
        match self {
            Self::Graph { plan, .. } => Some(plan),
            Self::CaseWhen { plan } => plan,
        }
    }

    fn path_state(self) -> Option<&'a CypherCompileState> {
        match self {
            Self::Graph { path_state, .. } => path_state,
            Self::CaseWhen { .. } => None,
        }
    }

    fn scalar_alias_state(self) -> Option<&'a CypherCompileState> {
        self.path_state()
    }

    fn unsupported_predicate_message(self) -> &'static str {
        match self {
            Self::Graph { .. } => {
                "WHERE only supports graph property, id(), elementId(), labels(), keys(), exists(property), isEmpty(scalar), contains(scalar, scalar), startsWith(scalar, scalar), endsWith(scalar, scalar), and supported scalar predicates combined with AND, OR, XOR, and NOT"
            }
            Self::CaseWhen { .. } => {
                "CASE WHEN predicates support property/scalar comparisons, static graph metadata predicates including labels()/keys() list predicates and indexes, IN literal lists, null checks, exists(property), isEmpty(scalar), contains(scalar, scalar), startsWith(scalar, scalar), endsWith(scalar, scalar), boolean literals, and AND/OR/XOR/NOT"
            }
        }
    }

    fn unsupported_comparison_message(self) -> &'static str {
        match self {
            Self::Graph { .. } => {
                "comparisons must include at least one variable.property, id(variable), elementId(variable), type(relationship), or supported scalar expression operand"
            }
            Self::CaseWhen { .. } => {
                "CASE WHEN comparisons must include at least one variable.property, type(relationship), or supported scalar expression operand"
            }
        }
    }

    fn unsupported_in_message(self) -> &'static str {
        match self {
            Self::Graph { .. } => {
                "IN predicates require variable.property, id(variable), elementId(variable), type(relationship), supported scalar expression, '<label>' IN labels(node), or '<key>' IN keys(variable)"
            }
            Self::CaseWhen { .. } => {
                "CASE WHEN IN predicates require variable.property, type(relationship), supported scalar expression, '<label>' IN labels(node), or '<key>' IN keys(variable)"
            }
        }
    }

    fn unsupported_null_message(self) -> &'static str {
        match self {
            Self::Graph { .. } => {
                "IS NULL predicates require a graph variable, variable.property, id(variable), elementId(variable), type(relationship), or supported scalar expression"
            }
            Self::CaseWhen { .. } => {
                "CASE WHEN null checks require a graph variable, variable.property, id(variable), elementId(variable), or supported scalar expression operands"
            }
        }
    }

    fn graph_metadata_plan(self) -> Option<&'a GraphPlan> {
        match self {
            Self::Graph { plan, .. } => Some(plan),
            Self::CaseWhen { .. } => None,
        }
    }

    fn static_metadata_plan(self) -> Option<&'a GraphPlan> {
        match self {
            Self::Graph { plan, .. } => Some(plan),
            Self::CaseWhen { plan } => plan,
        }
    }
}

/// Runtime value that can be bound to a Cypher parameter in the supported subset.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum CypherParameterValue {
    /// Scalar literal parameter, usable where a literal expression is accepted.
    Literal(Literal),
    /// Scalar-list parameter, usable as the right-hand side of `IN`.
    List(Vec<Literal>),
}

/// Parses and compiles the Coral-supported read-only Cypher subset into a shared graph plan.
///
/// # Errors
///
/// Returns [`CoreError::InvalidInput`] when the query cannot be parsed or uses
/// Cypher/GQL features outside Coral's current read-only virtual graph subset.
pub fn compile_cypher(cypher: &str) -> Result<GraphPlan, CoreError> {
    compile_cypher_with_parameters(cypher, &BTreeMap::new())
}

/// Parses and compiles Cypher with typed parameter values into a shared graph plan.
///
/// Parameter values are bound before SQL lowering and only in positions where
/// the same literal or literal-list value is already supported by the read-only
/// Cypher subset.
///
/// # Errors
///
/// Returns [`CoreError::InvalidInput`] when the query cannot be parsed, uses
/// unsupported Cypher/GQL features, references a missing parameter, or binds a
/// list parameter where a scalar literal is required.
pub fn compile_cypher_with_parameters(
    cypher: &str,
    parameters: &BTreeMap<String, CypherParameterValue>,
) -> Result<GraphPlan, CoreError> {
    match compile_cypher_query_with_parameters(cypher, parameters)? {
        GraphQuery::Plan(plan) => Ok(plan),
        GraphQuery::Union(_) => Err(unsupported(
            "query.union",
            "compile_cypher returns a single graph plan; use compile_cypher_query for UNION queries",
        )),
    }
}

/// Parses and compiles Cypher against a graph declaration into a shared graph plan.
///
/// Declaration-aware compilation enables syntax such as `RETURN *` that must
/// expand mapped graph variables into concrete tabular projections.
///
/// # Errors
///
/// Returns [`CoreError::InvalidInput`] when the query cannot be parsed, uses
/// unsupported Cypher/GQL features, or references graph metadata that cannot be
/// resolved from the declaration.
pub fn compile_cypher_for_graph(graph: &Declaration, cypher: &str) -> Result<GraphPlan, CoreError> {
    compile_cypher_for_graph_with_parameters(graph, cypher, &BTreeMap::new())
}

/// Parses and compiles Cypher with typed parameter values against a graph declaration.
///
/// # Errors
///
/// Returns [`CoreError::InvalidInput`] when the query cannot be parsed, uses
/// unsupported Cypher/GQL features, references a missing parameter, binds a
/// parameter value in an unsupported position, or uses graph metadata that
/// cannot be resolved from the declaration.
pub fn compile_cypher_for_graph_with_parameters(
    graph: &Declaration,
    cypher: &str,
    parameters: &BTreeMap<String, CypherParameterValue>,
) -> Result<GraphPlan, CoreError> {
    match compile_cypher_query_for_graph_with_parameters(graph, cypher, parameters)? {
        GraphQuery::Plan(plan) => Ok(plan),
        GraphQuery::Union(_) => Err(unsupported(
            "query.union",
            "compile_cypher_for_graph returns a single graph plan; use compile_cypher_query_for_graph for UNION queries",
        )),
    }
}

/// Parses and compiles Cypher into a read-only virtual graph query.
///
/// This accepts the same single-query subset as [`compile_cypher`] plus
/// top-level `UNION` / `UNION ALL` composition between supported branch queries.
///
/// # Errors
///
/// Returns [`CoreError::InvalidInput`] when the query cannot be parsed or uses
/// Cypher/GQL features outside Coral's current read-only virtual graph subset.
pub fn compile_cypher_query(cypher: &str) -> Result<GraphQuery, CoreError> {
    compile_cypher_query_with_parameters(cypher, &BTreeMap::new())
}

/// Parses and compiles Cypher into a read-only virtual graph query using graph metadata.
///
/// Declaration-aware compilation enables syntax such as `RETURN *` that must
/// expand mapped graph variables into concrete tabular projections.
///
/// # Errors
///
/// Returns [`CoreError::InvalidInput`] when the query cannot be parsed or uses
/// Cypher/GQL features outside Coral's current read-only virtual graph subset.
pub fn compile_cypher_query_for_graph(
    graph: &Declaration,
    cypher: &str,
) -> Result<GraphQuery, CoreError> {
    compile_cypher_query_for_graph_with_parameters(graph, cypher, &BTreeMap::new())
}

/// Parses and compiles Cypher with typed parameter values into a read-only graph query.
///
/// # Errors
///
/// Returns [`CoreError::InvalidInput`] when the query cannot be parsed, uses
/// unsupported Cypher/GQL features, references a missing parameter, or binds a
/// parameter value in an unsupported position.
pub fn compile_cypher_query_with_parameters(
    cypher: &str,
    parameters: &BTreeMap<String, CypherParameterValue>,
) -> Result<GraphQuery, CoreError> {
    compile_cypher_query_with_optional_graph(cypher, parameters, None)
}

/// Parses and compiles Cypher with typed parameter values into a read-only graph query
/// using graph metadata.
///
/// # Errors
///
/// Returns [`CoreError::InvalidInput`] when the query cannot be parsed, uses
/// unsupported Cypher/GQL features, references a missing parameter, binds a
/// parameter value in an unsupported position, or uses graph metadata that
/// cannot be resolved from the declaration.
pub fn compile_cypher_query_for_graph_with_parameters(
    graph: &Declaration,
    cypher: &str,
    parameters: &BTreeMap<String, CypherParameterValue>,
) -> Result<GraphQuery, CoreError> {
    let query = compile_cypher_query_with_optional_graph(cypher, parameters, Some(graph))?;
    graph.validate_graph_query(&query)?;
    Ok(query)
}

fn compile_cypher_query_with_optional_graph(
    cypher: &str,
    parameters: &BTreeMap<String, CypherParameterValue>,
    graph: Option<&Declaration>,
) -> Result<GraphQuery, CoreError> {
    let count_normalized = normalize_compact_count_subqueries(cypher);
    let range_normalized = normalize_static_range_functions(count_normalized.as_ref());
    let string_predicate_function_normalized =
        normalize_string_predicate_functions(range_normalized.as_ref());
    let null_normalized =
        normalize_order_null_placements(string_predicate_function_normalized.as_ref());
    let cypher = null_normalized.cypher.as_ref();
    let query = decypher::parse(cypher).map_err(|error| {
        Diagnostic::new("CYPHER_PARSE_ERROR", "query", error.to_string()).into_core_error()
    })?;
    let order_null_placements =
        collect_order_null_placements_for_query(&query, &null_normalized.placements)?;
    let context = CypherCompileContext::from_source_with_parameters_and_graph(
        cypher,
        parameters.clone(),
        graph.cloned(),
        order_null_placements,
    );
    compile_query(&query, &context)
}

fn compile_query(query: &Query, context: &CypherCompileContext) -> Result<GraphQuery, CoreError> {
    if query.statements.len() != 1 {
        return Err(unsupported(
            "query",
            "only a single Cypher statement is supported",
        ));
    }
    let statement = query
        .statements
        .first()
        .ok_or_else(|| unsupported("query", "Cypher query must contain a statement"))?;

    match statement {
        QueryBody::SingleQuery(single_query) => {
            compile_single_query_as_graph_query(single_query, context, "query")
        }
        QueryBody::Regular(regular_query) => compile_regular_query(regular_query, context),
        _ => Err(unsupported(
            "query",
            "only read-only MATCH queries and UNION queries are supported",
        )),
    }
}

fn compile_single_query_as_graph_query(
    single_query: &SingleQuery,
    context: &CypherCompileContext,
    path: impl Into<String>,
) -> Result<GraphQuery, CoreError> {
    let path = path.into();
    let contains_static_unwind = single_query_contains_unwind(single_query);
    let mut variants = expand_single_query_static_branches(single_query, context, &path)?;
    if variants.len() == 1 {
        let variant = variants
            .first()
            .ok_or_else(|| CoreError::internal("Cypher query expansion produced no variants"))?;
        let mut plan = compile_single_query(&variant.query, context)?;
        if variant.force_empty {
            force_empty_plan(&mut plan);
        }
        return Ok(GraphQuery::Plan(plan));
    }

    validate_pattern_alternative_expansion_supported(single_query, &path, context)?;
    let outer_projection_plan =
        analyze_static_alternative_outer_projection(single_query, &path, context)?;
    let hidden_order_plan = analyze_static_alternative_hidden_order(
        single_query,
        outer_projection_plan.as_ref(),
        &path,
    )?;
    let hidden_order_plans = compile_static_branch_hidden_order_plans(
        &variants,
        hidden_order_plan.as_ref(),
        outer_projection_plan.as_ref(),
        contains_static_unwind,
        &path,
    )?;
    for (variant, hidden_order_plan) in variants.iter_mut().zip(hidden_order_plans.iter()) {
        apply_static_alternative_outer_projection_rewrite(
            &mut variant.query,
            outer_projection_plan.as_ref(),
            &path,
        )?;
        apply_static_alternative_hidden_order_rewrite(
            &mut variant.query,
            hidden_order_plan.as_ref(),
            &path,
        )?;
        clear_final_return_outer_modifiers(&mut variant.query, &path)?;
    }
    let plans = variants
        .iter()
        .map(|variant| {
            let mut plan = compile_single_query(&variant.query, context)?;
            if variant.force_empty {
                force_empty_plan(&mut plan);
            }
            Ok(plan)
        })
        .collect::<Result<Vec<_>, CoreError>>()?;
    let mut plans = plans;
    rewrite_missing_branch_properties_as_null(&mut plans, context);
    let projection_names = plans
        .first()
        .map(GraphPlan::projection_output_names)
        .ok_or_else(|| CoreError::internal("Cypher query expansion produced no graph plans"))?;
    let outer_projection = compile_static_alternative_outer_projection(
        outer_projection_plan.as_ref(),
        &projection_names,
    )?;
    let outer_projection = compile_static_alternative_hidden_order_outer_projection(
        outer_projection,
        hidden_order_plan.as_ref(),
        &projection_names,
        final_return_clause(single_query, &path)?.items.len(),
    )?;
    let projection_names = outer_projection.as_ref().map_or_else(
        || projection_names.clone(),
        GraphUnionOuterProjection::output_names,
    );
    let order_by = compile_static_alternative_outer_order_by(
        single_query,
        &projection_names,
        hidden_order_plan.as_ref(),
        context,
        &path,
    )?;
    let (skip, limit) = compile_static_alternative_outer_skip_limit(single_query, context, &path)?;
    let distinct = final_return_clause(single_query, &path)?.distinct;
    graph_query_from_alternative_plans(plans, outer_projection, distinct, order_by, skip, limit)
}

fn compile_static_branch_hidden_order_plans(
    variants: &[ExpandedSingleQuery],
    hidden_order_plan: Option<&StaticAlternativeHiddenOrderPlan>,
    outer_projection_plan: Option<&StaticAlternativeOuterProjectionPlan>,
    contains_static_unwind: bool,
    path: &str,
) -> Result<Vec<Option<StaticAlternativeHiddenOrderPlan>>, CoreError> {
    if hidden_order_plan.is_none() {
        return Ok(vec![None; variants.len()]);
    }

    if !contains_static_unwind {
        return Ok(vec![hidden_order_plan.cloned(); variants.len()]);
    }

    let hidden_order_plans = variants
        .iter()
        .enumerate()
        .map(|(index, variant)| {
            let branch_path = format!("{path}.static_branches[{index}]");
            analyze_static_alternative_hidden_order(
                &variant.query,
                outer_projection_plan,
                branch_path.as_str(),
            )
        })
        .collect::<Result<Vec<_>, CoreError>>()?;
    validate_static_branch_hidden_order_alignment(hidden_order_plan, &hidden_order_plans)?;
    Ok(hidden_order_plans)
}

fn validate_static_branch_hidden_order_alignment(
    expected: Option<&StaticAlternativeHiddenOrderPlan>,
    actual: &[Option<StaticAlternativeHiddenOrderPlan>],
) -> Result<(), CoreError> {
    let Some(expected) = expected else {
        return Ok(());
    };

    for plan in actual {
        let Some(plan) = plan else {
            return Err(CoreError::internal(
                "static branch hidden ORDER BY plan disappeared after expansion",
            ));
        };
        if plan.items.len() != expected.items.len()
            || plan
                .items
                .iter()
                .zip(expected.items.iter())
                .any(|(left, right)| {
                    left.order_index != right.order_index || left.alias != right.alias
                })
        {
            return Err(CoreError::internal(
                "static branch hidden ORDER BY plans were not aligned after expansion",
            ));
        }
    }
    Ok(())
}

fn expand_single_query_static_branches(
    single_query: &SingleQuery,
    context: &CypherCompileContext,
    path: &str,
) -> Result<Vec<ExpandedSingleQuery>, CoreError> {
    let unwind_variants = expand_single_query_static_unwinds(single_query, context, path)?;
    let mut expanded = Vec::new();
    for variant in unwind_variants {
        let pattern_variants = expand_single_query_pattern_alternatives(&variant.query, context)?;
        for pattern_variant in pattern_variants {
            if expanded.len() >= MAX_PATTERN_ALTERNATIVE_BRANCHES {
                return Err(unsupported(
                    path,
                    format!(
                        "static branch expansion produced more than {MAX_PATTERN_ALTERNATIVE_BRANCHES} branches; simplify the query or split it explicitly"
                    ),
                ));
            }
            expanded.push(ExpandedSingleQuery {
                query: pattern_variant.query,
                force_empty: variant.force_empty || pattern_variant.force_empty,
            });
        }
    }
    Ok(expanded)
}

fn expand_single_query_static_unwinds(
    single_query: &SingleQuery,
    context: &CypherCompileContext,
    path: &str,
) -> Result<Vec<ExpandedSingleQuery>, CoreError> {
    let mut expanded = vec![ExpandedSingleQuery {
        query: single_query.clone(),
        force_empty: false,
    }];

    loop {
        let mut progressed = false;
        let mut next = Vec::new();
        for variant in expanded {
            let Some(index) = first_static_unwind_index(&variant.query, path)? else {
                next.push(variant);
                continue;
            };
            progressed = true;
            let alternatives = expand_static_unwind_at_index(&variant, index, context, path)?;
            for alternative in alternatives {
                if next.len() >= MAX_STATIC_UNWIND_BRANCHES {
                    return Err(unsupported(
                        path,
                        format!(
                            "static UNWIND expands to more than {MAX_STATIC_UNWIND_BRANCHES} branches; use a smaller static list or split the query explicitly"
                        ),
                    ));
                }
                next.push(alternative);
            }
        }
        expanded = next;
        if !progressed {
            return Ok(expanded);
        }
    }
}

fn first_static_unwind_index(
    single_query: &SingleQuery,
    path: &str,
) -> Result<Option<usize>, CoreError> {
    match &single_query.kind {
        SingleQueryKind::SinglePart(query) => Ok(query
            .reading_clauses
            .iter()
            .position(|clause| matches!(clause, ReadingClause::Unwind(_)))),
        SingleQueryKind::MultiPart(query) => {
            if multi_part_query_contains_unwind(query) {
                Err(unsupported(
                    path,
                    "UNWIND with WITH-separated multipart queries requires staged row-source planning and is not supported yet",
                ))
            } else {
                Ok(None)
            }
        }
    }
}

fn multi_part_query_contains_unwind(query: &MultiPartQuery) -> bool {
    query.parts.iter().any(|part| {
        part.reading_clauses
            .iter()
            .any(|clause| matches!(clause, ReadingClause::Unwind(_)))
    }) || query
        .final_part
        .reading_clauses
        .iter()
        .any(|clause| matches!(clause, ReadingClause::Unwind(_)))
}

fn single_query_contains_unwind(single_query: &SingleQuery) -> bool {
    match &single_query.kind {
        SingleQueryKind::SinglePart(query) => query
            .reading_clauses
            .iter()
            .any(|clause| matches!(clause, ReadingClause::Unwind(_))),
        SingleQueryKind::MultiPart(query) => multi_part_query_contains_unwind(query),
    }
}

fn expand_static_unwind_at_index(
    variant: &ExpandedSingleQuery,
    index: usize,
    context: &CypherCompileContext,
    path: &str,
) -> Result<Vec<ExpandedSingleQuery>, CoreError> {
    let SingleQueryKind::SinglePart(query) = &variant.query.kind else {
        return Err(CoreError::internal(
            "static UNWIND expansion reached non-single-part query",
        ));
    };
    let ReadingClause::Unwind(unwind) = query
        .reading_clauses
        .get(index)
        .ok_or_else(|| CoreError::internal("static UNWIND index was out of bounds"))?
    else {
        return Err(CoreError::internal(
            "static UNWIND expansion index did not point at UNWIND",
        ));
    };
    let variable = variable_name(&unwind.variable);
    validate_static_unwind_scope(query, index, &variable, path)?;
    let values = compile_static_unwind_values(unwind, index, context, path)?;

    if values.is_empty() {
        return Ok(vec![expand_static_unwind_literal_branch(
            variant,
            index,
            &variable,
            &Literal::Null,
            true,
        )?]);
    }

    values
        .iter()
        .map(|literal| {
            expand_static_unwind_literal_branch(
                variant,
                index,
                &variable,
                literal,
                variant.force_empty,
            )
        })
        .collect()
}

fn compile_static_unwind_values(
    unwind: &Unwind,
    index: usize,
    context: &CypherCompileContext,
    path: &str,
) -> Result<Vec<Literal>, CoreError> {
    let expression_path = format!("{path}.reading_clauses[{index}].unwind.expression");
    let value = if let Some(source) = context.unwind_expression_source(unwind) {
        compile_static_unwind_value_source(source, expression_path.clone(), context)?
    } else {
        compile_optional_static_unwind_value(&unwind.expression, expression_path.clone(), context)?
    }
    .ok_or_else(|| {
        unsupported(
            expression_path.clone(),
            "UNWIND currently supports literal lists, list parameters, and folded static list expressions; dynamic graph property lists require row-source planning",
        )
    })?;
    if value.presence_variable.is_some() {
        return Err(unsupported(
            expression_path,
            "UNWIND over optional graph metadata lists requires row-source planning and is not supported yet",
        ));
    }
    Ok(value.literals)
}

fn compile_static_unwind_value_source(
    source: &str,
    path: impl Into<String>,
    context: &CypherCompileContext,
) -> Result<Option<StaticListValue>, CoreError> {
    let path = path.into();
    let (expression, fragment_context) =
        parse_cypher_expression_fragment(source, path.clone(), context)?;
    compile_optional_static_unwind_value(&expression, path, &fragment_context)
}

fn compile_optional_static_unwind_value(
    expression: &Expression,
    path: impl Into<String>,
    context: &CypherCompileContext,
) -> Result<Option<StaticListValue>, CoreError> {
    let path = path.into();
    match expression {
        Expression::Parenthesized(inner) => {
            compile_optional_static_unwind_value(inner, path, context)
        }
        Expression::Case(case) => compile_optional_static_unwind_case_value(case, path, context),
        Expression::ListSlice {
            list, start, end, ..
        } => {
            if let Some(value) =
                compile_optional_static_unwind_value(list, format!("{path}.list"), context)?
            {
                return slice_static_list_value(
                    value,
                    start.as_deref(),
                    end.as_deref(),
                    path,
                    context,
                )
                .map(Some);
            }
            compile_optional_static_list_value(expression, path, None, context)
        }
        _ => compile_optional_static_list_value(expression, path, None, context),
    }
}

fn compile_optional_static_unwind_case_value(
    case: &CaseExpression,
    path: impl Into<String>,
    context: &CypherCompileContext,
) -> Result<Option<StaticListValue>, CoreError> {
    let path = path.into();
    let Some(parts) = compile_optional_static_list_case_parts(
        case,
        path.clone(),
        PredicateCompileMode::CaseWhen { plan: None },
        context,
    )?
    else {
        return Ok(None);
    };
    for (index, (when, result)) in parts.alternatives.into_iter().enumerate() {
        match when {
            PredicateExpression::Boolean(true) => {
                return Ok(Some(static_unwind_case_result_value(
                    result,
                    parts.element_type,
                )));
            }
            PredicateExpression::Boolean(false) => {}
            _ => {
                return Err(unsupported(
                    format!("{path}.alternatives[{index}].when"),
                    "UNWIND over list-valued CASE expressions requires statically foldable WHEN predicates",
                ));
            }
        }
    }
    match parts.default {
        Some(result) => Ok(Some(static_unwind_case_result_value(
            result,
            parts.element_type,
        ))),
        None => Ok(Some(StaticListValue {
            presence_variable: None,
            literals: Vec::new(),
            element_type: parts.element_type,
        })),
    }
}

fn static_unwind_case_result_value(
    result: StaticListCaseResult,
    element_type: Option<LiteralListElementType>,
) -> StaticListValue {
    match result {
        StaticListCaseResult::Null => StaticListValue {
            presence_variable: None,
            literals: Vec::new(),
            element_type,
        },
        StaticListCaseResult::List(value) => match element_type {
            Some(element_type) => with_static_list_element_type(value, element_type),
            None => value,
        },
        StaticListCaseResult::Coalesce(coalesce) => {
            let Some(element_type) = element_type else {
                return StaticListValue {
                    presence_variable: None,
                    literals: Vec::new(),
                    element_type: None,
                };
            };
            for argument in coalesce.arguments {
                let StaticListCoalesceArgument::List(value) = argument else {
                    continue;
                };
                return with_static_list_element_type(value, element_type);
            }
            StaticListValue {
                presence_variable: None,
                literals: Vec::new(),
                element_type: Some(element_type),
            }
        }
    }
}

fn validate_static_unwind_scope(
    query: &SinglePartQuery,
    index: usize,
    variable: &str,
    path: &str,
) -> Result<(), CoreError> {
    for (clause_index, clause) in query.reading_clauses.iter().take(index).enumerate() {
        if reading_clause_binds_variable(clause, variable) {
            return Err(unsupported(
                format!("{path}.reading_clauses[{index}].unwind.variable"),
                format!(
                    "UNWIND variable '{variable}' is already bound before reading clause {clause_index}"
                ),
            ));
        }
    }
    for (clause_index, clause) in query.reading_clauses.iter().enumerate().skip(index + 1) {
        if reading_clause_binds_variable(clause, variable) {
            return Err(unsupported(
                format!("{path}.reading_clauses[{clause_index}]"),
                format!(
                    "static UNWIND variable '{variable}' cannot be rebound by a later reading clause"
                ),
            ));
        }
    }
    Ok(())
}

fn reading_clause_binds_variable(clause: &ReadingClause, variable: &str) -> bool {
    match clause {
        ReadingClause::Match(match_clause) => match_clause_bound_variables(match_clause)
            .iter()
            .any(|candidate| candidate == variable),
        ReadingClause::Unwind(unwind) => variable_name(&unwind.variable) == variable,
        ReadingClause::InQueryCall(_)
        | ReadingClause::CallSubquery(_)
        | ReadingClause::LoadCsv(_) => false,
    }
}

fn match_clause_bound_variables(match_clause: &Match) -> BTreeSet<String> {
    let mut variables = BTreeSet::new();
    for part in &match_clause.pattern.parts {
        pattern_part_bound_variables(part, &mut variables);
    }
    variables
}

fn pattern_part_bound_variables(pattern_part: &PatternPart, variables: &mut BTreeSet<String>) {
    if let Some(variable) = pattern_part.variable.as_ref() {
        variables.insert(variable_name(variable));
    }
    pattern_element_bound_variables(&pattern_part.anonymous.element, variables);
}

fn pattern_element_bound_variables(element: &PatternElement, variables: &mut BTreeSet<String>) {
    match element {
        PatternElement::Path { start, chains } => {
            node_pattern_bound_variables(start, variables);
            for chain in chains {
                relationship_pattern_bound_variables(&chain.relationship, variables);
                node_pattern_bound_variables(&chain.node, variables);
            }
        }
        PatternElement::Parenthesized(inner) => pattern_element_bound_variables(inner, variables),
        PatternElement::Quantified { element, .. } => {
            pattern_element_bound_variables(element, variables);
        }
    }
}

fn pattern_element_path(
    element: &PatternElement,
) -> Option<(&CypherNodePattern, &[PatternElementChain])> {
    match element {
        PatternElement::Path { start, chains } => Some((start, chains.as_slice())),
        PatternElement::Parenthesized(inner) => pattern_element_path(inner),
        PatternElement::Quantified {
            element,
            quantifier,
            ..
        } if is_exact_one_path_quantifier(quantifier) => pattern_element_path(element),
        PatternElement::Quantified { .. } => None,
    }
}

fn pattern_element_path_mut(
    element: &mut PatternElement,
) -> Option<(&mut CypherNodePattern, &mut Vec<PatternElementChain>)> {
    match element {
        PatternElement::Path { start, chains } => Some((start, chains)),
        PatternElement::Parenthesized(inner) => pattern_element_path_mut(inner),
        PatternElement::Quantified {
            element,
            quantifier,
            ..
        } if is_exact_one_path_quantifier(quantifier) => pattern_element_path_mut(element),
        PatternElement::Quantified { .. } => None,
    }
}

fn is_exact_one_path_quantifier(quantifier: &Quantifier) -> bool {
    quantifier.start == Some(1) && quantifier.end == Some(1)
}

fn node_pattern_bound_variables(pattern: &CypherNodePattern, variables: &mut BTreeSet<String>) {
    if let Some(variable) = pattern.variable.as_ref() {
        variables.insert(variable_name(variable));
    }
}

fn relationship_pattern_bound_variables(
    pattern: &CypherRelationshipPattern,
    variables: &mut BTreeSet<String>,
) {
    if let Some(variable) = pattern
        .detail
        .as_ref()
        .and_then(|detail| detail.variable.as_ref())
    {
        variables.insert(variable_name(variable));
    }
}

fn expand_static_unwind_literal_branch(
    variant: &ExpandedSingleQuery,
    index: usize,
    variable: &str,
    literal: &Literal,
    force_empty: bool,
) -> Result<ExpandedSingleQuery, CoreError> {
    let mut query = variant.query.clone();
    let SingleQueryKind::SinglePart(single_part) = &mut query.kind else {
        return Err(CoreError::internal(
            "static UNWIND literal branch reached non-single-part query",
        ));
    };
    single_part.reading_clauses.remove(index);
    substitute_static_unwind_literal(single_part, index, variable, literal);
    Ok(ExpandedSingleQuery { query, force_empty })
}

fn substitute_static_unwind_literal(
    query: &mut SinglePartQuery,
    start_index: usize,
    variable: &str,
    literal: &Literal,
) {
    let mut substitution = StaticUnwindSubstitution { variable, literal };
    for clause in query.reading_clauses.iter_mut().skip(start_index) {
        substitution.visit_reading_clause(clause);
    }
    substitution.visit_single_part_body(&mut query.body);
}

struct StaticUnwindSubstitution<'a> {
    variable: &'a str,
    literal: &'a Literal,
}

impl StaticUnwindSubstitution<'_> {
    fn visit_reading_clause(&mut self, clause: &mut ReadingClause) {
        match clause {
            ReadingClause::Match(match_clause) => self.visit_match(match_clause),
            ReadingClause::Unwind(unwind) => self.visit_unwind(unwind),
            ReadingClause::InQueryCall(call) => self.visit_in_query_call(call),
            ReadingClause::CallSubquery(subquery) => self.visit_call_subquery_mut(subquery),
            ReadingClause::LoadCsv(load_csv) => self.visit_load_csv_mut(load_csv),
        }
    }

    fn visit_single_part_body(&mut self, body: &mut SinglePartBody) {
        match body {
            SinglePartBody::Return(return_clause) => self.visit_return(return_clause),
            SinglePartBody::Updating {
                updating,
                return_clause,
            } => {
                for clause in updating {
                    match clause {
                        decypher::ast::query::UpdatingClause::Create(create) => {
                            self.visit_create(create);
                        }
                        decypher::ast::query::UpdatingClause::Merge(merge) => {
                            self.visit_merge(merge);
                        }
                        decypher::ast::query::UpdatingClause::Delete(delete) => {
                            self.visit_delete(delete);
                        }
                        decypher::ast::query::UpdatingClause::Set(set) => {
                            self.visit_set(set);
                        }
                        decypher::ast::query::UpdatingClause::Remove(remove) => {
                            self.visit_remove(remove);
                        }
                        decypher::ast::query::UpdatingClause::Foreach(foreach) => {
                            self.visit_foreach_mut(foreach);
                        }
                    }
                }
                if let Some(return_clause) = return_clause {
                    self.visit_return(return_clause);
                }
            }
            SinglePartBody::Finish(finish) => self.visit_finish_mut(finish),
        }
    }
}

impl VisitMut for StaticUnwindSubstitution<'_> {
    fn visit_expression(&mut self, expression: &mut Expression) {
        if let Expression::Variable(variable) = expression
            && variable_name(variable) == self.variable
        {
            *expression = cypher_literal_expression(self.literal, variable.name.span);
            return;
        }
        visit::walk_expression_mut(self, expression);
    }
}

fn cypher_literal_expression(literal: &Literal, span: decypher::error::Span) -> Expression {
    Expression::Literal(match literal {
        Literal::String(value) => CypherLiteral::String(StringLiteral {
            value: value.clone(),
            span,
            raw: None,
        }),
        Literal::Integer(value) => CypherLiteral::Number(NumberLiteral::Integer(*value)),
        Literal::Float(value) => CypherLiteral::Number(NumberLiteral::Float(value.into_inner())),
        Literal::Boolean(value) => CypherLiteral::Boolean(*value),
        Literal::Null => CypherLiteral::Null,
    })
}

fn force_empty_plan(plan: &mut GraphPlan) {
    append_predicate_expression(PredicateExpression::Boolean(false), plan);
}

fn graph_query_from_alternative_plans(
    mut plans: Vec<GraphPlan>,
    outer_projection: Option<GraphUnionOuterProjection>,
    distinct: bool,
    order_by: Vec<OrderKey>,
    skip: Option<u64>,
    limit: Option<u64>,
) -> Result<GraphQuery, CoreError> {
    if plans.is_empty() {
        return Err(CoreError::internal(
            "Cypher query expansion produced no graph plans",
        ));
    }
    let first = plans.remove(0);
    if plans.is_empty() {
        return Ok(GraphQuery::Plan(first));
    }
    Ok(GraphQuery::Union(GraphUnion {
        first,
        branches: plans
            .into_iter()
            .map(|plan| GraphUnionBranch { all: true, plan })
            .collect(),
        outer_projection,
        distinct,
        order_by,
        skip,
        limit,
    }))
}

fn rewrite_missing_branch_properties_as_null(
    plans: &mut [GraphPlan],
    context: &CypherCompileContext,
) {
    let Some(graph) = context.graph.as_ref() else {
        return;
    };
    for plan in plans {
        let nodes = plan
            .nodes
            .iter()
            .map(|node| (node.variable.clone(), node.label.clone()))
            .collect::<BTreeMap<_, _>>();
        let relationships = plan.relationships.clone();
        rewrite_missing_branch_scalar_expressions_as_null(plan, graph, &nodes, &relationships);
        rewrite_missing_branch_property_predicates_as_null(plan, graph, &nodes, &relationships);
        for projection in &mut plan.projections {
            let (property, alias) = match projection {
                Projection::Property { property, alias } => {
                    let alias = alias
                        .clone()
                        .unwrap_or_else(|| format!("{}_{}", property.variable, property.property));
                    (property.clone(), alias)
                }
                _ => continue,
            };
            if !branch_property_is_missing(graph, &nodes, &relationships, &property) {
                continue;
            }
            *projection = Projection::Literal {
                literal: Literal::Null,
                alias,
            };
        }
    }
}

fn rewrite_missing_branch_scalar_expressions_as_null(
    plan: &mut GraphPlan,
    graph: &Declaration,
    nodes: &BTreeMap<String, String>,
    relationships: &[RelationshipPattern],
) {
    for projection in &mut plan.projections {
        match projection {
            Projection::Expression { expression, .. } => {
                rewrite_missing_branch_scalar_expression_as_null(
                    expression,
                    graph,
                    nodes,
                    relationships,
                );
            }
            Projection::Aggregate { target, .. } => {
                rewrite_missing_branch_aggregate_target_as_null(
                    target,
                    graph,
                    nodes,
                    relationships,
                );
            }
            Projection::Property { .. }
            | Projection::Key { .. }
            | Projection::ElementId { .. }
            | Projection::RelationshipType { .. }
            | Projection::NodeLabels { .. }
            | Projection::PropertyKeys { .. }
            | Projection::Literal { .. }
            | Projection::LiteralList { .. }
            | Projection::CountAll { .. } => {}
        }
    }

    for order_key in &mut plan.order_by {
        if let OrderExpression::Scalar(expression) = &mut order_key.expression {
            rewrite_missing_branch_scalar_expression_as_null(
                expression,
                graph,
                nodes,
                relationships,
            );
        }
    }
}

fn rewrite_missing_branch_aggregate_target_as_null(
    target: &mut AggregateTarget,
    graph: &Declaration,
    nodes: &BTreeMap<String, String>,
    relationships: &[RelationshipPattern],
) {
    match target {
        AggregateTarget::Expression(expression) => {
            rewrite_missing_branch_scalar_expression_as_null(
                expression,
                graph,
                nodes,
                relationships,
            );
        }
        AggregateTarget::Property(_)
        | AggregateTarget::PresenceGatedProperty { .. }
        | AggregateTarget::VariableKey { .. }
        | AggregateTarget::PresenceGatedVariableKey { .. } => {}
    }
}

fn rewrite_missing_branch_property_predicates_as_null(
    plan: &mut GraphPlan,
    graph: &Declaration,
    nodes: &BTreeMap<String, String>,
    relationships: &[RelationshipPattern],
) {
    if let Some(predicate) = plan.predicate.take() {
        plan.predicate = Some(rewrite_missing_branch_property_predicate_expression(
            predicate,
            graph,
            nodes,
            relationships,
        ));
    }

    let mut retained = Vec::with_capacity(plan.predicates.len());
    let predicates = std::mem::take(&mut plan.predicates);
    for predicate in predicates {
        match rewrite_missing_branch_property_predicate(predicate, graph, nodes, relationships) {
            BranchPropertyPredicateRewrite::Keep(predicate) => retained.push(predicate),
            BranchPropertyPredicateRewrite::Rewrite(expression) => {
                append_predicate_expression(expression, plan);
            }
        }
    }
    plan.predicates = retained;

    for optional_match in &mut plan.optional_matches {
        if let Some(predicate) = optional_match.predicate.take() {
            optional_match.predicate = Some(rewrite_missing_branch_property_predicate_expression(
                predicate,
                graph,
                nodes,
                relationships,
            ));
        }
    }
}

fn rewrite_missing_branch_property_predicate_expression(
    expression: PredicateExpression,
    graph: &Declaration,
    nodes: &BTreeMap<String, String>,
    relationships: &[RelationshipPattern],
) -> PredicateExpression {
    match expression {
        PredicateExpression::Comparison(predicate) => {
            match rewrite_missing_branch_property_predicate(predicate, graph, nodes, relationships)
            {
                BranchPropertyPredicateRewrite::Keep(predicate) => {
                    PredicateExpression::Comparison(predicate)
                }
                BranchPropertyPredicateRewrite::Rewrite(expression) => expression,
            }
        }
        PredicateExpression::ScalarComparison(predicate) => {
            rewrite_missing_branch_scalar_predicate(predicate, graph, nodes, relationships)
        }
        PredicateExpression::And { left, right } => PredicateExpression::And {
            left: Box::new(rewrite_missing_branch_property_predicate_expression(
                *left,
                graph,
                nodes,
                relationships,
            )),
            right: Box::new(rewrite_missing_branch_property_predicate_expression(
                *right,
                graph,
                nodes,
                relationships,
            )),
        },
        PredicateExpression::Or { left, right } => PredicateExpression::Or {
            left: Box::new(rewrite_missing_branch_property_predicate_expression(
                *left,
                graph,
                nodes,
                relationships,
            )),
            right: Box::new(rewrite_missing_branch_property_predicate_expression(
                *right,
                graph,
                nodes,
                relationships,
            )),
        },
        PredicateExpression::Xor { left, right } => PredicateExpression::Xor {
            left: Box::new(rewrite_missing_branch_property_predicate_expression(
                *left,
                graph,
                nodes,
                relationships,
            )),
            right: Box::new(rewrite_missing_branch_property_predicate_expression(
                *right,
                graph,
                nodes,
                relationships,
            )),
        },
        PredicateExpression::Not { expression } => PredicateExpression::Not {
            expression: Box::new(rewrite_missing_branch_property_predicate_expression(
                *expression,
                graph,
                nodes,
                relationships,
            )),
        },
        PredicateExpression::ExistsPattern(mut predicate) => {
            rewrite_missing_branch_exists_pattern_as_null(
                &mut predicate,
                graph,
                nodes,
                relationships,
            );
            PredicateExpression::ExistsPattern(predicate)
        }
        _ => expression,
    }
}

fn rewrite_missing_branch_scalar_predicate(
    mut predicate: ScalarPredicate,
    graph: &Declaration,
    nodes: &BTreeMap<String, String>,
    relationships: &[RelationshipPattern],
) -> PredicateExpression {
    let lhs_was_missing = rewrite_missing_branch_scalar_expression_as_null(
        &mut predicate.lhs,
        graph,
        nodes,
        relationships,
    );
    let rhs_was_missing = rewrite_missing_branch_scalar_predicate_rhs_as_null(
        &mut predicate.rhs,
        graph,
        nodes,
        relationships,
    );
    if rhs_was_missing
        || (lhs_was_missing
            && scalar_predicate_rhs_is_literal_null(&predicate.rhs)
            && (matches!(
                predicate.operator,
                ComparisonOperator::Equal | ComparisonOperator::NotEqual
            ) || is_range_comparison_operator(predicate.operator)))
    {
        return unknown_boolean_predicate();
    }
    PredicateExpression::ScalarComparison(predicate)
}

fn rewrite_missing_branch_scalar_predicate_rhs_as_null(
    rhs: &mut ScalarPredicateRhs,
    graph: &Declaration,
    nodes: &BTreeMap<String, String>,
    relationships: &[RelationshipPattern],
) -> bool {
    match rhs {
        ScalarPredicateRhs::Expression(expression) => {
            rewrite_missing_branch_scalar_expression_as_null(
                expression,
                graph,
                nodes,
                relationships,
            )
        }
        ScalarPredicateRhs::List(_) => false,
    }
}

fn scalar_predicate_rhs_is_literal_null(rhs: &ScalarPredicateRhs) -> bool {
    matches!(
        rhs,
        ScalarPredicateRhs::Expression(ScalarExpression::Literal(Literal::Null))
    )
}

fn rewrite_missing_branch_scalar_expression_as_null(
    expression: &mut ScalarExpression,
    graph: &Declaration,
    nodes: &BTreeMap<String, String>,
    relationships: &[RelationshipPattern],
) -> bool {
    if let ScalarExpression::Property(property) = expression
        && branch_property_is_missing(graph, nodes, relationships, property)
    {
        *expression = ScalarExpression::Literal(Literal::Null);
        return true;
    }

    if let Some(expression) = unary_scalar_expression_operand_mut(expression) {
        rewrite_missing_branch_scalar_expression_as_null(expression, graph, nodes, relationships);
        return false;
    }

    rewrite_nested_missing_branch_scalar_expressions_as_null(
        expression,
        graph,
        nodes,
        relationships,
    );
    false
}

fn rewrite_nested_missing_branch_scalar_expressions_as_null(
    expression: &mut ScalarExpression,
    graph: &Declaration,
    nodes: &BTreeMap<String, String>,
    relationships: &[RelationshipPattern],
) {
    if rewrite_missing_branch_scalar_leaf_as_null(expression, graph, nodes, relationships) {
        return;
    }
    rewrite_missing_branch_compound_scalar_expression_as_null(
        expression,
        graph,
        nodes,
        relationships,
    );
}

fn rewrite_missing_branch_scalar_leaf_as_null(
    expression: &mut ScalarExpression,
    graph: &Declaration,
    nodes: &BTreeMap<String, String>,
    relationships: &[RelationshipPattern],
) -> bool {
    match expression {
        ScalarExpression::Property(_)
        | ScalarExpression::UndirectedEndpointProperty { .. }
        | ScalarExpression::UndirectedEndpointKey { .. }
        | ScalarExpression::UndirectedEndpointElementId { .. }
        | ScalarExpression::UndirectedEndpointLabels { .. }
        | ScalarExpression::UndirectedEndpointPropertyKeys { .. }
        | ScalarExpression::Literal(_)
        | ScalarExpression::LiteralList { .. }
        | ScalarExpression::TypedLiteralList { .. }
        | ScalarExpression::Key { .. }
        | ScalarExpression::ElementId { .. }
        | ScalarExpression::GraphIdentity { .. }
        | ScalarExpression::GraphPresence { .. }
        | ScalarExpression::NodeLabels { .. }
        | ScalarExpression::PropertyKeys { .. }
        | ScalarExpression::RelationshipType { .. } => true,
        ScalarExpression::CountSubquery {
            pattern,
            distinct_target,
        } => {
            rewrite_missing_branch_count_subquery_as_null(pattern, graph, nodes, relationships);
            if let Some(target) = distinct_target {
                rewrite_missing_branch_scalar_expression_as_null(
                    target,
                    graph,
                    nodes,
                    relationships,
                );
            }
            true
        }
        ScalarExpression::Predicate(predicate) => {
            **predicate = rewrite_missing_branch_property_predicate_expression(
                (**predicate).clone(),
                graph,
                nodes,
                relationships,
            );
            true
        }
        _ => false,
    }
}

fn rewrite_missing_branch_compound_scalar_expression_as_null(
    expression: &mut ScalarExpression,
    graph: &Declaration,
    nodes: &BTreeMap<String, String>,
    relationships: &[RelationshipPattern],
) {
    if rewrite_missing_branch_primary_compound_scalar_expression_as_null(
        expression,
        graph,
        nodes,
        relationships,
    ) {
        return;
    }
    rewrite_missing_branch_secondary_compound_scalar_expression_as_null(
        expression,
        graph,
        nodes,
        relationships,
    );
}

fn rewrite_missing_branch_primary_compound_scalar_expression_as_null(
    expression: &mut ScalarExpression,
    graph: &Declaration,
    nodes: &BTreeMap<String, String>,
    relationships: &[RelationshipPattern],
) -> bool {
    match expression {
        ScalarExpression::PresenceGated { expression, .. } => {
            rewrite_missing_branch_scalar_expression_as_null(
                expression,
                graph,
                nodes,
                relationships,
            );
            true
        }
        ScalarExpression::Coalesce { expressions } => {
            rewrite_missing_branch_scalar_expression_list_as_null(
                expressions,
                graph,
                nodes,
                relationships,
            );
            true
        }
        ScalarExpression::NullIf { expression, value } => {
            rewrite_missing_branch_scalar_expression_as_null(
                expression,
                graph,
                nodes,
                relationships,
            );
            rewrite_missing_branch_scalar_expression_as_null(value, graph, nodes, relationships);
            true
        }
        ScalarExpression::Round { expression, places } => {
            rewrite_missing_branch_scalar_expression_as_null(
                expression,
                graph,
                nodes,
                relationships,
            );
            if let Some(places) = places {
                rewrite_missing_branch_scalar_expression_as_null(
                    places,
                    graph,
                    nodes,
                    relationships,
                );
            }
            true
        }
        ScalarExpression::Left { expression, count }
        | ScalarExpression::Right { expression, count } => {
            rewrite_missing_branch_scalar_expression_as_null(
                expression,
                graph,
                nodes,
                relationships,
            );
            rewrite_missing_branch_scalar_expression_as_null(count, graph, nodes, relationships);
            true
        }
        ScalarExpression::StringContains {
            expression,
            pattern: operand,
        }
        | ScalarExpression::StringStartsWith {
            expression,
            pattern: operand,
        }
        | ScalarExpression::StringEndsWith {
            expression,
            pattern: operand,
        } => {
            rewrite_missing_branch_scalar_expression_as_null(
                expression,
                graph,
                nodes,
                relationships,
            );
            rewrite_missing_branch_scalar_expression_as_null(operand, graph, nodes, relationships);
            true
        }
        _ => false,
    }
}

fn rewrite_missing_branch_secondary_compound_scalar_expression_as_null(
    expression: &mut ScalarExpression,
    graph: &Declaration,
    nodes: &BTreeMap<String, String>,
    relationships: &[RelationshipPattern],
) {
    match expression {
        ScalarExpression::Replace {
            expression,
            search,
            replacement,
        } => {
            rewrite_missing_branch_scalar_expression_as_null(
                expression,
                graph,
                nodes,
                relationships,
            );
            rewrite_missing_branch_scalar_expression_as_null(search, graph, nodes, relationships);
            rewrite_missing_branch_scalar_expression_as_null(
                replacement,
                graph,
                nodes,
                relationships,
            );
        }
        ScalarExpression::Substring {
            expression,
            start,
            length,
        } => {
            rewrite_missing_branch_scalar_expression_as_null(
                expression,
                graph,
                nodes,
                relationships,
            );
            rewrite_missing_branch_scalar_expression_as_null(start, graph, nodes, relationships);
            if let Some(length) = length {
                rewrite_missing_branch_scalar_expression_as_null(
                    length,
                    graph,
                    nodes,
                    relationships,
                );
            }
        }
        ScalarExpression::Arithmetic { left, right, .. } => {
            rewrite_missing_branch_scalar_expression_as_null(left, graph, nodes, relationships);
            rewrite_missing_branch_scalar_expression_as_null(right, graph, nodes, relationships);
        }
        ScalarExpression::Atan2 { y, x } => {
            rewrite_missing_branch_scalar_expression_as_null(y, graph, nodes, relationships);
            rewrite_missing_branch_scalar_expression_as_null(x, graph, nodes, relationships);
        }
        ScalarExpression::Case {
            alternatives,
            else_expression,
        } => rewrite_missing_branch_case_expression_as_null(
            alternatives,
            else_expression.as_deref_mut(),
            graph,
            nodes,
            relationships,
        ),
        _ => unreachable!("scalar leaves and unary expressions handled before compound rewrite"),
    }
}

fn rewrite_missing_branch_count_subquery_as_null(
    pattern: &mut CountSubqueryPattern,
    graph: &Declaration,
    nodes: &BTreeMap<String, String>,
    relationships: &[RelationshipPattern],
) {
    match pattern {
        CountSubqueryPattern::Relationships(pattern) => {
            rewrite_missing_branch_exists_pattern_as_null(pattern, graph, nodes, relationships);
        }
        CountSubqueryPattern::Nodes {
            nodes: local_nodes,
            predicates,
            predicate,
        } => {
            let scoped_nodes = scoped_branch_nodes(nodes, local_nodes);
            let scoped_relationships = relationships.to_vec();
            rewrite_missing_branch_property_predicate_list_as_null(
                predicates,
                predicate,
                graph,
                &scoped_nodes,
                &scoped_relationships,
            );
        }
    }
}

fn rewrite_missing_branch_exists_pattern_as_null(
    pattern: &mut ExistsPatternPredicate,
    graph: &Declaration,
    nodes: &BTreeMap<String, String>,
    relationships: &[RelationshipPattern],
) {
    let scoped_nodes = scoped_branch_nodes(nodes, &pattern.nodes);
    let scoped_relationships = scoped_branch_relationships(relationships, &pattern.relationships);
    rewrite_missing_branch_property_predicate_list_as_null(
        &mut pattern.predicates,
        &mut pattern.predicate,
        graph,
        &scoped_nodes,
        &scoped_relationships,
    );
}

fn scoped_branch_nodes(
    nodes: &BTreeMap<String, String>,
    local_nodes: &[NodePattern],
) -> BTreeMap<String, String> {
    let mut scoped_nodes = nodes.clone();
    for node in local_nodes {
        scoped_nodes.insert(node.variable.clone(), node.label.clone());
    }
    scoped_nodes
}

fn scoped_branch_relationships(
    relationships: &[RelationshipPattern],
    local_relationships: &[RelationshipPattern],
) -> Vec<RelationshipPattern> {
    let mut scoped_relationships = local_relationships.to_vec();
    scoped_relationships.extend_from_slice(relationships);
    scoped_relationships
}

fn rewrite_missing_branch_property_predicate_list_as_null(
    predicates: &mut Vec<PropertyPredicate>,
    predicate: &mut Option<Box<PredicateExpression>>,
    graph: &Declaration,
    nodes: &BTreeMap<String, String>,
    relationships: &[RelationshipPattern],
) {
    let mut retained = Vec::with_capacity(predicates.len());
    for property_predicate in std::mem::take(predicates) {
        match rewrite_missing_branch_property_predicate(
            property_predicate,
            graph,
            nodes,
            relationships,
        ) {
            BranchPropertyPredicateRewrite::Keep(property_predicate) => {
                retained.push(property_predicate);
            }
            BranchPropertyPredicateRewrite::Rewrite(expression) => {
                append_scoped_predicate_expression(expression, predicate);
            }
        }
    }
    *predicates = retained;

    if let Some(existing) = predicate.take() {
        *predicate = Some(Box::new(
            rewrite_missing_branch_property_predicate_expression(
                *existing,
                graph,
                nodes,
                relationships,
            ),
        ));
    }
}

fn append_scoped_predicate_expression(
    expression: PredicateExpression,
    predicate: &mut Option<Box<PredicateExpression>>,
) {
    let combined = match predicate.take() {
        Some(existing) => PredicateExpression::And {
            left: existing,
            right: Box::new(expression),
        },
        None => expression,
    };
    *predicate = Some(Box::new(combined));
}

fn rewrite_missing_branch_scalar_expression_list_as_null(
    expressions: &mut [ScalarExpression],
    graph: &Declaration,
    nodes: &BTreeMap<String, String>,
    relationships: &[RelationshipPattern],
) {
    for expression in expressions {
        rewrite_missing_branch_scalar_expression_as_null(expression, graph, nodes, relationships);
    }
}

fn rewrite_missing_branch_case_expression_as_null(
    alternatives: &mut [ScalarCaseAlternative],
    else_expression: Option<&mut ScalarExpression>,
    graph: &Declaration,
    nodes: &BTreeMap<String, String>,
    relationships: &[RelationshipPattern],
) {
    for alternative in alternatives {
        let original = std::mem::replace(&mut alternative.when, PredicateExpression::Boolean(true));
        alternative.when = rewrite_missing_branch_property_predicate_expression(
            original,
            graph,
            nodes,
            relationships,
        );
        rewrite_missing_branch_scalar_expression_as_null(
            &mut alternative.then,
            graph,
            nodes,
            relationships,
        );
    }
    if let Some(else_expression) = else_expression {
        rewrite_missing_branch_scalar_expression_as_null(
            else_expression,
            graph,
            nodes,
            relationships,
        );
    }
}

enum BranchPropertyPredicateRewrite {
    Keep(PropertyPredicate),
    Rewrite(PredicateExpression),
}

fn rewrite_missing_branch_property_predicate(
    predicate: PropertyPredicate,
    graph: &Declaration,
    nodes: &BTreeMap<String, String>,
    relationships: &[RelationshipPattern],
) -> BranchPropertyPredicateRewrite {
    if branch_property_is_missing(graph, nodes, relationships, &predicate.property) {
        return BranchPropertyPredicateRewrite::Rewrite(
            missing_branch_property_predicate_expression(predicate, graph, nodes, relationships),
        );
    }
    if branch_predicate_rhs_is_missing_property(&predicate.rhs, graph, nodes, relationships) {
        return BranchPropertyPredicateRewrite::Rewrite(unknown_boolean_predicate());
    }
    BranchPropertyPredicateRewrite::Keep(predicate)
}

fn missing_branch_property_predicate_expression(
    predicate: PropertyPredicate,
    graph: &Declaration,
    nodes: &BTreeMap<String, String>,
    relationships: &[RelationshipPattern],
) -> PredicateExpression {
    let rhs = branch_predicate_rhs_as_scalar_rhs(predicate.rhs, graph, nodes, relationships);
    if rhs.was_missing_property
        || (rhs.is_null_literal && is_range_comparison_operator(predicate.operator))
    {
        return unknown_boolean_predicate();
    }
    PredicateExpression::ScalarComparison(ScalarPredicate {
        lhs: ScalarExpression::Literal(Literal::Null),
        operator: predicate.operator,
        rhs: rhs.value,
    })
}

struct BranchScalarPredicateRhs {
    value: ScalarPredicateRhs,
    is_null_literal: bool,
    was_missing_property: bool,
}

fn branch_predicate_rhs_as_scalar_rhs(
    rhs: PredicateRhs,
    graph: &Declaration,
    nodes: &BTreeMap<String, String>,
    relationships: &[RelationshipPattern],
) -> BranchScalarPredicateRhs {
    match rhs {
        PredicateRhs::Literal(literal) => {
            let is_null = matches!(literal, Literal::Null);
            BranchScalarPredicateRhs {
                value: ScalarPredicateRhs::Expression(ScalarExpression::Literal(literal)),
                is_null_literal: is_null,
                was_missing_property: false,
            }
        }
        PredicateRhs::Property(property)
            if branch_property_is_missing(graph, nodes, relationships, &property) =>
        {
            BranchScalarPredicateRhs {
                value: ScalarPredicateRhs::Expression(ScalarExpression::Literal(Literal::Null)),
                is_null_literal: true,
                was_missing_property: true,
            }
        }
        PredicateRhs::Property(property) => BranchScalarPredicateRhs {
            value: ScalarPredicateRhs::Expression(ScalarExpression::Property(property)),
            is_null_literal: false,
            was_missing_property: false,
        },
        PredicateRhs::Key { variable } => BranchScalarPredicateRhs {
            value: ScalarPredicateRhs::Expression(ScalarExpression::Key { variable }),
            is_null_literal: false,
            was_missing_property: false,
        },
        PredicateRhs::ElementId { variable } => BranchScalarPredicateRhs {
            value: ScalarPredicateRhs::Expression(ScalarExpression::ElementId { variable }),
            is_null_literal: false,
            was_missing_property: false,
        },
        PredicateRhs::List(literals) => BranchScalarPredicateRhs {
            value: ScalarPredicateRhs::List(literals),
            is_null_literal: false,
            was_missing_property: false,
        },
    }
}

fn branch_predicate_rhs_is_missing_property(
    rhs: &PredicateRhs,
    graph: &Declaration,
    nodes: &BTreeMap<String, String>,
    relationships: &[RelationshipPattern],
) -> bool {
    match rhs {
        PredicateRhs::Property(property) => {
            branch_property_is_missing(graph, nodes, relationships, property)
        }
        PredicateRhs::Literal(_)
        | PredicateRhs::Key { .. }
        | PredicateRhs::ElementId { .. }
        | PredicateRhs::List(_) => false,
    }
}

fn branch_property_is_missing(
    graph: &Declaration,
    nodes: &BTreeMap<String, String>,
    relationships: &[RelationshipPattern],
    property: &PropertyRef,
) -> bool {
    if let Some(label) = nodes.get(&property.variable)
        && let Some(node) = graph.nodes.iter().find(|node| node.label == *label)
    {
        return node.column_for_property(&property.property).is_none();
    }
    if let Some(relationship) =
        branch_relationship_for_property(graph, nodes, relationships, property)
    {
        return relationship
            .column_for_property(&property.property)
            .is_none();
    }
    false
}

fn branch_relationship_for_property<'a>(
    graph: &'a Declaration,
    nodes: &BTreeMap<String, String>,
    relationships: &[RelationshipPattern],
    property: &PropertyRef,
) -> Option<&'a DeclaredRelationship> {
    let relationship = relationships.iter().find(|relationship| {
        relationship.variable.as_deref() == Some(property.variable.as_str())
    })?;
    let left_label = nodes.get(&relationship.left)?;
    let right_label = nodes.get(&relationship.right)?;
    branch_relationship_declaration(graph, relationship, left_label, right_label)
}

fn branch_relationship_declaration<'a>(
    graph: &'a Declaration,
    relationship: &RelationshipPattern,
    left_label: &str,
    right_label: &str,
) -> Option<&'a DeclaredRelationship> {
    let mut matches = graph.relationships.iter().filter(|candidate| {
        candidate.relationship_type == relationship.relationship_type
            && branch_relationship_matches_direction(
                candidate,
                relationship.direction,
                left_label,
                right_label,
            )
    });
    let relationship = matches.next()?;
    if matches.next().is_some() {
        return None;
    }
    Some(relationship)
}

fn branch_relationship_matches_direction(
    candidate: &DeclaredRelationship,
    direction: Direction,
    left_label: &str,
    right_label: &str,
) -> bool {
    match direction {
        Direction::Outgoing => {
            candidate.from.label == left_label && candidate.to.label == right_label
        }
        Direction::Incoming => {
            candidate.from.label == right_label && candidate.to.label == left_label
        }
        Direction::Undirected => {
            (candidate.from.label == left_label && candidate.to.label == right_label)
                || (candidate.from.label == right_label && candidate.to.label == left_label)
        }
    }
}

fn is_range_comparison_operator(operator: ComparisonOperator) -> bool {
    matches!(
        operator,
        ComparisonOperator::GreaterThan
            | ComparisonOperator::GreaterThanOrEqual
            | ComparisonOperator::LessThan
            | ComparisonOperator::LessThanOrEqual
    )
}

fn clear_final_return_outer_modifiers(
    single_query: &mut SingleQuery,
    path: &str,
) -> Result<(), CoreError> {
    let return_clause = final_return_clause_mut(single_query, path)?;
    return_clause.distinct = false;
    return_clause.order = None;
    return_clause.skip = None;
    return_clause.limit = None;
    Ok(())
}

#[derive(Debug, Clone)]
struct StaticAlternativeOuterProjectionPlan {
    items: Vec<StaticAlternativeOuterProjectionItem>,
    group_item_indices: Vec<usize>,
}

#[derive(Debug, Clone)]
enum StaticAlternativeOuterProjectionItem {
    Column {
        return_index: usize,
    },
    CountAll {
        alias: String,
    },
    Aggregate {
        function: AggregateFunction,
        source_alias: String,
        source_expression: Box<Expression>,
        distinct: bool,
        alias: String,
    },
}

fn analyze_static_alternative_outer_projection(
    single_query: &SingleQuery,
    path: &str,
    context: &CypherCompileContext,
) -> Result<Option<StaticAlternativeOuterProjectionPlan>, CoreError> {
    let return_clause = final_return_clause(single_query, path)?;
    let mut items = Vec::new();
    let mut group_item_indices = Vec::new();
    let has_outer_aggregate = return_clause
        .items
        .iter()
        .any(|item| expression_contains_aggregate(&item.expression));

    for (index, item) in return_clause.items.iter().enumerate() {
        if let Some(alias) = count_star_item_alias(item) {
            items.push(StaticAlternativeOuterProjectionItem::CountAll { alias });
        } else if let Some(item) =
            compile_static_alternative_outer_aggregate_item(item, index, path, context)?
        {
            items.push(item);
        } else if expression_contains_aggregate(&item.expression) {
            return Err(unsupported(
                format!("{path}.return.items[{index}].expression"),
                "pattern alternatives with property or non-count aggregate RETURN projections require staged query planning and are not supported yet",
            ));
        } else if has_outer_aggregate {
            group_item_indices.push(index);
            items.push(StaticAlternativeOuterProjectionItem::Column {
                return_index: index,
            });
        }
    }

    if has_outer_aggregate {
        return Ok(Some(StaticAlternativeOuterProjectionPlan {
            items,
            group_item_indices,
        }));
    }
    Ok(None)
}

fn compile_static_alternative_outer_projection(
    plan: Option<&StaticAlternativeOuterProjectionPlan>,
    branch_projection_names: &[String],
) -> Result<Option<GraphUnionOuterProjection>, CoreError> {
    let Some(plan) = plan else {
        return Ok(None);
    };
    let mut group_names = BTreeMap::new();
    for (position, return_index) in plan.group_item_indices.iter().enumerate() {
        let name = branch_projection_names
            .get(position)
            .cloned()
            .ok_or_else(|| {
                CoreError::internal("static alternative group projection names were not aligned")
            })?;
        group_names.insert(*return_index, name);
    }

    let mut items = Vec::with_capacity(plan.items.len());
    for item in &plan.items {
        match item {
            StaticAlternativeOuterProjectionItem::Column { return_index } => {
                let name = group_names.get(return_index).cloned().ok_or_else(|| {
                    CoreError::internal(
                        "static alternative group projection item had no branch output name",
                    )
                })?;
                items.push(GraphUnionOuterProjectionItem::Column { name });
            }
            StaticAlternativeOuterProjectionItem::CountAll { alias } => {
                items.push(GraphUnionOuterProjectionItem::CountAll {
                    alias: alias.clone(),
                });
            }
            StaticAlternativeOuterProjectionItem::Aggregate {
                function,
                source_alias,
                distinct,
                alias,
                ..
            } => items.push(GraphUnionOuterProjectionItem::Aggregate {
                function: *function,
                source: source_alias.clone(),
                distinct: *distinct,
                alias: alias.clone(),
            }),
        }
    }

    Ok(Some(GraphUnionOuterProjection {
        items,
        group_by: plan
            .group_item_indices
            .iter()
            .map(|return_index| {
                group_names.get(return_index).cloned().ok_or_else(|| {
                    CoreError::internal(
                        "static alternative group projection item had no GROUP BY name",
                    )
                })
            })
            .collect::<Result<Vec<_>, CoreError>>()?,
    }))
}

fn apply_static_alternative_outer_projection_rewrite(
    single_query: &mut SingleQuery,
    outer_projection: Option<&StaticAlternativeOuterProjectionPlan>,
    path: &str,
) -> Result<(), CoreError> {
    let Some(outer_projection) = outer_projection else {
        return Ok(());
    };
    let return_clause = final_return_clause_mut(single_query, path)?;
    return_clause.distinct = false;
    let aggregate_source_items = outer_projection
        .items
        .iter()
        .filter_map(|item| match item {
            StaticAlternativeOuterProjectionItem::Aggregate {
                source_alias,
                source_expression,
                ..
            } => Some((source_alias, source_expression.as_ref())),
            StaticAlternativeOuterProjectionItem::Column { .. }
            | StaticAlternativeOuterProjectionItem::CountAll { .. } => None,
        })
        .collect::<Vec<_>>();
    if outer_projection.group_item_indices.is_empty() && aggregate_source_items.is_empty() {
        let span = return_clause.span;
        return_clause.items = vec![ProjectionItem {
            expression: Expression::Literal(CypherLiteral::Number(NumberLiteral::Integer(1))),
            alias: Some(Variable {
                name: SymbolicName {
                    name: "__coral_count_row".to_string(),
                    span,
                },
            }),
        }];
    } else {
        let original_items = return_clause.items.clone();
        let mut rewritten_items = outer_projection
            .group_item_indices
            .iter()
            .map(|index| {
                original_items.get(*index).cloned().ok_or_else(|| {
                    CoreError::internal(
                        "static alternative group projection index was out of bounds",
                    )
                })
            })
            .collect::<Result<Vec<_>, CoreError>>()?;
        let span = return_clause.span;
        rewritten_items.extend(aggregate_source_items.into_iter().map(
            |(source_alias, source_expression)| ProjectionItem {
                expression: source_expression.clone(),
                alias: Some(Variable {
                    name: SymbolicName {
                        name: source_alias.clone(),
                        span,
                    },
                }),
            },
        ));
        return_clause.items = rewritten_items;
    }
    Ok(())
}

fn compile_static_alternative_outer_aggregate_item(
    item: &ProjectionItem,
    index: usize,
    path: &str,
    context: &CypherCompileContext,
) -> Result<Option<StaticAlternativeOuterProjectionItem>, CoreError> {
    let Some(function) = aggregate_function_call(&item.expression) else {
        return Ok(None);
    };
    let item_path = format!("{path}.return.items[{index}]");
    let function_kind =
        compile_aggregate_function(function, &format!("{item_path}.expression"), context)?
            .ok_or_else(|| {
                unsupported(
                    format!("{item_path}.expression"),
                    "pattern alternatives only support property aggregates after expansion",
                )
            })?;
    let source_expression = compile_static_alternative_outer_aggregate_source_expression(
        function,
        function_kind,
        &item_path,
        context,
    )?;
    Ok(Some(StaticAlternativeOuterProjectionItem::Aggregate {
        function: function_kind,
        source_alias: format!("__coral_agg_{index}"),
        source_expression: Box::new(source_expression),
        distinct: function.distinct,
        alias: item.alias.as_ref().map_or_else(
            || aggregate_function_name(function_kind).to_string(),
            variable_name,
        ),
    }))
}

fn compile_static_alternative_outer_aggregate_source_expression(
    function: &FunctionInvocation,
    function_kind: AggregateFunction,
    item_path: &str,
    context: &CypherCompileContext,
) -> Result<Expression, CoreError> {
    let target =
        compile_function_aggregate_target(function, function_kind, item_path, None, context);
    match target {
        Ok(AggregateTarget::Property(_)) => {
            let [argument] = function.arguments.as_slice() else {
                return Err(unsupported(
                    format!("{item_path}.expression.arguments"),
                    "pattern alternatives with property aggregates require one graph property argument",
                ));
            };
            Ok(argument.clone())
        }
        Ok(AggregateTarget::PresenceGatedProperty { .. }) => {
            let [argument] = function.arguments.as_slice() else {
                return Err(unsupported(
                    format!("{item_path}.expression.arguments"),
                    "pattern alternatives with optional relationship endpoint property aggregates require one graph property argument",
                ));
            };
            Ok(argument.clone())
        }
        Ok(AggregateTarget::Expression(_)) => Err(unsupported(
            format!("{item_path}.expression.arguments"),
            "pattern alternatives do not support aggregate expression targets yet",
        )),
        Ok(AggregateTarget::VariableKey { variable }) => match function_kind {
            AggregateFunction::Count => {
                if function.distinct {
                    Ok(graph_identity_function_expression_for_variable(
                        &variable, function,
                    ))
                } else {
                    Ok(graph_presence_function_expression_for_variable(
                        &variable, function,
                    ))
                }
            }
            AggregateFunction::Collect => Ok(graph_identity_function_expression_for_variable(
                &variable, function,
            )),
            _ => Err(unsupported(
                format!("{item_path}.expression.arguments"),
                "pattern alternatives only support count(variable) and collect(variable) over graph variables",
            )),
        },
        Ok(AggregateTarget::PresenceGatedVariableKey { .. }) => {
            if !matches!(
                function_kind,
                AggregateFunction::Count | AggregateFunction::Collect
            ) {
                return Err(unsupported(
                    format!("{item_path}.expression.arguments"),
                    "pattern alternatives only support count(endpoint) and collect(endpoint) over optional relationship endpoints",
                ));
            }
            let [argument] = function.arguments.as_slice() else {
                return Err(unsupported(
                    format!("{item_path}.expression.arguments"),
                    "pattern alternatives with optional relationship endpoint aggregates require one graph endpoint argument",
                ));
            };
            Ok(id_function_expression_for_expression(argument, function))
        }
        Err(error) => {
            if let Some(source) = compile_static_alternative_outer_endpoint_aggregate_source(
                function,
                function_kind,
                item_path,
            )? {
                Ok(source)
            } else {
                compile_static_alternative_outer_aggregate_expression_source(function, item_path)?
                    .ok_or(error)
            }
        }
    }
}

fn compile_static_alternative_outer_endpoint_aggregate_source(
    function: &FunctionInvocation,
    function_kind: AggregateFunction,
    path: &str,
) -> Result<Option<Expression>, CoreError> {
    let [argument] = function.arguments.as_slice() else {
        return Ok(None);
    };
    if is_relationship_endpoint_property_expression(argument) {
        return Ok(Some(argument.clone()));
    }
    if !is_relationship_endpoint_expression(argument) {
        return Ok(None);
    }
    if !matches!(
        function_kind,
        AggregateFunction::Count | AggregateFunction::Collect
    ) {
        return Err(unsupported(
            format!("{path}.expression.arguments[0]"),
            "pattern alternatives only support count(endpoint) and collect(endpoint) over relationship endpoints",
        ));
    }
    Ok(Some(id_function_expression_for_expression(
        argument, function,
    )))
}

fn is_relationship_endpoint_property_expression(expression: &Expression) -> bool {
    match expression {
        Expression::Parenthesized(inner) => is_relationship_endpoint_property_expression(inner),
        Expression::PropertyLookup { base, .. } => is_relationship_endpoint_expression(base),
        _ => false,
    }
}

fn is_relationship_endpoint_expression(expression: &Expression) -> bool {
    match expression {
        Expression::Parenthesized(inner) => is_relationship_endpoint_expression(inner),
        Expression::FunctionCall(function)
            if is_start_node_function(function) || is_end_node_function(function) =>
        {
            true
        }
        _ => false,
    }
}

fn compile_static_alternative_outer_aggregate_expression_source(
    function: &FunctionInvocation,
    path: &str,
) -> Result<Option<Expression>, CoreError> {
    let [argument] = function.arguments.as_slice() else {
        return Ok(None);
    };
    if !is_static_alternative_aggregate_scalar_source(argument) {
        return Ok(None);
    }
    if expression_contains_aggregate(argument) || expression_contains_subquery(argument) {
        return Err(unsupported(
            format!("{path}.expression.arguments[0]"),
            "pattern alternatives do not support nested aggregates or correlated subqueries inside aggregate expression targets",
        ));
    }
    Ok(Some(argument.clone()))
}

fn is_static_alternative_aggregate_scalar_source(expression: &Expression) -> bool {
    match expression {
        Expression::Parenthesized(inner) => is_static_alternative_aggregate_scalar_source(inner),
        expression if is_boolean_scalar_expression(expression) => true,
        expression if is_literal_expression(expression) => true,
        Expression::BinaryOp {
            op:
                CypherBinaryOperator::Add
                | CypherBinaryOperator::Subtract
                | CypherBinaryOperator::Multiply
                | CypherBinaryOperator::Divide
                | CypherBinaryOperator::Modulo
                | CypherBinaryOperator::Power,
            ..
        }
        | Expression::UnaryOp {
            op: UnaryOperator::Negate,
            ..
        }
        | Expression::Case(_)
        | Expression::ListIndex { .. } => true,
        Expression::FunctionCall(function) => {
            is_static_alternative_aggregate_scalar_function(function)
        }
        _ => false,
    }
}

fn is_static_alternative_aggregate_scalar_function(function: &FunctionInvocation) -> bool {
    is_id_function(function)
        || is_element_id_function(function)
        || is_type_function(function)
        || is_coalesce_function(function)
        || is_null_if_function(function)
        || is_to_string_function(function)
        || is_to_integer_function(function)
        || is_to_float_function(function)
        || is_to_boolean_function(function)
        || is_to_string_or_null_function(function)
        || is_to_integer_or_null_function(function)
        || is_to_float_or_null_function(function)
        || is_to_boolean_or_null_function(function)
        || is_static_list_cast_function(function)
        || is_to_lower_function(function)
        || is_to_upper_function(function)
        || is_trim_function(function)
        || is_ltrim_function(function)
        || is_rtrim_function(function)
        || is_replace_function(function)
        || is_head_function(function)
        || is_last_function(function)
        || is_tail_function(function)
        || is_character_length_function(function)
        || is_substring_function(function)
        || is_left_function(function)
        || is_right_function(function)
        || is_contains_function(function)
        || is_starts_with_function(function)
        || is_ends_with_function(function)
        || is_reverse_function(function)
        || is_abs_function(function)
        || is_ceil_function(function)
        || is_floor_function(function)
        || is_round_function(function)
        || is_sqrt_function(function)
        || is_sign_function(function)
        || is_exp_function(function)
        || is_log_function(function)
        || is_log10_function(function)
        || is_power_function(function)
        || is_pi_function(function)
        || is_e_function(function)
        || is_sin_function(function)
        || is_cos_function(function)
        || is_tan_function(function)
        || is_cot_function(function)
        || is_asin_function(function)
        || is_acos_function(function)
        || is_atan_function(function)
        || is_atan2_function(function)
        || is_degrees_function(function)
        || is_radians_function(function)
        || is_haversin_function(function)
}

fn expression_contains_subquery(expression: &Expression) -> bool {
    match expression {
        Expression::CountStar { .. }
        | Expression::CountSubquery(_)
        | Expression::CollectSubquery(_)
        | Expression::Exists(_) => true,
        Expression::FunctionCall(function) => {
            function.arguments.iter().any(expression_contains_subquery)
        }
        Expression::Literal(literal) => literal_contains_subquery(literal),
        Expression::PropertyLookup { base, .. }
        | Expression::IsNull { operand: base, .. }
        | Expression::UnaryOp { operand: base, .. }
        | Expression::Parenthesized(base) => expression_contains_subquery(base),
        Expression::NodeLabels { base, labels, .. } => {
            expression_contains_subquery(base)
                || labels.iter().any(label_expression_contains_subquery)
        }
        Expression::BinaryOp { lhs, rhs, .. } | Expression::In { lhs, rhs, .. } => {
            expression_contains_subquery(lhs) || expression_contains_subquery(rhs)
        }
        Expression::Comparison { lhs, operators, .. } => {
            expression_contains_subquery(lhs)
                || operators
                    .iter()
                    .any(|(_, rhs)| expression_contains_subquery(rhs))
        }
        Expression::ListIndex { list, index, .. } => {
            expression_contains_subquery(list) || expression_contains_subquery(index)
        }
        Expression::ListSlice {
            list, start, end, ..
        } => {
            expression_contains_subquery(list)
                || start.as_deref().is_some_and(expression_contains_subquery)
                || end.as_deref().is_some_and(expression_contains_subquery)
        }
        Expression::Case(case) => case_contains_subquery(case),
        Expression::ListComprehension(comprehension) => {
            list_comprehension_contains_subquery(comprehension)
        }
        Expression::PatternComprehension(comprehension) => {
            pattern_comprehension_contains_subquery(comprehension)
        }
        Expression::All(filter)
        | Expression::Any(filter)
        | Expression::None(filter)
        | Expression::Single(filter) => filter_expression_contains_subquery(filter),
        Expression::MapProjection(map) => map_projection_contains_subquery(map),
        Expression::Variable(_) | Expression::Parameter(_) | Expression::Pattern(_) => false,
    }
}

fn literal_contains_subquery(literal: &CypherLiteral) -> bool {
    match literal {
        CypherLiteral::List(list) => list.elements.iter().any(expression_contains_subquery),
        CypherLiteral::Map(map) => map
            .entries
            .iter()
            .any(|(_, value)| expression_contains_subquery(value)),
        CypherLiteral::Number(_)
        | CypherLiteral::String(_)
        | CypherLiteral::Boolean(_)
        | CypherLiteral::Null => false,
    }
}

fn case_contains_subquery(case: &CaseExpression) -> bool {
    case.scrutinee
        .as_deref()
        .is_some_and(expression_contains_subquery)
        || case.alternatives.iter().any(|alternative| {
            expression_contains_subquery(&alternative.when)
                || expression_contains_subquery(&alternative.then)
        })
        || case
            .default
            .as_deref()
            .is_some_and(expression_contains_subquery)
}

fn list_comprehension_contains_subquery(
    comprehension: &decypher::ast::expr::ListComprehension,
) -> bool {
    comprehension
        .filter
        .as_deref()
        .is_some_and(expression_contains_subquery)
        || comprehension
            .map
            .as_ref()
            .is_some_and(expression_contains_subquery)
}

fn pattern_comprehension_contains_subquery(
    comprehension: &decypher::ast::expr::PatternComprehension,
) -> bool {
    comprehension
        .where_clause
        .as_ref()
        .is_some_and(expression_contains_subquery)
        || expression_contains_subquery(&comprehension.map)
}

fn filter_expression_contains_subquery(filter: &decypher::ast::expr::FilterExpression) -> bool {
    expression_contains_subquery(&filter.collection)
        || filter
            .predicate
            .as_deref()
            .is_some_and(expression_contains_subquery)
}

fn map_projection_contains_subquery(map: &decypher::ast::expr::MapProjection) -> bool {
    map.items.iter().any(|item| match item {
        decypher::ast::expr::MapProjectionItem::Literal { value, .. } => {
            expression_contains_subquery(value)
        }
        decypher::ast::expr::MapProjectionItem::AllProperties { .. }
        | decypher::ast::expr::MapProjectionItem::PropertyLookup { .. } => false,
    })
}

fn label_expression_contains_subquery(expression: &LabelExpression) -> bool {
    match expression {
        LabelExpression::Dynamic {
            expression: dynamic,
            ..
        } => expression_contains_subquery(dynamic),
        LabelExpression::Or { lhs, rhs, .. } | LabelExpression::And { lhs, rhs, .. } => {
            label_expression_contains_subquery(lhs) || label_expression_contains_subquery(rhs)
        }
        LabelExpression::Not { inner, .. } | LabelExpression::Group { inner, .. } => {
            label_expression_contains_subquery(inner)
        }
        LabelExpression::Static(_) => false,
    }
}

fn graph_identity_function_expression_for_variable(
    variable: &str,
    source_function: &FunctionInvocation,
) -> Expression {
    function_expression_for_variable(INTERNAL_GRAPH_IDENTITY_FUNCTION, variable, source_function)
}

fn graph_presence_function_expression_for_variable(
    variable: &str,
    source_function: &FunctionInvocation,
) -> Expression {
    function_expression_for_variable(INTERNAL_GRAPH_PRESENCE_FUNCTION, variable, source_function)
}

fn function_expression_for_variable(
    function_name: &str,
    variable: &str,
    source_function: &FunctionInvocation,
) -> Expression {
    let span = source_function.span;
    Expression::FunctionCall(FunctionInvocation {
        name: vec![SymbolicName {
            name: function_name.to_string(),
            span,
        }],
        distinct: false,
        arguments: vec![Expression::Variable(Variable {
            name: SymbolicName {
                name: variable.to_string(),
                span,
            },
        })],
        span,
    })
}

fn id_function_expression_for_expression(
    argument: &Expression,
    source_function: &FunctionInvocation,
) -> Expression {
    let span = source_function.span;
    Expression::FunctionCall(FunctionInvocation {
        name: vec![SymbolicName {
            name: "id".to_string(),
            span,
        }],
        distinct: false,
        arguments: vec![argument.clone()],
        span,
    })
}

fn aggregate_function_call(expression: &Expression) -> Option<&FunctionInvocation> {
    match expression {
        Expression::Parenthesized(inner) => aggregate_function_call(inner),
        Expression::FunctionCall(function) if is_aggregate_function_call(function) => {
            Some(function)
        }
        _ => None,
    }
}

fn count_star_item_alias(item: &ProjectionItem) -> Option<String> {
    if !matches!(item.expression, Expression::CountStar { .. }) {
        return None;
    }
    Some(
        item.alias
            .as_ref()
            .map_or_else(|| "count".to_string(), variable_name),
    )
}

#[derive(Debug, Clone)]
struct StaticAlternativeHiddenOrderPlan {
    items: Vec<StaticAlternativeHiddenOrderItem>,
}

#[derive(Debug, Clone)]
struct StaticAlternativeHiddenOrderItem {
    order_index: usize,
    expression: Expression,
    alias: String,
}

impl StaticAlternativeHiddenOrderPlan {
    fn alias_for_order_index(&self, order_index: usize) -> Option<&str> {
        self.items
            .iter()
            .find(|item| item.order_index == order_index)
            .map(|item| item.alias.as_str())
    }
}

fn analyze_static_alternative_hidden_order(
    single_query: &SingleQuery,
    outer_projection: Option<&StaticAlternativeOuterProjectionPlan>,
    path: &str,
) -> Result<Option<StaticAlternativeHiddenOrderPlan>, CoreError> {
    let return_clause = final_return_clause(single_query, path)?;
    let Some(order) = &return_clause.order else {
        return Ok(None);
    };
    let mut hidden_items = Vec::new();
    let projection_names = return_clause
        .items
        .iter()
        .map(return_item_projection_name)
        .collect::<Vec<_>>();
    for (index, item) in order.items.iter().enumerate() {
        if resolve_projected_static_alternative_outer_order_alias(
            &item.expression,
            return_clause,
            &projection_names,
            format!("{path}.return.order.items[{index}].expression"),
        )?
        .is_some()
        {
            continue;
        }
        if outer_projection.is_some() {
            return Err(unsupported(
                format!("{path}.return.order.items[{index}].expression"),
                "pattern alternatives with aggregate RETURN projections cannot ORDER BY unprojected expressions yet",
            ));
        }
        if return_clause.distinct {
            return Err(unsupported(
                format!("{path}.return.order.items[{index}].expression"),
                "pattern alternatives with RETURN DISTINCT cannot ORDER BY unprojected expressions yet",
            ));
        }
        hidden_items.push(StaticAlternativeHiddenOrderItem {
            order_index: index,
            expression: item.expression.clone(),
            alias: format!("__coral_order_{index}"),
        });
    }
    if hidden_items.is_empty() {
        Ok(None)
    } else {
        Ok(Some(StaticAlternativeHiddenOrderPlan {
            items: hidden_items,
        }))
    }
}

fn return_item_projection_name(item: &ProjectionItem) -> String {
    item.alias.as_ref().map_or_else(
        || match &item.expression {
            Expression::PropertyLookup { base, property, .. } => match base.as_ref() {
                Expression::Variable(variable) => {
                    format!("{}_{}", variable_name(variable), property.name.name)
                }
                _ => "expression".to_string(),
            },
            Expression::Variable(variable) => variable_name(variable),
            Expression::CountStar { .. } => "count".to_string(),
            Expression::FunctionCall(function) => {
                if let Some(alias) = aggregate_function_default_alias(function) {
                    alias.to_string()
                } else {
                    default_scalar_function_alias(function)
                }
            }
            Expression::Case(_) => "case".to_string(),
            _ => "expression".to_string(),
        },
        variable_name,
    )
}

fn apply_static_alternative_hidden_order_rewrite(
    single_query: &mut SingleQuery,
    hidden_order: Option<&StaticAlternativeHiddenOrderPlan>,
    path: &str,
) -> Result<(), CoreError> {
    let Some(hidden_order) = hidden_order else {
        return Ok(());
    };
    let return_clause = final_return_clause_mut(single_query, path)?;
    let span = return_clause.span;
    return_clause
        .items
        .extend(hidden_order.items.iter().map(|item| ProjectionItem {
            expression: item.expression.clone(),
            alias: Some(Variable {
                name: SymbolicName {
                    name: item.alias.clone(),
                    span,
                },
            }),
        }));
    Ok(())
}

fn compile_static_alternative_hidden_order_outer_projection(
    outer_projection: Option<GraphUnionOuterProjection>,
    hidden_order: Option<&StaticAlternativeHiddenOrderPlan>,
    branch_projection_names: &[String],
    return_item_count: usize,
) -> Result<Option<GraphUnionOuterProjection>, CoreError> {
    if hidden_order.is_none() {
        return Ok(outer_projection);
    }
    if outer_projection.is_some() {
        return Err(CoreError::internal(
            "hidden static alternative ORDER BY should have been rejected for aggregate outer projections",
        ));
    }
    let items = branch_projection_names
        .get(..return_item_count)
        .ok_or_else(|| {
            CoreError::internal(
                "static alternative hidden ORDER BY projection names were not aligned",
            )
        })?
        .iter()
        .cloned()
        .map(|name| GraphUnionOuterProjectionItem::Column { name })
        .collect();
    Ok(Some(GraphUnionOuterProjection {
        items,
        group_by: Vec::new(),
    }))
}

fn compile_static_alternative_outer_order_by(
    single_query: &SingleQuery,
    projection_names: &[String],
    hidden_order: Option<&StaticAlternativeHiddenOrderPlan>,
    context: &CypherCompileContext,
    path: &str,
) -> Result<Vec<OrderKey>, CoreError> {
    let return_clause = final_return_clause(single_query, path)?;
    let Some(order) = &return_clause.order else {
        return Ok(Vec::new());
    };

    let mut order_by = Vec::with_capacity(order.items.len());
    for (index, item) in order.items.iter().enumerate() {
        let alias = resolve_projected_static_alternative_outer_order_alias(
            &item.expression,
            return_clause,
            projection_names,
            format!("{path}.return.order.items[{index}].expression"),
        )?
        .or_else(|| {
            hidden_order.and_then(|hidden_order| {
                hidden_order
                    .alias_for_order_index(index)
                    .map(ToString::to_string)
            })
        })
        .ok_or_else(|| {
            unsupported(
                format!("{path}.return.order.items[{index}].expression"),
                "pattern alternatives with global ORDER BY currently require projected aliases, projected expressions, or row-preserving hidden sort expressions",
            )
        })?;
        order_by.push(OrderKey {
            expression: OrderExpression::ProjectionAlias(alias),
            direction: match item.direction {
                Some(SortDirection::Descending) => OrderDirection::Descending,
                Some(SortDirection::Ascending) | None => OrderDirection::Ascending,
            },
            nulls: context.order_null_placement(item),
        });
    }
    Ok(order_by)
}

fn resolve_projected_static_alternative_outer_order_alias(
    expression: &Expression,
    return_clause: &Return,
    projection_names: &[String],
    path: impl Into<String>,
) -> Result<Option<String>, CoreError> {
    let path = path.into();
    if let Expression::Variable(variable) = expression {
        let alias = variable_name(variable);
        if projection_names.iter().any(|name| name == &alias) {
            return Ok(Some(alias));
        }
        return Err(unsupported(
            path,
            format!("ORDER BY alias '{alias}' does not match a RETURN projection"),
        ));
    }

    for (index, item) in return_clause.items.iter().enumerate() {
        if expressions_equivalent_ignoring_span(&item.expression, expression) {
            return projection_names
                .get(index)
                .cloned()
                .map(Some)
                .ok_or_else(|| {
                    CoreError::internal(
                        "RETURN projection names were not aligned with RETURN items",
                    )
                });
        }
    }

    Ok(None)
}

fn expressions_equivalent_ignoring_span(left: &Expression, right: &Expression) -> bool {
    match (left, right) {
        (Expression::Parenthesized(left), right) => {
            expressions_equivalent_ignoring_span(left, right)
        }
        (left, Expression::Parenthesized(right)) => {
            expressions_equivalent_ignoring_span(left, right)
        }
        (Expression::Variable(left), Expression::Variable(right)) => {
            variable_name(left) == variable_name(right)
        }
        (Expression::Parameter(left), Expression::Parameter(right)) => {
            left.name.name == right.name.name
        }
        (
            Expression::PropertyLookup {
                base: left_base,
                property: left_property,
                ..
            },
            Expression::PropertyLookup {
                base: right_base,
                property: right_property,
                ..
            },
        ) => {
            left_property.name.name == right_property.name.name
                && expressions_equivalent_ignoring_span(left_base, right_base)
        }
        (Expression::FunctionCall(left), Expression::FunctionCall(right)) => {
            left.name.len() == right.name.len()
                && left
                    .name
                    .iter()
                    .zip(&right.name)
                    .all(|(left, right)| left.name == right.name)
                && left.distinct == right.distinct
                && left.arguments.len() == right.arguments.len()
                && left
                    .arguments
                    .iter()
                    .zip(&right.arguments)
                    .all(|(left, right)| expressions_equivalent_ignoring_span(left, right))
        }
        (
            Expression::UnaryOp {
                op: left_op,
                operand: left_operand,
                ..
            },
            Expression::UnaryOp {
                op: right_op,
                operand: right_operand,
                ..
            },
        ) => {
            left_op == right_op && expressions_equivalent_ignoring_span(left_operand, right_operand)
        }
        (
            Expression::BinaryOp {
                op: left_op,
                lhs: left_lhs,
                rhs: left_rhs,
                ..
            },
            Expression::BinaryOp {
                op: right_op,
                lhs: right_lhs,
                rhs: right_rhs,
                ..
            },
        ) => {
            left_op == right_op
                && expressions_equivalent_ignoring_span(left_lhs, right_lhs)
                && expressions_equivalent_ignoring_span(left_rhs, right_rhs)
        }
        (Expression::Literal(left), Expression::Literal(right)) => {
            literals_equivalent_ignoring_span(left, right)
        }
        (Expression::CountStar { .. }, Expression::CountStar { .. }) => true,
        _ => false,
    }
}

fn literals_equivalent_ignoring_span(left: &CypherLiteral, right: &CypherLiteral) -> bool {
    match (left, right) {
        (CypherLiteral::Number(left), CypherLiteral::Number(right)) => left == right,
        (CypherLiteral::String(left), CypherLiteral::String(right)) => left.value == right.value,
        (CypherLiteral::Boolean(left), CypherLiteral::Boolean(right)) => left == right,
        (CypherLiteral::Null, CypherLiteral::Null) => true,
        (CypherLiteral::List(left), CypherLiteral::List(right)) => {
            left.elements.len() == right.elements.len()
                && left
                    .elements
                    .iter()
                    .zip(&right.elements)
                    .all(|(left, right)| expressions_equivalent_ignoring_span(left, right))
        }
        (CypherLiteral::Map(left), CypherLiteral::Map(right)) => {
            left.entries.len() == right.entries.len()
                && left.entries.iter().zip(&right.entries).all(
                    |((left_key, left_value), (right_key, right_value))| {
                        left_key.name.name == right_key.name.name
                            && expressions_equivalent_ignoring_span(left_value, right_value)
                    },
                )
        }
        _ => false,
    }
}

fn compile_static_alternative_outer_skip_limit(
    single_query: &SingleQuery,
    context: &CypherCompileContext,
    path: &str,
) -> Result<(Option<u64>, Option<u64>), CoreError> {
    let return_clause = final_return_clause(single_query, path)?;
    let skip = return_clause
        .skip
        .as_ref()
        .map(|skip| compile_skip(skip, format!("{path}.return.skip"), context))
        .transpose()?;
    let limit = return_clause
        .limit
        .as_ref()
        .map(|limit| compile_limit(limit, format!("{path}.return.limit"), context))
        .transpose()?;
    Ok((skip, limit))
}

fn final_return_clause<'a>(
    single_query: &'a SingleQuery,
    path: &str,
) -> Result<&'a Return, CoreError> {
    match &single_query.kind {
        SingleQueryKind::SinglePart(single_part) => {
            return_clause_from_single_part(single_part, path)
        }
        SingleQueryKind::MultiPart(multi_part) => {
            return_clause_from_single_part(&multi_part.final_part, format!("{path}.final_part"))
        }
    }
}

fn final_return_clause_mut<'a>(
    single_query: &'a mut SingleQuery,
    path: &str,
) -> Result<&'a mut Return, CoreError> {
    match &mut single_query.kind {
        SingleQueryKind::SinglePart(single_part) => {
            return_clause_mut_from_single_part(single_part, path)
        }
        SingleQueryKind::MultiPart(multi_part) => return_clause_mut_from_single_part(
            &mut multi_part.final_part,
            format!("{path}.final_part"),
        ),
    }
}

fn return_clause_mut_from_single_part(
    query: &mut SinglePartQuery,
    path: impl Into<String>,
) -> Result<&mut Return, CoreError> {
    let path = path.into();
    match &mut query.body {
        SinglePartBody::Return(return_clause) => Ok(return_clause),
        SinglePartBody::Updating { .. } => Err(unsupported(
            path,
            "write clauses are not supported by Coral virtual graphs",
        )),
        SinglePartBody::Finish(_) => Err(unsupported(
            path,
            "FINISH is not supported because virtual graph queries must return rows",
        )),
    }
}

fn compile_single_query(
    single_query: &SingleQuery,
    context: &CypherCompileContext,
) -> Result<GraphPlan, CoreError> {
    match &single_query.kind {
        SingleQueryKind::SinglePart(single_part) => compile_single_part(single_part, context),
        SingleQueryKind::MultiPart(multi_part) => compile_multi_part(multi_part, context),
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum ExplicitUnionMode {
    All,
    Distinct,
    Mixed,
}

fn explicit_union_mode(query: &RegularQuery) -> ExplicitUnionMode {
    if query.unions.iter().all(|union| union.all) {
        return ExplicitUnionMode::All;
    }
    if query.unions.iter().all(|union| !union.all) {
        return ExplicitUnionMode::Distinct;
    }
    ExplicitUnionMode::Mixed
}

fn compile_regular_query(
    query: &RegularQuery,
    context: &CypherCompileContext,
) -> Result<GraphQuery, CoreError> {
    let first_query =
        compile_single_query_as_graph_query(&query.single_query, context, "query.single_query")?;
    if query.unions.is_empty() {
        return Ok(first_query);
    }

    let union_mode = explicit_union_mode(query);
    let mut flattened = Vec::with_capacity(query.unions.len() + 1);
    let mut flattened_static_alternative_union = false;
    append_explicit_union_component(
        first_query,
        None,
        union_mode,
        "query.single_query",
        &mut flattened,
        &mut flattened_static_alternative_union,
    )?;

    for (index, union) in query.unions.iter().enumerate() {
        let component = compile_single_query_as_graph_query(
            &union.single_query,
            context,
            format!("query.unions[{index}].single_query"),
        )?;
        append_explicit_union_component(
            component,
            Some(union.all),
            union_mode,
            format!("query.unions[{index}].single_query"),
            &mut flattened,
            &mut flattened_static_alternative_union,
        )?;
    }

    let use_outer_distinct =
        union_mode == ExplicitUnionMode::Distinct && flattened_static_alternative_union;
    let mut flattened = flattened.into_iter();
    let (first_all, first) = flattened
        .next()
        .ok_or_else(|| CoreError::internal("explicit union produced no graph plans"))?;
    if first_all.is_some() {
        return Err(CoreError::internal(
            "explicit union first graph plan unexpectedly had a union operator",
        ));
    }
    let expected_projection_names = projection_names(&first);
    let mut branches = Vec::new();
    for (index, (all, plan)) in flattened.enumerate() {
        let leading_all = all.ok_or_else(|| {
            CoreError::internal("explicit union branch graph plan had no union operator")
        })?;
        let projection_names = projection_names(&plan);
        if projection_names != expected_projection_names {
            return Err(unsupported(
                format!("query.union_branches[{index}].return"),
                format!(
                    "UNION branch projections must match the first branch; expected [{}], got [{}]",
                    expected_projection_names.join(", "),
                    projection_names.join(", ")
                ),
            ));
        }
        branches.push(GraphUnionBranch {
            all: if use_outer_distinct {
                true
            } else {
                leading_all
            },
            plan,
        });
    }

    Ok(GraphQuery::Union(GraphUnion {
        first,
        branches,
        outer_projection: None,
        distinct: use_outer_distinct,
        order_by: Vec::new(),
        skip: None,
        limit: None,
    }))
}

fn projection_names(plan: &GraphPlan) -> Vec<String> {
    plan.projection_output_names()
}

fn append_explicit_union_component(
    component: GraphQuery,
    leading_all: Option<bool>,
    union_mode: ExplicitUnionMode,
    path: impl Into<String>,
    output: &mut Vec<(Option<bool>, GraphPlan)>,
    flattened_static_alternative_union: &mut bool,
) -> Result<(), CoreError> {
    let path = path.into();
    match component {
        GraphQuery::Plan(plan) => {
            output.push((leading_all, plan));
            Ok(())
        }
        GraphQuery::Union(union) => {
            if union_mode == ExplicitUnionMode::Mixed {
                return Err(unsupported(
                    path,
                    "pattern alternatives can be combined with uniform top-level UNION ALL or UNION; mixed UNION and UNION ALL requires nested union grouping",
                ));
            }
            if union.outer_projection.is_some()
                || !union.order_by.is_empty()
                || union.skip.is_some()
                || union.limit.is_some()
            {
                return Err(unsupported(
                    path,
                    "pattern alternatives with branch-level ORDER BY, SKIP, LIMIT, or aggregate outer projections require nested union grouping",
                ));
            }
            if union.distinct && union_mode != ExplicitUnionMode::Distinct {
                return Err(unsupported(
                    path,
                    "pattern alternatives with branch-level DISTINCT can only be flattened into uniform top-level UNION distinct",
                ));
            }
            *flattened_static_alternative_union = true;
            output.push((leading_all, union.first));
            for branch in union.branches {
                if !branch.all {
                    return Err(CoreError::internal(
                        "pattern alternative expansion produced a non-UNION ALL branch",
                    ));
                }
                output.push((Some(true), branch.plan));
            }
            Ok(())
        }
    }
}

fn expand_single_query_pattern_alternatives(
    single_query: &SingleQuery,
    context: &CypherCompileContext,
) -> Result<Vec<ExpandedSingleQuery>, CoreError> {
    let mut expanded = vec![ExpandedSingleQuery {
        query: single_query.clone(),
        force_empty: false,
    }];
    loop {
        let mut progressed = false;
        let mut next = Vec::with_capacity(expanded.len());
        for expanded_query in expanded {
            if let Some(site) =
                first_static_label_type_alternative_site(&expanded_query.query, context)?
            {
                progressed = true;
                let alternatives = match &site {
                    StaticLabelTypeAlternativeSite::SinglePart { alternatives, .. }
                    | StaticLabelTypeAlternativeSite::MultiPart { alternatives, .. } => {
                        alternatives.clone()
                    }
                };
                for alternative in alternatives {
                    if next.len() >= MAX_PATTERN_ALTERNATIVE_BRANCHES {
                        return Err(unsupported(
                            "query.pattern",
                            format!(
                                "pattern alternatives expand to more than {MAX_PATTERN_ALTERNATIVE_BRANCHES} branches; simplify the pattern or split the query explicitly"
                            ),
                        ));
                    }
                    let mut variant = expanded_query.query.clone();
                    apply_static_label_type_alternative(&mut variant, &site, alternative)?;
                    next.push(ExpandedSingleQuery {
                        query: variant,
                        force_empty: expanded_query.force_empty,
                    });
                }
                continue;
            }

            if let Some(site) =
                first_bounded_relationship_range_site(&expanded_query.query, context)?
            {
                progressed = true;
                let alternatives = match &site {
                    BoundedRelationshipRangeSite::SinglePart { alternatives, .. }
                    | BoundedRelationshipRangeSite::MultiPart { alternatives, .. } => {
                        alternatives.clone()
                    }
                };
                for alternative in alternatives {
                    if next.len() >= MAX_PATTERN_ALTERNATIVE_BRANCHES {
                        return Err(unsupported(
                            "query.pattern",
                            format!(
                                "pattern alternatives expand to more than {MAX_PATTERN_ALTERNATIVE_BRANCHES} branches; simplify the pattern or split the query explicitly"
                            ),
                        ));
                    }
                    let mut variant = expanded_query.query.clone();
                    apply_bounded_relationship_range_alternative(
                        &mut variant,
                        &site,
                        alternative.length,
                    )?;
                    next.push(ExpandedSingleQuery {
                        query: variant,
                        force_empty: expanded_query.force_empty || alternative.force_empty,
                    });
                }
                continue;
            }

            next.push(expanded_query);
        }
        expanded = next;
        if !progressed {
            return Ok(expanded);
        }
    }
}

fn first_static_label_type_alternative_site(
    single_query: &SingleQuery,
    context: &CypherCompileContext,
) -> Result<Option<StaticLabelTypeAlternativeSite>, CoreError> {
    match &single_query.kind {
        SingleQueryKind::SinglePart(single_part) => {
            first_single_part_static_label_type_alternative_site(single_part, context)
        }
        SingleQueryKind::MultiPart(multi_part) => {
            first_multi_part_static_label_type_alternative_site(multi_part, context)
        }
    }
}

fn first_single_part_static_label_type_alternative_site(
    single_part: &SinglePartQuery,
    context: &CypherCompileContext,
) -> Result<Option<StaticLabelTypeAlternativeSite>, CoreError> {
    Ok(first_reading_clause_static_label_type_alternative_site(
        &single_part.reading_clauses,
        context,
    )?
    .map(
        |(reading_clause_index, pattern_part_index, target, alternatives)| {
            StaticLabelTypeAlternativeSite::SinglePart {
                reading_clause_index,
                pattern_part_index,
                target,
                alternatives,
            }
        },
    ))
}

fn first_multi_part_static_label_type_alternative_site(
    multi_part: &MultiPartQuery,
    context: &CypherCompileContext,
) -> Result<Option<StaticLabelTypeAlternativeSite>, CoreError> {
    for (part_index, part) in multi_part.parts.iter().enumerate() {
        if let Some((reading_clause_index, pattern_part_index, target, alternatives)) =
            first_reading_clause_static_label_type_alternative_site(&part.reading_clauses, context)?
        {
            return Ok(Some(StaticLabelTypeAlternativeSite::MultiPart {
                query_part: MultiPartAlternativePart::Part(part_index),
                reading_clause_index,
                pattern_part_index,
                target,
                alternatives,
            }));
        }
    }
    Ok(first_reading_clause_static_label_type_alternative_site(
        &multi_part.final_part.reading_clauses,
        context,
    )?
    .map(
        |(reading_clause_index, pattern_part_index, target, alternatives)| {
            StaticLabelTypeAlternativeSite::MultiPart {
                query_part: MultiPartAlternativePart::FinalPart,
                reading_clause_index,
                pattern_part_index,
                target,
                alternatives,
            }
        },
    ))
}

fn first_reading_clause_static_label_type_alternative_site(
    reading_clauses: &[ReadingClause],
    context: &CypherCompileContext,
) -> Result<Option<ReadingClauseLabelTypeAlternativeSite>, CoreError> {
    for (reading_clause_index, clause) in reading_clauses.iter().enumerate() {
        let ReadingClause::Match(match_clause) = clause else {
            continue;
        };
        if let Some((pattern_part_index, target, alternatives)) =
            first_match_static_label_type_alternative_site(match_clause, context)?
        {
            return Ok(Some((
                reading_clause_index,
                pattern_part_index,
                target,
                alternatives,
            )));
        }
    }
    Ok(None)
}

fn first_match_static_label_type_alternative_site(
    match_clause: &Match,
    context: &CypherCompileContext,
) -> Result<Option<MatchLabelTypeAlternativeSite>, CoreError> {
    for (part_index, pattern_part) in match_clause.pattern.parts.iter().enumerate() {
        let Some((start, chains)) = pattern_element_path(&pattern_part.anonymous.element) else {
            continue;
        };
        if let Some(alternatives) =
            graph_declared_standalone_node_label_alternatives(start, chains, context)
        {
            return Ok(Some((
                part_index,
                PatternAlternativeTarget::StartNode,
                alternatives,
            )));
        }
        let raw_alternatives = label_expression_list_alternatives(
            &start.labels,
            "query.pattern.start.labels",
            context,
        )?;
        if raw_alternatives.len() > 1 {
            let alternatives = deduplicate_node_label_alternatives(raw_alternatives);
            return Ok(Some((
                part_index,
                PatternAlternativeTarget::StartNode,
                alternatives
                    .into_iter()
                    .map(LabelTypeAlternative::NodeLabels)
                    .collect(),
            )));
        }
        for (chain_index, chain) in chains.iter().enumerate() {
            if let Some(types) = chain
                .relationship
                .detail
                .as_ref()
                .and_then(|detail| detail.types.as_ref())
            {
                let raw_alternatives = label_expression_alternatives(
                    types,
                    format!("query.pattern.relationships[{chain_index}].types"),
                    context,
                )?;
                if raw_alternatives.len() > 1 {
                    let alternatives = deduplicate_relationship_type_alternatives(raw_alternatives);
                    return Ok(Some((
                        part_index,
                        PatternAlternativeTarget::Relationship(chain_index),
                        alternatives
                            .into_iter()
                            .map(LabelTypeAlternative::RelationshipType)
                            .collect(),
                    )));
                }
            }
            let raw_alternatives = label_expression_list_alternatives(
                &chain.node.labels,
                format!("query.pattern.nodes[{}].labels", chain_index + 1),
                context,
            )?;
            if raw_alternatives.len() > 1 {
                let alternatives = deduplicate_node_label_alternatives(raw_alternatives);
                return Ok(Some((
                    part_index,
                    PatternAlternativeTarget::ChainNode(chain_index),
                    alternatives
                        .into_iter()
                        .map(LabelTypeAlternative::NodeLabels)
                        .collect(),
                )));
            }
        }
    }
    Ok(None)
}

fn graph_declared_standalone_node_label_alternatives(
    start: &CypherNodePattern,
    chains: &[PatternElementChain],
    context: &CypherCompileContext,
) -> Option<Vec<LabelTypeAlternative>> {
    if !start.labels.is_empty() || !chains.is_empty() {
        return None;
    }
    let graph = context.graph.as_ref()?;
    if graph.nodes.is_empty() {
        return None;
    }
    Some(
        graph
            .nodes
            .iter()
            .map(|node| {
                LabelTypeAlternative::NodeLabels(vec![LabelExpression::Static(SymbolicName {
                    name: node.label.clone(),
                    span: start.span,
                })])
            })
            .collect(),
    )
}

fn deduplicate_node_label_alternatives(
    alternatives: Vec<Vec<LabelExpression>>,
) -> Vec<Vec<LabelExpression>> {
    let mut seen = BTreeSet::new();
    alternatives
        .into_iter()
        .filter(|alternative| {
            let Ok(label) = single_static_label(alternative, "query.pattern.alternative") else {
                return true;
            };
            seen.insert(label)
        })
        .collect()
}

fn deduplicate_relationship_type_alternatives(
    alternatives: Vec<LabelExpression>,
) -> Vec<LabelExpression> {
    let mut seen = BTreeSet::new();
    alternatives
        .into_iter()
        .filter(|alternative| {
            let Ok(relationship_type) = single_static_label(
                std::slice::from_ref(alternative),
                "query.pattern.alternative",
            ) else {
                return true;
            };
            seen.insert(relationship_type)
        })
        .collect()
}

fn label_expression_list_alternatives(
    labels: &[LabelExpression],
    path: impl Into<String>,
    context: &CypherCompileContext,
) -> Result<Vec<Vec<LabelExpression>>, CoreError> {
    let path = path.into();
    let mut variants = vec![Vec::new()];
    for (index, label) in labels.iter().enumerate() {
        let label_alternatives =
            label_expression_alternatives(label, format!("{path}[{index}]"), context)?;
        let mut next = Vec::with_capacity(variants.len() * label_alternatives.len());
        for variant in &variants {
            for label_alternative in &label_alternatives {
                let mut next_variant = variant.clone();
                next_variant.push(label_alternative.clone());
                next.push(next_variant);
            }
        }
        variants = next;
    }
    Ok(variants)
}

fn label_expression_alternatives(
    expression: &LabelExpression,
    path: impl Into<String>,
    context: &CypherCompileContext,
) -> Result<Vec<LabelExpression>, CoreError> {
    let path = path.into();
    match expression {
        LabelExpression::Or { lhs, rhs, .. } => {
            let lhs = label_expression_alternatives(lhs, format!("{path}.lhs"), context)?;
            let rhs = label_expression_alternatives(rhs, format!("{path}.rhs"), context)?;
            Ok(lhs.into_iter().chain(rhs).collect())
        }
        LabelExpression::And { lhs, rhs, span } => {
            let lhs_alternatives =
                label_expression_alternatives(lhs, format!("{path}.lhs"), context)?;
            let rhs_alternatives =
                label_expression_alternatives(rhs, format!("{path}.rhs"), context)?;
            let mut alternatives =
                Vec::with_capacity(lhs_alternatives.len() * rhs_alternatives.len());
            for lhs_alternative in &lhs_alternatives {
                for rhs_alternative in &rhs_alternatives {
                    alternatives.push(LabelExpression::And {
                        lhs: Box::new(lhs_alternative.clone()),
                        rhs: Box::new(rhs_alternative.clone()),
                        span: *span,
                    });
                }
            }
            Ok(alternatives)
        }
        LabelExpression::Group { inner, .. } => label_expression_alternatives(inner, path, context),
        LabelExpression::Static(_) => Ok(vec![expression.clone()]),
        LabelExpression::Dynamic { expression, span } => {
            let name = compile_dynamic_label_expression(expression, path, context)?;
            Ok(vec![LabelExpression::Static(SymbolicName {
                name,
                span: *span,
            })])
        }
        LabelExpression::Not { .. } => Ok(vec![resolve_compile_time_label_expression(
            expression, path, context,
        )?]),
    }
}

fn resolve_compile_time_label_expression(
    expression: &LabelExpression,
    path: impl Into<String>,
    context: &CypherCompileContext,
) -> Result<LabelExpression, CoreError> {
    let path = path.into();
    match expression {
        LabelExpression::Static(_) => Ok(expression.clone()),
        LabelExpression::Dynamic { expression, span } => {
            let name = compile_dynamic_label_expression(expression, path, context)?;
            Ok(LabelExpression::Static(SymbolicName { name, span: *span }))
        }
        LabelExpression::Or { lhs, rhs, span } => Ok(LabelExpression::Or {
            lhs: Box::new(resolve_compile_time_label_expression(
                lhs,
                format!("{path}.lhs"),
                context,
            )?),
            rhs: Box::new(resolve_compile_time_label_expression(
                rhs,
                format!("{path}.rhs"),
                context,
            )?),
            span: *span,
        }),
        LabelExpression::And { lhs, rhs, span } => Ok(LabelExpression::And {
            lhs: Box::new(resolve_compile_time_label_expression(
                lhs,
                format!("{path}.lhs"),
                context,
            )?),
            rhs: Box::new(resolve_compile_time_label_expression(
                rhs,
                format!("{path}.rhs"),
                context,
            )?),
            span: *span,
        }),
        LabelExpression::Not { inner, span } => Ok(LabelExpression::Not {
            inner: Box::new(resolve_compile_time_label_expression(
                inner,
                format!("{path}.inner"),
                context,
            )?),
            span: *span,
        }),
        LabelExpression::Group { inner, span } => Ok(LabelExpression::Group {
            inner: Box::new(resolve_compile_time_label_expression(inner, path, context)?),
            span: *span,
        }),
    }
}

fn apply_static_label_type_alternative(
    single_query: &mut SingleQuery,
    site: &StaticLabelTypeAlternativeSite,
    alternative: LabelTypeAlternative,
) -> Result<(), CoreError> {
    match site {
        StaticLabelTypeAlternativeSite::SinglePart {
            reading_clause_index,
            pattern_part_index,
            target,
            ..
        } => {
            let SingleQueryKind::SinglePart(single_part) = &mut single_query.kind else {
                return Err(CoreError::internal(
                    "single-part label/type alternative site applied to multi-part query",
                ));
            };
            apply_reading_clause_static_label_type_alternative(
                &mut single_part.reading_clauses,
                *reading_clause_index,
                *pattern_part_index,
                *target,
                alternative,
            )
        }
        StaticLabelTypeAlternativeSite::MultiPart {
            query_part,
            reading_clause_index,
            pattern_part_index,
            target,
            ..
        } => {
            let SingleQueryKind::MultiPart(multi_part) = &mut single_query.kind else {
                return Err(CoreError::internal(
                    "multi-part label/type alternative site applied to single-part query",
                ));
            };
            let reading_clauses = match query_part {
                MultiPartAlternativePart::Part(index) => multi_part
                    .parts
                    .get_mut(*index)
                    .map(|part| &mut part.reading_clauses),
                MultiPartAlternativePart::FinalPart => {
                    Some(&mut multi_part.final_part.reading_clauses)
                }
            }
            .ok_or_else(|| CoreError::internal("multi-part alternative site is out of bounds"))?;
            apply_reading_clause_static_label_type_alternative(
                reading_clauses,
                *reading_clause_index,
                *pattern_part_index,
                *target,
                alternative,
            )
        }
    }
}

fn apply_reading_clause_static_label_type_alternative(
    reading_clauses: &mut [ReadingClause],
    reading_clause_index: usize,
    pattern_part_index: usize,
    target: PatternAlternativeTarget,
    alternative: LabelTypeAlternative,
) -> Result<(), CoreError> {
    let ReadingClause::Match(match_clause) = reading_clauses
        .get_mut(reading_clause_index)
        .ok_or_else(|| {
            CoreError::internal("label/type alternative reading clause is out of bounds")
        })?
    else {
        return Err(CoreError::internal(
            "label/type alternative site did not point at a MATCH clause",
        ));
    };
    let pattern_part = match_clause
        .pattern
        .parts
        .get_mut(pattern_part_index)
        .ok_or_else(|| {
            CoreError::internal("label/type alternative pattern part is out of bounds")
        })?;
    let Some((start, chains)) = pattern_element_path_mut(&mut pattern_part.anonymous.element)
    else {
        return Err(CoreError::internal(
            "label/type alternative site did not point at a path pattern",
        ));
    };
    match (target, alternative) {
        (PatternAlternativeTarget::StartNode, LabelTypeAlternative::NodeLabels(labels)) => {
            start.labels = labels;
            Ok(())
        }
        (PatternAlternativeTarget::ChainNode(index), LabelTypeAlternative::NodeLabels(labels)) => {
            let chain = chains
                .get_mut(index)
                .ok_or_else(|| CoreError::internal("node alternative chain is out of bounds"))?;
            chain.node.labels = labels;
            Ok(())
        }
        (
            PatternAlternativeTarget::Relationship(index),
            LabelTypeAlternative::RelationshipType(relationship_type),
        ) => {
            let chain = chains.get_mut(index).ok_or_else(|| {
                CoreError::internal("relationship alternative chain is out of bounds")
            })?;
            let detail =
                chain.relationship.detail.as_mut().ok_or_else(|| {
                    CoreError::internal("relationship alternative detail is missing")
                })?;
            detail.types = Some(relationship_type);
            Ok(())
        }
        _ => Err(CoreError::internal(
            "label/type alternative site and replacement kind did not match",
        )),
    }
}

fn first_bounded_relationship_range_site(
    single_query: &SingleQuery,
    context: &CypherCompileContext,
) -> Result<Option<BoundedRelationshipRangeSite>, CoreError> {
    match &single_query.kind {
        SingleQueryKind::SinglePart(single_part) => {
            first_single_part_bounded_relationship_range_site(single_part, context)
        }
        SingleQueryKind::MultiPart(multi_part) => {
            first_multi_part_bounded_relationship_range_site(multi_part, context)
        }
    }
}

fn first_single_part_bounded_relationship_range_site(
    single_part: &SinglePartQuery,
    context: &CypherCompileContext,
) -> Result<Option<BoundedRelationshipRangeSite>, CoreError> {
    first_reading_clause_bounded_relationship_range_site(&single_part.reading_clauses, context).map(
        |site| {
            site.map(
                |(reading_clause_index, pattern_part_index, chain_index, target, alternatives)| {
                    BoundedRelationshipRangeSite::SinglePart {
                        reading_clause_index,
                        pattern_part_index,
                        chain_index,
                        target,
                        alternatives,
                    }
                },
            )
        },
    )
}

fn first_multi_part_bounded_relationship_range_site(
    multi_part: &MultiPartQuery,
    context: &CypherCompileContext,
) -> Result<Option<BoundedRelationshipRangeSite>, CoreError> {
    for (part_index, part) in multi_part.parts.iter().enumerate() {
        if let Some((reading_clause_index, pattern_part_index, chain_index, target, alternatives)) =
            first_reading_clause_bounded_relationship_range_site(&part.reading_clauses, context)?
        {
            return Ok(Some(BoundedRelationshipRangeSite::MultiPart {
                query_part: MultiPartAlternativePart::Part(part_index),
                reading_clause_index,
                pattern_part_index,
                chain_index,
                target,
                alternatives,
            }));
        }
    }
    first_reading_clause_bounded_relationship_range_site(
        &multi_part.final_part.reading_clauses,
        context,
    )
    .map(|site| {
        site.map(
            |(reading_clause_index, pattern_part_index, chain_index, target, alternatives)| {
                BoundedRelationshipRangeSite::MultiPart {
                    query_part: MultiPartAlternativePart::FinalPart,
                    reading_clause_index,
                    pattern_part_index,
                    chain_index,
                    target,
                    alternatives,
                }
            },
        )
    })
}

fn first_reading_clause_bounded_relationship_range_site(
    reading_clauses: &[ReadingClause],
    context: &CypherCompileContext,
) -> Result<Option<BoundedRelationshipRangeSiteInfo>, CoreError> {
    for (reading_clause_index, clause) in reading_clauses.iter().enumerate() {
        let ReadingClause::Match(match_clause) = clause else {
            continue;
        };
        if let Some((pattern_part_index, chain_index, target, alternatives)) =
            first_match_bounded_relationship_range_site(match_clause, context)?
        {
            if match_clause.optional {
                return Err(unsupported(
                    format!(
                        "match.reading_clauses[{reading_clause_index}].pattern.parts[{pattern_part_index}].relationships[{chain_index}]"
                    ),
                    "OPTIONAL MATCH with bounded variable-length relationship ranges is not supported yet because branch expansion would duplicate unmatched null rows",
                ));
            }
            return Ok(Some((
                reading_clause_index,
                pattern_part_index,
                chain_index,
                target,
                alternatives,
            )));
        }
    }
    Ok(None)
}

fn first_match_bounded_relationship_range_site(
    match_clause: &Match,
    context: &CypherCompileContext,
) -> Result<Option<MatchBoundedRelationshipRangeSiteInfo>, CoreError> {
    for (part_index, pattern_part) in match_clause.pattern.parts.iter().enumerate() {
        let Some((start, chains)) = pattern_element_path(&pattern_part.anonymous.element) else {
            continue;
        };
        for (chain_index, chain) in chains.iter().enumerate() {
            if let Some((target, alternatives)) = bounded_relationship_range_alternatives(
                &chain.relationship,
                format!("match.pattern.parts[{part_index}].relationships[{chain_index}]"),
            )? {
                let alternatives = filter_bounded_relationship_range_alternatives(
                    start,
                    chains,
                    chain_index,
                    &chain.relationship,
                    alternatives,
                    context,
                    format!("match.pattern.parts[{part_index}].relationships[{chain_index}]"),
                )?;
                return Ok(Some((part_index, chain_index, target, alternatives)));
            }
        }
    }
    Ok(None)
}

fn bounded_relationship_range_alternatives(
    pattern: &CypherRelationshipPattern,
    path: impl Into<String>,
) -> Result<Option<(RelationshipRangeTarget, Vec<usize>)>, CoreError> {
    let path = path.into();
    let detail_range = pattern
        .detail
        .as_ref()
        .and_then(|detail| detail.range.as_ref());
    if detail_range.is_some() && pattern.quantifier.is_some() {
        return Err(unsupported(
            path,
            "relationship patterns cannot combine a variable-length range and a GQL quantifier",
        ));
    }
    if let Some(range) = detail_range {
        return bounded_range_alternatives(
            range.start,
            range.end,
            format!("{path}.range"),
            "variable-length relationship ranges require finite non-negative bounds such as *0..3 or *1..3; unbounded ranges are not supported yet",
        )
        .map(|alternatives| alternatives.map(|alternatives| (RelationshipRangeTarget::DetailRange, alternatives)));
    }
    if let Some(quantifier) = pattern.quantifier.as_ref() {
        return bounded_range_alternatives(
            quantifier.start,
            quantifier.end,
            format!("{path}.quantifier"),
            "relationship quantifiers require finite non-negative bounds such as {0,3} or {1,3}; unbounded quantifiers are not supported yet",
        )
        .map(|alternatives| alternatives.map(|alternatives| (RelationshipRangeTarget::Quantifier, alternatives)));
    }
    Ok(None)
}

fn bounded_range_alternatives(
    start: Option<i64>,
    end: Option<i64>,
    path: impl Into<String>,
    message: &'static str,
) -> Result<Option<Vec<usize>>, CoreError> {
    let path = path.into();
    let (Some(start), Some(end)) = (start, end) else {
        return Err(unsupported(path, message));
    };
    if start == end {
        return Ok(None);
    }
    if start < 0 || end < 0 || start > end {
        return Err(unsupported(path, message));
    }
    let start = usize::try_from(start).map_err(|error| {
        unsupported(
            path.clone(),
            format!("bounded relationship range lower bound is out of range: {error}"),
        )
    })?;
    let end = usize::try_from(end).map_err(|error| {
        unsupported(
            path.clone(),
            format!("bounded relationship range upper bound is out of range: {error}"),
        )
    })?;
    if end > MAX_FIXED_RELATIONSHIP_LENGTH {
        return Err(unsupported(
            path,
            format!(
                "bounded relationship range upper bound {end} exceeds Coral's current maximum of {MAX_FIXED_RELATIONSHIP_LENGTH} hops"
            ),
        ));
    }
    Ok(Some((start..=end).collect()))
}

fn filter_bounded_relationship_range_alternatives(
    start: &CypherNodePattern,
    chains: &[PatternElementChain],
    chain_index: usize,
    relationship: &CypherRelationshipPattern,
    alternatives: Vec<usize>,
    context: &CypherCompileContext,
    path: impl Into<String>,
) -> Result<Vec<BoundedRelationshipRangeAlternative>, CoreError> {
    let path = path.into();
    let Some(graph) = context.graph.as_ref() else {
        return Ok(normal_bounded_relationship_range_alternatives(alternatives));
    };
    let (Some(start_label), Some(end_label)) =
        bounded_relationship_endpoint_labels(start, chains, chain_index, &path, context)?
    else {
        return Ok(normal_bounded_relationship_range_alternatives(alternatives));
    };
    let Some(relationship_type) = bounded_relationship_type(relationship, &path, context)? else {
        return Ok(normal_bounded_relationship_range_alternatives(alternatives));
    };
    let direction = relationship_pattern_direction(relationship.direction);
    let adjacency = fixed_length_label_adjacency(graph, &relationship_type, direction);
    let mut feasible = Vec::new();
    for length in alternatives {
        if feasible_fixed_relationship_length(
            &relationship_type,
            &adjacency,
            &start_label,
            &end_label,
            length,
            &path,
        )? {
            feasible.push(length);
        }
    }
    if feasible.is_empty() {
        return Ok(vec![BoundedRelationshipRangeAlternative {
            length: 0,
            force_empty: true,
        }]);
    }
    Ok(normal_bounded_relationship_range_alternatives(feasible))
}

fn normal_bounded_relationship_range_alternatives(
    lengths: Vec<usize>,
) -> Vec<BoundedRelationshipRangeAlternative> {
    lengths
        .into_iter()
        .map(|length| BoundedRelationshipRangeAlternative {
            length,
            force_empty: false,
        })
        .collect()
}

fn bounded_relationship_endpoint_labels(
    start: &CypherNodePattern,
    chains: &[PatternElementChain],
    chain_index: usize,
    path: &str,
    context: &CypherCompileContext,
) -> Result<(Option<String>, Option<String>), CoreError> {
    let left = if chain_index == 0 {
        start
    } else {
        &chains
            .get(chain_index - 1)
            .ok_or_else(|| CoreError::internal("bounded range chain start is out of bounds"))?
            .node
    };
    let right = &chains
        .get(chain_index)
        .ok_or_else(|| CoreError::internal("bounded range chain end is out of bounds"))?
        .node;
    Ok((
        optional_single_compile_time_label(&left.labels, format!("{path}.start.labels"), context)?,
        optional_single_compile_time_label(&right.labels, format!("{path}.end.labels"), context)?,
    ))
}

fn bounded_relationship_type(
    relationship: &CypherRelationshipPattern,
    path: &str,
    context: &CypherCompileContext,
) -> Result<Option<String>, CoreError> {
    relationship
        .detail
        .as_ref()
        .and_then(|detail| detail.types.as_ref())
        .map(|relationship_type| {
            single_compile_time_label(
                std::slice::from_ref(relationship_type),
                format!("{path}.types"),
                context,
            )
        })
        .transpose()
}

fn relationship_pattern_direction(direction: CypherRelationshipDirection) -> Direction {
    match direction {
        CypherRelationshipDirection::Right => Direction::Outgoing,
        CypherRelationshipDirection::Left => Direction::Incoming,
        CypherRelationshipDirection::Both | CypherRelationshipDirection::Undirected => {
            Direction::Undirected
        }
    }
}

fn feasible_fixed_relationship_length(
    relationship_type: &str,
    adjacency: &BTreeMap<String, BTreeSet<String>>,
    start_label: &str,
    end_label: &str,
    length: usize,
    path: &str,
) -> Result<bool, CoreError> {
    if length == 0 {
        return Ok(start_label == end_label);
    }
    let sequences =
        fixed_length_label_sequences_with_adjacency(adjacency, start_label, end_label, length);
    match sequences.len() {
        0 => Ok(false),
        1 => Ok(true),
        count => Err(unsupported(
            path,
            format!(
                "bounded relationship range found at least {count} possible {length}-hop '{relationship_type}' label paths from {start_label} to {end_label}; use explicit intermediate nodes to disambiguate"
            ),
        )),
    }
}

fn apply_bounded_relationship_range_alternative(
    single_query: &mut SingleQuery,
    site: &BoundedRelationshipRangeSite,
    length: usize,
) -> Result<(), CoreError> {
    match site {
        BoundedRelationshipRangeSite::SinglePart {
            reading_clause_index,
            pattern_part_index,
            chain_index,
            target,
            ..
        } => {
            let SingleQueryKind::SinglePart(single_part) = &mut single_query.kind else {
                return Err(CoreError::internal(
                    "single-part bounded range site applied to multi-part query",
                ));
            };
            apply_reading_clause_bounded_relationship_range_alternative(
                &mut single_part.reading_clauses,
                *reading_clause_index,
                *pattern_part_index,
                *chain_index,
                *target,
                length,
            )
        }
        BoundedRelationshipRangeSite::MultiPart {
            query_part,
            reading_clause_index,
            pattern_part_index,
            chain_index,
            target,
            ..
        } => {
            let SingleQueryKind::MultiPart(multi_part) = &mut single_query.kind else {
                return Err(CoreError::internal(
                    "multi-part bounded range site applied to single-part query",
                ));
            };
            let reading_clauses = match query_part {
                MultiPartAlternativePart::Part(index) => multi_part
                    .parts
                    .get_mut(*index)
                    .map(|part| &mut part.reading_clauses),
                MultiPartAlternativePart::FinalPart => {
                    Some(&mut multi_part.final_part.reading_clauses)
                }
            }
            .ok_or_else(|| CoreError::internal("multi-part bounded range site is out of bounds"))?;
            apply_reading_clause_bounded_relationship_range_alternative(
                reading_clauses,
                *reading_clause_index,
                *pattern_part_index,
                *chain_index,
                *target,
                length,
            )
        }
    }
}

fn apply_reading_clause_bounded_relationship_range_alternative(
    reading_clauses: &mut [ReadingClause],
    reading_clause_index: usize,
    pattern_part_index: usize,
    chain_index: usize,
    target: RelationshipRangeTarget,
    length: usize,
) -> Result<(), CoreError> {
    let ReadingClause::Match(match_clause) = reading_clauses
        .get_mut(reading_clause_index)
        .ok_or_else(|| CoreError::internal("bounded range reading clause is out of bounds"))?
    else {
        return Err(CoreError::internal(
            "bounded range site did not point at a MATCH clause",
        ));
    };
    let pattern_part = match_clause
        .pattern
        .parts
        .get_mut(pattern_part_index)
        .ok_or_else(|| CoreError::internal("bounded range pattern part is out of bounds"))?;
    let Some((_, chains)) = pattern_element_path_mut(&mut pattern_part.anonymous.element) else {
        return Err(CoreError::internal(
            "bounded range site did not point at a path pattern",
        ));
    };
    let chain = chains
        .get_mut(chain_index)
        .ok_or_else(|| CoreError::internal("bounded range chain is out of bounds"))?;
    set_exact_relationship_range(&mut chain.relationship, target, length)
}

fn set_exact_relationship_range(
    relationship: &mut CypherRelationshipPattern,
    target: RelationshipRangeTarget,
    length: usize,
) -> Result<(), CoreError> {
    let length = i64::try_from(length)
        .map_err(|error| CoreError::internal(format!("range length out of range: {error}")))?;
    match target {
        RelationshipRangeTarget::DetailRange => {
            let detail = relationship
                .detail
                .as_mut()
                .ok_or_else(|| CoreError::internal("bounded range relationship detail missing"))?;
            let range = detail
                .range
                .as_mut()
                .ok_or_else(|| CoreError::internal("bounded relationship range missing"))?;
            set_exact_range_literal(range, length);
            Ok(())
        }
        RelationshipRangeTarget::Quantifier => {
            let quantifier = relationship
                .quantifier
                .as_mut()
                .ok_or_else(|| CoreError::internal("bounded relationship quantifier missing"))?;
            set_exact_quantifier(quantifier, length);
            Ok(())
        }
    }
}

fn set_exact_range_literal(range: &mut RangeLiteral, length: i64) {
    range.start = Some(length);
    range.end = Some(length);
}

fn set_exact_quantifier(quantifier: &mut Quantifier, length: i64) {
    quantifier.start = Some(length);
    quantifier.end = Some(length);
}

fn validate_pattern_alternative_expansion_supported(
    single_query: &SingleQuery,
    path: &str,
    context: &CypherCompileContext,
) -> Result<(), CoreError> {
    match &single_query.kind {
        SingleQueryKind::SinglePart(single_part) => {
            validate_single_part_pattern_alternative_expansion_supported(single_part, path, context)
        }
        SingleQueryKind::MultiPart(multi_part) => {
            validate_multi_part_pattern_alternative_expansion_supported(multi_part, path, context)
        }
    }
}

fn validate_single_part_pattern_alternative_expansion_supported(
    single_part: &SinglePartQuery,
    path: &str,
    context: &CypherCompileContext,
) -> Result<(), CoreError> {
    let return_clause = return_clause_from_single_part(single_part, path)?;
    validate_return_allows_pattern_alternative_expansion(return_clause, path, context)
}

fn validate_multi_part_pattern_alternative_expansion_supported(
    multi_part: &MultiPartQuery,
    path: &str,
    context: &CypherCompileContext,
) -> Result<(), CoreError> {
    for (index, part) in multi_part.parts.iter().enumerate() {
        if !part.updating_clauses.is_empty() {
            return Err(unsupported(
                format!("{path}.parts[{index}].updating_clauses"),
                "write clauses are not supported by Coral virtual graphs",
            ));
        }
        validate_with_allows_pattern_alternative_expansion(
            &part.with,
            &format!("{path}.parts[{index}].with"),
        )?;
    }
    validate_single_part_pattern_alternative_expansion_supported(
        &multi_part.final_part,
        &format!("{path}.final_part"),
        context,
    )
}

fn validate_with_allows_pattern_alternative_expansion(
    with: &With,
    path: &str,
) -> Result<(), CoreError> {
    if with.distinct {
        return Err(unsupported(
            format!("{path}.distinct"),
            "pattern alternatives with WITH DISTINCT require staged query planning and are not supported yet",
        ));
    }
    if with.order.is_some() || with.skip.is_some() || with.limit.is_some() {
        return Err(unsupported(
            path,
            "pattern alternatives with WITH ORDER BY, SKIP, or LIMIT require staged query planning and are not supported yet",
        ));
    }
    for (index, item) in with.items.iter().enumerate() {
        if expression_contains_aggregate(&item.expression) {
            return Err(unsupported(
                format!("{path}.items[{index}].expression"),
                "pattern alternatives with aggregate WITH projections require staged query planning and are not supported yet",
            ));
        }
    }
    Ok(())
}

fn validate_return_allows_pattern_alternative_expansion(
    return_clause: &Return,
    path: &str,
    context: &CypherCompileContext,
) -> Result<(), CoreError> {
    for (index, item) in return_clause.items.iter().enumerate() {
        if count_star_item_alias(item).is_none()
            && compile_static_alternative_outer_aggregate_item(item, index, path, context)?
                .is_none()
            && expression_contains_aggregate(&item.expression)
        {
            return Err(unsupported(
                format!("{path}.return.items[{index}].expression"),
                "pattern alternatives with property or non-count aggregate RETURN projections require staged query planning and are not supported yet",
            ));
        }
    }
    Ok(())
}

fn expression_contains_aggregate(expression: &Expression) -> bool {
    match expression {
        Expression::CountStar { .. } => true,
        Expression::FunctionCall(function) => {
            is_aggregate_function_call(function)
                || function.arguments.iter().any(expression_contains_aggregate)
        }
        Expression::Literal(literal) => literal_contains_aggregate(literal),
        Expression::PropertyLookup { base, .. }
        | Expression::IsNull { operand: base, .. }
        | Expression::UnaryOp { operand: base, .. }
        | Expression::Parenthesized(base) => expression_contains_aggregate(base),
        Expression::NodeLabels { base, labels, .. } => {
            expression_contains_aggregate(base)
                || labels.iter().any(label_expression_contains_aggregate)
        }
        Expression::BinaryOp { lhs, rhs, .. } | Expression::In { lhs, rhs, .. } => {
            expression_contains_aggregate(lhs) || expression_contains_aggregate(rhs)
        }
        Expression::Comparison { lhs, operators, .. } => {
            expression_contains_aggregate(lhs)
                || operators
                    .iter()
                    .any(|(_, rhs)| expression_contains_aggregate(rhs))
        }
        Expression::ListIndex { list, index, .. } => {
            expression_contains_aggregate(list) || expression_contains_aggregate(index)
        }
        Expression::ListSlice {
            list, start, end, ..
        } => {
            expression_contains_aggregate(list)
                || start.as_deref().is_some_and(expression_contains_aggregate)
                || end.as_deref().is_some_and(expression_contains_aggregate)
        }
        Expression::Case(case) => case_contains_aggregate(case),
        Expression::ListComprehension(comprehension) => {
            list_comprehension_contains_aggregate(comprehension)
        }
        Expression::PatternComprehension(comprehension) => {
            pattern_comprehension_contains_aggregate(comprehension)
        }
        Expression::All(filter)
        | Expression::Any(filter)
        | Expression::None(filter)
        | Expression::Single(filter) => filter_expression_contains_aggregate(filter),
        Expression::Exists(exists) => exists_expression_contains_aggregate(exists),
        Expression::MapProjection(map) => map_projection_contains_aggregate(map),
        Expression::CountSubquery(_)
        | Expression::CollectSubquery(_)
        | Expression::Variable(_)
        | Expression::Parameter(_)
        | Expression::Pattern(_) => false,
    }
}

fn literal_contains_aggregate(literal: &CypherLiteral) -> bool {
    match literal {
        CypherLiteral::List(list) => list.elements.iter().any(expression_contains_aggregate),
        CypherLiteral::Map(map) => map
            .entries
            .iter()
            .any(|(_, value)| expression_contains_aggregate(value)),
        CypherLiteral::Number(_)
        | CypherLiteral::String(_)
        | CypherLiteral::Boolean(_)
        | CypherLiteral::Null => false,
    }
}

fn case_contains_aggregate(case: &CaseExpression) -> bool {
    case.scrutinee
        .as_deref()
        .is_some_and(expression_contains_aggregate)
        || case.alternatives.iter().any(|alternative| {
            expression_contains_aggregate(&alternative.when)
                || expression_contains_aggregate(&alternative.then)
        })
        || case
            .default
            .as_deref()
            .is_some_and(expression_contains_aggregate)
}

fn list_comprehension_contains_aggregate(
    comprehension: &decypher::ast::expr::ListComprehension,
) -> bool {
    comprehension
        .filter
        .as_deref()
        .is_some_and(expression_contains_aggregate)
        || comprehension
            .map
            .as_ref()
            .is_some_and(expression_contains_aggregate)
}

fn pattern_comprehension_contains_aggregate(
    comprehension: &decypher::ast::expr::PatternComprehension,
) -> bool {
    comprehension
        .where_clause
        .as_ref()
        .is_some_and(expression_contains_aggregate)
        || expression_contains_aggregate(&comprehension.map)
}

fn filter_expression_contains_aggregate(filter: &decypher::ast::expr::FilterExpression) -> bool {
    expression_contains_aggregate(&filter.collection)
        || filter
            .predicate
            .as_deref()
            .is_some_and(expression_contains_aggregate)
}

fn exists_expression_contains_aggregate(exists: &decypher::ast::expr::ExistsExpression) -> bool {
    match exists.inner.as_ref() {
        decypher::ast::expr::ExistsInner::Pattern(_, predicate) => predicate
            .as_deref()
            .is_some_and(expression_contains_aggregate),
        decypher::ast::expr::ExistsInner::RegularQuery(_) => true,
    }
}

fn map_projection_contains_aggregate(map: &decypher::ast::expr::MapProjection) -> bool {
    map.items.iter().any(|item| match item {
        decypher::ast::expr::MapProjectionItem::Literal { value, .. } => {
            expression_contains_aggregate(value)
        }
        decypher::ast::expr::MapProjectionItem::AllProperties { .. }
        | decypher::ast::expr::MapProjectionItem::PropertyLookup { .. } => false,
    })
}

fn label_expression_contains_aggregate(expression: &LabelExpression) -> bool {
    match expression {
        LabelExpression::Dynamic {
            expression: dynamic,
            ..
        } => expression_contains_aggregate(dynamic),
        LabelExpression::Or { lhs, rhs, .. } | LabelExpression::And { lhs, rhs, .. } => {
            label_expression_contains_aggregate(lhs) || label_expression_contains_aggregate(rhs)
        }
        LabelExpression::Not { inner, .. } | LabelExpression::Group { inner, .. } => {
            label_expression_contains_aggregate(inner)
        }
        LabelExpression::Static(_) => false,
    }
}

fn compile_single_part(
    query: &SinglePartQuery,
    context: &CypherCompileContext,
) -> Result<GraphPlan, CoreError> {
    let return_clause = return_clause_from_single_part(query, "query")?;

    let mut plan = GraphPlan::default();
    let mut state = compile_state_for_single_part(query, context);
    compile_reading_clauses_into(
        &query.reading_clauses,
        "match",
        &mut plan,
        &mut state,
        context,
    )?;
    compile_return(return_clause, &mut plan, &state, context)?;
    reject_ignored_path_variable_references(&plan, &state, "return")?;
    Ok(plan)
}

fn compile_state_for_single_part(
    query: &SinglePartQuery,
    context: &CypherCompileContext,
) -> CypherCompileState {
    let mut state = CypherCompileState::default();
    collect_relationship_element_path_variables_in_single_part(
        query,
        context,
        &mut state.relationship_element_path_variables,
    );
    state
}

fn compile_state_for_multi_part(
    query: &MultiPartQuery,
    context: &CypherCompileContext,
) -> CypherCompileState {
    let mut state = CypherCompileState::default();
    for part in &query.parts {
        collect_relationship_element_path_variables_in_reading_clauses(
            &part.reading_clauses,
            context,
            &mut state.relationship_element_path_variables,
        );
        collect_relationship_element_path_variables_in_with(
            &part.with,
            context,
            &mut state.relationship_element_path_variables,
        );
    }
    collect_relationship_element_path_variables_in_single_part(
        &query.final_part,
        context,
        &mut state.relationship_element_path_variables,
    );
    state
}

fn collect_relationship_element_path_variables_in_single_part(
    query: &SinglePartQuery,
    context: &CypherCompileContext,
    variables: &mut BTreeSet<String>,
) {
    collect_relationship_element_path_variables_in_reading_clauses(
        &query.reading_clauses,
        context,
        variables,
    );
    if let SinglePartBody::Return(return_clause) = &query.body {
        collect_relationship_element_path_variables_in_return(return_clause, context, variables);
    }
}

fn collect_relationship_element_path_variables_in_reading_clauses(
    clauses: &[ReadingClause],
    context: &CypherCompileContext,
    variables: &mut BTreeSet<String>,
) {
    for clause in clauses {
        if let ReadingClause::Match(match_clause) = clause
            && let Some(where_clause) = &match_clause.where_clause
        {
            collect_relationship_element_path_variables_in_expression(
                where_clause,
                context,
                variables,
            );
        }
    }
}

fn collect_relationship_element_path_variables_in_with(
    with: &With,
    context: &CypherCompileContext,
    variables: &mut BTreeSet<String>,
) {
    for item in &with.items {
        collect_relationship_element_path_variables_in_expression(
            &item.expression,
            context,
            variables,
        );
    }
    if let Some(where_clause) = &with.where_clause {
        collect_relationship_element_path_variables_in_expression(where_clause, context, variables);
    }
    collect_relationship_element_path_variables_in_order_by(
        with.order.as_ref(),
        context,
        variables,
    );
    if let Some(skip) = &with.skip {
        collect_relationship_element_path_variables_in_expression(skip, context, variables);
    }
    if let Some(limit) = &with.limit {
        collect_relationship_element_path_variables_in_expression(limit, context, variables);
    }
}

fn collect_relationship_element_path_variables_in_return(
    return_clause: &Return,
    context: &CypherCompileContext,
    variables: &mut BTreeSet<String>,
) {
    for item in &return_clause.items {
        collect_relationship_element_path_variables_in_expression(
            &item.expression,
            context,
            variables,
        );
    }
    collect_relationship_element_path_variables_in_order_by(
        return_clause.order.as_ref(),
        context,
        variables,
    );
    if let Some(skip) = &return_clause.skip {
        collect_relationship_element_path_variables_in_expression(skip, context, variables);
    }
    if let Some(limit) = &return_clause.limit {
        collect_relationship_element_path_variables_in_expression(limit, context, variables);
    }
}

fn collect_relationship_element_path_variables_in_order_by(
    order: Option<&Order>,
    context: &CypherCompileContext,
    variables: &mut BTreeSet<String>,
) {
    let Some(order) = order else {
        return;
    };
    for item in &order.items {
        collect_relationship_element_path_variables_in_expression(
            &item.expression,
            context,
            variables,
        );
    }
}

fn collect_relationship_element_path_variables_in_expression(
    expression: &Expression,
    context: &CypherCompileContext,
    variables: &mut BTreeSet<String>,
) {
    match expression {
        Expression::Parenthesized(inner) => {
            collect_relationship_element_path_variables_in_expression(inner, context, variables);
        }
        Expression::UnaryOp { operand, .. } | Expression::IsNull { operand, .. } => {
            collect_relationship_element_path_variables_in_expression(operand, context, variables);
        }
        Expression::BinaryOp { lhs, rhs, .. } | Expression::In { lhs, rhs, .. } => {
            collect_relationship_element_path_variables_in_expression(lhs, context, variables);
            collect_relationship_element_path_variables_in_expression(rhs, context, variables);
        }
        Expression::Comparison { lhs, operators, .. } => {
            collect_relationship_element_path_variables_in_expression(lhs, context, variables);
            for (_, rhs) in operators {
                collect_relationship_element_path_variables_in_expression(rhs, context, variables);
            }
        }
        Expression::ListIndex { list, index, .. } => {
            collect_relationship_element_path_variables_in_expression(list, context, variables);
            collect_relationship_element_path_variables_in_expression(index, context, variables);
        }
        Expression::ListSlice {
            list, start, end, ..
        } => {
            collect_relationship_element_path_variables_in_expression(list, context, variables);
            if let Some(start) = start.as_deref() {
                collect_relationship_element_path_variables_in_expression(
                    start, context, variables,
                );
            }
            if let Some(end) = end.as_deref() {
                collect_relationship_element_path_variables_in_expression(end, context, variables);
            }
        }
        Expression::Case(case) => {
            collect_relationship_element_path_variables_in_case(case, context, variables);
        }
        Expression::FunctionCall(function) => {
            collect_relationship_element_path_variables_in_function(function, context, variables);
        }
        Expression::ListComprehension(comprehension) => {
            if let Some(filter) = comprehension.filter.as_deref() {
                collect_relationship_element_path_variables_in_expression(
                    filter, context, variables,
                );
            }
            if let Some(map) = comprehension.map.as_ref() {
                collect_relationship_element_path_variables_in_expression(map, context, variables);
            }
        }
        Expression::PatternComprehension(comprehension) => {
            if let Some(where_clause) = comprehension.where_clause.as_ref() {
                collect_relationship_element_path_variables_in_expression(
                    where_clause,
                    context,
                    variables,
                );
            }
            collect_relationship_element_path_variables_in_expression(
                &comprehension.map,
                context,
                variables,
            );
        }
        Expression::All(filter)
        | Expression::Any(filter)
        | Expression::None(filter)
        | Expression::Single(filter) => {
            collect_relationship_element_path_variables_in_expression(
                &filter.collection,
                context,
                variables,
            );
            if let Some(predicate) = filter.predicate.as_deref() {
                collect_relationship_element_path_variables_in_expression(
                    predicate, context, variables,
                );
            }
        }
        Expression::Literal(_)
        | Expression::Variable(_)
        | Expression::Parameter(_)
        | Expression::CountStar { .. }
        | Expression::PropertyLookup { .. }
        | Expression::NodeLabels { .. }
        | Expression::Pattern(_)
        | Expression::Exists(_)
        | Expression::CountSubquery(_)
        | Expression::CollectSubquery(_)
        | Expression::MapProjection(_) => {}
    }
}

fn collect_relationship_element_path_variables_in_case(
    case: &CaseExpression,
    context: &CypherCompileContext,
    variables: &mut BTreeSet<String>,
) {
    if let Some(scrutinee) = case.scrutinee.as_deref() {
        collect_relationship_element_path_variables_in_expression(scrutinee, context, variables);
    }
    for alternative in &case.alternatives {
        collect_relationship_element_path_variables_in_expression(
            &alternative.when,
            context,
            variables,
        );
        collect_relationship_element_path_variables_in_expression(
            &alternative.then,
            context,
            variables,
        );
    }
    if let Some(default) = case.default.as_deref() {
        collect_relationship_element_path_variables_in_expression(default, context, variables);
    }
}

fn collect_relationship_element_path_variables_in_function(
    function: &FunctionInvocation,
    context: &CypherCompileContext,
    variables: &mut BTreeSet<String>,
) {
    if is_size_function(function) {
        for argument in &function.arguments {
            if expression_relationships_path_variable(argument, context).is_none() {
                collect_relationship_element_path_variables_in_expression(
                    argument, context, variables,
                );
            }
        }
        return;
    }

    if is_relationships_function(function)
        && let Some(variable) = function_relationships_path_variable(function, context)
    {
        variables.insert(variable);
    }
    for argument in &function.arguments {
        collect_relationship_element_path_variables_in_expression(argument, context, variables);
    }
}

fn expression_relationships_path_variable(
    expression: &Expression,
    context: &CypherCompileContext,
) -> Option<String> {
    let Expression::FunctionCall(function) = expression else {
        return None;
    };
    function_relationships_path_variable(function, context)
}

fn function_relationships_path_variable(
    function: &FunctionInvocation,
    context: &CypherCompileContext,
) -> Option<String> {
    if !is_relationships_function(function) {
        return None;
    }
    context
        .variable_function_argument(function)
        .map(str::to_string)
        .or_else(|| match function.arguments.as_slice() {
            [Expression::Variable(variable)] => Some(variable_name(variable)),
            _ => None,
        })
}

fn compile_multi_part(
    query: &MultiPartQuery,
    context: &CypherCompileContext,
) -> Result<GraphPlan, CoreError> {
    if let Some(plan) = compile_terminal_with_projection(query, context)? {
        return Ok(plan);
    }
    if let Some(plan) = compile_terminal_with_graph_modifiers(query, context)? {
        return Ok(plan);
    }
    compile_transparent_multi_part(query, context)
}

fn compile_terminal_with_projection(
    query: &MultiPartQuery,
    context: &CypherCompileContext,
) -> Result<Option<GraphPlan>, CoreError> {
    let terminal_projection_candidate = query
        .parts
        .iter()
        .any(|part| with_requires_terminal_projection(&part.with));
    if !terminal_projection_candidate {
        return Ok(None);
    }
    if query.parts.len() != 1 || !query.final_part.reading_clauses.is_empty() {
        return Ok(None);
    }
    let [part] = query.parts.as_slice() else {
        return Err(unsupported(
            "query.parts",
            "terminal WITH projections currently support exactly one MATCH ... WITH ... RETURN query part",
        ));
    };
    if !part.updating_clauses.is_empty() {
        return Err(unsupported(
            "parts[0].updating_clauses",
            "write clauses are not supported by Coral virtual graphs",
        ));
    }
    let return_clause = return_clause_from_single_part(&query.final_part, "final_part")?;
    let mut plan = GraphPlan::default();
    let mut state = compile_state_for_multi_part(query, context);
    compile_reading_clauses_into(
        &part.reading_clauses,
        "parts[0].match",
        &mut plan,
        &mut state,
        context,
    )?;

    compile_terminal_with_clause(&part.with, &mut plan, &state, context)?;
    apply_terminal_return_projection_aliases(
        return_clause,
        &mut plan,
        &state,
        context,
        part.with.star,
    )?;
    apply_terminal_return_modifiers(return_clause, &mut plan, context)?;
    reject_ignored_path_variable_references(&plan, &state, "with")?;
    Ok(Some(plan))
}

fn with_requires_terminal_projection(with: &With) -> bool {
    with.items
        .iter()
        .any(|item| !matches!(&item.expression, Expression::Variable(_)))
}

fn compile_terminal_with_graph_modifiers(
    query: &MultiPartQuery,
    context: &CypherCompileContext,
) -> Result<Option<GraphPlan>, CoreError> {
    let terminal_graph_candidate = query
        .parts
        .iter()
        .any(|part| part.with.distinct || with_has_row_modifiers(&part.with));
    if !terminal_graph_candidate {
        return Ok(None);
    }
    let [part] = query.parts.as_slice() else {
        return Err(unsupported(
            "query.parts",
            "terminal graph-variable WITH DISTINCT, ORDER BY, SKIP, and LIMIT currently support exactly one MATCH ... WITH ... RETURN query part",
        ));
    };
    if with_requires_terminal_projection(&part.with) {
        return Ok(None);
    }
    if !part.updating_clauses.is_empty() {
        return Err(unsupported(
            "parts[0].updating_clauses",
            "write clauses are not supported by Coral virtual graphs",
        ));
    }
    if !query.final_part.reading_clauses.is_empty() {
        return Err(unsupported(
            "final_part.reading_clauses",
            "WITH DISTINCT, ORDER BY, SKIP, and LIMIT before another MATCH require staged query planning and are not supported yet",
        ));
    }

    let return_clause = return_clause_from_single_part(&query.final_part, "final_part")?;
    if with_has_row_modifiers(&part.with)
        && (return_clause.order.is_some()
            || return_clause.skip.is_some()
            || return_clause.limit.is_some())
    {
        return Err(unsupported(
            "final_part.return",
            "terminal WITH and RETURN cannot both define ORDER BY, SKIP, or LIMIT without staged query planning",
        ));
    }

    let mut plan = GraphPlan::default();
    let mut state = compile_state_for_multi_part(query, context);
    compile_reading_clauses_into(
        &part.reading_clauses,
        "parts[0].match",
        &mut plan,
        &mut state,
        context,
    )?;
    if let Some(predicate) =
        apply_transparent_with_scope(&part.with, &mut plan, &mut state, "parts[0].with", context)?
    {
        append_predicate_expression(predicate, &mut plan);
    }
    apply_terminal_graph_with_modifiers(&part.with, &mut plan, &state, context)?;
    if part.with.distinct {
        validate_terminal_distinct_graph_return(return_clause, &plan, &state)?;
    }
    compile_return(return_clause, &mut plan, &state, context)?;
    if part.with.distinct {
        plan.distinct = true;
    }
    reject_ignored_path_variable_references(&plan, &state, "return")?;
    Ok(Some(plan))
}

fn with_has_row_modifiers(with: &With) -> bool {
    with.order.is_some() || with.skip.is_some() || with.limit.is_some()
}

fn validate_terminal_distinct_graph_return(
    return_clause: &Return,
    plan: &GraphPlan,
    state: &CypherCompileState,
) -> Result<(), CoreError> {
    if return_clause.star {
        if return_clause.items.is_empty() {
            return Ok(());
        }
        return Err(unsupported(
            "final_part.return.star",
            "RETURN * mixed with explicit projections after WITH DISTINCT requires staged query planning and is not supported yet",
        ));
    }

    let visible = visible_graph_variables(plan, state);
    for (index, item) in return_clause.items.iter().enumerate() {
        let Some(variable) = terminal_return_graph_variable(&item.expression) else {
            return Err(unsupported(
                format!("final_part.return.items[{index}].expression"),
                "terminal WITH DISTINCT over graph variables currently requires RETURN of carried graph variables or RETURN *; scalar projections require staged query planning and are not supported yet",
            ));
        };
        if !visible.contains(&variable) {
            return Err(unsupported(
                format!("final_part.return.items[{index}].expression"),
                format!("terminal RETURN references unknown WITH graph variable '{variable}'"),
            ));
        }
    }
    Ok(())
}

fn terminal_return_graph_variable(expression: &Expression) -> Option<String> {
    match expression {
        Expression::Parenthesized(inner) => terminal_return_graph_variable(inner),
        Expression::Variable(variable) => Some(variable_name(variable)),
        _ => None,
    }
}

fn apply_terminal_graph_with_modifiers(
    with: &With,
    plan: &mut GraphPlan,
    state: &CypherCompileState,
    context: &CypherCompileContext,
) -> Result<(), CoreError> {
    if let Some(order) = &with.order {
        for (index, item) in order.items.iter().enumerate() {
            plan.order_by.push(OrderKey {
                expression: compile_order_expression(
                    &item.expression,
                    &[],
                    plan,
                    state,
                    context,
                    format!("with.order.items[{index}].expression"),
                )?,
                direction: match item.direction {
                    Some(SortDirection::Descending) => OrderDirection::Descending,
                    Some(SortDirection::Ascending) | None => OrderDirection::Ascending,
                },
                nulls: context.order_null_placement(item),
            });
        }
    }
    if let Some(skip) = &with.skip {
        plan.skip = Some(compile_skip(skip, "with.skip", context)?);
    }
    if let Some(limit) = &with.limit {
        plan.limit = Some(compile_limit(limit, "with.limit", context)?);
    }
    Ok(())
}

fn compile_terminal_with_clause(
    with: &With,
    plan: &mut GraphPlan,
    state: &CypherCompileState,
    context: &CypherCompileContext,
) -> Result<(), CoreError> {
    plan.distinct = with.distinct;
    if with.items.is_empty() {
        return Err(unsupported(
            "with.items",
            "WITH must include at least one projection",
        ));
    }

    let mut aliases = BTreeSet::new();
    for (index, item) in with.items.iter().enumerate() {
        let Some(alias) = item.alias.as_ref().map(variable_name) else {
            return Err(unsupported(
                format!("with.items[{index}].alias"),
                "terminal WITH projections require explicit aliases",
            ));
        };
        if !aliases.insert(alias.clone()) {
            return Err(unsupported(
                format!("with.items[{index}].alias"),
                format!("terminal WITH projection alias '{alias}' is defined more than once"),
            ));
        }
        if matches!(&item.expression, Expression::Variable(_)) {
            return Err(unsupported(
                format!("with.items[{index}].expression"),
                "terminal WITH projections support graph properties and aggregates, not graph variable aliases",
            ));
        }
        let projection =
            compile_projection(item, format!("with.items[{index}]"), context, plan, state)?;
        plan.projections.push(projection);
    }
    if let Some(where_clause) = &with.where_clause {
        plan.post_projection_predicate = Some(compile_projection_predicate_expression(
            where_clause,
            "with.where",
            context,
        )?);
    }

    if let Some(order) = &with.order {
        for (index, item) in order.items.iter().enumerate() {
            plan.order_by.push(OrderKey {
                expression: compile_terminal_alias_order_expression(
                    &item.expression,
                    &plan.projections,
                    format!("with.order.items[{index}].expression"),
                )?,
                direction: match item.direction {
                    Some(SortDirection::Descending) => OrderDirection::Descending,
                    Some(SortDirection::Ascending) | None => OrderDirection::Ascending,
                },
                nulls: context.order_null_placement(item),
            });
        }
    }
    if let Some(skip) = &with.skip {
        plan.skip = Some(compile_skip(skip, "with.skip", context)?);
    }
    if let Some(limit) = &with.limit {
        plan.limit = Some(compile_limit(limit, "with.limit", context)?);
    }
    Ok(())
}

fn apply_terminal_return_projection_aliases(
    return_clause: &Return,
    plan: &mut GraphPlan,
    state: &CypherCompileState,
    context: &CypherCompileContext,
    with_star: bool,
) -> Result<(), CoreError> {
    if return_clause.star {
        if return_clause.items.is_empty() {
            if with_star {
                expand_terminal_with_star_return_star(
                    plan,
                    state,
                    context,
                    "final_part.return.star",
                )?;
            }
            return Ok(());
        }
        return Err(unsupported(
            "final_part.return.star",
            "RETURN * mixed with explicit projections after WITH requires scoped query planning and is not supported yet",
        ));
    }
    if return_clause.items.len() != plan.projections.len() {
        return Err(unsupported(
            "final_part.return.items",
            "terminal RETURN after WITH must pass through every WITH alias",
        ));
    }
    let mut reordered = Vec::with_capacity(plan.projections.len());
    let mut available = plan.projections.clone();
    let mut returned_aliases = BTreeSet::new();
    for (index, item) in return_clause.items.iter().enumerate() {
        let Expression::Variable(variable) = &item.expression else {
            return Err(unsupported(
                format!("final_part.return.items[{index}].expression"),
                "terminal RETURN after WITH must project WITH aliases",
            ));
        };
        let alias = variable_name(variable);
        if !returned_aliases.insert(alias.clone()) {
            return Err(unsupported(
                format!("final_part.return.items[{index}].expression"),
                format!("terminal RETURN projects WITH alias '{alias}' more than once"),
            ));
        }
        let position = available
            .iter()
            .position(|projection| projection_output_alias(projection) == Some(alias.as_str()))
            .ok_or_else(|| {
                unsupported(
                    format!("final_part.return.items[{index}].expression"),
                    format!("terminal RETURN references unknown WITH alias '{alias}'"),
                )
            })?;
        let mut projection = available.remove(position);
        if let Some(alias) = &item.alias {
            set_projection_output_alias(&mut projection, variable_name(alias));
        }
        reordered.push(projection);
    }
    plan.projections = reordered;
    Ok(())
}

fn expand_terminal_with_star_return_star(
    plan: &mut GraphPlan,
    state: &CypherCompileState,
    context: &CypherCompileContext,
    path: &str,
) -> Result<(), CoreError> {
    let explicit_projections = std::mem::take(&mut plan.projections);
    if explicit_projections
        .iter()
        .any(terminal_with_star_projection_requires_grouping)
    {
        return Err(unsupported(
            path,
            "RETURN * after WITH * with aggregate aliases requires grouped scoped query planning and is not supported yet",
        ));
    }
    compile_return_star(plan, state, context, path)?;
    for projection in explicit_projections {
        push_unique_terminal_with_star_projection(plan, projection, path)?;
    }
    Ok(())
}

fn terminal_with_star_projection_requires_grouping(projection: &Projection) -> bool {
    matches!(
        projection,
        Projection::CountAll { .. } | Projection::Aggregate { .. }
    )
}

fn push_unique_terminal_with_star_projection(
    plan: &mut GraphPlan,
    projection: Projection,
    path: &str,
) -> Result<(), CoreError> {
    let alias = projection.output_name();
    if plan
        .projections
        .iter()
        .any(|existing| existing.output_name() == alias)
    {
        return Err(unsupported(
            path.to_string(),
            format!("RETURN * expansion produced duplicate output column '{alias}'"),
        ));
    }
    plan.projections.push(projection);
    Ok(())
}

fn set_projection_output_alias(projection: &mut Projection, alias: String) {
    match projection {
        Projection::Property {
            alias: projection_alias,
            ..
        } => *projection_alias = Some(alias),
        Projection::Key {
            alias: projection_alias,
            ..
        }
        | Projection::ElementId {
            alias: projection_alias,
            ..
        }
        | Projection::NodeLabels {
            alias: projection_alias,
            ..
        }
        | Projection::PropertyKeys {
            alias: projection_alias,
            ..
        }
        | Projection::RelationshipType {
            alias: projection_alias,
            ..
        }
        | Projection::Literal {
            alias: projection_alias,
            ..
        }
        | Projection::LiteralList {
            alias: projection_alias,
            ..
        }
        | Projection::Expression {
            alias: projection_alias,
            ..
        }
        | Projection::CountAll {
            alias: projection_alias,
        }
        | Projection::Aggregate {
            alias: projection_alias,
            ..
        } => *projection_alias = alias,
    }
}

fn scalar_alias_names(state: &CypherCompileState) -> BTreeSet<String> {
    state
        .scalar_aliases
        .iter()
        .map(Projection::output_name)
        .collect()
}

fn scalar_alias_projection<'a>(
    state: &'a CypherCompileState,
    alias: &str,
) -> Option<&'a Projection> {
    state
        .scalar_aliases
        .iter()
        .find(|projection| projection.output_name() == alias)
}

fn scalar_alias_projection_expression(
    projection: &Projection,
    path: impl Into<String>,
) -> Result<ScalarExpression, CoreError> {
    let path = path.into();
    match projection {
        Projection::Property { property, .. } => Ok(ScalarExpression::Property(property.clone())),
        Projection::Key { variable, .. } => Ok(ScalarExpression::Key {
            variable: variable.clone(),
        }),
        Projection::ElementId { variable, .. } => Ok(ScalarExpression::ElementId {
            variable: variable.clone(),
        }),
        Projection::RelationshipType {
            variable,
            relationship_type,
            ..
        } => Ok(ScalarExpression::RelationshipType {
            variable: variable.clone(),
            relationship_type: relationship_type.clone(),
        }),
        Projection::NodeLabels {
            variable, label, ..
        } => Ok(ScalarExpression::NodeLabels {
            variable: variable.clone(),
            label: label.clone(),
        }),
        Projection::PropertyKeys { variable, .. } => Ok(ScalarExpression::PropertyKeys {
            variable: variable.clone(),
        }),
        Projection::Literal { literal, .. } => Ok(ScalarExpression::Literal(literal.clone())),
        Projection::LiteralList { literals, .. } => Ok(ScalarExpression::LiteralList {
            literals: literals.clone(),
        }),
        Projection::Expression { expression, .. } => Ok(expression.clone()),
        Projection::CountAll { .. } | Projection::Aggregate { .. } => Err(unsupported(
            path,
            "aggregate WITH aliases require staged query planning and are not supported before another MATCH",
        )),
    }
}

fn expression_variable_name(expression: &Expression) -> Option<String> {
    match expression {
        Expression::Parenthesized(inner) => expression_variable_name(inner),
        Expression::Variable(variable) => Some(variable_name(variable)),
        _ => None,
    }
}

fn compile_optional_scalar_alias_expression(
    expression: &Expression,
    path: impl Into<String>,
    state: Option<&CypherCompileState>,
) -> Result<Option<ScalarExpression>, CoreError> {
    let path = path.into();
    let Some(state) = state else {
        return Ok(None);
    };
    let Some(alias) = expression_variable_name(expression) else {
        return Ok(None);
    };
    let Some(projection) = scalar_alias_projection(state, &alias) else {
        return Ok(None);
    };
    scalar_alias_projection_expression(projection, path).map(Some)
}

fn compile_optional_scalar_alias_return_item(
    item: &ProjectionItem,
    state: &CypherCompileState,
    path: impl Into<String>,
) -> Result<Option<Projection>, CoreError> {
    let path = path.into();
    let Some(alias) = expression_variable_name(&item.expression) else {
        return Ok(None);
    };
    let Some(projection) = scalar_alias_projection(state, &alias) else {
        return Ok(None);
    };
    let mut projection = projection.clone();
    if let Some(alias) = &item.alias {
        set_projection_output_alias(&mut projection, variable_name(alias));
    }
    reject_ignored_path_variable_references_in_projection(&projection, state, path)?;
    Ok(Some(projection))
}

fn apply_terminal_return_modifiers(
    return_clause: &Return,
    plan: &mut GraphPlan,
    context: &CypherCompileContext,
) -> Result<(), CoreError> {
    plan.distinct |= return_clause.distinct;
    if (return_clause.order.is_some()
        || return_clause.skip.is_some()
        || return_clause.limit.is_some())
        && (!plan.order_by.is_empty() || plan.skip.is_some() || plan.limit.is_some())
    {
        return Err(unsupported(
            "final_part.return",
            "terminal WITH and RETURN cannot both define ORDER BY, SKIP, or LIMIT without staged query planning",
        ));
    }
    if let Some(skip) = &return_clause.skip {
        plan.skip = Some(compile_skip(skip, "final_part.return.skip", context)?);
    }
    if let Some(order) = &return_clause.order {
        for (index, item) in order.items.iter().enumerate() {
            plan.order_by.push(OrderKey {
                expression: compile_terminal_alias_order_expression(
                    &item.expression,
                    &plan.projections,
                    format!("final_part.return.order.items[{index}].expression"),
                )?,
                direction: match item.direction {
                    Some(SortDirection::Descending) => OrderDirection::Descending,
                    Some(SortDirection::Ascending) | None => OrderDirection::Ascending,
                },
                nulls: context.order_null_placement(item),
            });
        }
    }
    if let Some(limit) = &return_clause.limit {
        plan.limit = Some(compile_limit(limit, "final_part.return.limit", context)?);
    }
    Ok(())
}

fn compile_terminal_alias_order_expression(
    expression: &Expression,
    projections: &[Projection],
    path: impl Into<String>,
) -> Result<OrderExpression, CoreError> {
    let path = path.into();
    match expression {
        Expression::Parenthesized(inner) => {
            compile_terminal_alias_order_expression(inner, projections, path)
        }
        Expression::Variable(variable) => {
            projection_order_expression_for_alias(variable, projections, path)
        }
        _ => Err(unsupported(
            path,
            "ORDER BY after terminal WITH only supports projected aliases",
        )),
    }
}

fn projection_output_alias(projection: &Projection) -> Option<&str> {
    match projection {
        Projection::Property { alias, .. } => alias.as_deref(),
        Projection::Key { alias, .. }
        | Projection::ElementId { alias, .. }
        | Projection::NodeLabels { alias, .. }
        | Projection::PropertyKeys { alias, .. }
        | Projection::RelationshipType { alias, .. }
        | Projection::Literal { alias, .. }
        | Projection::LiteralList { alias, .. }
        | Projection::Expression { alias, .. }
        | Projection::CountAll { alias }
        | Projection::Aggregate { alias, .. } => Some(alias),
    }
}

fn compile_transparent_multi_part(
    query: &MultiPartQuery,
    context: &CypherCompileContext,
) -> Result<GraphPlan, CoreError> {
    let mut plan = GraphPlan::default();
    let mut state = compile_state_for_multi_part(query, context);
    for (index, part) in query.parts.iter().enumerate() {
        compile_transparent_multi_part_part(part, index, &mut plan, &mut state, context)?;
    }

    match query.final_part.reading_clauses.as_slice() {
        [] => {}
        clauses => {
            compile_reading_clauses_into(
                clauses,
                "final_part.match",
                &mut plan,
                &mut state,
                context,
            )?;
        }
    }
    let return_clause = return_clause_from_single_part(&query.final_part, "final_part")?;
    compile_return(return_clause, &mut plan, &state, context)?;
    reject_ignored_path_variable_references(&plan, &state, "final_part.return")?;
    Ok(plan)
}

fn compile_transparent_multi_part_part(
    part: &MultiPartQueryPart,
    index: usize,
    plan: &mut GraphPlan,
    state: &mut CypherCompileState,
    context: &CypherCompileContext,
) -> Result<(), CoreError> {
    if !part.updating_clauses.is_empty() {
        return Err(unsupported(
            format!("parts[{index}].updating_clauses"),
            "write clauses are not supported by Coral virtual graphs",
        ));
    }
    compile_reading_clauses_into(
        &part.reading_clauses,
        format!("parts[{index}].match"),
        plan,
        state,
        context,
    )?;
    if let Some(predicate) = validate_transparent_with(
        &part.with,
        plan,
        state,
        format!("parts[{index}].with"),
        context,
    )? {
        append_predicate_expression(predicate, plan);
    }
    Ok(())
}

fn validate_transparent_with(
    with: &With,
    plan: &mut GraphPlan,
    state: &mut CypherCompileState,
    path: impl Into<String>,
    context: &CypherCompileContext,
) -> Result<Option<PredicateExpression>, CoreError> {
    let path = path.into();
    if with.distinct {
        return Err(unsupported(
            format!("{path}.distinct"),
            "WITH DISTINCT requires staged query planning and is not supported yet",
        ));
    }
    if with.order.is_some() || with.skip.is_some() || with.limit.is_some() {
        return Err(unsupported(
            path.clone(),
            "WITH ORDER BY, SKIP, and LIMIT require staged query planning and are not supported yet",
        ));
    }
    apply_transparent_with_scope(with, plan, state, path, context)
}

fn apply_transparent_with_scope(
    with: &With,
    plan: &mut GraphPlan,
    state: &mut CypherCompileState,
    path: impl Into<String>,
    context: &CypherCompileContext,
) -> Result<Option<PredicateExpression>, CoreError> {
    let path = path.into();
    if with.star {
        return apply_transparent_with_star_scope(with, plan, state, path, context);
    }
    if with.items.is_empty() {
        return Err(unsupported(
            format!("{path}.items"),
            "WITH must carry every currently bound variable in this transparent subset",
        ));
    }

    let scope = compile_transparent_with_items(with, plan, state, &path, context)?;
    reject_explicit_with_where_path_variable_references(with, state, &scope, &path, context)?;
    let visible = visible_graph_variables(plan, state);
    let dropped_variables = visible
        .difference(&scope.carried_inputs)
        .cloned()
        .collect::<Vec<_>>();
    let mut hidden_renames = BTreeMap::new();
    let mut renames = scope.renames;
    for variable in &dropped_variables {
        let hidden = fresh_hidden_graph_variable(plan, state, variable);
        renames.insert(variable.clone(), hidden.clone());
        hidden_renames.insert(hidden.clone(), hidden);
    }
    let mut next_scalar_aliases = scope.scalar_aliases;
    if renames.iter().any(|(from, to)| from != to) {
        rename_graph_plan_variables(plan, &renames);
        rename_hidden_graph_variables(state, &renames);
        for projection in &mut next_scalar_aliases {
            rename_projection_variables(projection, &renames);
        }
    }
    state
        .hidden_graph_variables
        .extend(hidden_renames.into_values());
    state.out_of_scope_graph_names.extend(dropped_variables);
    for variable in scope.carried_graph_outputs {
        state.out_of_scope_graph_names.remove(&variable);
    }
    state.scalar_aliases = next_scalar_aliases;

    let mut predicate_state = state.clone();
    predicate_state.path_variables.clear();
    let predicate =
        compile_transparent_with_where(with, plan, Some(&predicate_state), path.clone(), context)?;
    reject_ignored_path_variable_references(plan, state, &path)?;
    if let Some(predicate) = predicate.as_ref() {
        reject_ignored_path_variable_references_in_predicate(
            predicate,
            state,
            format!("{path}.where"),
        )?;
    }
    state.path_variables.clear();
    Ok(predicate)
}

fn apply_transparent_with_star_scope(
    with: &With,
    plan: &GraphPlan,
    state: &mut CypherCompileState,
    path: String,
    context: &CypherCompileContext,
) -> Result<Option<PredicateExpression>, CoreError> {
    let aliases = compile_transparent_with_star_scalar_aliases(with, plan, state, &path, context)?;
    state.scalar_aliases.extend(aliases);
    compile_transparent_with_where(with, plan, Some(state), path, context)
}

#[derive(Default)]
struct TransparentWithScopePlan {
    carried_inputs: BTreeSet<String>,
    carried_outputs: BTreeSet<String>,
    carried_graph_outputs: BTreeSet<String>,
    scalar_aliases: Vec<Projection>,
    renames: BTreeMap<String, String>,
}

fn compile_transparent_with_items(
    with: &With,
    plan: &GraphPlan,
    state: &CypherCompileState,
    path: &str,
    context: &CypherCompileContext,
) -> Result<TransparentWithScopePlan, CoreError> {
    let visible = visible_graph_variables(plan, state);
    let mut scope = TransparentWithScopePlan::default();
    for (index, item) in with.items.iter().enumerate() {
        if compile_transparent_with_variable_item(item, index, path, state, &visible, &mut scope)? {
            continue;
        }
        let projection = compile_transparent_with_scalar_alias(
            item,
            format!("{path}.items[{index}]"),
            plan,
            state,
            context,
        )?;
        push_transparent_with_scalar_alias(&mut scope, projection, path, index)?;
    }
    Ok(scope)
}

fn compile_transparent_with_star_scalar_aliases(
    with: &With,
    plan: &GraphPlan,
    state: &CypherCompileState,
    path: &str,
    context: &CypherCompileContext,
) -> Result<Vec<Projection>, CoreError> {
    let visible = visible_graph_variables(plan, state);
    let mut outputs = transparent_with_star_output_names(plan, state);
    let mut aliases = Vec::new();

    for (index, item) in with.items.iter().enumerate() {
        if let Some(variable) = expression_variable_name(&item.expression)
            && visible.contains(&variable)
        {
            return Err(unsupported(
                format!("{path}.items[{index}].expression"),
                "WITH * plus explicit graph-variable aliases requires graph-value aliasing and is not supported yet",
            ));
        }
        let projection = compile_transparent_with_star_scalar_alias(
            item,
            format!("{path}.items[{index}]"),
            plan,
            state,
            context,
        )?;
        let output = projection.output_name();
        if !outputs.insert(output.clone()) {
            return Err(unsupported(
                format!("{path}.items[{index}].alias"),
                format!("WITH * output variable '{output}' is already in scope"),
            ));
        }
        aliases.push(projection);
    }
    Ok(aliases)
}

fn transparent_with_star_output_names(
    plan: &GraphPlan,
    state: &CypherCompileState,
) -> BTreeSet<String> {
    let mut outputs = visible_graph_variables(plan, state);
    outputs.extend(state.path_variables.keys().cloned());
    outputs.extend(state.scalar_aliases.iter().map(Projection::output_name));
    outputs
}

fn compile_transparent_with_star_scalar_alias(
    item: &ProjectionItem,
    path: impl Into<String>,
    plan: &GraphPlan,
    state: &CypherCompileState,
    context: &CypherCompileContext,
) -> Result<Projection, CoreError> {
    let path = path.into();
    if let Some(input) = expression_variable_name(&item.expression)
        && let Some(projection) = scalar_alias_projection(state, &input)
    {
        let Some(alias) = item.alias.as_ref().map(validate_variable).transpose()? else {
            return Err(unsupported(
                format!("{path}.alias"),
                "WITH * explicit scalar alias copies require a new alias",
            ));
        };
        let mut projection = projection.clone();
        set_projection_output_alias(&mut projection, alias);
        return Ok(projection);
    }

    compile_transparent_with_scalar_alias(item, path, plan, state, context)
}

fn reject_explicit_with_where_path_variable_references(
    with: &With,
    state: &CypherCompileState,
    scope: &TransparentWithScopePlan,
    path: &str,
    context: &CypherCompileContext,
) -> Result<(), CoreError> {
    let Some(where_clause) = &with.where_clause else {
        return Ok(());
    };
    if state.path_variables.is_empty() {
        return Ok(());
    }

    let mut variables = BTreeSet::new();
    expression_variables(where_clause, &mut variables);
    recovered_function_argument_variables(where_clause, context, &mut variables);
    if let Some(variable) = variables.iter().find(|variable| {
        state.path_variables.contains_key(variable.as_str())
            && !scope.carried_outputs.contains(variable.as_str())
    }) {
        return Err(unsupported(
            format!("{path}.where"),
            format!(
                "path variable '{variable}' is not in scope after WITH because Coral does not materialize path values yet"
            ),
        ));
    }
    Ok(())
}

fn recovered_function_argument_variables(
    expression: &Expression,
    context: &CypherCompileContext,
    variables: &mut BTreeSet<String>,
) {
    match expression {
        Expression::Parenthesized(inner) => {
            recovered_function_argument_variables(inner, context, variables);
        }
        Expression::UnaryOp { operand, .. } | Expression::IsNull { operand, .. } => {
            recovered_function_argument_variables(operand, context, variables);
        }
        Expression::BinaryOp { lhs, rhs, .. } | Expression::In { lhs, rhs, .. } => {
            recovered_function_argument_variables(lhs, context, variables);
            recovered_function_argument_variables(rhs, context, variables);
        }
        Expression::Comparison { lhs, operators, .. } => {
            recovered_function_argument_variables(lhs, context, variables);
            for (_, rhs) in operators {
                recovered_function_argument_variables(rhs, context, variables);
            }
        }
        Expression::ListIndex { list, index, .. } => {
            recovered_function_argument_variables(list, context, variables);
            recovered_function_argument_variables(index, context, variables);
        }
        Expression::ListSlice {
            list, start, end, ..
        } => {
            recovered_function_argument_variables(list, context, variables);
            if let Some(start) = start.as_deref() {
                recovered_function_argument_variables(start, context, variables);
            }
            if let Some(end) = end.as_deref() {
                recovered_function_argument_variables(end, context, variables);
            }
        }
        Expression::Case(case) => {
            if let Some(scrutinee) = case.scrutinee.as_deref() {
                recovered_function_argument_variables(scrutinee, context, variables);
            }
            for alternative in &case.alternatives {
                recovered_function_argument_variables(&alternative.when, context, variables);
                recovered_function_argument_variables(&alternative.then, context, variables);
            }
            if let Some(default) = case.default.as_deref() {
                recovered_function_argument_variables(default, context, variables);
            }
        }
        Expression::FunctionCall(function) => {
            if let Some(variable) = context.variable_function_argument(function) {
                variables.insert(variable.to_string());
            }
            for argument in &function.arguments {
                recovered_function_argument_variables(argument, context, variables);
            }
        }
        Expression::ListComprehension(comprehension) => {
            if let Some(filter) = comprehension.filter.as_deref() {
                recovered_function_argument_variables(filter, context, variables);
            }
            if let Some(map) = comprehension.map.as_ref() {
                recovered_function_argument_variables(map, context, variables);
            }
        }
        Expression::PatternComprehension(comprehension) => {
            if let Some(where_clause) = comprehension.where_clause.as_ref() {
                recovered_function_argument_variables(where_clause, context, variables);
            }
            recovered_function_argument_variables(&comprehension.map, context, variables);
        }
        Expression::All(filter)
        | Expression::Any(filter)
        | Expression::None(filter)
        | Expression::Single(filter) => {
            recovered_function_argument_variables(&filter.collection, context, variables);
            if let Some(predicate) = filter.predicate.as_deref() {
                recovered_function_argument_variables(predicate, context, variables);
            }
        }
        Expression::Literal(_)
        | Expression::Variable(_)
        | Expression::Parameter(_)
        | Expression::CountStar { .. }
        | Expression::PropertyLookup { .. }
        | Expression::NodeLabels { .. }
        | Expression::Pattern(_)
        | Expression::Exists(_)
        | Expression::CountSubquery(_)
        | Expression::CollectSubquery(_)
        | Expression::MapProjection(_) => {}
    }
}

fn compile_transparent_with_variable_item(
    item: &ProjectionItem,
    index: usize,
    path: &str,
    state: &CypherCompileState,
    visible: &BTreeSet<String>,
    scope: &mut TransparentWithScopePlan,
) -> Result<bool, CoreError> {
    let Expression::Variable(variable) = &item.expression else {
        return Ok(false);
    };
    let input = variable_name(variable);
    if visible.contains(&input) {
        push_transparent_with_graph_variable(item, index, path, input, scope)?;
        return Ok(true);
    }
    if let Some(projection) = scalar_alias_projection(state, &input) {
        let output = item
            .alias
            .as_ref()
            .map(validate_variable)
            .transpose()?
            .unwrap_or_else(|| input.clone());
        push_transparent_with_output_name(scope, &output, path, index)?;
        let mut projection = projection.clone();
        set_projection_output_alias(&mut projection, output);
        scope.scalar_aliases.push(projection);
        return Ok(true);
    }
    Err(unsupported(
        format!("{path}.items[{index}].expression"),
        format!(
            "WITH can only carry visible graph variables or scalar aliases; '{input}' is not in scope"
        ),
    ))
}

fn push_transparent_with_graph_variable(
    item: &ProjectionItem,
    index: usize,
    path: &str,
    input: String,
    scope: &mut TransparentWithScopePlan,
) -> Result<(), CoreError> {
    let output = item
        .alias
        .as_ref()
        .map(validate_variable)
        .transpose()?
        .unwrap_or_else(|| input.clone());
    if !scope.carried_inputs.insert(input.clone()) {
        return Err(unsupported(
            format!("{path}.items[{index}].expression"),
            format!("WITH carries graph variable '{input}' more than once"),
        ));
    }
    push_transparent_with_output_name(scope, &output, path, index)?;
    scope.carried_graph_outputs.insert(output.clone());
    scope.renames.insert(input, output);
    Ok(())
}

fn push_transparent_with_scalar_alias(
    scope: &mut TransparentWithScopePlan,
    projection: Projection,
    path: &str,
    index: usize,
) -> Result<(), CoreError> {
    let output = projection.output_name();
    push_transparent_with_output_name(scope, &output, path, index)?;
    scope.scalar_aliases.push(projection);
    Ok(())
}

fn push_transparent_with_output_name(
    scope: &mut TransparentWithScopePlan,
    output: &str,
    path: &str,
    index: usize,
) -> Result<(), CoreError> {
    if !scope.carried_outputs.insert(output.to_string()) {
        return Err(unsupported(
            format!("{path}.items[{index}].alias"),
            format!("WITH output variable '{output}' is defined more than once"),
        ));
    }
    Ok(())
}

fn compile_transparent_with_scalar_alias(
    item: &ProjectionItem,
    path: impl Into<String>,
    plan: &GraphPlan,
    state: &CypherCompileState,
    context: &CypherCompileContext,
) -> Result<Projection, CoreError> {
    let path = path.into();
    let Some(alias) = item.alias.as_ref().map(validate_variable).transpose()? else {
        return Err(unsupported(
            format!("{path}.alias"),
            "non-terminal WITH scalar aliases require explicit aliases",
        ));
    };
    if expression_contains_aggregate(&item.expression) {
        return Err(unsupported(
            format!("{path}.expression"),
            "aggregate WITH aliases require staged query planning and are not supported before another MATCH",
        ));
    }
    if expression_contains_subquery(&item.expression) {
        return Err(unsupported(
            format!("{path}.expression"),
            "subquery WITH aliases require staged query planning and are not supported before another MATCH",
        ));
    }
    let mut projection = compile_projection(item, path.clone(), context, plan, state)?;
    set_projection_output_alias(&mut projection, alias);
    if projection.is_aggregate() {
        return Err(unsupported(
            format!("{path}.expression"),
            "aggregate WITH aliases require staged query planning and are not supported before another MATCH",
        ));
    }
    if projection_contains_correlated_subquery(&projection) {
        return Err(unsupported(
            format!("{path}.expression"),
            "subquery WITH aliases require staged query planning and are not supported before another MATCH",
        ));
    }
    reject_ignored_path_variable_references_in_projection(&projection, state, path)?;
    Ok(projection)
}

fn projection_contains_correlated_subquery(projection: &Projection) -> bool {
    match projection {
        Projection::Expression { expression, .. } => {
            scalar_expression_contains_correlated_subquery(expression)
        }
        Projection::Aggregate { target, .. } => {
            aggregate_target_contains_correlated_subquery(target)
        }
        Projection::Property { .. }
        | Projection::Key { .. }
        | Projection::ElementId { .. }
        | Projection::RelationshipType { .. }
        | Projection::NodeLabels { .. }
        | Projection::PropertyKeys { .. }
        | Projection::Literal { .. }
        | Projection::LiteralList { .. }
        | Projection::CountAll { .. } => false,
    }
}

fn aggregate_target_contains_correlated_subquery(target: &AggregateTarget) -> bool {
    matches!(target, AggregateTarget::Expression(expression) if scalar_expression_contains_correlated_subquery(expression))
}

fn compile_transparent_with_where(
    with: &With,
    plan: &GraphPlan,
    path_state: Option<&CypherCompileState>,
    path: impl Into<String>,
    context: &CypherCompileContext,
) -> Result<Option<PredicateExpression>, CoreError> {
    let path = path.into();
    with.where_clause
        .as_ref()
        .map(|where_clause| {
            compile_predicate_expression_with_path_state(
                where_clause,
                format!("{path}.where"),
                plan,
                path_state,
                context,
            )
        })
        .transpose()
}

fn bound_graph_variables(plan: &GraphPlan) -> BTreeSet<String> {
    plan.nodes
        .iter()
        .map(|node| node.variable.clone())
        .chain(
            plan.relationships
                .iter()
                .filter_map(|relationship| relationship.variable.clone()),
        )
        .collect()
}

fn visible_graph_variables(plan: &GraphPlan, state: &CypherCompileState) -> BTreeSet<String> {
    bound_graph_variables(plan)
        .difference(&state.hidden_graph_variables)
        .cloned()
        .collect()
}

fn rename_hidden_graph_variables(
    state: &mut CypherCompileState,
    renames: &BTreeMap<String, String>,
) {
    state.hidden_graph_variables = state
        .hidden_graph_variables
        .iter()
        .map(|variable| renames.get(variable).unwrap_or(variable).clone())
        .collect();
}

fn rename_graph_plan_variables(plan: &mut GraphPlan, renames: &BTreeMap<String, String>) {
    for node in &mut plan.nodes {
        rename_string(&mut node.variable, renames);
    }
    for relationship in &mut plan.relationships {
        if let Some(variable) = &mut relationship.variable {
            rename_string(variable, renames);
        }
        rename_string(&mut relationship.left, renames);
        rename_string(&mut relationship.right, renames);
    }
    for projection in &mut plan.projections {
        rename_projection_variables(projection, renames);
    }
    for predicate in &mut plan.predicates {
        rename_property_predicate_variables(predicate, renames);
    }
    if let Some(predicate) = &mut plan.predicate {
        rename_predicate_expression_variables(predicate, renames);
    }
    for optional_match in &mut plan.optional_matches {
        if let Some(predicate) = &mut optional_match.predicate {
            rename_predicate_expression_variables(predicate, renames);
        }
    }
    for order_key in &mut plan.order_by {
        rename_order_expression_variables(&mut order_key.expression, renames);
    }
}

fn rename_projection_variables(projection: &mut Projection, renames: &BTreeMap<String, String>) {
    match projection {
        Projection::Property { property, .. } => rename_property_ref_variables(property, renames),
        Projection::Key { variable, .. }
        | Projection::ElementId { variable, .. }
        | Projection::RelationshipType { variable, .. }
        | Projection::NodeLabels { variable, .. }
        | Projection::PropertyKeys { variable, .. } => rename_string(variable, renames),
        Projection::Expression { expression, .. } => {
            rename_scalar_expression_variables(expression, renames);
        }
        Projection::Aggregate { target, .. } => rename_aggregate_target_variables(target, renames),
        Projection::Literal { .. }
        | Projection::LiteralList { .. }
        | Projection::CountAll { .. } => {}
    }
}

fn rename_aggregate_target_variables(
    target: &mut AggregateTarget,
    renames: &BTreeMap<String, String>,
) {
    match target {
        AggregateTarget::Property(property) => rename_property_ref_variables(property, renames),
        AggregateTarget::PresenceGatedProperty {
            property,
            presence_variable,
        } => {
            rename_property_ref_variables(property, renames);
            rename_string(presence_variable, renames);
        }
        AggregateTarget::Expression(expression) => {
            rename_scalar_expression_variables(expression, renames);
        }
        AggregateTarget::VariableKey { variable } => rename_string(variable, renames),
        AggregateTarget::PresenceGatedVariableKey {
            variable,
            presence_variable,
        } => {
            rename_string(variable, renames);
            rename_string(presence_variable, renames);
        }
    }
}

fn rename_order_expression_variables(
    expression: &mut OrderExpression,
    renames: &BTreeMap<String, String>,
) {
    match expression {
        OrderExpression::Property(property) => rename_property_ref_variables(property, renames),
        OrderExpression::Key { variable }
        | OrderExpression::ElementId { variable }
        | OrderExpression::RelationshipType { variable, .. }
        | OrderExpression::NodeLabels { variable, .. }
        | OrderExpression::PropertyKeys { variable } => rename_string(variable, renames),
        OrderExpression::Aggregate { target, .. } => {
            rename_aggregate_target_variables(target, renames);
        }
        OrderExpression::Scalar(expression) => {
            rename_scalar_expression_variables(expression, renames);
        }
        OrderExpression::CountAll
        | OrderExpression::Literal(_)
        | OrderExpression::ProjectionAlias(_) => {}
    }
}

fn rename_predicate_expression_variables(
    expression: &mut PredicateExpression,
    renames: &BTreeMap<String, String>,
) {
    match expression {
        PredicateExpression::Boolean(_) => {}
        PredicateExpression::Comparison(predicate) => {
            rename_property_predicate_variables(predicate, renames);
        }
        PredicateExpression::KeyComparison(predicate) => {
            rename_string(&mut predicate.variable, renames);
            rename_predicate_rhs_variables(&mut predicate.rhs, renames);
        }
        PredicateExpression::ElementIdComparison(predicate) => {
            rename_string(&mut predicate.variable, renames);
            rename_predicate_rhs_variables(&mut predicate.rhs, renames);
        }
        PredicateExpression::Presence(predicate) => {
            rename_string(&mut predicate.variable, renames);
        }
        PredicateExpression::PropertyKeyMembership(predicate) => {
            rename_string(&mut predicate.variable, renames);
        }
        PredicateExpression::ExistsPattern(predicate) => {
            for node in &mut predicate.nodes {
                rename_string(&mut node.variable, renames);
            }
            for relationship in &mut predicate.relationships {
                if let Some(variable) = &mut relationship.variable {
                    rename_string(variable, renames);
                }
                rename_string(&mut relationship.left, renames);
                rename_string(&mut relationship.right, renames);
            }
            for predicate in &mut predicate.predicates {
                rename_property_predicate_variables(predicate, renames);
            }
            if let Some(predicate) = &mut predicate.predicate {
                rename_predicate_expression_variables(predicate, renames);
            }
        }
        PredicateExpression::ScalarComparison(predicate) => {
            rename_scalar_expression_variables(&mut predicate.lhs, renames);
            rename_scalar_predicate_rhs_variables(&mut predicate.rhs, renames);
        }
        PredicateExpression::And { left, right }
        | PredicateExpression::Or { left, right }
        | PredicateExpression::Xor { left, right } => {
            rename_predicate_expression_variables(left, renames);
            rename_predicate_expression_variables(right, renames);
        }
        PredicateExpression::Not { expression } => {
            rename_predicate_expression_variables(expression, renames);
        }
    }
}

fn rename_property_predicate_variables(
    predicate: &mut PropertyPredicate,
    renames: &BTreeMap<String, String>,
) {
    rename_property_ref_variables(&mut predicate.property, renames);
    rename_predicate_rhs_variables(&mut predicate.rhs, renames);
}

fn rename_predicate_rhs_variables(rhs: &mut PredicateRhs, renames: &BTreeMap<String, String>) {
    match rhs {
        PredicateRhs::Property(property) => rename_property_ref_variables(property, renames),
        PredicateRhs::Key { variable } | PredicateRhs::ElementId { variable } => {
            rename_string(variable, renames);
        }
        PredicateRhs::Literal(_) | PredicateRhs::List(_) => {}
    }
}

fn rename_scalar_predicate_rhs_variables(
    rhs: &mut ScalarPredicateRhs,
    renames: &BTreeMap<String, String>,
) {
    match rhs {
        ScalarPredicateRhs::Expression(expression) => {
            rename_scalar_expression_variables(expression, renames);
        }
        ScalarPredicateRhs::List(_) => {}
    }
}

fn rename_scalar_expression_variables(
    expression: &mut ScalarExpression,
    renames: &BTreeMap<String, String>,
) {
    if let Some(expression) = unary_scalar_expression_operand_mut(expression) {
        rename_scalar_expression_variables(expression, renames);
        return;
    }

    rename_non_unary_scalar_expression_variables(expression, renames);
}

fn rename_non_unary_scalar_expression_variables(
    expression: &mut ScalarExpression,
    renames: &BTreeMap<String, String>,
) {
    if let Some((left, right)) = binary_scalar_expression_operands_mut(expression) {
        rename_scalar_expression_variables(left, renames);
        rename_scalar_expression_variables(right, renames);
        return;
    }

    match expression {
        ScalarExpression::Property(property) => rename_property_ref_variables(property, renames),
        ScalarExpression::UndirectedEndpointProperty { relationship, .. }
        | ScalarExpression::UndirectedEndpointKey { relationship, .. }
        | ScalarExpression::UndirectedEndpointElementId { relationship, .. }
        | ScalarExpression::UndirectedEndpointLabels { relationship, .. }
        | ScalarExpression::UndirectedEndpointPropertyKeys { relationship, .. } => {
            rename_string(relationship, renames);
        }
        ScalarExpression::Literal(_)
        | ScalarExpression::LiteralList { .. }
        | ScalarExpression::TypedLiteralList { .. } => {}
        ScalarExpression::Predicate(predicate) => {
            rename_predicate_expression_variables(predicate, renames);
        }
        ScalarExpression::Key { variable }
        | ScalarExpression::ElementId { variable }
        | ScalarExpression::GraphIdentity { variable }
        | ScalarExpression::GraphPresence { variable }
        | ScalarExpression::PropertyKeys { variable }
        | ScalarExpression::RelationshipType { variable, .. }
        | ScalarExpression::NodeLabels { variable, .. } => {
            rename_string(variable, renames);
        }
        ScalarExpression::PresenceGated {
            presence_variable,
            expression,
        } => {
            rename_string(presence_variable, renames);
            rename_scalar_expression_variables(expression, renames);
        }
        ScalarExpression::Coalesce { expressions } => {
            rename_scalar_expression_list_variables(expressions, renames);
        }
        ScalarExpression::Round { expression, places } => {
            rename_scalar_expression_variables(expression, renames);
            if let Some(places) = places {
                rename_scalar_expression_variables(places, renames);
            }
        }
        ScalarExpression::Replace {
            expression,
            search,
            replacement,
        } => {
            rename_scalar_expression_variables(expression, renames);
            rename_scalar_expression_variables(search, renames);
            rename_scalar_expression_variables(replacement, renames);
        }
        ScalarExpression::Substring {
            expression,
            start,
            length,
        } => {
            rename_scalar_expression_variables(expression, renames);
            rename_scalar_expression_variables(start, renames);
            if let Some(length) = length {
                rename_scalar_expression_variables(length, renames);
            }
        }
        ScalarExpression::Case {
            alternatives,
            else_expression,
        } => {
            rename_case_expression_variables(alternatives, else_expression.as_deref_mut(), renames);
        }
        _ => {
            unreachable!("unary scalar expressions handled before structural rename")
        }
    }
}

fn binary_scalar_expression_operands_mut(
    expression: &mut ScalarExpression,
) -> Option<(&mut ScalarExpression, &mut ScalarExpression)> {
    match expression {
        ScalarExpression::NullIf { expression, value } => Some((expression, value)),
        ScalarExpression::Left { expression, count }
        | ScalarExpression::Right { expression, count } => Some((expression, count)),
        ScalarExpression::StringContains {
            expression,
            pattern,
        }
        | ScalarExpression::StringStartsWith {
            expression,
            pattern,
        }
        | ScalarExpression::StringEndsWith {
            expression,
            pattern,
        } => Some((expression, pattern)),
        ScalarExpression::Arithmetic { left, right, .. } => Some((left, right)),
        ScalarExpression::Atan2 { y, x } => Some((y, x)),
        _ => None,
    }
}

fn rename_scalar_expression_list_variables(
    expressions: &mut [ScalarExpression],
    renames: &BTreeMap<String, String>,
) {
    for expression in expressions {
        rename_scalar_expression_variables(expression, renames);
    }
}

fn rename_case_expression_variables(
    alternatives: &mut [ScalarCaseAlternative],
    else_expression: Option<&mut ScalarExpression>,
    renames: &BTreeMap<String, String>,
) {
    for alternative in alternatives {
        rename_predicate_expression_variables(&mut alternative.when, renames);
        rename_scalar_expression_variables(&mut alternative.then, renames);
    }
    if let Some(else_expression) = else_expression {
        rename_scalar_expression_variables(else_expression, renames);
    }
}

fn unary_scalar_expression_operand_mut(
    expression: &mut ScalarExpression,
) -> Option<&mut ScalarExpression> {
    match expression {
        ScalarExpression::ToString { expression }
        | ScalarExpression::ToInteger { expression }
        | ScalarExpression::ToFloat { expression }
        | ScalarExpression::ToBoolean { expression }
        | ScalarExpression::ToStringOrNull { expression }
        | ScalarExpression::ToIntegerOrNull { expression }
        | ScalarExpression::ToFloatOrNull { expression }
        | ScalarExpression::ToBooleanOrNull { expression }
        | ScalarExpression::ToLower { expression }
        | ScalarExpression::ToUpper { expression }
        | ScalarExpression::Trim { expression }
        | ScalarExpression::LTrim { expression }
        | ScalarExpression::RTrim { expression }
        | ScalarExpression::CharacterLength { expression }
        | ScalarExpression::Reverse { expression }
        | ScalarExpression::Abs { expression }
        | ScalarExpression::Ceil { expression }
        | ScalarExpression::Floor { expression }
        | ScalarExpression::Sqrt { expression }
        | ScalarExpression::Sign { expression }
        | ScalarExpression::Exp { expression }
        | ScalarExpression::Log { expression }
        | ScalarExpression::Log10 { expression }
        | ScalarExpression::Sin { expression }
        | ScalarExpression::Cos { expression }
        | ScalarExpression::Tan { expression }
        | ScalarExpression::Cot { expression }
        | ScalarExpression::Asin { expression }
        | ScalarExpression::Acos { expression }
        | ScalarExpression::Atan { expression }
        | ScalarExpression::Degrees { expression }
        | ScalarExpression::Radians { expression }
        | ScalarExpression::Negate { expression } => Some(expression),
        _ => None,
    }
}

fn rename_property_ref_variables(property: &mut PropertyRef, renames: &BTreeMap<String, String>) {
    rename_string(&mut property.variable, renames);
}

fn rename_string(value: &mut String, renames: &BTreeMap<String, String>) {
    if let Some(replacement) = renames.get(value.as_str()) {
        *value = replacement.clone();
    }
}

fn reject_ignored_path_variable_references(
    plan: &GraphPlan,
    state: &CypherCompileState,
    path: impl Into<String>,
) -> Result<(), CoreError> {
    let path = path.into();
    if state.path_variables.is_empty() && state.out_of_scope_graph_names.is_empty() {
        return Ok(());
    }
    for (index, projection) in plan.projections.iter().enumerate() {
        reject_ignored_path_variable_references_in_projection(
            projection,
            state,
            format!("{path}.projections[{index}]"),
        )?;
    }
    for (index, predicate) in plan.predicates.iter().enumerate() {
        reject_ignored_path_variable_references_in_property_predicate(
            predicate,
            state,
            format!("{path}.predicates[{index}]"),
        )?;
    }
    if let Some(predicate) = &plan.predicate {
        reject_ignored_path_variable_references_in_predicate(
            predicate,
            state,
            format!("{path}.predicate"),
        )?;
    }
    for (index, optional_match) in plan.optional_matches.iter().enumerate() {
        if let Some(predicate) = &optional_match.predicate {
            reject_ignored_path_variable_references_in_predicate(
                predicate,
                state,
                format!("{path}.optional_matches[{index}].predicate"),
            )?;
        }
    }
    for (index, order_key) in plan.order_by.iter().enumerate() {
        reject_ignored_path_variable_references_in_order_expression(
            &order_key.expression,
            state,
            format!("{path}.order_by[{index}]"),
        )?;
    }
    Ok(())
}

fn reject_ignored_path_variable_references_in_projection(
    projection: &Projection,
    state: &CypherCompileState,
    path: impl Into<String>,
) -> Result<(), CoreError> {
    let path = path.into();
    match projection {
        Projection::Property { property, .. } => {
            reject_ignored_path_variable_property_ref(property, state, path)
        }
        Projection::Key { variable, .. }
        | Projection::ElementId { variable, .. }
        | Projection::RelationshipType { variable, .. }
        | Projection::NodeLabels { variable, .. }
        | Projection::PropertyKeys { variable, .. } => {
            reject_ignored_path_variable(variable, state, path)
        }
        Projection::Expression { expression, .. } => {
            reject_ignored_path_variable_references_in_scalar_expression(expression, state, path)
        }
        Projection::Aggregate { target, .. } => {
            reject_ignored_path_variable_references_in_aggregate_target(target, state, path)
        }
        Projection::Literal { .. }
        | Projection::LiteralList { .. }
        | Projection::CountAll { .. } => Ok(()),
    }
}

fn reject_ignored_path_variable_references_in_aggregate_target(
    target: &AggregateTarget,
    state: &CypherCompileState,
    path: impl Into<String>,
) -> Result<(), CoreError> {
    let path = path.into();
    match target {
        AggregateTarget::Property(property) => {
            reject_ignored_path_variable_property_ref(property, state, path)
        }
        AggregateTarget::PresenceGatedProperty {
            property,
            presence_variable,
        } => {
            reject_ignored_path_variable_property_ref(property, state, format!("{path}.property"))?;
            reject_ignored_path_variable(
                presence_variable,
                state,
                format!("{path}.presence_variable"),
            )
        }
        AggregateTarget::Expression(expression) => {
            reject_ignored_path_variable_references_in_scalar_expression(expression, state, path)
        }
        AggregateTarget::VariableKey { variable } => {
            reject_ignored_path_variable(variable, state, path)
        }
        AggregateTarget::PresenceGatedVariableKey {
            variable,
            presence_variable,
        } => {
            reject_ignored_path_variable(variable, state, format!("{path}.variable"))?;
            reject_ignored_path_variable(
                presence_variable,
                state,
                format!("{path}.presence_variable"),
            )
        }
    }
}

fn reject_ignored_path_variable_references_in_order_expression(
    expression: &OrderExpression,
    state: &CypherCompileState,
    path: impl Into<String>,
) -> Result<(), CoreError> {
    let path = path.into();
    match expression {
        OrderExpression::Property(property) => {
            reject_ignored_path_variable_property_ref(property, state, path)
        }
        OrderExpression::Key { variable }
        | OrderExpression::ElementId { variable }
        | OrderExpression::RelationshipType { variable, .. }
        | OrderExpression::NodeLabels { variable, .. }
        | OrderExpression::PropertyKeys { variable } => {
            reject_ignored_path_variable(variable, state, path)
        }
        OrderExpression::Aggregate { target, .. } => {
            reject_ignored_path_variable_references_in_aggregate_target(target, state, path)
        }
        OrderExpression::Scalar(expression) => {
            reject_ignored_path_variable_references_in_scalar_expression(expression, state, path)
        }
        OrderExpression::CountAll
        | OrderExpression::Literal(_)
        | OrderExpression::ProjectionAlias(_) => Ok(()),
    }
}

fn reject_ignored_path_variable_references_in_predicate(
    expression: &PredicateExpression,
    state: &CypherCompileState,
    path: impl Into<String>,
) -> Result<(), CoreError> {
    let path = path.into();
    match expression {
        PredicateExpression::Boolean(_) => Ok(()),
        PredicateExpression::Comparison(predicate) => {
            reject_ignored_path_variable_references_in_property_predicate(predicate, state, path)
        }
        PredicateExpression::KeyComparison(predicate) => {
            reject_ignored_path_variable(&predicate.variable, state, format!("{path}.variable"))?;
            reject_ignored_path_variable_references_in_predicate_rhs(
                &predicate.rhs,
                state,
                format!("{path}.rhs"),
            )
        }
        PredicateExpression::ElementIdComparison(predicate) => {
            reject_ignored_path_variable(&predicate.variable, state, format!("{path}.variable"))?;
            reject_ignored_path_variable_references_in_predicate_rhs(
                &predicate.rhs,
                state,
                format!("{path}.rhs"),
            )
        }
        PredicateExpression::Presence(predicate) => {
            reject_ignored_path_variable(&predicate.variable, state, format!("{path}.variable"))
        }
        PredicateExpression::PropertyKeyMembership(predicate) => {
            reject_ignored_path_variable(&predicate.variable, state, format!("{path}.variable"))
        }
        PredicateExpression::ExistsPattern(predicate) => {
            for (index, node) in predicate.nodes.iter().enumerate() {
                reject_ignored_path_variable(
                    &node.variable,
                    state,
                    format!("{path}.nodes[{index}].variable"),
                )?;
            }
            for (index, relationship) in predicate.relationships.iter().enumerate() {
                if let Some(variable) = &relationship.variable {
                    reject_ignored_path_variable(
                        variable,
                        state,
                        format!("{path}.relationships[{index}].variable"),
                    )?;
                }
                reject_ignored_path_variable(
                    &relationship.left,
                    state,
                    format!("{path}.relationships[{index}].left"),
                )?;
                reject_ignored_path_variable(
                    &relationship.right,
                    state,
                    format!("{path}.relationships[{index}].right"),
                )?;
            }
            for (index, predicate) in predicate.predicates.iter().enumerate() {
                reject_ignored_path_variable_references_in_property_predicate(
                    predicate,
                    state,
                    format!("{path}.predicates[{index}]"),
                )?;
            }
            Ok(())
        }
        PredicateExpression::ScalarComparison(predicate) => {
            reject_ignored_path_variable_references_in_scalar_expression(
                &predicate.lhs,
                state,
                format!("{path}.lhs"),
            )?;
            reject_ignored_path_variable_references_in_scalar_predicate_rhs(
                &predicate.rhs,
                state,
                format!("{path}.rhs"),
            )
        }
        PredicateExpression::And { left, right }
        | PredicateExpression::Or { left, right }
        | PredicateExpression::Xor { left, right } => {
            reject_ignored_path_variable_references_in_predicate(
                left,
                state,
                format!("{path}.left"),
            )?;
            reject_ignored_path_variable_references_in_predicate(
                right,
                state,
                format!("{path}.right"),
            )
        }
        PredicateExpression::Not { expression } => {
            reject_ignored_path_variable_references_in_predicate(
                expression,
                state,
                format!("{path}.expression"),
            )
        }
    }
}

fn reject_ignored_path_variable_references_in_property_predicate(
    predicate: &PropertyPredicate,
    state: &CypherCompileState,
    path: impl Into<String>,
) -> Result<(), CoreError> {
    let path = path.into();
    reject_ignored_path_variable_property_ref(
        &predicate.property,
        state,
        format!("{path}.property"),
    )?;
    reject_ignored_path_variable_references_in_predicate_rhs(
        &predicate.rhs,
        state,
        format!("{path}.rhs"),
    )
}

fn reject_ignored_path_variable_references_in_predicate_rhs(
    rhs: &PredicateRhs,
    state: &CypherCompileState,
    path: impl Into<String>,
) -> Result<(), CoreError> {
    let path = path.into();
    match rhs {
        PredicateRhs::Property(property) => {
            reject_ignored_path_variable_property_ref(property, state, path)
        }
        PredicateRhs::Key { variable } | PredicateRhs::ElementId { variable } => {
            reject_ignored_path_variable(variable, state, path)
        }
        PredicateRhs::Literal(_) | PredicateRhs::List(_) => Ok(()),
    }
}

fn reject_ignored_path_variable_references_in_scalar_predicate_rhs(
    rhs: &ScalarPredicateRhs,
    state: &CypherCompileState,
    path: impl Into<String>,
) -> Result<(), CoreError> {
    let path = path.into();
    match rhs {
        ScalarPredicateRhs::Expression(expression) => {
            reject_ignored_path_variable_references_in_scalar_expression(expression, state, path)
        }
        ScalarPredicateRhs::List(_) => Ok(()),
    }
}

fn reject_ignored_path_variable_references_in_scalar_expression(
    expression: &ScalarExpression,
    state: &CypherCompileState,
    path: impl Into<String>,
) -> Result<(), CoreError> {
    let path = path.into();
    if let Some(expression) = unary_scalar_expression_operand(expression) {
        return reject_ignored_path_variable_references_in_scalar_expression(
            expression, state, path,
        );
    }

    match expression {
        ScalarExpression::Property(property) => {
            reject_ignored_path_variable_property_ref(property, state, path)
        }
        ScalarExpression::UndirectedEndpointProperty { relationship, .. }
        | ScalarExpression::UndirectedEndpointKey { relationship, .. }
        | ScalarExpression::UndirectedEndpointElementId { relationship, .. }
        | ScalarExpression::UndirectedEndpointLabels { relationship, .. }
        | ScalarExpression::UndirectedEndpointPropertyKeys { relationship, .. } => {
            reject_ignored_path_variable(relationship, state, path)
        }
        ScalarExpression::Literal(_)
        | ScalarExpression::LiteralList { .. }
        | ScalarExpression::TypedLiteralList { .. } => Ok(()),
        ScalarExpression::Predicate(predicate) => {
            reject_ignored_path_variable_references_in_predicate(predicate, state, path)
        }
        ScalarExpression::CountSubquery {
            pattern,
            distinct_target,
        } => {
            reject_ignored_path_variable_references_in_count_subquery(
                pattern,
                state,
                format!("{path}.pattern"),
            )?;
            if let Some(target) = distinct_target {
                reject_ignored_path_variable_references_in_scalar_expression(
                    target,
                    state,
                    format!("{path}.distinct_target"),
                )?;
            }
            Ok(())
        }
        ScalarExpression::CollectSubquery {
            pattern, target, ..
        } => {
            reject_ignored_path_variable_references_in_count_subquery(
                pattern,
                state,
                format!("{path}.pattern"),
            )?;
            reject_ignored_path_variable_references_in_scalar_expression(
                target,
                state,
                format!("{path}.target"),
            )
        }
        ScalarExpression::Key { variable }
        | ScalarExpression::ElementId { variable }
        | ScalarExpression::GraphIdentity { variable }
        | ScalarExpression::GraphPresence { variable }
        | ScalarExpression::PropertyKeys { variable }
        | ScalarExpression::RelationshipType { variable, .. }
        | ScalarExpression::NodeLabels { variable, .. } => {
            reject_ignored_path_variable(variable, state, path)
        }
        ScalarExpression::PresenceGated {
            presence_variable,
            expression,
        } => {
            reject_ignored_path_variable(
                presence_variable,
                state,
                format!("{path}.presence_variable"),
            )?;
            reject_ignored_path_variable_references_in_scalar_expression(
                expression,
                state,
                format!("{path}.expression"),
            )
        }
        _ => reject_ignored_path_variable_references_in_structural_scalar_expression(
            expression, state, path,
        ),
    }
}

fn reject_ignored_path_variable_references_in_structural_scalar_expression(
    expression: &ScalarExpression,
    state: &CypherCompileState,
    path: String,
) -> Result<(), CoreError> {
    match expression {
        ScalarExpression::Coalesce { expressions } => {
            reject_path_variables_in_scalar_list(expressions, state, format!("{path}.expressions"))
        }
        ScalarExpression::NullIf { expression, value } => reject_path_variables_in_scalar_pair(
            ("expression", expression),
            ("value", value),
            state,
            path,
        ),
        ScalarExpression::Round { expression, places } => {
            reject_path_variables_in_scalar_optional_pair(
                ("expression", expression),
                ("places", places.as_deref()),
                state,
                path,
            )
        }
        ScalarExpression::Left { expression, count }
        | ScalarExpression::Right { expression, count } => reject_path_variables_in_scalar_pair(
            ("expression", expression),
            ("count", count),
            state,
            path,
        ),
        ScalarExpression::StringContains {
            expression,
            pattern: operand,
        }
        | ScalarExpression::StringStartsWith {
            expression,
            pattern: operand,
        }
        | ScalarExpression::StringEndsWith {
            expression,
            pattern: operand,
        } => reject_path_variables_in_scalar_pair(
            ("expression", expression),
            ("pattern", operand),
            state,
            path,
        ),
        ScalarExpression::Replace {
            expression,
            search,
            replacement,
        } => reject_path_variables_in_replace_expression(
            expression,
            search,
            replacement,
            state,
            path,
        ),
        ScalarExpression::Substring {
            expression,
            start,
            length,
        } => reject_path_variables_in_substring_expression(
            expression,
            start,
            length.as_deref(),
            state,
            path,
        ),
        ScalarExpression::Arithmetic { left, right, .. } => {
            reject_path_variables_in_scalar_pair(("left", left), ("right", right), state, path)
        }
        ScalarExpression::Atan2 { y, x } => {
            reject_path_variables_in_scalar_pair(("y", y), ("x", x), state, path)
        }
        ScalarExpression::Case {
            alternatives,
            else_expression,
        } => reject_ignored_path_variable_references_in_case_expression(
            alternatives,
            else_expression.as_deref(),
            state,
            path,
        ),
        _ => {
            reject_ignored_path_variable_references_in_non_structural_scalar_expression(expression);
            Ok(())
        }
    }
}

fn reject_ignored_path_variable_references_in_non_structural_scalar_expression(
    expression: &ScalarExpression,
) {
    match expression {
        ScalarExpression::Property(_)
        | ScalarExpression::UndirectedEndpointProperty { .. }
        | ScalarExpression::UndirectedEndpointKey { .. }
        | ScalarExpression::UndirectedEndpointElementId { .. }
        | ScalarExpression::UndirectedEndpointLabels { .. }
        | ScalarExpression::UndirectedEndpointPropertyKeys { .. }
        | ScalarExpression::Literal(_)
        | ScalarExpression::LiteralList { .. }
        | ScalarExpression::TypedLiteralList { .. }
        | ScalarExpression::Predicate(_)
        | ScalarExpression::CountSubquery { .. }
        | ScalarExpression::CollectSubquery { .. }
        | ScalarExpression::Key { .. }
        | ScalarExpression::ElementId { .. }
        | ScalarExpression::GraphIdentity { .. }
        | ScalarExpression::GraphPresence { .. }
        | ScalarExpression::NodeLabels { .. }
        | ScalarExpression::PropertyKeys { .. }
        | ScalarExpression::PresenceGated { .. }
        | ScalarExpression::RelationshipType { .. } => {
            unreachable!("simple scalar expressions handled before structural path checks")
        }
        ScalarExpression::GraphKeyList { .. } => {}
        ScalarExpression::ToString { .. }
        | ScalarExpression::ToInteger { .. }
        | ScalarExpression::ToFloat { .. }
        | ScalarExpression::ToBoolean { .. }
        | ScalarExpression::ToStringOrNull { .. }
        | ScalarExpression::ToIntegerOrNull { .. }
        | ScalarExpression::ToFloatOrNull { .. }
        | ScalarExpression::ToBooleanOrNull { .. }
        | ScalarExpression::ToLower { .. }
        | ScalarExpression::ToUpper { .. }
        | ScalarExpression::Trim { .. }
        | ScalarExpression::LTrim { .. }
        | ScalarExpression::RTrim { .. }
        | ScalarExpression::CharacterLength { .. }
        | ScalarExpression::Reverse { .. }
        | ScalarExpression::Abs { .. }
        | ScalarExpression::Ceil { .. }
        | ScalarExpression::Floor { .. }
        | ScalarExpression::Sqrt { .. }
        | ScalarExpression::Sign { .. }
        | ScalarExpression::Exp { .. }
        | ScalarExpression::Log { .. }
        | ScalarExpression::Log10 { .. }
        | ScalarExpression::Sin { .. }
        | ScalarExpression::Cos { .. }
        | ScalarExpression::Tan { .. }
        | ScalarExpression::Cot { .. }
        | ScalarExpression::Asin { .. }
        | ScalarExpression::Acos { .. }
        | ScalarExpression::Atan { .. }
        | ScalarExpression::Degrees { .. }
        | ScalarExpression::Radians { .. }
        | ScalarExpression::Negate { .. } => {
            unreachable!("unary scalar expressions handled before structural path checks")
        }
        ScalarExpression::Coalesce { .. }
        | ScalarExpression::NullIf { .. }
        | ScalarExpression::Round { .. }
        | ScalarExpression::Left { .. }
        | ScalarExpression::Right { .. }
        | ScalarExpression::StringContains { .. }
        | ScalarExpression::StringStartsWith { .. }
        | ScalarExpression::StringEndsWith { .. }
        | ScalarExpression::Replace { .. }
        | ScalarExpression::Substring { .. }
        | ScalarExpression::Arithmetic { .. }
        | ScalarExpression::Atan2 { .. }
        | ScalarExpression::Case { .. } => {
            unreachable!("structural scalar expressions handled before this path check")
        }
    }
}

fn reject_ignored_path_variable_references_in_count_subquery(
    pattern: &CountSubqueryPattern,
    state: &CypherCompileState,
    path: impl Into<String>,
) -> Result<(), CoreError> {
    let path = path.into();
    match pattern {
        CountSubqueryPattern::Relationships(pattern) => {
            reject_ignored_path_variable_references_in_exists_pattern(pattern, state, path)?;
        }
        CountSubqueryPattern::Nodes {
            nodes,
            predicates,
            predicate,
        } => {
            for (index, node) in nodes.iter().enumerate() {
                reject_ignored_path_variable(
                    &node.variable,
                    state,
                    format!("{path}.nodes[{index}].variable"),
                )?;
            }
            for (index, predicate) in predicates.iter().enumerate() {
                reject_ignored_path_variable_references_in_property_predicate(
                    predicate,
                    state,
                    format!("{path}.predicates[{index}]"),
                )?;
            }
            if let Some(predicate) = predicate {
                reject_ignored_path_variable_references_in_predicate(
                    predicate,
                    state,
                    format!("{path}.predicate"),
                )?;
            }
        }
    }
    Ok(())
}

fn reject_ignored_path_variable_references_in_exists_pattern(
    pattern: &ExistsPatternPredicate,
    state: &CypherCompileState,
    path: impl Into<String>,
) -> Result<(), CoreError> {
    let path = path.into();
    for (index, node) in pattern.nodes.iter().enumerate() {
        reject_ignored_path_variable(
            &node.variable,
            state,
            format!("{path}.nodes[{index}].variable"),
        )?;
    }
    for (index, relationship) in pattern.relationships.iter().enumerate() {
        if let Some(variable) = &relationship.variable {
            reject_ignored_path_variable(
                variable,
                state,
                format!("{path}.relationships[{index}].variable"),
            )?;
        }
        reject_ignored_path_variable(
            &relationship.left,
            state,
            format!("{path}.relationships[{index}].left"),
        )?;
        reject_ignored_path_variable(
            &relationship.right,
            state,
            format!("{path}.relationships[{index}].right"),
        )?;
    }
    for (index, predicate) in pattern.predicates.iter().enumerate() {
        reject_ignored_path_variable_references_in_property_predicate(
            predicate,
            state,
            format!("{path}.predicates[{index}]"),
        )?;
    }
    if let Some(predicate) = &pattern.predicate {
        reject_ignored_path_variable_references_in_predicate(
            predicate,
            state,
            format!("{path}.predicate"),
        )?;
    }
    Ok(())
}

fn reject_path_variables_in_scalar_list(
    expressions: &[ScalarExpression],
    state: &CypherCompileState,
    path: impl Into<String>,
) -> Result<(), CoreError> {
    let path = path.into();
    for (index, expression) in expressions.iter().enumerate() {
        reject_ignored_path_variable_references_in_scalar_expression(
            expression,
            state,
            format!("{path}[{index}]"),
        )?;
    }
    Ok(())
}

fn reject_path_variables_in_scalar_pair(
    left: (&str, &ScalarExpression),
    right: (&str, &ScalarExpression),
    state: &CypherCompileState,
    path: impl Into<String>,
) -> Result<(), CoreError> {
    let path = path.into();
    reject_ignored_path_variable_references_in_scalar_expression(
        left.1,
        state,
        format!("{path}.{}", left.0),
    )?;
    reject_ignored_path_variable_references_in_scalar_expression(
        right.1,
        state,
        format!("{path}.{}", right.0),
    )
}

fn reject_path_variables_in_scalar_optional_pair(
    required: (&str, &ScalarExpression),
    optional: (&str, Option<&ScalarExpression>),
    state: &CypherCompileState,
    path: impl Into<String>,
) -> Result<(), CoreError> {
    let path = path.into();
    reject_ignored_path_variable_references_in_scalar_expression(
        required.1,
        state,
        format!("{path}.{}", required.0),
    )?;
    if let Some(expression) = optional.1 {
        reject_ignored_path_variable_references_in_scalar_expression(
            expression,
            state,
            format!("{path}.{}", optional.0),
        )?;
    }
    Ok(())
}

fn reject_path_variables_in_replace_expression(
    expression: &ScalarExpression,
    search: &ScalarExpression,
    replacement: &ScalarExpression,
    state: &CypherCompileState,
    path: impl Into<String>,
) -> Result<(), CoreError> {
    let path = path.into();
    reject_ignored_path_variable_references_in_scalar_expression(
        expression,
        state,
        format!("{path}.expression"),
    )?;
    reject_ignored_path_variable_references_in_scalar_expression(
        search,
        state,
        format!("{path}.search"),
    )?;
    reject_ignored_path_variable_references_in_scalar_expression(
        replacement,
        state,
        format!("{path}.replacement"),
    )
}

fn reject_path_variables_in_substring_expression(
    expression: &ScalarExpression,
    start: &ScalarExpression,
    length: Option<&ScalarExpression>,
    state: &CypherCompileState,
    path: impl Into<String>,
) -> Result<(), CoreError> {
    let path = path.into();
    reject_ignored_path_variable_references_in_scalar_expression(
        expression,
        state,
        format!("{path}.expression"),
    )?;
    reject_ignored_path_variable_references_in_scalar_expression(
        start,
        state,
        format!("{path}.start"),
    )?;
    if let Some(length) = length {
        reject_ignored_path_variable_references_in_scalar_expression(
            length,
            state,
            format!("{path}.length"),
        )?;
    }
    Ok(())
}

fn reject_ignored_path_variable_references_in_case_expression(
    alternatives: &[ScalarCaseAlternative],
    else_expression: Option<&ScalarExpression>,
    state: &CypherCompileState,
    path: impl Into<String>,
) -> Result<(), CoreError> {
    let path = path.into();
    for (index, alternative) in alternatives.iter().enumerate() {
        reject_ignored_path_variable_references_in_predicate(
            &alternative.when,
            state,
            format!("{path}.alternatives[{index}].when"),
        )?;
        reject_ignored_path_variable_references_in_scalar_expression(
            &alternative.then,
            state,
            format!("{path}.alternatives[{index}].then"),
        )?;
    }
    if let Some(else_expression) = else_expression {
        reject_ignored_path_variable_references_in_scalar_expression(
            else_expression,
            state,
            format!("{path}.else"),
        )?;
    }
    Ok(())
}

fn unary_scalar_expression_operand(expression: &ScalarExpression) -> Option<&ScalarExpression> {
    match expression {
        ScalarExpression::ToString { expression }
        | ScalarExpression::ToInteger { expression }
        | ScalarExpression::ToFloat { expression }
        | ScalarExpression::ToBoolean { expression }
        | ScalarExpression::ToStringOrNull { expression }
        | ScalarExpression::ToIntegerOrNull { expression }
        | ScalarExpression::ToFloatOrNull { expression }
        | ScalarExpression::ToBooleanOrNull { expression }
        | ScalarExpression::ToLower { expression }
        | ScalarExpression::ToUpper { expression }
        | ScalarExpression::Trim { expression }
        | ScalarExpression::LTrim { expression }
        | ScalarExpression::RTrim { expression }
        | ScalarExpression::CharacterLength { expression }
        | ScalarExpression::Reverse { expression }
        | ScalarExpression::Abs { expression }
        | ScalarExpression::Ceil { expression }
        | ScalarExpression::Floor { expression }
        | ScalarExpression::Sqrt { expression }
        | ScalarExpression::Sign { expression }
        | ScalarExpression::Exp { expression }
        | ScalarExpression::Log { expression }
        | ScalarExpression::Log10 { expression }
        | ScalarExpression::Sin { expression }
        | ScalarExpression::Cos { expression }
        | ScalarExpression::Tan { expression }
        | ScalarExpression::Cot { expression }
        | ScalarExpression::Asin { expression }
        | ScalarExpression::Acos { expression }
        | ScalarExpression::Atan { expression }
        | ScalarExpression::Degrees { expression }
        | ScalarExpression::Radians { expression }
        | ScalarExpression::Negate { expression } => Some(expression),
        _ => None,
    }
}

fn reject_ignored_path_variable_property_ref(
    property: &PropertyRef,
    state: &CypherCompileState,
    path: impl Into<String>,
) -> Result<(), CoreError> {
    reject_ignored_path_variable(&property.variable, state, path)
}

fn reject_ignored_path_variable(
    variable: &str,
    state: &CypherCompileState,
    path: impl Into<String>,
) -> Result<(), CoreError> {
    let path = path.into();
    if state.out_of_scope_graph_names.contains(variable) {
        return Err(unsupported(
            path,
            format!("graph variable '{variable}' is not in scope after WITH"),
        ));
    }
    if state.path_variables.contains_key(variable) {
        return Err(unsupported(
            path,
            format!(
                "path variable '{variable}' cannot be used as a graph value because Coral does not materialize path values yet"
            ),
        ));
    }
    Ok(())
}

fn mark_graph_variable_in_scope(state: &mut CypherCompileState, variable: &str) {
    state.out_of_scope_graph_names.remove(variable);
}

fn compile_reading_clauses_into(
    reading_clauses: &[ReadingClause],
    path: impl Into<String>,
    plan: &mut GraphPlan,
    state: &mut CypherCompileState,
    context: &CypherCompileContext,
) -> Result<(), CoreError> {
    let path = path.into();
    if reading_clauses.is_empty() {
        return Err(unsupported(
            path,
            "at least one MATCH clause is required before RETURN",
        ));
    }

    for (index, clause) in reading_clauses.iter().enumerate() {
        match clause {
            ReadingClause::Match(match_clause) => {
                reject_match_scalar_alias_conflicts(
                    match_clause,
                    state,
                    format!("{path}[{index}].pattern"),
                )?;
                let predicate_start = plan.predicates.len();
                let node_start = plan.nodes.len();
                let relationship_start = plan.relationships.len();
                let path_variables_start = state
                    .path_variables
                    .keys()
                    .cloned()
                    .collect::<BTreeSet<_>>();
                compile_match_into(match_clause, plan, state, context)?;
                if match_clause.optional {
                    let introduced_path_variables = state
                        .path_variables
                        .keys()
                        .filter(|variable| !path_variables_start.contains(*variable))
                        .cloned()
                        .collect::<Vec<_>>();
                    let predicate = match_clause
                        .where_clause
                        .as_ref()
                        .map(|where_clause| {
                            compile_predicate_expression_with_path_state(
                                where_clause,
                                format!("{path}[{index}].where"),
                                plan,
                                Some(state),
                                context,
                            )
                        })
                        .transpose()?;
                    attach_optional_match_scope(
                        plan,
                        OptionalMatchStart {
                            node: node_start,
                            relationship: relationship_start,
                            predicate: predicate_start,
                        },
                        predicate,
                        state,
                        &introduced_path_variables,
                        format!("{path}[{index}]"),
                    )?;
                } else if let Some(where_clause) = &match_clause.where_clause {
                    let predicate = compile_predicate_expression_with_path_state(
                        where_clause,
                        format!("{path}[{index}].where"),
                        plan,
                        Some(state),
                        context,
                    )?;
                    append_predicate_expression(predicate, plan);
                }
            }
            ReadingClause::Unwind(_) => return Err(unsupported(path, "UNWIND is not supported")),
            ReadingClause::InQueryCall(_) | ReadingClause::CallSubquery(_) => {
                return Err(unsupported(path, "CALL is not supported"));
            }
            ReadingClause::LoadCsv(_) => {
                return Err(unsupported(path, "LOAD CSV is not supported"));
            }
        }
    }
    Ok(())
}

fn reject_match_scalar_alias_conflicts(
    match_clause: &Match,
    state: &CypherCompileState,
    path: impl Into<String>,
) -> Result<(), CoreError> {
    let path = path.into();
    let aliases = scalar_alias_names(state);
    if aliases.is_empty() {
        return Ok(());
    }
    let variables = match_clause_bound_variables(match_clause);
    if let Some(conflict) = variables
        .iter()
        .find(|variable| aliases.contains(*variable))
    {
        return Err(unsupported(
            path,
            format!("MATCH variable '{conflict}' conflicts with an in-scope WITH scalar alias"),
        ));
    }
    Ok(())
}

#[derive(Clone, Copy)]
struct OptionalMatchStart {
    node: usize,
    relationship: usize,
    predicate: usize,
}

fn attach_optional_match_scope(
    plan: &mut GraphPlan,
    start: OptionalMatchStart,
    predicate: Option<PredicateExpression>,
    state: &mut CypherCompileState,
    introduced_path_variables: &[String],
    path: impl Into<String>,
) -> Result<(), CoreError> {
    let path = path.into();
    let relationship_indices = (start.relationship..plan.relationships.len()).collect::<Vec<_>>();
    let inline_predicates = plan.predicates.drain(start.predicate..).collect::<Vec<_>>();
    let predicate = combine_optional_predicates(inline_predicates, predicate);
    if relationship_indices.is_empty()
        && let Some(predicate) = &predicate
    {
        if attach_zero_hop_path_predicate_gate(state, introduced_path_variables, predicate, &path)?
        {
            return Ok(());
        }
        return Err(unsupported(
            path,
            "OPTIONAL MATCH predicates currently require a relationship pattern",
        ));
    }
    if relationship_indices.is_empty() {
        return Ok(());
    }

    plan.optional_matches.push(OptionalMatchScope {
        node_indices: (start.node..plan.nodes.len()).collect(),
        relationship_indices,
        predicate,
    });
    Ok(())
}

fn attach_zero_hop_path_predicate_gate(
    state: &mut CypherCompileState,
    introduced_path_variables: &[String],
    predicate: &PredicateExpression,
    path: &str,
) -> Result<bool, CoreError> {
    let mut attached = false;
    for variable in introduced_path_variables {
        let Some(binding) = state.path_variables.get_mut(variable) else {
            continue;
        };
        if !binding.optional || binding.length != 0 {
            continue;
        }
        if binding.zero_hop_endpoint_introduced {
            return Err(unsupported(
                path.to_string(),
                "OPTIONAL MATCH local predicates over zero-hop paths with newly introduced endpoints require nullable zero-hop endpoint binding and are not supported yet",
            ));
        }
        binding.presence_gate = Some(conjoin_path_presence_gate(
            binding.presence_gate.take(),
            predicate.clone(),
        ));
        attached = true;
    }
    Ok(attached)
}

fn conjoin_path_presence_gate(
    existing: Option<PathPresenceGate>,
    predicate: PredicateExpression,
) -> PathPresenceGate {
    match existing {
        Some(existing) => PathPresenceGate::Predicate(PredicateExpression::And {
            left: Box::new(path_presence_gate_predicate(existing)),
            right: Box::new(predicate),
        }),
        None => PathPresenceGate::Predicate(predicate),
    }
}

fn path_presence_gate_predicate(gate: PathPresenceGate) -> PredicateExpression {
    match gate {
        PathPresenceGate::Variable(variable) => PredicateExpression::Presence(PresencePredicate {
            variable,
            operator: ComparisonOperator::NotEqual,
        }),
        PathPresenceGate::Predicate(predicate) => predicate,
    }
}

fn combine_optional_predicates(
    predicates: Vec<PropertyPredicate>,
    predicate: Option<PredicateExpression>,
) -> Option<PredicateExpression> {
    predicates
        .into_iter()
        .map(PredicateExpression::Comparison)
        .chain(predicate)
        .reduce(|left, right| PredicateExpression::And {
            left: Box::new(left),
            right: Box::new(right),
        })
}

fn return_clause_from_single_part(
    query: &SinglePartQuery,
    path: impl Into<String>,
) -> Result<&Return, CoreError> {
    let path = path.into();
    match &query.body {
        SinglePartBody::Return(return_clause) => Ok(return_clause),
        SinglePartBody::Updating { .. } => Err(unsupported(
            path,
            "write clauses are not supported by Coral virtual graphs",
        )),
        SinglePartBody::Finish(_) => Err(unsupported(
            path,
            "FINISH is not supported because virtual graph queries must return rows",
        )),
    }
}

fn compile_match_into(
    match_clause: &Match,
    plan: &mut GraphPlan,
    state: &mut CypherCompileState,
    context: &CypherCompileContext,
) -> Result<(), CoreError> {
    if match_clause.pattern.parts.is_empty() {
        return Err(unsupported(
            "match.pattern",
            "MATCH pattern must not be empty",
        ));
    }
    if match_clause.optional && match_clause.pattern.parts.len() != 1 {
        return Err(unsupported(
            "match.pattern.parts",
            "OPTIONAL MATCH currently supports one connected pattern part",
        ));
    }

    let initially_bound_nodes = plan
        .nodes
        .iter()
        .map(|node| node.variable.as_str())
        .collect::<BTreeSet<_>>();
    if match_clause.optional
        && !match_clause
            .pattern
            .parts
            .iter()
            .any(|part| pattern_part_uses_bound_node(part, &initially_bound_nodes))
    {
        return Err(unsupported(
            "match.pattern",
            "OPTIONAL MATCH must be anchored to a previously bound node variable",
        ));
    }

    for (part_index, pattern_part) in match_clause.pattern.parts.iter().enumerate() {
        compile_pattern_part_into(
            pattern_part,
            part_index,
            match_clause.optional,
            plan,
            state,
            context,
        )?;
    }

    Ok(())
}

fn compile_pattern_part_into(
    pattern_part: &PatternPart,
    part_index: usize,
    optional: bool,
    plan: &mut GraphPlan,
    state: &mut CypherCompileState,
    context: &CypherCompileContext,
) -> Result<(), CoreError> {
    let pending_path_binding = validate_path_variable_binding(
        pattern_part,
        plan,
        state,
        format!("match.pattern.parts[{part_index}]"),
    )?;

    let Some((start, chains)) = pattern_element_path(&pattern_part.anonymous.element) else {
        return Err(unsupported(
            format!("match.pattern.parts[{part_index}]"),
            "quantified path patterns are not supported yet",
        ));
    };

    let label_hints = infer_path_node_label_hints(
        start,
        chains,
        plan,
        context,
        format!("match.pattern.parts[{part_index}]"),
    )?;
    let start_node = compile_node(
        start,
        plan,
        state,
        fresh_internal_node_variable(plan, part_index, 0),
        path_node_label_hint(start, 0, &label_hints),
        format!("match.pattern.parts[{part_index}].nodes[0]"),
        context,
    )?;
    let previous_variable = start_node.variable.clone();
    plan.predicates.extend(start_node.predicates);
    if let Some(pattern) = start_node.pattern {
        mark_graph_variable_in_scope(state, &pattern.variable);
        plan.nodes.push(pattern);
    }
    let force_optional_path_presence = optional && pending_path_binding.is_some();
    let force_path_relationship_variables = pending_path_binding.as_ref().is_some_and(|pending| {
        state
            .relationship_element_path_variables
            .contains(pending.name.as_str())
    });
    let mut chain_state = PathChainCompileState {
        path_node_variables: vec![previous_variable.clone()],
        path_relationship_variables: Vec::new(),
        previous_variable,
        previous_label: start_node.label,
        path_presence_gate: None,
        hidden_path_presence_variables: Vec::new(),
        zero_hop_endpoint_introduced: false,
    };

    for (chain_index, chain) in chains.iter().enumerate() {
        compile_path_chain_into(
            chain,
            PathChainCompileOptions {
                part_index,
                chain_index,
                total_chains: chains.len(),
                optional,
                force_path_relationship_variables,
                force_optional_path_presence,
            },
            &mut chain_state,
            &label_hints,
            plan,
            state,
            context,
        )?;
    }

    if let Some(pending) = pending_path_binding {
        state
            .hidden_graph_variables
            .extend(chain_state.hidden_path_presence_variables);
        let presence_gate = optional.then_some(chain_state.path_presence_gate).flatten();
        let zero_hop_endpoint_introduced = chain_state.zero_hop_endpoint_introduced;
        bind_path_variable(
            state,
            pending,
            chain_state.path_node_variables,
            chain_state.path_relationship_variables,
            optional,
            presence_gate,
            zero_hop_endpoint_introduced,
        );
    }

    Ok(())
}

struct PathChainCompileState {
    path_node_variables: Vec<String>,
    path_relationship_variables: Vec<String>,
    previous_variable: String,
    previous_label: String,
    path_presence_gate: Option<PathPresenceGate>,
    hidden_path_presence_variables: Vec<String>,
    zero_hop_endpoint_introduced: bool,
}

#[derive(Debug, Clone, Copy)]
struct PathChainCompileOptions {
    part_index: usize,
    chain_index: usize,
    total_chains: usize,
    optional: bool,
    force_path_relationship_variables: bool,
    force_optional_path_presence: bool,
}

fn infer_path_node_label_hints(
    start: &CypherNodePattern,
    chains: &[PatternElementChain],
    plan: &GraphPlan,
    context: &CypherCompileContext,
    path: impl Into<String>,
) -> Result<PathNodeLabelHints, CoreError> {
    let path = path.into();
    let Some(graph) = context.graph.as_ref() else {
        return Ok(PathNodeLabelHints::default());
    };

    let mut nodes = Vec::with_capacity(chains.len() + 1);
    nodes.push(start);
    nodes.extend(chains.iter().map(|chain| &chain.node));

    let mut labels = explicit_and_bound_path_node_label_hints(&nodes, plan, context, &path)?;
    let mut changed = true;
    while changed {
        changed = false;
        for (index, chain) in chains.iter().enumerate() {
            let Some(descriptor) =
                relationship_label_inference_descriptor(&chain.relationship, context)
                    .transpose()?
            else {
                continue;
            };
            let pairs = relationship_label_pairs(
                graph,
                descriptor.relationship_type.as_deref(),
                descriptor.direction,
                descriptor.length,
            );
            if pairs.is_empty() {
                continue;
            }

            let left_node = nodes
                .get(index)
                .ok_or_else(|| CoreError::internal("path label inference left node missing"))?;
            let right_node = nodes
                .get(index + 1)
                .ok_or_else(|| CoreError::internal("path label inference right node missing"))?;
            let left_label = path_node_label_hint(left_node, index, &labels).map(str::to_string);
            let right_label =
                path_node_label_hint(right_node, index + 1, &labels).map(str::to_string);
            let compatible_pairs = pairs
                .iter()
                .filter(|(left, right)| {
                    left_label.as_ref().is_none_or(|label| label == left)
                        && right_label.as_ref().is_none_or(|label| label == right)
                })
                .collect::<Vec<_>>();
            if compatible_pairs.is_empty() {
                continue;
            }

            let relationship_path = format!("{path}.relationships[{index}]");
            let relationship_description = descriptor.relationship_description();
            if left_label.is_none() {
                changed |= infer_path_node_label(
                    &mut labels,
                    left_node,
                    index,
                    compatible_pairs.iter().map(|(left, _)| left.as_str()),
                    &relationship_description,
                    &relationship_path,
                )?;
            }
            if right_label.is_none() {
                changed |= infer_path_node_label(
                    &mut labels,
                    right_node,
                    index + 1,
                    compatible_pairs.iter().map(|(_, right)| right.as_str()),
                    &relationship_description,
                    &relationship_path,
                )?;
            }
        }
    }
    Ok(labels)
}

#[derive(Default)]
struct PathNodeLabelHints {
    variables: BTreeMap<String, String>,
    positions: BTreeMap<usize, String>,
}

fn explicit_and_bound_path_node_label_hints(
    nodes: &[&CypherNodePattern],
    plan: &GraphPlan,
    context: &CypherCompileContext,
    path: &str,
) -> Result<PathNodeLabelHints, CoreError> {
    let mut labels = PathNodeLabelHints::default();
    for (index, node) in nodes.iter().enumerate() {
        if let Some(variable) = path_node_variable(node)
            && let Some(existing) = plan.nodes.iter().find(|node| node.variable == variable)
        {
            record_path_node_label_hint(
                &mut labels,
                node,
                index,
                existing.label.clone(),
                format!("{path}.nodes[{index}]"),
            )?;
        }
        if let Some(label) = optional_single_compile_time_label(
            &node.labels,
            format!("{path}.nodes[{index}].labels"),
            context,
        )? {
            record_path_node_label_hint(
                &mut labels,
                node,
                index,
                label,
                format!("{path}.nodes[{index}]"),
            )?;
        }
    }
    Ok(labels)
}

fn record_path_node_label_hint(
    labels: &mut PathNodeLabelHints,
    node: &CypherNodePattern,
    index: usize,
    label: String,
    path: impl Into<String>,
) -> Result<bool, CoreError> {
    if let Some(variable) = path_node_variable(node) {
        return record_path_variable_label(&mut labels.variables, &variable, label, path);
    }
    record_path_position_label(&mut labels.positions, index, label, path)
}

fn record_path_variable_label(
    labels: &mut BTreeMap<String, String>,
    variable: &str,
    label: String,
    path: impl Into<String>,
) -> Result<bool, CoreError> {
    match labels.get(variable) {
        Some(existing) if existing == &label => Ok(false),
        Some(existing) => Err(unsupported(
            path,
            format!(
                "node variable '{variable}' has conflicting inferred labels '{existing}' and '{label}'"
            ),
        )),
        None => {
            labels.insert(variable.to_string(), label);
            Ok(true)
        }
    }
}

fn record_path_position_label(
    labels: &mut BTreeMap<usize, String>,
    index: usize,
    label: String,
    path: impl Into<String>,
) -> Result<bool, CoreError> {
    match labels.get(&index) {
        Some(existing) if existing == &label => Ok(false),
        Some(existing) => Err(unsupported(
            path,
            format!(
                "anonymous node at path position {index} has conflicting inferred labels '{existing}' and '{label}'"
            ),
        )),
        None => {
            labels.insert(index, label);
            Ok(true)
        }
    }
}

fn infer_path_node_label<'a>(
    labels: &mut PathNodeLabelHints,
    node: &CypherNodePattern,
    index: usize,
    candidates: impl Iterator<Item = &'a str>,
    relationship_description: &str,
    path: &str,
) -> Result<bool, CoreError> {
    let candidates = candidates.collect::<BTreeSet<_>>();
    match candidates.len() {
        0 => Ok(false),
        1 => record_path_node_label_hint(
            labels,
            node,
            index,
            candidates
                .into_iter()
                .next()
                .expect("candidate label set length was checked")
                .to_string(),
            path,
        ),
        _ => Err(unsupported(
            path,
            format!(
                "relationship pattern could not infer a unique label for {} from {relationship_description} mappings; add an explicit node label",
                path_node_description(node, index)
            ),
        )),
    }
}

fn path_node_description(node: &CypherNodePattern, index: usize) -> String {
    path_node_variable(node).map_or_else(
        || format!("anonymous node at path position {index}"),
        |variable| format!("node variable '{variable}'"),
    )
}

struct RelationshipLabelInferenceDescriptor {
    direction: Direction,
    relationship_type: Option<String>,
    length: usize,
}

impl RelationshipLabelInferenceDescriptor {
    fn relationship_description(&self) -> String {
        self.relationship_type.as_ref().map_or_else(
            || "untyped relationship".to_string(),
            |relationship_type| format!("'{relationship_type}'"),
        )
    }
}

fn relationship_label_inference_descriptor(
    pattern: &CypherRelationshipPattern,
    context: &CypherCompileContext,
) -> Option<Result<RelationshipLabelInferenceDescriptor, CoreError>> {
    let length = relationship_fixed_length(pattern, "relationship").ok()?;
    let relationship_type = pattern
        .detail
        .as_ref()
        .and_then(|detail| detail.types.as_ref())
        .map(|relationship_type| {
            single_compile_time_label(
                std::slice::from_ref(relationship_type),
                "relationship.types",
                context,
            )
        })
        .transpose();
    let direction = match pattern.direction {
        CypherRelationshipDirection::Right => Direction::Outgoing,
        CypherRelationshipDirection::Left => Direction::Incoming,
        CypherRelationshipDirection::Both | CypherRelationshipDirection::Undirected => {
            Direction::Undirected
        }
    };
    Some(
        relationship_type.map(|relationship_type| RelationshipLabelInferenceDescriptor {
            direction,
            relationship_type,
            length,
        }),
    )
}

fn relationship_label_pairs(
    graph: &Declaration,
    relationship_type: Option<&str>,
    direction: Direction,
    length: usize,
) -> BTreeSet<(String, String)> {
    if length == 0 {
        return graph
            .nodes
            .iter()
            .map(|node| (node.label.clone(), node.label.clone()))
            .collect();
    }
    if length > 1 {
        let Some(relationship_type) = relationship_type else {
            return BTreeSet::new();
        };
        return fixed_length_relationship_label_pairs(graph, relationship_type, direction, length);
    }
    match relationship_type {
        Some(relationship_type) => graph
            .relationships_for_type(relationship_type)
            .flat_map(|relationship| {
                relationship_label_pairs_for_direction(relationship, direction)
            })
            .collect(),
        None => graph
            .relationships
            .iter()
            .flat_map(|relationship| {
                relationship_label_pairs_for_direction(relationship, direction)
            })
            .collect(),
    }
}

fn fixed_length_relationship_label_pairs(
    graph: &Declaration,
    relationship_type: &str,
    direction: Direction,
    length: usize,
) -> BTreeSet<(String, String)> {
    let adjacency = fixed_length_label_adjacency(graph, relationship_type, direction);
    let graph_labels = graph
        .nodes
        .iter()
        .map(|node| node.label.as_str())
        .collect::<BTreeSet<_>>();
    let mut pairs = BTreeSet::new();
    for start in &graph.nodes {
        let mut frontier = BTreeSet::from([start.label.clone()]);
        for _ in 0..length {
            let mut next = BTreeSet::new();
            for label in &frontier {
                if let Some(targets) = adjacency.get(label) {
                    next.extend(targets.iter().cloned());
                }
            }
            frontier = next;
            if frontier.is_empty() {
                break;
            }
        }
        pairs.extend(
            frontier
                .into_iter()
                .filter(|end| graph_labels.contains(end.as_str()))
                .map(|end| (start.label.clone(), end)),
        );
    }
    pairs
}

fn relationship_label_pairs_for_direction(
    relationship: &DeclaredRelationship,
    direction: Direction,
) -> Vec<(String, String)> {
    match direction {
        Direction::Outgoing => vec![(
            relationship.from.label.clone(),
            relationship.to.label.clone(),
        )],
        Direction::Incoming => vec![(
            relationship.to.label.clone(),
            relationship.from.label.clone(),
        )],
        Direction::Undirected => {
            let forward = (
                relationship.from.label.clone(),
                relationship.to.label.clone(),
            );
            let reverse = (
                relationship.to.label.clone(),
                relationship.from.label.clone(),
            );
            if forward == reverse {
                vec![forward]
            } else {
                vec![forward, reverse]
            }
        }
    }
}

fn path_node_variable(node: &CypherNodePattern) -> Option<String> {
    node.variable.as_ref().map(variable_name)
}

fn path_node_label_hint<'a>(
    node: &CypherNodePattern,
    index: usize,
    hints: &'a PathNodeLabelHints,
) -> Option<&'a str> {
    path_node_variable(node)
        .and_then(|variable| hints.variables.get(&variable))
        .or_else(|| hints.positions.get(&index))
        .map(String::as_str)
}

fn compile_path_chain_into(
    chain: &PatternElementChain,
    options: PathChainCompileOptions,
    chain_state: &mut PathChainCompileState,
    label_hints: &PathNodeLabelHints,
    plan: &mut GraphPlan,
    state: &mut CypherCompileState,
    context: &CypherCompileContext,
) -> Result<(), CoreError> {
    let node_path = format!(
        "match.pattern.parts[{}].nodes[{}]",
        options.part_index,
        options.chain_index + 1
    );
    let next_node = compile_node(
        &chain.node,
        plan,
        state,
        fresh_internal_node_variable(plan, options.part_index, options.chain_index + 1),
        path_node_label_hint(&chain.node, options.chain_index + 1, label_hints),
        node_path,
        context,
    )?;
    let next_variable = next_node.variable.clone();
    let next_label = next_node.label.clone();
    let relationship_index = plan.relationships.len();
    let relationship_path = format!(
        "match.pattern.parts[{}].relationships[{}]",
        options.part_index, options.chain_index
    );
    let force_relationship_variable = options.force_path_relationship_variables
        || (options.force_optional_path_presence
            && options.chain_index + 1 == options.total_chains);
    let relationship = compile_relationship(
        &chain.relationship,
        RelationshipCompileEndpoints {
            left_variable: &chain_state.previous_variable,
            right_variable: &next_variable,
            left_label: &chain_state.previous_label,
            right_label: &next_label,
        },
        plan,
        state,
        RelationshipCompileOptions {
            index: relationship_index,
            path: relationship_path,
            force_variable: force_relationship_variable,
        },
        context,
    )?;
    let next_node_introduced = next_node.pattern.is_some();
    plan.predicates.extend(next_node.predicates);
    if let Some(pattern) = next_node.pattern {
        mark_graph_variable_in_scope(state, &pattern.variable);
        plan.nodes.push(pattern);
    }
    if relationship.length == 0 {
        append_zero_length_relationship(
            &relationship,
            &next_label,
            next_node_introduced,
            options,
            plan,
            chain_state,
        )?;
    } else if relationship.length == 1 {
        append_single_relationship(
            relationship,
            relationship_index,
            options,
            plan,
            state,
            chain_state,
        );
    } else {
        let intermediate_labels = infer_fixed_length_intermediate_labels(
            context.graph.as_ref(),
            &relationship.pattern.relationship_type,
            relationship.pattern.direction,
            &chain_state.previous_label,
            &next_label,
            relationship.length,
            format!(
                "match.pattern.parts[{}].relationships[{}]",
                options.part_index, options.chain_index
            ),
        )?;
        append_repeated_relationship(
            &relationship,
            &next_variable,
            &intermediate_labels,
            options,
            plan,
            state,
            chain_state,
        )?;
    }
    chain_state.previous_variable = next_variable;
    chain_state.previous_label = next_label;
    Ok(())
}

fn append_zero_length_relationship(
    relationship: &CompiledRelationship,
    next_label: &str,
    next_node_introduced: bool,
    options: PathChainCompileOptions,
    plan: &mut GraphPlan,
    chain_state: &mut PathChainCompileState,
) -> Result<(), CoreError> {
    if options.optional && options.force_optional_path_presence && next_node_introduced {
        chain_state.zero_hop_endpoint_introduced = true;
    }
    if options.optional && options.force_optional_path_presence && !next_node_introduced {
        if relationship.pattern.left == relationship.pattern.right {
            return Ok(());
        }
        record_path_presence_predicate(
            chain_state,
            zero_length_relationship_presence_predicate(
                relationship,
                &chain_state.previous_label,
                next_label,
            ),
        );
        return Ok(());
    }
    if options.optional && !next_node_introduced {
        return Ok(());
    }
    if options.optional && chain_state.previous_label != next_label {
        return Err(unsupported(
            format!(
                "match.pattern.parts[{}].relationships[{}]",
                options.part_index, options.chain_index
            ),
            "OPTIONAL MATCH with zero-hop relationship ranges across different endpoint labels requires nullable node binding and is not supported yet",
        ));
    }
    let predicate = if chain_state.previous_label == next_label {
        PredicateExpression::KeyComparison(KeyPredicate {
            variable: relationship.pattern.left.clone(),
            operator: ComparisonOperator::Equal,
            rhs: PredicateRhs::Key {
                variable: relationship.pattern.right.clone(),
            },
        })
    } else {
        PredicateExpression::Boolean(false)
    };
    append_predicate_expression(predicate, plan);
    Ok(())
}

fn append_single_relationship(
    relationship: CompiledRelationship,
    relationship_index: usize,
    options: PathChainCompileOptions,
    plan: &mut GraphPlan,
    state: &mut CypherCompileState,
    chain_state: &mut PathChainCompileState,
) {
    let force_relationship_variable = options.force_path_relationship_variables
        || (options.force_optional_path_presence
            && options.chain_index + 1 == options.total_chains);
    plan.predicates.extend(relationship.predicates);
    let relationship_variable = relationship.pattern.variable.clone();
    let right_variable = relationship.pattern.right.clone();
    if let Some(variable) = relationship.pattern.variable.as_deref() {
        mark_graph_variable_in_scope(state, variable);
    }
    if options.optional {
        plan.optional_relationships.push(relationship_index);
    }
    plan.relationships.push(relationship.pattern);
    chain_state.path_node_variables.push(right_variable);
    if force_relationship_variable && let Some(variable) = relationship_variable {
        chain_state
            .path_relationship_variables
            .push(variable.clone());
        record_path_presence_variable(chain_state, variable);
    }
}

fn append_repeated_relationship(
    relationship: &CompiledRelationship,
    next_variable: &str,
    intermediate_labels: &[String],
    options: PathChainCompileOptions,
    plan: &mut GraphPlan,
    state: &mut CypherCompileState,
    chain_state: &mut PathChainCompileState,
) -> Result<(), CoreError> {
    let force_relationship_variable = options.force_path_relationship_variables
        || (options.force_optional_path_presence
            && options.chain_index + 1 == options.total_chains);
    let expansion_result = append_fixed_length_relationship(
        plan,
        state,
        &relationship.pattern,
        &relationship.predicates,
        relationship.length,
        &FixedLengthExpansion {
            part_index: options.part_index,
            chain_index: options.chain_index,
            left_variable: &chain_state.previous_variable,
            right_variable: next_variable,
            intermediate_labels,
            optional: options.optional,
        },
    )?;
    chain_state
        .path_node_variables
        .extend(expansion_result.node_variables.iter().cloned());
    chain_state
        .path_relationship_variables
        .extend(expansion_result.relationship_variables.iter().cloned());
    if force_relationship_variable {
        record_path_presence_variables(chain_state, expansion_result.relationship_variables);
    }
    Ok(())
}

fn record_path_presence_variables(
    chain_state: &mut PathChainCompileState,
    relationship_variables: Vec<String>,
) {
    if let Some(variable) = relationship_variables.last() {
        chain_state.path_presence_gate = Some(PathPresenceGate::Variable(variable.clone()));
    }
    chain_state.hidden_path_presence_variables.extend(
        relationship_variables
            .into_iter()
            .filter(|variable| is_internal_graph_variable(variable)),
    );
}

fn record_path_presence_variable(chain_state: &mut PathChainCompileState, variable: String) {
    chain_state.path_presence_gate = Some(PathPresenceGate::Variable(variable.clone()));
    if is_internal_graph_variable(&variable) {
        chain_state.hidden_path_presence_variables.push(variable);
    }
}

fn record_path_presence_predicate(
    chain_state: &mut PathChainCompileState,
    predicate: PredicateExpression,
) {
    chain_state.path_presence_gate = Some(PathPresenceGate::Predicate(predicate));
}

fn zero_length_relationship_presence_predicate(
    relationship: &CompiledRelationship,
    left_label: &str,
    right_label: &str,
) -> PredicateExpression {
    if left_label != right_label {
        return PredicateExpression::Boolean(false);
    }
    PredicateExpression::KeyComparison(KeyPredicate {
        variable: relationship.pattern.left.clone(),
        operator: ComparisonOperator::Equal,
        rhs: PredicateRhs::Key {
            variable: relationship.pattern.right.clone(),
        },
    })
}

fn infer_fixed_length_intermediate_labels(
    graph: Option<&Declaration>,
    relationship_type: &str,
    direction: Direction,
    start_label: &str,
    end_label: &str,
    length: usize,
    path: impl Into<String>,
) -> Result<Vec<String>, CoreError> {
    let path = path.into();
    if length <= 1 {
        return Ok(Vec::new());
    }

    let Some(graph) = graph else {
        if start_label == end_label {
            return Ok(vec![start_label.to_string(); length - 1]);
        }
        return Err(unsupported(
            path,
            "fixed-length relationship ranges greater than 1 with different endpoint labels require a graph declaration so Coral can infer intermediate node mappings",
        ));
    };

    let sequences = fixed_length_label_sequences(
        graph,
        relationship_type,
        direction,
        start_label,
        end_label,
        length,
    );
    match sequences.as_slice() {
        [sequence] => sequence
            .get(1..sequence.len().saturating_sub(1))
            .map(<[String]>::to_vec)
            .ok_or_else(|| CoreError::internal("fixed-hop label sequence was too short")),
        [] => Err(unsupported(
            path,
            format!(
                "fixed-length relationship range could not infer a {length}-hop '{relationship_type}' label path from {start_label} to {end_label}"
            ),
        )),
        _ => Err(unsupported(
            path,
            format!(
                "fixed-length relationship range found at least {} possible {length}-hop '{relationship_type}' label paths from {start_label} to {end_label}; use explicit intermediate nodes to disambiguate",
                sequences.len()
            ),
        )),
    }
}

fn fixed_length_label_sequences(
    graph: &Declaration,
    relationship_type: &str,
    direction: Direction,
    start_label: &str,
    end_label: &str,
    length: usize,
) -> Vec<Vec<String>> {
    let adjacency = fixed_length_label_adjacency(graph, relationship_type, direction);
    fixed_length_label_sequences_with_adjacency(&adjacency, start_label, end_label, length)
}

fn fixed_length_label_sequences_with_adjacency(
    adjacency: &BTreeMap<String, BTreeSet<String>>,
    start_label: &str,
    end_label: &str,
    length: usize,
) -> Vec<Vec<String>> {
    let mut sequences = Vec::new();
    let mut current = vec![start_label.to_string()];
    collect_fixed_length_label_sequences(
        adjacency,
        end_label,
        length,
        &mut current,
        &mut sequences,
    );
    sequences
}

fn collect_fixed_length_label_sequences(
    adjacency: &BTreeMap<String, BTreeSet<String>>,
    end_label: &str,
    remaining_hops: usize,
    current: &mut Vec<String>,
    sequences: &mut Vec<Vec<String>>,
) {
    if sequences.len() >= MAX_FIXED_LABEL_SEQUENCE_RESULTS {
        return;
    }
    let Some(current_label) = current.last().cloned() else {
        return;
    };
    if remaining_hops == 0 {
        if current_label == end_label {
            sequences.push(current.clone());
        }
        return;
    }

    let Some(next_labels) = adjacency.get(&current_label) else {
        return;
    };
    for next_label in next_labels {
        if sequences.len() >= MAX_FIXED_LABEL_SEQUENCE_RESULTS {
            break;
        }
        current.push(next_label.clone());
        collect_fixed_length_label_sequences(
            adjacency,
            end_label,
            remaining_hops - 1,
            current,
            sequences,
        );
        current.pop();
    }
}

fn fixed_length_label_adjacency(
    graph: &Declaration,
    relationship_type: &str,
    direction: Direction,
) -> BTreeMap<String, BTreeSet<String>> {
    let mut adjacency = BTreeMap::new();
    for relationship in graph.relationships_for_type(relationship_type) {
        match direction {
            Direction::Outgoing => {
                adjacency
                    .entry(relationship.from.label.clone())
                    .or_insert_with(BTreeSet::new)
                    .insert(relationship.to.label.clone());
            }
            Direction::Incoming => {
                adjacency
                    .entry(relationship.to.label.clone())
                    .or_insert_with(BTreeSet::new)
                    .insert(relationship.from.label.clone());
            }
            Direction::Undirected => {
                adjacency
                    .entry(relationship.from.label.clone())
                    .or_insert_with(BTreeSet::new)
                    .insert(relationship.to.label.clone());
                adjacency
                    .entry(relationship.to.label.clone())
                    .or_insert_with(BTreeSet::new)
                    .insert(relationship.from.label.clone());
            }
        }
    }
    adjacency
}

struct FixedLengthExpansion<'a> {
    part_index: usize,
    chain_index: usize,
    left_variable: &'a str,
    right_variable: &'a str,
    intermediate_labels: &'a [String],
    optional: bool,
}

struct FixedLengthExpansionResult {
    node_variables: Vec<String>,
    relationship_variables: Vec<String>,
}

fn append_fixed_length_relationship(
    plan: &mut GraphPlan,
    state: &mut CypherCompileState,
    template: &RelationshipPattern,
    predicates: &[PropertyPredicate],
    length: usize,
    expansion: &FixedLengthExpansion<'_>,
) -> Result<FixedLengthExpansionResult, CoreError> {
    let mut left = expansion.left_variable.to_string();
    let mut node_variables = Vec::new();
    let mut relationship_variables = Vec::new();
    for hop in 1..=length {
        let right = if hop == length {
            expansion.right_variable.to_string()
        } else {
            let label = expansion.intermediate_labels.get(hop - 1).ok_or_else(|| {
                CoreError::internal("fixed-length expansion label sequence was incomplete")
            })?;
            let variable = fresh_internal_node_variable_avoiding(
                plan,
                expansion.part_index,
                expansion.chain_index + hop,
                expansion.right_variable,
            );
            mark_graph_variable_in_scope(state, &variable);
            plan.nodes.push(NodePattern {
                variable: variable.clone(),
                label: label.clone(),
            });
            variable
        };
        let relationship_index = plan.relationships.len();
        let mut pattern = template.clone();
        pattern.left = left;
        pattern.right.clone_from(&right);
        pattern.variable = template
            .variable
            .as_ref()
            .map(|_| fresh_internal_relationship_variable(plan, &right, relationship_index));
        if let (Some(template_variable), Some(hop_variable)) =
            (template.variable.as_deref(), pattern.variable.as_deref())
        {
            plan.predicates.extend(predicates.iter().map(|predicate| {
                rebind_property_predicate_variable(predicate, template_variable, hop_variable)
            }));
            mark_graph_variable_in_scope(state, hop_variable);
            relationship_variables.push(hop_variable.to_string());
        }
        if expansion.optional {
            plan.optional_relationships.push(relationship_index);
        }
        plan.relationships.push(pattern);
        node_variables.push(right.clone());
        left = right;
    }
    Ok(FixedLengthExpansionResult {
        node_variables,
        relationship_variables,
    })
}

fn rebind_property_predicate_variable(
    predicate: &PropertyPredicate,
    from: &str,
    to: &str,
) -> PropertyPredicate {
    let mut predicate = predicate.clone();
    if predicate.property.variable == from {
        predicate.property.variable = to.to_string();
    }
    predicate
}

fn validate_path_variable_binding(
    pattern_part: &PatternPart,
    plan: &GraphPlan,
    state: &CypherCompileState,
    path: impl Into<String>,
) -> Result<Option<PendingPathBinding>, CoreError> {
    let path = path.into();
    let anonymous_variables = anonymous_pattern_variables(pattern_part);
    if let Some(conflict) = anonymous_variables
        .iter()
        .find(|variable| state.path_variables.contains_key(*variable))
    {
        return Err(unsupported(
            format!("{path}.anonymous"),
            format!("graph variable '{conflict}' conflicts with an in-scope path variable"),
        ));
    }

    let Some(variable) = pattern_part.variable.as_ref() else {
        return Ok(None);
    };
    let name = validate_variable(variable)?;
    if plan_uses_variable(plan, &name)
        || state.path_variables.contains_key(&name)
        || anonymous_variables.contains(&name)
    {
        return Err(unsupported(
            format!("{path}.variable"),
            format!("path variable '{name}' conflicts with an in-scope graph or path variable"),
        ));
    }
    let length = path_pattern_length(pattern_part, &path)?;
    Ok(Some(PendingPathBinding { name, length }))
}

fn bind_path_variable(
    state: &mut CypherCompileState,
    pending: PendingPathBinding,
    node_variables: Vec<String>,
    relationship_variables: Vec<String>,
    optional: bool,
    presence_gate: Option<PathPresenceGate>,
    zero_hop_endpoint_introduced: bool,
) {
    state.path_variables.insert(
        pending.name,
        PathBinding {
            length: pending.length,
            node_variables,
            relationship_variables,
            optional,
            presence_gate,
            zero_hop_endpoint_introduced,
        },
    );
}

fn relationships_pattern_variables(
    pattern: &decypher::ast::pattern::RelationshipsPattern,
    variables: &mut BTreeSet<String>,
) {
    node_pattern_variables(&pattern.start, variables);
    for chain in &pattern.chains {
        relationship_pattern_variables(&chain.relationship, variables);
        node_pattern_variables(&chain.node, variables);
    }
}

fn node_pattern_variables(pattern: &CypherNodePattern, variables: &mut BTreeSet<String>) {
    if let Some(variable) = pattern.variable.as_ref() {
        variables.insert(variable_name(variable));
    }
    for label in &pattern.labels {
        label_expression_variables(label, variables);
    }
    properties_variables(pattern.properties.as_ref(), variables);
}

fn relationship_pattern_variables(
    pattern: &CypherRelationshipPattern,
    variables: &mut BTreeSet<String>,
) {
    let Some(detail) = pattern.detail.as_ref() else {
        return;
    };
    if let Some(variable) = detail.variable.as_ref() {
        variables.insert(variable_name(variable));
    }
    if let Some(types) = detail.types.as_ref() {
        label_expression_variables(types, variables);
    }
    properties_variables(detail.properties.as_ref(), variables);
}

fn properties_variables(properties: Option<&Properties>, variables: &mut BTreeSet<String>) {
    let Some(Properties::Map(map)) = properties else {
        return;
    };
    for (_, expression) in &map.entries {
        expression_variables(expression, variables);
    }
}

fn label_expression_variables(label: &LabelExpression, variables: &mut BTreeSet<String>) {
    match label {
        LabelExpression::Static(_) => {}
        LabelExpression::Dynamic { expression, .. } => expression_variables(expression, variables),
        LabelExpression::Or { lhs, rhs, .. } | LabelExpression::And { lhs, rhs, .. } => {
            label_expression_variables(lhs, variables);
            label_expression_variables(rhs, variables);
        }
        LabelExpression::Not { inner, .. } | LabelExpression::Group { inner, .. } => {
            label_expression_variables(inner, variables);
        }
    }
}

fn expression_variables(expression: &Expression, variables: &mut BTreeSet<String>) {
    match expression {
        Expression::Literal(literal) => literal_variables(literal, variables),
        Expression::Variable(variable) => {
            variables.insert(variable_name(variable));
        }
        Expression::Parameter(_)
        | Expression::CountStar { .. }
        | Expression::Exists(_)
        | Expression::CountSubquery(_)
        | Expression::CollectSubquery(_) => {}
        Expression::PropertyLookup { base, .. } | Expression::NodeLabels { base, .. } => {
            expression_variables(base, variables);
        }
        Expression::BinaryOp { lhs, rhs, .. } | Expression::In { lhs, rhs, .. } => {
            expression_variables(lhs, variables);
            expression_variables(rhs, variables);
        }
        Expression::Comparison { lhs, operators, .. } => {
            expression_variables(lhs, variables);
            for (_, rhs) in operators {
                expression_variables(rhs, variables);
            }
        }
        Expression::UnaryOp { operand, .. } | Expression::IsNull { operand, .. } => {
            expression_variables(operand, variables);
        }
        Expression::ListIndex { list, index, .. } => {
            expression_variables(list, variables);
            expression_variables(index, variables);
        }
        Expression::ListSlice {
            list, start, end, ..
        } => {
            expression_variables(list, variables);
            if let Some(start) = start.as_deref() {
                expression_variables(start, variables);
            }
            if let Some(end) = end.as_deref() {
                expression_variables(end, variables);
            }
        }
        Expression::FunctionCall(function) => {
            for argument in &function.arguments {
                expression_variables(argument, variables);
            }
        }
        Expression::Case(case) => {
            if let Some(scrutinee) = case.scrutinee.as_deref() {
                expression_variables(scrutinee, variables);
            }
            for alternative in &case.alternatives {
                expression_variables(&alternative.when, variables);
                expression_variables(&alternative.then, variables);
            }
            if let Some(default) = case.default.as_deref() {
                expression_variables(default, variables);
            }
        }
        Expression::ListComprehension(comprehension) => {
            if let Some(filter) = comprehension.filter.as_deref() {
                expression_variables(filter, variables);
            }
            if let Some(map) = comprehension.map.as_ref() {
                expression_variables(map, variables);
            }
        }
        Expression::PatternComprehension(comprehension) => {
            if let Some(variable) = comprehension.variable.as_ref() {
                variables.insert(variable_name(variable));
            }
            relationships_pattern_variables(&comprehension.pattern, variables);
            if let Some(where_clause) = comprehension.where_clause.as_ref() {
                expression_variables(where_clause, variables);
            }
            expression_variables(&comprehension.map, variables);
        }
        Expression::All(filter)
        | Expression::Any(filter)
        | Expression::None(filter)
        | Expression::Single(filter) => {
            variables.insert(variable_name(&filter.variable));
            expression_variables(&filter.collection, variables);
            if let Some(predicate) = filter.predicate.as_deref() {
                expression_variables(predicate, variables);
            }
        }
        Expression::Parenthesized(inner) => expression_variables(inner, variables),
        Expression::Pattern(pattern) => relationships_pattern_variables(pattern, variables),
        Expression::MapProjection(map) => {
            variables.insert(variable_name(&map.base));
            for item in &map.items {
                if let decypher::ast::expr::MapProjectionItem::Literal { value, .. } = item {
                    expression_variables(value, variables);
                }
            }
        }
    }
}

fn literal_variables(literal: &CypherLiteral, variables: &mut BTreeSet<String>) {
    match literal {
        CypherLiteral::List(list) => {
            for element in &list.elements {
                expression_variables(element, variables);
            }
        }
        CypherLiteral::Map(map) => {
            for (_, expression) in &map.entries {
                expression_variables(expression, variables);
            }
        }
        CypherLiteral::Number(_)
        | CypherLiteral::String(_)
        | CypherLiteral::Boolean(_)
        | CypherLiteral::Null => {}
    }
}

fn path_pattern_length(pattern_part: &PatternPart, path: &str) -> Result<usize, CoreError> {
    let Some((_, chains)) = pattern_element_path(&pattern_part.anonymous.element) else {
        return Err(unsupported(
            format!("{path}.anonymous"),
            "path variables require a path pattern",
        ));
    };

    let mut length = 0;
    for (index, chain) in chains.iter().enumerate() {
        length += relationship_fixed_length(
            &chain.relationship,
            &format!("{path}.anonymous.relationships[{index}]"),
        )?;
    }
    Ok(length)
}

fn anonymous_pattern_variables(pattern_part: &PatternPart) -> BTreeSet<String> {
    let Some((start, chains)) = pattern_element_path(&pattern_part.anonymous.element) else {
        return BTreeSet::new();
    };
    let mut variables = BTreeSet::new();
    if let Some(variable) = start.variable.as_ref() {
        variables.insert(variable_name(variable));
    }
    for chain in chains {
        if let Some(variable) = chain.node.variable.as_ref() {
            variables.insert(variable_name(variable));
        }
        if let Some(variable) = chain
            .relationship
            .detail
            .as_ref()
            .and_then(|detail| detail.variable.as_ref())
        {
            variables.insert(variable_name(variable));
        }
    }
    variables
}

fn pattern_part_uses_bound_node(pattern_part: &PatternPart, bound_nodes: &BTreeSet<&str>) -> bool {
    let Some((start, chains)) = pattern_element_path(&pattern_part.anonymous.element) else {
        return false;
    };
    node_pattern_uses_bound_variable(start, bound_nodes)
        || chains
            .iter()
            .any(|chain| node_pattern_uses_bound_variable(&chain.node, bound_nodes))
}

fn node_pattern_uses_bound_variable(
    pattern: &CypherNodePattern,
    bound_nodes: &BTreeSet<&str>,
) -> bool {
    pattern
        .variable
        .as_ref()
        .is_some_and(|variable| bound_nodes.contains(variable_name(variable).as_str()))
}

fn compile_node(
    pattern: &CypherNodePattern,
    plan: &GraphPlan,
    state: &CypherCompileState,
    anonymous_variable: String,
    label_hint: Option<&str>,
    path: impl Into<String>,
    context: &CypherCompileContext,
) -> Result<CompiledNode, CoreError> {
    let path = path.into();
    let is_anonymous = pattern.variable.is_none();
    let variable = match pattern.variable.as_ref() {
        Some(variable) => validate_variable(variable)?,
        None => anonymous_variable,
    };
    let label =
        optional_single_compile_time_label(&pattern.labels, format!("{path}.labels"), context)?
            .or_else(|| label_hint.map(str::to_string));
    if is_anonymous && label.is_none() {
        return Err(unsupported(
            format!("{path}.labels"),
            "anonymous node patterns require exactly one static label",
        ));
    }
    let predicates = pattern.properties.as_ref().map_or_else(
        || Ok(Vec::new()),
        |properties| {
            compile_inline_properties(
                properties,
                &variable,
                plan,
                state,
                format!("{path}.properties"),
                context,
            )
        },
    )?;
    if let Some(existing) = plan.nodes.iter().find(|node| node.variable == variable) {
        if let Some(label) = label
            && label != existing.label
        {
            return Err(unsupported(
                format!("{path}.labels"),
                format!(
                    "node variable '{variable}' was already bound with label '{}'",
                    existing.label
                ),
            ));
        }
        return Ok(CompiledNode {
            variable,
            label: existing.label.clone(),
            pattern: None,
            predicates,
        });
    }
    let label = label.ok_or_else(|| {
        unsupported(
            format!("{path}.labels"),
            "a node label is required when a variable is first bound",
        )
    })?;

    Ok(CompiledNode {
        variable: variable.clone(),
        label: label.clone(),
        pattern: Some(NodePattern { variable, label }),
        predicates,
    })
}

fn compile_inline_properties(
    properties: &Properties,
    variable: &str,
    plan: &GraphPlan,
    state: &CypherCompileState,
    path: impl Into<String>,
    context: &CypherCompileContext,
) -> Result<Vec<PropertyPredicate>, CoreError> {
    let path = path.into();
    let Properties::Map(map) = properties else {
        return Err(unsupported(
            path,
            "parameterized property maps are not supported yet",
        ));
    };

    let mut predicates = Vec::with_capacity(map.entries.len());
    for (index, (key, expression)) in map.entries.iter().enumerate() {
        predicates.push(PropertyPredicate {
            property: PropertyRef {
                variable: variable.to_string(),
                property: key.name.name.clone(),
            },
            operator: ComparisonOperator::Equal,
            rhs: compile_inline_property_predicate_rhs(
                expression,
                format!("{path}.entries[{index}].value"),
                plan,
                state,
                context,
            )?,
        });
    }
    Ok(predicates)
}

fn compile_inline_property_predicate_rhs(
    expression: &Expression,
    path: impl Into<String>,
    plan: &GraphPlan,
    state: &CypherCompileState,
    context: &CypherCompileContext,
) -> Result<PredicateRhs, CoreError> {
    let path = path.into();
    if let Some(source) = context.truncated_inline_property_value_source(expression) {
        let (expression, fragment_context) =
            parse_cypher_expression_fragment(&source.source, path.clone(), context)?;
        return compile_inline_property_predicate_rhs_expression(
            &expression,
            path,
            plan,
            state,
            &fragment_context,
        );
    }
    compile_inline_property_predicate_rhs_expression(expression, path, plan, state, context)
}

fn compile_inline_property_predicate_rhs_expression(
    expression: &Expression,
    path: impl Into<String>,
    plan: &GraphPlan,
    state: &CypherCompileState,
    context: &CypherCompileContext,
) -> Result<PredicateRhs, CoreError> {
    let path = path.into();
    if let Some(expression) =
        compile_optional_scalar_alias_expression(expression, path.clone(), Some(state))?
    {
        return scalar_alias_expression_to_predicate_rhs(expression, path);
    }
    if let Some(property) =
        compile_optional_property_ref(expression, path.clone(), Some(plan), context)?
    {
        return Ok(PredicateRhs::Property(property));
    }
    if let Some(variable) = compile_optional_id_ref(expression, path.clone(), plan, context)? {
        return Ok(PredicateRhs::Key { variable });
    }
    if let Some(variable) =
        compile_optional_element_id_ref(expression, path.clone(), plan, context)?
    {
        return Ok(PredicateRhs::ElementId { variable });
    }
    Ok(PredicateRhs::Literal(compile_literal(
        expression, path, context,
    )?))
}

fn scalar_alias_expression_to_predicate_rhs(
    expression: ScalarExpression,
    path: impl Into<String>,
) -> Result<PredicateRhs, CoreError> {
    let path = path.into();
    match expression {
        ScalarExpression::Property(property) => Ok(PredicateRhs::Property(property)),
        ScalarExpression::Key { variable } => Ok(PredicateRhs::Key { variable }),
        ScalarExpression::ElementId { variable } => Ok(PredicateRhs::ElementId { variable }),
        ScalarExpression::Literal(literal) => Ok(PredicateRhs::Literal(literal)),
        ScalarExpression::LiteralList { literals }
        | ScalarExpression::TypedLiteralList { literals, .. } => Ok(PredicateRhs::List(literals)),
        _ => Err(unsupported(
            path,
            "inline property maps can only use WITH scalar aliases backed by graph properties, id(), elementId(), scalar literals, or literal lists",
        )),
    }
}

#[derive(Clone, Copy)]
struct RelationshipCompileEndpoints<'a> {
    left_variable: &'a str,
    right_variable: &'a str,
    left_label: &'a str,
    right_label: &'a str,
}

struct RelationshipCompileOptions {
    index: usize,
    path: String,
    force_variable: bool,
}

fn compile_relationship(
    pattern: &CypherRelationshipPattern,
    endpoints: RelationshipCompileEndpoints<'_>,
    plan: &GraphPlan,
    state: &CypherCompileState,
    options: RelationshipCompileOptions,
    context: &CypherCompileContext,
) -> Result<CompiledRelationship, CoreError> {
    let RelationshipCompileOptions {
        index,
        path,
        force_variable,
    } = options;
    let length = relationship_fixed_length(pattern, &path)?;

    let direction = match pattern.direction {
        CypherRelationshipDirection::Right => Direction::Outgoing,
        CypherRelationshipDirection::Left => Direction::Incoming,
        CypherRelationshipDirection::Both | CypherRelationshipDirection::Undirected => {
            Direction::Undirected
        }
    };

    let detail = pattern.detail.as_ref();
    let relationship_variable = detail.and_then(|detail| detail.variable.as_ref());
    if length == 0 && relationship_variable.is_some() {
        return Err(unsupported(
            format!("{path}.variable"),
            "zero-hop relationship ranges cannot bind a relationship variable because Coral does not materialize relationship lists yet",
        ));
    }
    if length > 1 && relationship_variable.is_some() {
        return Err(unsupported(
            format!("{path}.variable"),
            "fixed-length relationship ranges greater than 1 cannot bind a relationship variable because Coral does not materialize relationship lists yet",
        ));
    }
    let relationship_type = compile_relationship_type(
        detail,
        direction,
        length,
        (endpoints.left_label, endpoints.right_label),
        path.clone(),
        context,
    )?;
    let variable = relationship_variable
        .map(validate_variable)
        .transpose()?
        .or_else(|| {
            (length > 0
                && (force_variable
                    || detail
                        .and_then(|detail| detail.properties.as_ref())
                        .is_some()))
            .then(|| fresh_internal_relationship_variable(plan, endpoints.right_variable, index))
        });
    let predicates = if length == 0 {
        Vec::new()
    } else {
        match (
            detail.and_then(|detail| detail.properties.as_ref()),
            &variable,
        ) {
            (Some(properties), Some(variable)) => compile_inline_properties(
                properties,
                variable,
                plan,
                state,
                format!("{path}.properties"),
                context,
            )?,
            (Some(_), None) => {
                return Err(CoreError::internal(
                    "relationship property predicates require a relationship variable",
                ));
            }
            (None, _) => Vec::new(),
        }
    };

    Ok(CompiledRelationship {
        pattern: RelationshipPattern {
            variable,
            relationship_type,
            left: endpoints.left_variable.to_string(),
            direction,
            right: endpoints.right_variable.to_string(),
        },
        predicates,
        length,
    })
}

fn compile_relationship_type(
    detail: Option<&decypher::ast::pattern::RelationshipDetail>,
    direction: Direction,
    length: usize,
    endpoint_labels: (&str, &str),
    path: impl Into<String>,
    context: &CypherCompileContext,
) -> Result<String, CoreError> {
    let path = path.into();
    if let Some(relationship_type) = detail.and_then(|detail| detail.types.as_ref()) {
        return single_compile_time_label(
            std::slice::from_ref(relationship_type),
            format!("{path}.types"),
            context,
        );
    }
    if length != 1 {
        return Err(unsupported(
            format!("{path}.types"),
            "untyped relationship ranges require an explicit relationship type",
        ));
    }
    let Some(graph) = context.graph.as_ref() else {
        return Err(unsupported(
            format!("{path}.types"),
            "relationship type is required for virtual graph queries unless a graph declaration can infer one from endpoint labels",
        ));
    };
    let (left_label, right_label) = endpoint_labels;
    let candidates = graph
        .relationships
        .iter()
        .filter(|relationship| {
            relationship_mapping_matches_pattern(relationship, direction, left_label, right_label)
        })
        .map(|relationship| relationship.relationship_type.as_str())
        .collect::<BTreeSet<_>>();
    match candidates.len() {
        0 => Err(unsupported(
            format!("{path}.types"),
            format!(
                "relationship pattern could not infer a relationship type from {left_label} to {right_label}; add an explicit relationship type"
            ),
        )),
        1 => Ok(candidates
            .into_iter()
            .next()
            .expect("candidate relationship type set length was checked")
            .to_string()),
        _ => Err(unsupported(
            format!("{path}.types"),
            format!(
                "relationship pattern could not infer a unique relationship type from {left_label} to {right_label}; add an explicit relationship type"
            ),
        )),
    }
}

fn relationship_fixed_length(
    pattern: &CypherRelationshipPattern,
    path: &str,
) -> Result<usize, CoreError> {
    let quantifier_length = pattern
        .quantifier
        .as_ref()
        .map(|quantifier| {
            fixed_length_bounds(
                quantifier.start,
                quantifier.end,
                format!("{path}.quantifier"),
                "relationship quantifiers must be exact non-negative fixed lengths such as {0} or {2}",
            )
        })
        .transpose()?;
    let range_length = pattern
        .detail
        .as_ref()
        .and_then(|detail| detail.range.as_ref())
        .map(|range| {
            fixed_length_bounds(
                range.start,
                range.end,
                format!("{path}.range"),
                "variable-length relationship ranges must be exact non-negative fixed lengths such as *0, *2, or *2..2",
            )
        })
        .transpose()?;

    match (quantifier_length, range_length) {
        (Some(_), Some(_)) => Err(unsupported(
            path,
            "relationship patterns cannot combine a variable-length range and a GQL quantifier",
        )),
        (Some(length), None) | (None, Some(length)) => Ok(length),
        (None, None) => Ok(1),
    }
}

fn fixed_length_bounds(
    start: Option<i64>,
    end: Option<i64>,
    path: impl Into<String>,
    message: impl Into<String>,
) -> Result<usize, CoreError> {
    let path = path.into();
    let message = message.into();
    let (Some(start), Some(end)) = (start, end) else {
        return Err(unsupported(path, message));
    };
    if start != end || start < 0 {
        return Err(unsupported(path, message));
    }
    let length = usize::try_from(start).map_err(|error| {
        unsupported(
            path.clone(),
            format!("fixed relationship length is out of range: {error}"),
        )
    })?;
    if length > MAX_FIXED_RELATIONSHIP_LENGTH {
        return Err(unsupported(
            path,
            format!(
                "fixed relationship length {length} exceeds Coral's current maximum of {MAX_FIXED_RELATIONSHIP_LENGTH} hops"
            ),
        ));
    }
    Ok(length)
}

fn compile_return(
    return_clause: &Return,
    plan: &mut GraphPlan,
    state: &CypherCompileState,
    context: &CypherCompileContext,
) -> Result<(), CoreError> {
    plan.distinct = return_clause.distinct;
    if return_clause.star {
        compile_return_star(plan, state, context, "return.star")?;
    }
    if let Some(skip) = &return_clause.skip {
        plan.skip = Some(compile_skip(skip, "return.skip", context)?);
    }
    if return_clause.items.is_empty() && !return_clause.star {
        return Err(unsupported(
            "return.items",
            "RETURN must include at least one projection",
        ));
    }

    for (index, item) in return_clause.items.iter().enumerate() {
        if let Some(projection) = compile_optional_scalar_alias_return_item(
            item,
            state,
            format!("return.items[{index}]"),
        )? {
            plan.projections.push(projection);
            continue;
        }
        if let Some(projections) = compile_graph_variable_return_item(
            item,
            plan,
            state,
            context,
            format!("return.items[{index}]"),
        )? {
            plan.projections.extend(projections);
            continue;
        }
        if let Some(projections) = compile_graph_endpoint_return_item(
            item,
            plan,
            context,
            format!("return.items[{index}]"),
        )? {
            plan.projections.extend(projections);
            continue;
        }
        let projection =
            compile_projection(item, format!("return.items[{index}]"), context, plan, state)?;
        plan.projections.push(projection);
    }

    if let Some(order) = &return_clause.order {
        for (index, item) in order.items.iter().enumerate() {
            plan.order_by.push(OrderKey {
                expression: compile_order_expression(
                    &item.expression,
                    &plan.projections,
                    plan,
                    state,
                    context,
                    format!("return.order.items[{index}].expression"),
                )?,
                direction: match item.direction {
                    Some(SortDirection::Descending) => OrderDirection::Descending,
                    Some(SortDirection::Ascending) | None => OrderDirection::Ascending,
                },
                nulls: context.order_null_placement(item),
            });
        }
    }

    if let Some(limit) = &return_clause.limit {
        plan.limit = Some(compile_limit(limit, "return.limit", context)?);
    }

    Ok(())
}

fn compile_return_star(
    plan: &mut GraphPlan,
    state: &CypherCompileState,
    context: &CypherCompileContext,
    path: impl Into<String>,
) -> Result<(), CoreError> {
    let path = path.into();
    if !state.path_variables.is_empty() {
        return Err(unsupported(
            path,
            "RETURN * cannot carry path variables because Coral does not materialize path values yet; explicitly project graph variables or length(path)",
        ));
    }
    let graph = context.graph_declaration(path.clone())?;
    let visible = visible_graph_variables(plan, state);
    let node_labels_by_variable = plan
        .nodes
        .iter()
        .map(|node| (node.variable.as_str(), node.label.as_str()))
        .collect::<BTreeMap<_, _>>();
    let mut expansion = ReturnStarExpansion::default();

    for node in &plan.nodes {
        append_return_star_node_projections(node, graph, &visible, &mut expansion, &path)?;
    }

    for relationship in &plan.relationships {
        append_return_star_relationship_projections(
            relationship,
            graph,
            &node_labels_by_variable,
            &visible,
            &mut expansion,
            &path,
        )?;
    }
    for projection in &state.scalar_aliases {
        push_unique_star_projection(&mut expansion, projection.clone(), &path)?;
    }

    if expansion.projections.is_empty() {
        return Err(unsupported(
            path,
            "RETURN * did not resolve any visible graph variables",
        ));
    }
    plan.projections.extend(expansion.projections);
    Ok(())
}

#[derive(Default)]
struct ReturnStarExpansion {
    projections: Vec<Projection>,
    aliases: BTreeSet<String>,
}

fn append_return_star_node_projections(
    node: &NodePattern,
    graph: &Declaration,
    visible: &BTreeSet<String>,
    expansion: &mut ReturnStarExpansion,
    path: &str,
) -> Result<(), CoreError> {
    if !is_visible_star_variable(&node.variable, visible) {
        return Ok(());
    }
    append_node_variable_expansion(node, graph, &node.variable, expansion, path)
}

fn append_node_variable_expansion(
    node: &NodePattern,
    graph: &Declaration,
    output_prefix: &str,
    expansion: &mut ReturnStarExpansion,
    path: &str,
) -> Result<(), CoreError> {
    let mapping = graph.node(&node.label).ok_or_else(|| {
        unsupported(
            path.to_string(),
            format!("could not resolve node label '{}'", node.label),
        )
    })?;
    push_unique_star_projection(
        expansion,
        Projection::Key {
            variable: node.variable.clone(),
            alias: format!("{output_prefix}.__id"),
        },
        path,
    )?;
    push_unique_star_projection(
        expansion,
        Projection::NodeLabels {
            variable: node.variable.clone(),
            label: node.label.clone(),
            alias: format!("{output_prefix}.__labels"),
        },
        path,
    )?;
    for property in mapping.properties.keys() {
        push_unique_star_projection(
            expansion,
            Projection::Property {
                property: PropertyRef {
                    variable: node.variable.clone(),
                    property: property.clone(),
                },
                alias: Some(format!("{output_prefix}.{property}")),
            },
            path,
        )?;
    }
    Ok(())
}

fn append_graph_value_ref_expansion(
    value: &GraphValueRef,
    label: &str,
    graph: &Declaration,
    output_prefix: &str,
    expansion: &mut ReturnStarExpansion,
    path: &str,
) -> Result<(), CoreError> {
    let mapping = graph.node(label).ok_or_else(|| {
        unsupported(
            path.to_string(),
            format!("could not resolve node label '{label}'"),
        )
    })?;
    push_unique_star_projection(
        expansion,
        Projection::Expression {
            expression: graph_value_key_scalar_expression(value.clone()),
            alias: format!("{output_prefix}.__id"),
        },
        path,
    )?;
    push_unique_star_projection(
        expansion,
        Projection::Expression {
            expression: graph_value_labels_scalar_expression(value.clone(), label.to_string()),
            alias: format!("{output_prefix}.__labels"),
        },
        path,
    )?;
    for property in mapping.properties.keys() {
        push_unique_star_projection(
            expansion,
            Projection::Expression {
                expression: graph_value_property_scalar_expression(value.clone(), property.clone()),
                alias: format!("{output_prefix}.{property}"),
            },
            path,
        )?;
    }
    Ok(())
}

fn append_same_label_undirected_endpoint_expansion(
    value: &SameLabelUndirectedEndpointRef,
    graph: &Declaration,
    output_prefix: &str,
    expansion: &mut ReturnStarExpansion,
    path: &str,
) -> Result<(), CoreError> {
    let mapping = graph.node(&value.label).ok_or_else(|| {
        unsupported(
            path.to_string(),
            format!("could not resolve node label '{}'", value.label),
        )
    })?;
    push_unique_star_projection(
        expansion,
        Projection::Expression {
            expression: same_label_undirected_endpoint_key_scalar_expression(value.clone()),
            alias: format!("{output_prefix}.__id"),
        },
        path,
    )?;
    push_unique_star_projection(
        expansion,
        Projection::Expression {
            expression: same_label_undirected_endpoint_labels_scalar_expression(value.clone()),
            alias: format!("{output_prefix}.__labels"),
        },
        path,
    )?;
    for property in mapping.properties.keys() {
        push_unique_star_projection(
            expansion,
            Projection::Expression {
                expression: ScalarExpression::UndirectedEndpointProperty {
                    relationship: value.relationship.clone(),
                    endpoint: value.endpoint,
                    property: property.clone(),
                },
                alias: format!("{output_prefix}.{property}"),
            },
            path,
        )?;
    }
    Ok(())
}

fn append_return_star_relationship_projections(
    relationship: &RelationshipPattern,
    graph: &Declaration,
    node_labels_by_variable: &BTreeMap<&str, &str>,
    visible: &BTreeSet<String>,
    expansion: &mut ReturnStarExpansion,
    path: &str,
) -> Result<(), CoreError> {
    let Some(variable) = relationship.variable.as_ref() else {
        return Ok(());
    };
    if !is_visible_star_variable(variable, visible) {
        return Ok(());
    }
    let mapping =
        return_star_relationship_mapping(graph, relationship, node_labels_by_variable, path)?;
    append_relationship_variable_expansion(relationship, mapping, variable, expansion, path)
}

fn append_relationship_variable_expansion(
    relationship: &RelationshipPattern,
    mapping: &DeclaredRelationship,
    output_prefix: &str,
    expansion: &mut ReturnStarExpansion,
    path: &str,
) -> Result<(), CoreError> {
    let variable = relationship
        .variable
        .as_ref()
        .ok_or_else(|| CoreError::internal("relationship expansion requires a variable"))?;
    if mapping.key.is_some() {
        push_unique_star_projection(
            expansion,
            Projection::Key {
                variable: variable.clone(),
                alias: format!("{output_prefix}.__id"),
            },
            path,
        )?;
    }
    push_unique_star_projection(
        expansion,
        Projection::RelationshipType {
            variable: variable.clone(),
            relationship_type: relationship.relationship_type.clone(),
            alias: format!("{output_prefix}.__type"),
        },
        path,
    )?;
    for property in mapping.properties.keys() {
        push_unique_star_projection(
            expansion,
            Projection::Property {
                property: PropertyRef {
                    variable: variable.clone(),
                    property: property.clone(),
                },
                alias: Some(format!("{output_prefix}.{property}")),
            },
            path,
        )?;
    }
    Ok(())
}

fn compile_graph_variable_return_item(
    item: &ProjectionItem,
    plan: &GraphPlan,
    state: &CypherCompileState,
    context: &CypherCompileContext,
    path: impl Into<String>,
) -> Result<Option<Vec<Projection>>, CoreError> {
    let path = path.into();
    let Expression::Variable(variable) = &item.expression else {
        return Ok(None);
    };
    let name = variable_name(variable);
    reject_ignored_path_variable(&name, state, format!("{path}.expression"))?;
    let visible = visible_graph_variables(plan, state);
    if !is_visible_star_variable(&name, &visible) {
        return Ok(None);
    }
    let graph = context.graph_declaration(format!("{path}.expression"))?;
    let output_prefix = item
        .alias
        .as_ref()
        .map(validate_variable)
        .transpose()?
        .unwrap_or_else(|| name.clone());
    let mut expansion = ReturnStarExpansion::default();
    if let Some(node) = plan.nodes.iter().find(|node| node.variable == name) {
        append_node_variable_expansion(node, graph, &output_prefix, &mut expansion, &path)?;
        return Ok(Some(expansion.projections));
    }
    if let Some(relationship) = plan
        .relationships
        .iter()
        .find(|relationship| relationship.variable.as_deref() == Some(name.as_str()))
    {
        let node_labels_by_variable = plan
            .nodes
            .iter()
            .map(|node| (node.variable.as_str(), node.label.as_str()))
            .collect::<BTreeMap<_, _>>();
        let mapping =
            return_star_relationship_mapping(graph, relationship, &node_labels_by_variable, &path)?;
        append_relationship_variable_expansion(
            relationship,
            mapping,
            &output_prefix,
            &mut expansion,
            &path,
        )?;
        return Ok(Some(expansion.projections));
    }
    Ok(None)
}

fn compile_graph_endpoint_return_item(
    item: &ProjectionItem,
    plan: &GraphPlan,
    context: &CypherCompileContext,
    path: impl Into<String>,
) -> Result<Option<Vec<Projection>>, CoreError> {
    let path = path.into();
    match &item.expression {
        Expression::Parenthesized(inner) => {
            let nested = ProjectionItem {
                expression: inner.as_ref().clone(),
                alias: item.alias.clone(),
            };
            compile_graph_endpoint_return_item(&nested, plan, context, path)
        }
        Expression::FunctionCall(function)
            if is_start_node_function(function) || is_end_node_function(function) =>
        {
            let graph = context.graph_declaration(format!("{path}.expression"))?;
            let output_prefix = relationship_endpoint_return_output_prefix(
                function,
                item.alias.as_ref(),
                context,
                format!("{path}.expression"),
            )?;
            let mut expansion = ReturnStarExpansion::default();
            if let Some(value) = compile_optional_same_label_undirected_relationship_endpoint(
                &item.expression,
                format!("{path}.expression"),
                plan,
                context,
            )? {
                append_same_label_undirected_endpoint_expansion(
                    &value,
                    graph,
                    &output_prefix,
                    &mut expansion,
                    &path,
                )?;
                return Ok(Some(expansion.projections));
            }
            let value = compile_relationship_endpoint_ref(
                function,
                format!("{path}.expression"),
                plan,
                context,
            )?;
            let label =
                node_label_for_variable(plan, &value.variable, format!("{path}.expression"))?;
            append_graph_value_ref_expansion(
                &value,
                label,
                graph,
                &output_prefix,
                &mut expansion,
                &path,
            )?;
            Ok(Some(expansion.projections))
        }
        _ => Ok(None),
    }
}

fn relationship_endpoint_return_output_prefix(
    function: &FunctionInvocation,
    alias: Option<&Variable>,
    context: &CypherCompileContext,
    path: impl Into<String>,
) -> Result<String, CoreError> {
    if let Some(alias) = alias {
        return validate_variable(alias);
    }
    let path = path.into();
    let endpoint = relationship_endpoint_function(function).ok_or_else(|| {
        unsupported(
            path.clone(),
            format!(
                "function '{}' is not a relationship endpoint function",
                qualified_function_name(function)
            ),
        )
    })?;
    let function_name = relationship_endpoint_function_name(endpoint);
    let variable = compile_single_variable_function_argument(
        function,
        format!("{path}.arguments"),
        match endpoint {
            RelationshipEndpoint::Start => {
                "startNode() supports exactly one relationship variable argument"
            }
            RelationshipEndpoint::End => {
                "endNode() supports exactly one relationship variable argument"
            }
        },
        context,
    )?;
    Ok(format!("{function_name}({variable})"))
}

fn is_visible_star_variable(variable: &str, visible: &BTreeSet<String>) -> bool {
    visible.contains(variable) && !is_internal_graph_variable(variable)
}

fn push_unique_star_projection(
    expansion: &mut ReturnStarExpansion,
    projection: Projection,
    path: &str,
) -> Result<(), CoreError> {
    let alias = projection.output_name();
    if !expansion.aliases.insert(alias.clone()) {
        return Err(unsupported(
            path.to_string(),
            format!("RETURN * expansion produced duplicate output column '{alias}'"),
        ));
    }
    expansion.projections.push(projection);
    Ok(())
}

fn return_star_relationship_mapping<'a>(
    graph: &'a Declaration,
    relationship: &RelationshipPattern,
    node_labels_by_variable: &BTreeMap<&str, &str>,
    path: &str,
) -> Result<&'a DeclaredRelationship, CoreError> {
    let left_label = node_labels_by_variable
        .get(relationship.left.as_str())
        .copied()
        .ok_or_else(|| {
            unsupported(
                path.to_string(),
                format!(
                    "RETURN * could not resolve left endpoint '{}'",
                    relationship.left
                ),
            )
        })?;
    let right_label = node_labels_by_variable
        .get(relationship.right.as_str())
        .copied()
        .ok_or_else(|| {
            unsupported(
                path.to_string(),
                format!(
                    "RETURN * could not resolve right endpoint '{}'",
                    relationship.right
                ),
            )
        })?;
    let matches = graph
        .relationships_for_type(&relationship.relationship_type)
        .filter(|mapping| {
            relationship_mapping_matches_pattern(
                mapping,
                relationship.direction,
                left_label,
                right_label,
            )
        })
        .collect::<Vec<_>>();
    match matches.as_slice() {
        [mapping] => Ok(*mapping),
        [] => Err(unsupported(
            path.to_string(),
            format!(
                "RETURN * could not resolve relationship type '{}' for {left_label} -> {right_label}",
                relationship.relationship_type
            ),
        )),
        _ => Err(unsupported(
            path.to_string(),
            format!(
                "RETURN * relationship type '{}' for {left_label} -> {right_label} is ambiguous; add direction or use distinct relationship types",
                relationship.relationship_type
            ),
        )),
    }
}

fn relationship_mapping_matches_pattern(
    mapping: &DeclaredRelationship,
    direction: Direction,
    left_label: &str,
    right_label: &str,
) -> bool {
    let matches_forward = left_label == mapping.from.label && right_label == mapping.to.label;
    let matches_reverse = left_label == mapping.to.label && right_label == mapping.from.label;
    match direction {
        Direction::Outgoing => matches_forward,
        Direction::Incoming => matches_reverse,
        Direction::Undirected => matches_forward || matches_reverse,
    }
}

fn compile_order_expression(
    expression: &Expression,
    projections: &[Projection],
    plan: &GraphPlan,
    state: &CypherCompileState,
    context: &CypherCompileContext,
    path: impl Into<String>,
) -> Result<OrderExpression, CoreError> {
    let path = path.into();
    if let Some((expression, _)) = compile_optional_endpoint_property_scalar_expression(
        expression,
        path.clone(),
        Some(plan),
        context,
    )? {
        return Ok(OrderExpression::Scalar(expression));
    }
    match expression {
        Expression::Parenthesized(inner) => {
            compile_order_expression(inner, projections, plan, state, context, path)
        }
        Expression::Variable(variable) => {
            if let Some(order) =
                optional_projection_order_expression_for_alias(variable, projections, path.clone())?
            {
                return Ok(order);
            }
            if let Some(expression) =
                compile_optional_scalar_alias_expression(expression, path.clone(), Some(state))?
            {
                return compile_scalar_order_expression(expression, projections, path);
            }
            projection_order_expression_for_alias(variable, projections, path)
        }
        Expression::CountStar { .. } => {
            count_star_order_expression_for_projection(projections, path)
        }
        Expression::CountSubquery(count) => compile_scalar_order_expression(
            compile_count_subquery_scalar_expression(count, path.clone(), Some(plan), context)?,
            projections,
            path,
        ),
        expression => {
            compile_order_expression_fallback(expression, projections, plan, state, context, path)
        }
    }
}

fn compile_order_expression_fallback(
    expression: &Expression,
    projections: &[Projection],
    plan: &GraphPlan,
    state: &CypherCompileState,
    context: &CypherCompileContext,
    path: String,
) -> Result<OrderExpression, CoreError> {
    if let Some(order) = compile_optional_path_list_index_order_expression(
        expression,
        projections,
        plan,
        state,
        context,
        path.clone(),
    )? {
        return Ok(order);
    }
    if let Some(expression) = compile_optional_path_list_slice_scalar_expression(
        expression,
        path.clone(),
        PredicateCompileMode::Graph {
            plan,
            path_state: Some(state),
        },
        context,
    )? {
        return compile_scalar_order_expression(expression, projections, path);
    }
    if let Some(expression) = compile_optional_metadata_list_index_scalar_expression(
        expression,
        path.clone(),
        plan,
        context,
    )? {
        return compile_scalar_order_expression(expression, projections, path);
    }
    if let Some(expression) = compile_optional_non_literal_static_list_index_scalar_expression(
        expression,
        path.clone(),
        Some(plan),
        context,
    )? {
        return compile_scalar_order_expression(expression, projections, path);
    }
    if is_list_slice_expression(expression)
        && let Some(value) =
            compile_optional_metadata_list_value(expression, path.clone(), plan, context)?
    {
        return compile_scalar_order_expression(
            metadata_list_value_scalar_expression(value, plan),
            projections,
            path,
        );
    }
    if is_non_literal_static_list_slice_expression(expression)
        && let Some(expression) = compile_optional_static_list_scalar_expression(
            expression,
            path.clone(),
            Some(plan),
            context,
        )?
    {
        return compile_scalar_order_expression(expression, projections, path);
    }
    if matches!(expression, Expression::ListComprehension(_))
        && let Some(expression) = compile_optional_static_list_scalar_expression(
            expression,
            path.clone(),
            Some(plan),
            context,
        )?
    {
        return compile_scalar_order_expression(expression, projections, path);
    }
    compile_order_expression_after_metadata_list_index(
        expression,
        projections,
        plan,
        state,
        context,
        path,
    )
}

fn compile_optional_path_list_index_order_expression(
    expression: &Expression,
    projections: &[Projection],
    plan: &GraphPlan,
    state: &CypherCompileState,
    context: &CypherCompileContext,
    path: impl Into<String>,
) -> Result<Option<OrderExpression>, CoreError> {
    let path = path.into();
    let Some(expression) = compile_optional_path_list_index_scalar_expression(
        expression,
        path.clone(),
        PredicateCompileMode::Graph {
            plan,
            path_state: Some(state),
        },
        context,
    )?
    else {
        return Ok(None);
    };
    compile_scalar_order_expression(expression, projections, path).map(Some)
}

fn compile_order_expression_after_metadata_list_index(
    expression: &Expression,
    projections: &[Projection],
    plan: &GraphPlan,
    state: &CypherCompileState,
    context: &CypherCompileContext,
    path: String,
) -> Result<OrderExpression, CoreError> {
    if let Some(expression) = compile_optional_graph_property_order_expression(
        expression,
        projections,
        plan,
        context,
        &path,
    )? {
        return Ok(expression);
    }
    match expression {
        expression if is_literal_expression(expression) => Ok(OrderExpression::Literal(
            compile_literal(expression, path, context)?,
        )),
        Expression::UnaryOp {
            op: UnaryOperator::Negate,
            ..
        } => compile_path_aware_arithmetic_order_expression(
            expression,
            path,
            projections,
            plan,
            state,
            context,
        ),
        Expression::BinaryOp { .. } => {
            compile_binary_order_expression(expression, path, projections, plan, state, context)
        }
        expression if is_boolean_scalar_expression(expression) => compile_scalar_order_expression(
            compile_boolean_scalar_expression(expression, path.clone(), plan, context)?,
            projections,
            path,
        ),
        Expression::Case(case) => {
            compile_case_order_expression(case, path, projections, plan, state, context)
        }
        Expression::FunctionCall(function) => {
            compile_function_call_order_expression_after_metadata_list_index(
                expression,
                function,
                projections,
                plan,
                state,
                context,
                path,
            )
        }
        _ => Ok(OrderExpression::Property(compile_property_ref(
            expression,
            path,
            Some(plan),
            context,
        )?)),
    }
}

fn compile_function_call_order_expression_after_metadata_list_index(
    expression: &Expression,
    function: &FunctionInvocation,
    projections: &[Projection],
    plan: &GraphPlan,
    state: &CypherCompileState,
    context: &CypherCompileContext,
    path: String,
) -> Result<OrderExpression, CoreError> {
    if is_id_function(function) {
        return compile_id_order_expression(function, path, plan, context);
    }
    if is_element_id_function(function) {
        return compile_element_id_order_expression(function, path, plan, context);
    }
    if is_type_function(function) {
        return compile_type_order_expression(function, path, plan, context);
    }
    if is_labels_function(function) {
        return compile_labels_order_expression(function, path, plan, context);
    }
    if is_keys_function(function) {
        return compile_keys_order_expression_after_metadata_list_index(
            expression,
            function,
            projections,
            plan,
            context,
            path,
        );
    }
    if is_length_function(function) {
        return compile_path_length_order_expression(function, path, state, context);
    }
    if let Some(expression) =
        compile_optional_size_path_length_order_expression(function, path.clone(), state, context)?
    {
        return Ok(expression);
    }
    if let Some(expression) = compile_scalar_function_expression_with_path_state(
        function,
        path.clone(),
        plan,
        Some(state),
        context,
    )? {
        return compile_scalar_order_expression(expression, projections, path);
    }
    if is_aggregate_function_call(function) {
        return aggregate_order_expression_for_projection(
            function,
            projections,
            path,
            plan,
            context,
        );
    }
    Ok(OrderExpression::Property(compile_property_ref(
        expression,
        path,
        Some(plan),
        context,
    )?))
}

fn compile_keys_order_expression_after_metadata_list_index(
    expression: &Expression,
    function: &FunctionInvocation,
    projections: &[Projection],
    plan: &GraphPlan,
    context: &CypherCompileContext,
    path: String,
) -> Result<OrderExpression, CoreError> {
    if is_literal_map_keys_function(function)
        && let Some(expression) = compile_optional_static_list_scalar_expression(
            expression,
            path.clone(),
            Some(plan),
            context,
        )?
    {
        return compile_scalar_order_expression(expression, projections, path);
    }
    compile_keys_order_expression(function, path, plan, context)
}

fn compile_optional_graph_property_order_expression(
    expression: &Expression,
    projections: &[Projection],
    plan: &GraphPlan,
    context: &CypherCompileContext,
    path: &str,
) -> Result<Option<OrderExpression>, CoreError> {
    if let Some((expression, _)) = compile_optional_endpoint_property_scalar_expression(
        expression,
        path.to_string(),
        Some(plan),
        context,
    )? {
        return compile_scalar_order_expression(expression, projections, path.to_string())
            .map(Some);
    }
    if let Some(literal) =
        compile_optional_static_map_lookup_literal(expression, path.to_string(), context)
            .ok()
            .flatten()
    {
        return Ok(Some(OrderExpression::Literal(literal)));
    }
    if let Some(expression) = compile_optional_non_literal_static_map_lookup_scalar_expression(
        expression,
        path.to_string(),
        PredicateCompileMode::Graph {
            plan,
            path_state: None,
        },
        context,
    )? {
        if let ScalarExpression::Property(property) = expression {
            return Ok(Some(OrderExpression::Property(property)));
        }
        return compile_scalar_order_expression(expression, projections, path.to_string())
            .map(Some);
    }
    Ok(
        compile_optional_property_ref(expression, path.to_string(), Some(plan), context)?
            .map(OrderExpression::Property),
    )
}

fn compile_scalar_order_expression(
    expression: ScalarExpression,
    projections: &[Projection],
    path: impl Into<String>,
) -> Result<OrderExpression, CoreError> {
    if scalar_expression_contains_correlated_subquery(&expression) {
        if let Some(alias) = projected_scalar_expression_alias(&expression, projections) {
            return Ok(OrderExpression::ProjectionAlias(alias));
        }
        if hidden_subquery_order_expression_can_be_precomputed(&expression) {
            return Ok(OrderExpression::Scalar(expression));
        }
        return Err(unsupported(
            path,
            "ORDER BY over correlated subqueries must use a projected alias, for example RETURN EXISTS { MATCH ... } AS has_match ORDER BY has_match",
        ));
    }
    Ok(OrderExpression::Scalar(expression))
}

fn hidden_subquery_order_expression_can_be_precomputed(expression: &ScalarExpression) -> bool {
    if let Some(operand) = unary_scalar_expression_operand(expression) {
        return hidden_subquery_order_expression_can_be_precomputed(operand);
    }

    if let Some(precomputable) = hidden_subquery_order_leaf_can_be_precomputed(expression) {
        return precomputable;
    }

    hidden_subquery_order_structural_expression_can_be_precomputed(expression)
}

fn hidden_subquery_order_leaf_can_be_precomputed(expression: &ScalarExpression) -> Option<bool> {
    match expression {
        ScalarExpression::Predicate(predicate) => Some(
            hidden_subquery_order_predicate_can_be_precomputed(predicate),
        ),
        ScalarExpression::CountSubquery { pattern, .. } => Some(match pattern.as_ref() {
            CountSubqueryPattern::Relationships(_) | CountSubqueryPattern::Nodes { .. } => true,
        }),
        ScalarExpression::CollectSubquery { .. } => Some(false),
        ScalarExpression::Property(_)
        | ScalarExpression::UndirectedEndpointProperty { .. }
        | ScalarExpression::UndirectedEndpointKey { .. }
        | ScalarExpression::UndirectedEndpointElementId { .. }
        | ScalarExpression::UndirectedEndpointLabels { .. }
        | ScalarExpression::UndirectedEndpointPropertyKeys { .. }
        | ScalarExpression::Literal(_)
        | ScalarExpression::LiteralList { .. }
        | ScalarExpression::TypedLiteralList { .. }
        | ScalarExpression::GraphKeyList { .. }
        | ScalarExpression::Key { .. }
        | ScalarExpression::ElementId { .. }
        | ScalarExpression::GraphIdentity { .. }
        | ScalarExpression::GraphPresence { .. }
        | ScalarExpression::NodeLabels { .. }
        | ScalarExpression::PropertyKeys { .. }
        | ScalarExpression::RelationshipType { .. } => Some(true),
        ScalarExpression::PresenceGated { .. }
        | ScalarExpression::Coalesce { .. }
        | ScalarExpression::NullIf { .. }
        | ScalarExpression::Replace { .. }
        | ScalarExpression::Substring { .. }
        | ScalarExpression::Left { .. }
        | ScalarExpression::Right { .. }
        | ScalarExpression::StringContains { .. }
        | ScalarExpression::StringStartsWith { .. }
        | ScalarExpression::StringEndsWith { .. }
        | ScalarExpression::Round { .. }
        | ScalarExpression::Arithmetic { .. }
        | ScalarExpression::Atan2 { .. }
        | ScalarExpression::Case { .. } => None,
        ScalarExpression::ToString { .. }
        | ScalarExpression::ToInteger { .. }
        | ScalarExpression::ToFloat { .. }
        | ScalarExpression::ToBoolean { .. }
        | ScalarExpression::ToStringOrNull { .. }
        | ScalarExpression::ToIntegerOrNull { .. }
        | ScalarExpression::ToFloatOrNull { .. }
        | ScalarExpression::ToBooleanOrNull { .. }
        | ScalarExpression::ToLower { .. }
        | ScalarExpression::ToUpper { .. }
        | ScalarExpression::Trim { .. }
        | ScalarExpression::LTrim { .. }
        | ScalarExpression::RTrim { .. }
        | ScalarExpression::CharacterLength { .. }
        | ScalarExpression::Reverse { .. }
        | ScalarExpression::Abs { .. }
        | ScalarExpression::Ceil { .. }
        | ScalarExpression::Floor { .. }
        | ScalarExpression::Sqrt { .. }
        | ScalarExpression::Sign { .. }
        | ScalarExpression::Exp { .. }
        | ScalarExpression::Log { .. }
        | ScalarExpression::Log10 { .. }
        | ScalarExpression::Sin { .. }
        | ScalarExpression::Cos { .. }
        | ScalarExpression::Tan { .. }
        | ScalarExpression::Cot { .. }
        | ScalarExpression::Asin { .. }
        | ScalarExpression::Acos { .. }
        | ScalarExpression::Atan { .. }
        | ScalarExpression::Degrees { .. }
        | ScalarExpression::Radians { .. }
        | ScalarExpression::Negate { .. } => {
            unreachable!("unary scalar expressions handled above")
        }
    }
}

fn hidden_subquery_order_structural_expression_can_be_precomputed(
    expression: &ScalarExpression,
) -> bool {
    match expression {
        ScalarExpression::PresenceGated { expression, .. } => {
            hidden_subquery_order_expression_can_be_precomputed(expression)
        }
        ScalarExpression::Coalesce { expressions } => expressions
            .iter()
            .all(hidden_subquery_order_expression_can_be_precomputed),
        ScalarExpression::NullIf { expression, value } => {
            hidden_subquery_order_expression_can_be_precomputed(expression)
                && hidden_subquery_order_expression_can_be_precomputed(value)
        }
        ScalarExpression::Round { expression, places } => {
            hidden_subquery_order_expression_can_be_precomputed(expression)
                && optional_hidden_subquery_order_expression_can_be_precomputed(places.as_deref())
        }
        ScalarExpression::Left { expression, count }
        | ScalarExpression::Right { expression, count } => {
            hidden_subquery_order_expression_can_be_precomputed(expression)
                && hidden_subquery_order_expression_can_be_precomputed(count)
        }
        ScalarExpression::StringContains {
            expression,
            pattern: operand,
        }
        | ScalarExpression::StringStartsWith {
            expression,
            pattern: operand,
        }
        | ScalarExpression::StringEndsWith {
            expression,
            pattern: operand,
        } => {
            hidden_subquery_order_expression_can_be_precomputed(expression)
                && hidden_subquery_order_expression_can_be_precomputed(operand)
        }
        ScalarExpression::Replace {
            expression,
            search,
            replacement,
        } => {
            hidden_subquery_order_expression_can_be_precomputed(expression)
                && hidden_subquery_order_expression_can_be_precomputed(search)
                && hidden_subquery_order_expression_can_be_precomputed(replacement)
        }
        ScalarExpression::Substring {
            expression,
            start,
            length,
        } => {
            hidden_subquery_order_expression_can_be_precomputed(expression)
                && hidden_subquery_order_expression_can_be_precomputed(start)
                && optional_hidden_subquery_order_expression_can_be_precomputed(length.as_deref())
        }
        ScalarExpression::Arithmetic { left, right, .. } => {
            hidden_subquery_order_expression_can_be_precomputed(left)
                && hidden_subquery_order_expression_can_be_precomputed(right)
        }
        ScalarExpression::Atan2 { y, x } => {
            hidden_subquery_order_expression_can_be_precomputed(y)
                && hidden_subquery_order_expression_can_be_precomputed(x)
        }
        ScalarExpression::Case {
            alternatives,
            else_expression,
        } => {
            hidden_subquery_order_case_can_be_precomputed(alternatives, else_expression.as_deref())
        }
        _ => unreachable!("leaf and unary scalar expressions handled above"),
    }
}

fn optional_hidden_subquery_order_expression_can_be_precomputed(
    expression: Option<&ScalarExpression>,
) -> bool {
    expression.is_none_or(hidden_subquery_order_expression_can_be_precomputed)
}

fn hidden_subquery_order_case_can_be_precomputed(
    alternatives: &[ScalarCaseAlternative],
    else_expression: Option<&ScalarExpression>,
) -> bool {
    alternatives.iter().all(|alternative| {
        hidden_subquery_order_predicate_can_be_precomputed(&alternative.when)
            && hidden_subquery_order_expression_can_be_precomputed(&alternative.then)
    }) && optional_hidden_subquery_order_expression_can_be_precomputed(else_expression)
}

fn hidden_subquery_order_predicate_can_be_precomputed(predicate: &PredicateExpression) -> bool {
    match predicate {
        PredicateExpression::ScalarComparison(predicate) => {
            hidden_subquery_order_expression_can_be_precomputed(&predicate.lhs)
                && match &predicate.rhs {
                    ScalarPredicateRhs::Expression(expression) => {
                        hidden_subquery_order_expression_can_be_precomputed(expression)
                    }
                    ScalarPredicateRhs::List(_) => true,
                }
        }
        PredicateExpression::And { left, right }
        | PredicateExpression::Or { left, right }
        | PredicateExpression::Xor { left, right } => {
            hidden_subquery_order_predicate_can_be_precomputed(left)
                && hidden_subquery_order_predicate_can_be_precomputed(right)
        }
        PredicateExpression::Not { expression } => {
            hidden_subquery_order_predicate_can_be_precomputed(expression)
        }
        PredicateExpression::ExistsPattern(_)
        | PredicateExpression::Boolean(_)
        | PredicateExpression::Comparison(_)
        | PredicateExpression::KeyComparison(_)
        | PredicateExpression::ElementIdComparison(_)
        | PredicateExpression::Presence(_)
        | PredicateExpression::PropertyKeyMembership(_) => true,
    }
}

fn projected_scalar_expression_alias(
    expression: &ScalarExpression,
    projections: &[Projection],
) -> Option<String> {
    projections.iter().find_map(|projection| match projection {
        Projection::Expression {
            expression: projected,
            alias,
        } if projected == expression => Some(alias.clone()),
        _ => None,
    })
}

fn scalar_expression_contains_correlated_subquery(expression: &ScalarExpression) -> bool {
    scalar_expression_correlated_subquery_count(expression) > 0
}

fn scalar_expression_correlated_subquery_count(expression: &ScalarExpression) -> usize {
    if let Some(count) = compound_scalar_expression_correlated_subquery_count(expression) {
        return count;
    }
    scalar_expression_leaf_correlated_subquery_count(expression)
}

fn compound_scalar_expression_correlated_subquery_count(
    expression: &ScalarExpression,
) -> Option<usize> {
    if let Some(operand) = unary_scalar_expression_operand(expression) {
        return Some(scalar_expression_correlated_subquery_count(operand));
    }

    match expression {
        ScalarExpression::PresenceGated { expression, .. } => {
            Some(scalar_expression_correlated_subquery_count(expression))
        }
        ScalarExpression::Coalesce { expressions } => Some(
            expressions
                .iter()
                .map(scalar_expression_correlated_subquery_count)
                .sum(),
        ),
        ScalarExpression::NullIf { expression, value } => Some(
            scalar_expression_correlated_subquery_count(expression)
                + scalar_expression_correlated_subquery_count(value),
        ),
        ScalarExpression::Round { expression, places } => Some(
            scalar_expression_correlated_subquery_count(expression)
                + optional_scalar_expression_correlated_subquery_count(places.as_deref()),
        ),
        ScalarExpression::Left { expression, count }
        | ScalarExpression::Right { expression, count } => Some(
            scalar_expression_correlated_subquery_count(expression)
                + scalar_expression_correlated_subquery_count(count),
        ),
        ScalarExpression::StringContains {
            expression,
            pattern: operand,
        }
        | ScalarExpression::StringStartsWith {
            expression,
            pattern: operand,
        }
        | ScalarExpression::StringEndsWith {
            expression,
            pattern: operand,
        } => Some(
            scalar_expression_correlated_subquery_count(expression)
                + scalar_expression_correlated_subquery_count(operand),
        ),
        ScalarExpression::Replace {
            expression,
            search,
            replacement,
        } => Some(
            scalar_expression_correlated_subquery_count(expression)
                + scalar_expression_correlated_subquery_count(search)
                + scalar_expression_correlated_subquery_count(replacement),
        ),
        ScalarExpression::Substring {
            expression,
            start,
            length,
        } => Some(
            scalar_expression_correlated_subquery_count(expression)
                + scalar_expression_correlated_subquery_count(start)
                + optional_scalar_expression_correlated_subquery_count(length.as_deref()),
        ),
        ScalarExpression::Arithmetic { left, right, .. } => Some(
            scalar_expression_correlated_subquery_count(left)
                + scalar_expression_correlated_subquery_count(right),
        ),
        ScalarExpression::Atan2 { y, x } => Some(
            scalar_expression_correlated_subquery_count(y)
                + scalar_expression_correlated_subquery_count(x),
        ),
        _ => None,
    }
}

fn optional_scalar_expression_correlated_subquery_count(
    expression: Option<&ScalarExpression>,
) -> usize {
    expression.map_or(0, scalar_expression_correlated_subquery_count)
}

fn scalar_expression_leaf_correlated_subquery_count(expression: &ScalarExpression) -> usize {
    match expression {
        ScalarExpression::Predicate(predicate) => {
            predicate_expression_correlated_subquery_count(predicate)
        }
        ScalarExpression::CountSubquery {
            pattern,
            distinct_target,
        } => usize::from(pattern.references_outer_variables() || distinct_target.is_some()),
        ScalarExpression::CollectSubquery { .. } => 1,
        ScalarExpression::Case {
            alternatives,
            else_expression,
        } => scalar_case_expression_correlated_subquery_count(
            alternatives,
            else_expression.as_deref(),
        ),
        ScalarExpression::Property(_)
        | ScalarExpression::UndirectedEndpointProperty { .. }
        | ScalarExpression::UndirectedEndpointKey { .. }
        | ScalarExpression::UndirectedEndpointElementId { .. }
        | ScalarExpression::UndirectedEndpointLabels { .. }
        | ScalarExpression::UndirectedEndpointPropertyKeys { .. }
        | ScalarExpression::Literal(_)
        | ScalarExpression::LiteralList { .. }
        | ScalarExpression::TypedLiteralList { .. }
        | ScalarExpression::GraphKeyList { .. }
        | ScalarExpression::Key { .. }
        | ScalarExpression::ElementId { .. }
        | ScalarExpression::GraphIdentity { .. }
        | ScalarExpression::GraphPresence { .. }
        | ScalarExpression::NodeLabels { .. }
        | ScalarExpression::PropertyKeys { .. }
        | ScalarExpression::RelationshipType { .. } => 0,
        ScalarExpression::PresenceGated { .. }
        | ScalarExpression::Coalesce { .. }
        | ScalarExpression::NullIf { .. }
        | ScalarExpression::Replace { .. }
        | ScalarExpression::Substring { .. }
        | ScalarExpression::Left { .. }
        | ScalarExpression::Right { .. }
        | ScalarExpression::StringContains { .. }
        | ScalarExpression::StringStartsWith { .. }
        | ScalarExpression::StringEndsWith { .. }
        | ScalarExpression::Round { .. }
        | ScalarExpression::Arithmetic { .. }
        | ScalarExpression::Atan2 { .. }
        | ScalarExpression::ToString { .. }
        | ScalarExpression::ToInteger { .. }
        | ScalarExpression::ToFloat { .. }
        | ScalarExpression::ToBoolean { .. }
        | ScalarExpression::ToStringOrNull { .. }
        | ScalarExpression::ToIntegerOrNull { .. }
        | ScalarExpression::ToFloatOrNull { .. }
        | ScalarExpression::ToBooleanOrNull { .. }
        | ScalarExpression::ToLower { .. }
        | ScalarExpression::ToUpper { .. }
        | ScalarExpression::Trim { .. }
        | ScalarExpression::LTrim { .. }
        | ScalarExpression::RTrim { .. }
        | ScalarExpression::CharacterLength { .. }
        | ScalarExpression::Reverse { .. }
        | ScalarExpression::Abs { .. }
        | ScalarExpression::Ceil { .. }
        | ScalarExpression::Floor { .. }
        | ScalarExpression::Sqrt { .. }
        | ScalarExpression::Sign { .. }
        | ScalarExpression::Exp { .. }
        | ScalarExpression::Log { .. }
        | ScalarExpression::Log10 { .. }
        | ScalarExpression::Sin { .. }
        | ScalarExpression::Cos { .. }
        | ScalarExpression::Tan { .. }
        | ScalarExpression::Cot { .. }
        | ScalarExpression::Asin { .. }
        | ScalarExpression::Acos { .. }
        | ScalarExpression::Atan { .. }
        | ScalarExpression::Degrees { .. }
        | ScalarExpression::Radians { .. }
        | ScalarExpression::Negate { .. } => {
            unreachable!("child-bearing scalar expressions handled above")
        }
    }
}

fn scalar_case_expression_correlated_subquery_count(
    alternatives: &[ScalarCaseAlternative],
    else_expression: Option<&ScalarExpression>,
) -> usize {
    alternatives
        .iter()
        .map(|alternative| {
            predicate_expression_correlated_subquery_count(&alternative.when)
                + scalar_expression_correlated_subquery_count(&alternative.then)
        })
        .sum::<usize>()
        + optional_scalar_expression_correlated_subquery_count(else_expression)
}

fn predicate_expression_correlated_subquery_count(predicate: &PredicateExpression) -> usize {
    match predicate {
        PredicateExpression::ExistsPattern(_) => 1,
        PredicateExpression::ScalarComparison(predicate) => {
            scalar_expression_correlated_subquery_count(&predicate.lhs)
                + match &predicate.rhs {
                    ScalarPredicateRhs::Expression(expression) => {
                        scalar_expression_correlated_subquery_count(expression)
                    }
                    ScalarPredicateRhs::List(_) => 0,
                }
        }
        PredicateExpression::And { left, right }
        | PredicateExpression::Or { left, right }
        | PredicateExpression::Xor { left, right } => {
            predicate_expression_correlated_subquery_count(left)
                + predicate_expression_correlated_subquery_count(right)
        }
        PredicateExpression::Not { expression } => {
            predicate_expression_correlated_subquery_count(expression)
        }
        PredicateExpression::Boolean(_)
        | PredicateExpression::Comparison(_)
        | PredicateExpression::KeyComparison(_)
        | PredicateExpression::ElementIdComparison(_)
        | PredicateExpression::Presence(_)
        | PredicateExpression::PropertyKeyMembership(_) => 0,
    }
}

fn count_star_order_expression_for_projection(
    projections: &[Projection],
    path: impl Into<String>,
) -> Result<OrderExpression, CoreError> {
    let path = path.into();
    let aliases = projections
        .iter()
        .filter_map(|projection| match projection {
            Projection::CountAll { alias } => Some(alias.clone()),
            _ => None,
        })
        .collect::<Vec<_>>();
    match aliases.as_slice() {
        [alias] => Ok(OrderExpression::ProjectionAlias(alias.clone())),
        [] => Ok(OrderExpression::CountAll),
        _ => Err(unsupported(
            path,
            "ORDER BY count(*) is ambiguous because multiple RETURN projections match",
        )),
    }
}

fn aggregate_order_expression_for_projection(
    function: &FunctionInvocation,
    projections: &[Projection],
    path: impl Into<String>,
    plan: &GraphPlan,
    context: &CypherCompileContext,
) -> Result<OrderExpression, CoreError> {
    let path = path.into();
    let function_kind = compile_aggregate_function(function, &path, context)?.ok_or_else(|| {
        unsupported(
            path.clone(),
            format!(
                "ORDER BY function '{}' is not supported yet",
                qualified_function_name(function)
            ),
        )
    })?;
    let target =
        compile_function_aggregate_target(function, function_kind, &path, Some(plan), context)?;
    let aliases = projections
        .iter()
        .filter_map(|projection| match projection {
            Projection::Aggregate {
                function: projection_function,
                target: projection_target,
                distinct,
                alias,
            } if *projection_function == function_kind
                && projection_target == &target
                && *distinct == function.distinct =>
            {
                Some(alias.clone())
            }
            _ => None,
        })
        .collect::<Vec<_>>();
    match aliases.as_slice() {
        [alias] => Ok(OrderExpression::ProjectionAlias(alias.clone())),
        [] => Ok(OrderExpression::Aggregate {
            function: function_kind,
            target,
            distinct: function.distinct,
        }),
        _ => Err(unsupported(
            path,
            format!(
                "ORDER BY {}() is ambiguous because multiple RETURN projections match",
                aggregate_function_name(function_kind)
            ),
        )),
    }
}

fn compile_id_order_expression(
    function: &FunctionInvocation,
    path: impl Into<String>,
    plan: &GraphPlan,
    context: &CypherCompileContext,
) -> Result<OrderExpression, CoreError> {
    let path = path.into();
    if let Some(value) = compile_optional_same_label_undirected_endpoint_function_argument(
        function,
        format!("{path}.arguments"),
        plan,
        context,
    )? {
        return Ok(OrderExpression::Scalar(
            same_label_undirected_endpoint_key_scalar_expression(value),
        ));
    }
    let value = compile_id_graph_value_ref(function, path, plan, context)?;
    Ok(match value.presence_variable {
        Some(_) => OrderExpression::Scalar(graph_value_key_scalar_expression(value)),
        None => OrderExpression::Key {
            variable: value.variable,
        },
    })
}

