fn compile_scalar_function_projection(
    function: &FunctionInvocation,
    item: &ProjectionItem,
    path: impl Into<String>,
    plan: &GraphPlan,
    state: &CypherCompileState,
    context: &CypherCompileContext,
) -> Result<Option<Projection>, CoreError> {
    let path = path.into();
    let Some(expression) = compile_scalar_function_expression_with_path_state(
        function,
        format!("{path}.expression"),
        plan,
        Some(state),
        context,
    )?
    else {
        return Ok(None);
    };
    Ok(Some(Projection::Expression {
        expression,
        alias: item
            .alias
            .as_ref()
            .map_or_else(|| default_scalar_function_alias(function), variable_name),
    }))
}

fn validate_aggregate_scalar_target_correlated_subqueries(
    expression: &ScalarExpression,
    path: impl Into<String>,
) -> Result<(), CoreError> {
    if scalar_expression_contains_correlated_subquery(expression) {
        return Err(unsupported(
            path,
            "aggregate expression targets do not support correlated COUNT { ... } or EXISTS { MATCH ... } subqueries",
        ));
    }
    Ok(())
}

fn default_scalar_function_alias(function: &FunctionInvocation) -> String {
    if is_character_length_function(function) {
        return "size".to_string();
    }
    if is_contains_function(function) {
        return "contains".to_string();
    }
    if is_starts_with_function(function) {
        return "startsWith".to_string();
    }
    if is_ends_with_function(function) {
        return "endsWith".to_string();
    }
    qualified_function_name(function)
}

fn compile_coalesce_scalar_expression(
    function: &FunctionInvocation,
    path: impl Into<String>,
    mode: PredicateCompileMode<'_>,
    context: &CypherCompileContext,
) -> Result<ScalarExpression, CoreError> {
    let path = path.into();
    if function.arguments.len() < 2 {
        return Err(unsupported(
            format!("{path}.arguments"),
            "coalesce() requires at least two arguments",
        ));
    }
    if let Some(expression) = compile_optional_static_list_coalesce_scalar_expression(
        function,
        path.clone(),
        mode.static_metadata_plan(),
        context,
    )? {
        return Ok(expression);
    }
    let expressions = function
        .arguments
        .iter()
        .enumerate()
        .map(|(index, expression)| {
            compile_scalar_expression_in_predicate_mode(
                expression,
                format!("{path}.arguments[{index}]"),
                mode,
                context,
            )
        })
        .collect::<Result<Vec<_>, _>>()?;
    Ok(ScalarExpression::Coalesce { expressions })
}

