fn haversin_expression(expression: ScalarExpression) -> ScalarExpression {
    ScalarExpression::Arithmetic {
        operator: ArithmeticOperator::Divide,
        left: Box::new(ScalarExpression::Arithmetic {
            operator: ArithmeticOperator::Subtract,
            left: Box::new(ScalarExpression::Literal(Literal::Integer(1))),
            right: Box::new(ScalarExpression::Cos {
                expression: Box::new(expression),
            }),
        }),
        right: Box::new(ScalarExpression::Literal(Literal::Integer(2))),
    }
}

fn compile_zero_scalar_function_arguments(
    function: &FunctionInvocation,
    path: impl Into<String>,
    function_name: &str,
) -> Result<(), CoreError> {
    let path = path.into();
    if function.arguments.is_empty() {
        return Ok(());
    }
    Err(unsupported(
        format!("{path}.arguments"),
        format!("{function_name}() requires exactly zero arguments"),
    ))
}

fn compile_single_scalar_function_argument(
    function: &FunctionInvocation,
    path: impl Into<String>,
    function_name: &str,
    mode: PredicateCompileMode<'_>,
    context: &CypherCompileContext,
) -> Result<ScalarExpression, CoreError> {
    let path = path.into();
    let [argument] = function.arguments.as_slice() else {
        return Err(unsupported(
            format!("{path}.arguments"),
            format!("{function_name}() requires exactly one argument"),
        ));
    };
    compile_scalar_expression_in_predicate_mode(
        argument,
        format!("{path}.arguments[0]"),
        mode,
        context,
    )
}

fn single_segment_function_name(function: &FunctionInvocation) -> Option<&str> {
    match function.name.as_slice() {
        [name] => Some(name.name.as_str()),
        _ => None,
    }
}

fn compile_two_scalar_function_arguments(
    function: &FunctionInvocation,
    path: impl Into<String>,
    function_name: &str,
    mode: PredicateCompileMode<'_>,
    context: &CypherCompileContext,
) -> Result<(ScalarExpression, ScalarExpression), CoreError> {
    let path = path.into();
    let [left, right] = function.arguments.as_slice() else {
        return Err(unsupported(
            format!("{path}.arguments"),
            format!("{function_name}() requires exactly two arguments"),
        ));
    };
    Ok((
        compile_scalar_expression_in_predicate_mode(
            left,
            format!("{path}.arguments[0]"),
            mode,
            context,
        )?,
        compile_scalar_expression_in_predicate_mode(
            right,
            format!("{path}.arguments[1]"),
            mode,
            context,
        )?,
    ))
}

fn compile_scalar_function_expression_with_path_state(
    function: &FunctionInvocation,
    path: impl Into<String>,
    plan: &GraphPlan,
    path_state: Option<&CypherCompileState>,
    context: &CypherCompileContext,
) -> Result<Option<ScalarExpression>, CoreError> {
    compile_scalar_function_expression_in_mode(
        function,
        path,
        PredicateCompileMode::Graph { plan, path_state },
        context,
    )
}

fn compile_scalar_function_expression_in_mode(
    function: &FunctionInvocation,
    path: impl Into<String>,
    mode: PredicateCompileMode<'_>,
    context: &CypherCompileContext,
) -> Result<Option<ScalarExpression>, CoreError> {
    let path = path.into();
    let plan = mode.static_metadata_plan();
    if is_id_function(function) {
        match plan {
            Some(plan) => {
                compile_key_scalar_expression(function, path.clone(), plan, context).map(Some)
            }
            None => Err(unsupported(
                path,
                "id() scalar expressions require graph context",
            )),
        }
    } else if is_element_id_function(function) {
        match plan {
            Some(plan) => {
                compile_element_id_scalar_expression(function, path.clone(), plan, context)
                    .map(Some)
            }
            None => Err(unsupported(
                path,
                "elementId() scalar expressions require graph context",
            )),
        }
    } else if is_type_function(function) {
        match plan {
            Some(plan) => {
                compile_relationship_type_scalar_expression(function, path.clone(), plan, context)
                    .map(Some)
            }
            None => Err(unsupported(
                path,
                "type() scalar expressions require graph context",
            )),
        }
    } else if let Some(target) = path_list_size_target(function) {
        compile_path_element_id_list_scalar_expression(function, target, path, mode, context)
            .map(Some)
    } else if let Some(expression) =
        compile_core_scalar_function_expression(function, &path, mode, context)?
    {
        Ok(Some(expression))
    } else {
        compile_numeric_scalar_function_expression(function, &path, mode, context)
    }
}

fn compile_core_scalar_function_expression(
    function: &FunctionInvocation,
    path: &str,
    mode: PredicateCompileMode<'_>,
    context: &CypherCompileContext,
) -> Result<Option<ScalarExpression>, CoreError> {
    let plan = mode.static_metadata_plan();
    let expression = if is_coalesce_function(function) {
        compile_coalesce_scalar_expression(function, path, mode, context)?
    } else if is_null_if_function(function) {
        compile_null_if_scalar_expression(function, path, mode, context)?
    } else if is_to_string_function(function) {
        compile_to_string_scalar_expression(function, path, mode, context)?
    } else if is_to_integer_function(function) {
        compile_to_integer_scalar_expression(function, path, mode, context)?
    } else if is_to_float_function(function) {
        compile_to_float_scalar_expression(function, path, mode, context)?
    } else if is_to_boolean_function(function) {
        compile_to_boolean_scalar_expression(function, path, mode, context)?
    } else if is_to_string_or_null_function(function) {
        compile_to_string_or_null_scalar_expression(function, path, mode, context)?
    } else if is_to_integer_or_null_function(function) {
        compile_to_integer_or_null_scalar_expression(function, path, mode, context)?
    } else if is_to_float_or_null_function(function) {
        compile_to_float_or_null_scalar_expression(function, path, mode, context)?
    } else if is_to_boolean_or_null_function(function) {
        compile_to_boolean_or_null_scalar_expression(function, path, mode, context)?
    } else if is_static_list_cast_function(function) {
        compile_static_list_cast_scalar_expression(function, path, plan, context)?
    } else if is_to_lower_function(function) {
        compile_to_lower_scalar_expression(function, path, mode, context)?
    } else if is_to_upper_function(function) {
        compile_to_upper_scalar_expression(function, path, mode, context)?
    } else if is_trim_function(function) {
        compile_trim_scalar_expression(function, path, mode, context)?
    } else if is_ltrim_function(function) {
        compile_ltrim_scalar_expression(function, path, mode, context)?
    } else if is_rtrim_function(function) {
        compile_rtrim_scalar_expression(function, path, mode, context)?
    } else if is_replace_function(function) {
        compile_replace_scalar_expression(function, path, mode, context)?
    } else if is_head_function(function) {
        compile_static_list_endpoint_scalar_expression(
            function,
            path,
            mode,
            context,
            ListEndpoint::Head,
        )?
    } else if is_last_function(function) {
        compile_static_list_endpoint_scalar_expression(
            function,
            path,
            mode,
            context,
            ListEndpoint::Last,
        )?
    } else if is_tail_function(function) {
        compile_static_list_tail_scalar_expression(function, path, mode, context)?
    } else if is_reduce_function(function) {
        compile_static_reduce_scalar_expression(function, path, mode, context)?
    } else if is_character_length_function(function) {
        compile_character_length_scalar_expression(function, path, mode, context)?
    } else if is_substring_function(function) {
        compile_substring_scalar_expression(function, path, mode, context)?
    } else if is_left_function(function) {
        compile_left_scalar_expression(function, path, mode, context)?
    } else if is_right_function(function) {
        compile_right_scalar_expression(function, path, mode, context)?
    } else if is_contains_function(function) {
        compile_contains_scalar_expression(function, path, mode, context)?
    } else if is_starts_with_function(function) {
        compile_starts_with_scalar_expression(function, path, mode, context)?
    } else if is_ends_with_function(function) {
        compile_ends_with_scalar_expression(function, path, mode, context)?
    } else if is_reverse_function(function) {
        compile_reverse_scalar_expression(function, path, mode, context)?
    } else {
        return Ok(None);
    };
    Ok(Some(expression))
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum ListEndpoint {
    Head,
    Last,
}

fn compile_static_list_endpoint_scalar_expression(
    function: &FunctionInvocation,
    path: impl Into<String>,
    mode: PredicateCompileMode<'_>,
    context: &CypherCompileContext,
    endpoint: ListEndpoint,
) -> Result<ScalarExpression, CoreError> {
    let path = path.into();
    let plan = mode.static_metadata_plan();
    let function_name = match endpoint {
        ListEndpoint::Head => "head",
        ListEndpoint::Last => "last",
    };
    let [argument] = function.arguments.as_slice() else {
        return Err(unsupported(
            format!("{path}.arguments"),
            format!("{function_name}() requires exactly one list argument"),
        ));
    };
    if let Some(expression) = compile_optional_path_list_endpoint_scalar_expression(
        argument,
        format!("{path}.arguments[0]"),
        mode,
        context,
        endpoint,
    )? {
        return Ok(expression);
    }
    if let Expression::ListSlice {
        list, start, end, ..
    } = argument
    {
        if let Some(expression) =
            compile_optional_static_list_case_slice_endpoint_scalar_expression(
                list,
                start.as_deref(),
                end.as_deref(),
                format!("{path}.arguments[0]"),
                mode,
                context,
                endpoint,
            )?
        {
            return Ok(expression);
        }
        if let Some(expression) =
            compile_optional_static_list_coalesce_slice_endpoint_scalar_expression(
                list,
                start.as_deref(),
                end.as_deref(),
                format!("{path}.arguments[0]"),
                plan,
                context,
                endpoint,
            )?
        {
            return Ok(expression);
        }
    }
    if let Expression::Case(case) = argument
        && let Some(expression) = compile_optional_static_list_case_endpoint_scalar_expression(
            case,
            format!("{path}.arguments[0]"),
            mode,
            context,
            endpoint,
        )?
    {
        return Ok(expression);
    }
    if let Expression::FunctionCall(function) = argument
        && is_coalesce_function(function)
        && let Some(coalesce) = compile_optional_static_list_coalesce_arguments(
            function,
            format!("{path}.arguments[0]"),
            plan,
            context,
        )?
    {
        return Ok(static_list_coalesce_endpoint_scalar_expression(
            coalesce, endpoint,
        ));
    }
    let Some(value) = compile_optional_static_list_value(
        argument,
        format!("{path}.arguments[0]"),
        plan,
        context,
    )?
    else {
        return Err(unsupported(
            format!("{path}.arguments[0]"),
            format!(
                "{function_name}() requires a literal list, list parameter, static split(...), range(...), or static labels()/keys() metadata list"
            ),
        ));
    };
    Ok(static_list_value_endpoint_scalar_expression(
        value, endpoint,
    ))
}

fn static_list_value_endpoint_scalar_expression(
    value: StaticListValue,
    endpoint: ListEndpoint,
) -> ScalarExpression {
    let literal = match endpoint {
        ListEndpoint::Head => value.literals.first(),
        ListEndpoint::Last => value.literals.last(),
    }
    .cloned()
    .unwrap_or(Literal::Null);
    presence_gate_scalar_expression(value.presence_variable, ScalarExpression::Literal(literal))
}

fn compile_static_list_tail_scalar_expression(
    function: &FunctionInvocation,
    path: impl Into<String>,
    mode: PredicateCompileMode<'_>,
    context: &CypherCompileContext,
) -> Result<ScalarExpression, CoreError> {
    let path = path.into();
    let plan = mode.static_metadata_plan();
    let [argument] = function.arguments.as_slice() else {
        return Err(unsupported(
            format!("{path}.arguments"),
            "tail() requires exactly one list argument",
        ));
    };
    if let Some(expression) = compile_optional_path_list_tail_scalar_expression(
        argument,
        format!("{path}.arguments[0]"),
        mode,
        context,
    )? {
        return Ok(expression);
    }
    let Some(value) = compile_optional_static_list_value(
        argument,
        format!("{path}.arguments[0]"),
        plan,
        context,
    )?
    else {
        return Err(unsupported(
            format!("{path}.arguments[0]"),
            "tail() requires a literal list, list parameter, static split(...), range(...), or static labels()/keys() metadata list",
        ));
    };
    static_list_tail_expression(value, format!("{path}.arguments[0]"))
}

fn compile_static_list_cast_scalar_expression(
    function: &FunctionInvocation,
    path: impl Into<String>,
    plan: Option<&GraphPlan>,
    context: &CypherCompileContext,
) -> Result<ScalarExpression, CoreError> {
    let path = path.into();
    let value = compile_static_list_cast_value(function, path.clone(), plan, context)?;
    static_list_value_scalar_expression(value, path)
}

fn compile_numeric_scalar_function_expression(
    function: &FunctionInvocation,
    path: &str,
    mode: PredicateCompileMode<'_>,
    context: &CypherCompileContext,
) -> Result<Option<ScalarExpression>, CoreError> {
    let expression = if is_abs_function(function) {
        compile_abs_scalar_expression(function, path, mode, context)?
    } else if is_ceil_function(function) {
        compile_ceil_scalar_expression(function, path, mode, context)?
    } else if is_floor_function(function) {
        compile_floor_scalar_expression(function, path, mode, context)?
    } else if is_round_function(function) {
        compile_round_scalar_expression(function, path, mode, context)?
    } else if is_sqrt_function(function) {
        compile_sqrt_scalar_expression(function, path, mode, context)?
    } else if is_sign_function(function) {
        compile_sign_scalar_expression(function, path, mode, context)?
    } else if is_exp_function(function) {
        compile_exp_scalar_expression(function, path, mode, context)?
    } else if is_log_function(function) {
        compile_log_scalar_expression(function, path, mode, context)?
    } else if is_log10_function(function) {
        compile_log10_scalar_expression(function, path, mode, context)?
    } else if is_power_function(function) {
        compile_power_scalar_expression(function, path, mode, context)?
    } else if is_pi_function(function) {
        compile_pi_scalar_expression(function, path)?
    } else if is_e_function(function) {
        compile_e_scalar_expression(function, path)?
    } else if is_sin_function(function) {
        compile_sin_scalar_expression(function, path, mode, context)?
    } else if is_cos_function(function) {
        compile_cos_scalar_expression(function, path, mode, context)?
    } else if is_tan_function(function) {
        compile_tan_scalar_expression(function, path, mode, context)?
    } else if is_cot_function(function) {
        compile_cot_scalar_expression(function, path, mode, context)?
    } else if is_asin_function(function) {
        compile_asin_scalar_expression(function, path, mode, context)?
    } else if is_acos_function(function) {
        compile_acos_scalar_expression(function, path, mode, context)?
    } else if is_atan_function(function) {
        compile_atan_scalar_expression(function, path, mode, context)?
    } else if is_atan2_function(function) {
        compile_atan2_scalar_expression(function, path, mode, context)?
    } else if is_degrees_function(function) {
        compile_degrees_scalar_expression(function, path, mode, context)?
    } else if is_radians_function(function) {
        compile_radians_scalar_expression(function, path, mode, context)?
    } else if is_haversin_function(function) {
        compile_haversin_scalar_expression(function, path, mode, context)?
    } else {
        return Ok(None);
    };
    Ok(Some(expression))
}

fn compile_scalar_expression_with_path_state(
    expression: &Expression,
    path: impl Into<String>,
    plan: &GraphPlan,
    path_state: Option<&CypherCompileState>,
    context: &CypherCompileContext,
) -> Result<ScalarExpression, CoreError> {
    compile_scalar_expression_in_predicate_mode(
        expression,
        path,
        PredicateCompileMode::Graph { plan, path_state },
        context,
    )
}

fn compile_list_index_scalar_expression_in_mode(
    expression: &Expression,
    path: impl Into<String>,
    mode: PredicateCompileMode<'_>,
    context: &CypherCompileContext,
) -> Result<ScalarExpression, CoreError> {
    let path = path.into();
    let plan = mode.static_metadata_plan();
    if let Some(expression) =
        compile_optional_path_list_index_scalar_expression(expression, path.clone(), mode, context)?
    {
        return Ok(expression);
    }
    if let Some(plan) = plan
        && let Some(expression) = compile_optional_metadata_list_index_scalar_expression(
            expression,
            path.clone(),
            plan,
            context,
        )?
    {
        return Ok(expression);
    }
    if let Some(expression) = compile_optional_static_list_index_scalar_expression(
        expression,
        path.clone(),
        plan,
        context,
    )? {
        return Ok(expression);
    }
    Ok(ScalarExpression::Literal(compile_literal(
        expression, path, context,
    )?))
}

fn compile_scalar_expression_in_mode(
    expression: &Expression,
    path: impl Into<String>,
    plan: Option<&GraphPlan>,
    context: &CypherCompileContext,
) -> Result<ScalarExpression, CoreError> {
    compile_scalar_expression_in_predicate_mode(
        expression,
        path,
        PredicateCompileMode::CaseWhen { plan },
        context,
    )
}

fn compile_scalar_expression_in_predicate_mode(
    expression: &Expression,
    path: impl Into<String>,
    mode: PredicateCompileMode<'_>,
    context: &CypherCompileContext,
) -> Result<ScalarExpression, CoreError> {
    let path = path.into();
    let plan = mode.static_metadata_plan();
    match expression {
        Expression::Parenthesized(inner) => {
            compile_scalar_expression_in_predicate_mode(inner, path, mode, context)
        }
        Expression::PropertyLookup { .. } => {
            compile_property_lookup_scalar_expression_in_mode(expression, path, mode, context)
        }
        Expression::ListIndex { .. } => compile_list_index_scalar_or_property_expression_in_mode(
            expression, path, mode, context,
        ),
        Expression::ListSlice { .. } => {
            compile_list_slice_scalar_expression_in_mode(expression, path, mode, context)
        }
        Expression::Variable(_) => {
            compile_scalar_alias_expression(expression, path, mode.scalar_alias_state())
        }
        expression if is_literal_expression(expression) => Ok(ScalarExpression::Literal(
            compile_literal(expression, path, context)?,
        )),
        Expression::BinaryOp { op, lhs, rhs, .. } => {
            if let Some(expression) = compile_optional_static_list_scalar_expression(
                expression,
                path.clone(),
                plan,
                context,
            )? {
                return Ok(expression);
            }
            Ok(ScalarExpression::Arithmetic {
                operator: compile_arithmetic_operator(*op, format!("{path}.operator"))?,
                left: Box::new(compile_scalar_expression_in_predicate_mode(
                    lhs,
                    format!("{path}.lhs"),
                    mode,
                    context,
                )?),
                right: Box::new(compile_scalar_expression_in_predicate_mode(
                    rhs,
                    format!("{path}.rhs"),
                    mode,
                    context,
                )?),
            })
        }
        Expression::UnaryOp {
            op: UnaryOperator::Negate,
            operand,
            ..
        } => Ok(ScalarExpression::Negate {
            expression: Box::new(compile_scalar_expression_in_predicate_mode(
                operand,
                format!("{path}.operand"),
                mode,
                context,
            )?),
        }),
        Expression::Case(case) => compile_case_scalar_expression_in_mode(case, path, mode, context),
        Expression::CountSubquery(count) => {
            compile_count_subquery_scalar_expression(count, path, plan, context)
        }
        Expression::CollectSubquery(collect) => {
            compile_collect_subquery_scalar_expression(collect, path, plan, context)
        }
        Expression::FunctionCall(function) => {
            if let Some(expression) = compile_optional_path_length_scalar_expression(
                expression,
                path.clone(),
                mode,
                context,
            )? {
                return Ok(expression);
            }
            compile_scalar_function_expression_in_mode(function, path.clone(), mode, context)?
                .ok_or_else(|| {
                    unsupported(
                        path,
                        format!(
                            "scalar function '{}' is not supported here",
                            qualified_function_name(function)
                        ),
                    )
                })
        }
        _ => Err(unsupported(
            path,
            "scalar expressions must be variable.property expressions, scalar literals, scalar parameters, arithmetic expressions, unary negation, nested coalesce(), nullIf(), toString(), toInteger(), toFloat(), toBoolean(), nullable scalar casts, toLower()/lower(), toUpper()/upper(), trim()/btrim(), lTrim(), rTrim(), replace(), head(), last(), tail(), reduce(), size(), char_length(), character_length(), substring(), left(), right(), reverse(), abs(), ceil(), floor(), round(), sqrt(), sign(), exp(), log(), log10(), pow()/power(), pi(), e(), sin(), cos(), tan(), cot(), asin(), acos(), atan(), atan2(), degrees(), radians(), or haversin() expressions",
        )),
    }
}

fn compile_property_lookup_scalar_expression_in_mode(
    expression: &Expression,
    path: String,
    mode: PredicateCompileMode<'_>,
    context: &CypherCompileContext,
) -> Result<ScalarExpression, CoreError> {
    let plan = mode.static_metadata_plan();
    if let Some((expression, _)) = compile_optional_endpoint_property_scalar_expression(
        expression,
        path.clone(),
        plan,
        context,
    )? {
        return Ok(expression);
    }
    if let Some(expression) = compile_optional_static_map_lookup_scalar_expression(
        expression,
        path.clone(),
        mode,
        context,
    )? {
        return Ok(expression);
    }
    Ok(ScalarExpression::Property(compile_property_ref(
        expression, path, plan, context,
    )?))
}

fn compile_list_index_scalar_or_property_expression_in_mode(
    expression: &Expression,
    path: String,
    mode: PredicateCompileMode<'_>,
    context: &CypherCompileContext,
) -> Result<ScalarExpression, CoreError> {
    let plan = mode.static_metadata_plan();
    if let Some((expression, _)) = compile_optional_endpoint_property_scalar_expression(
        expression,
        path.clone(),
        plan,
        context,
    )? {
        return Ok(expression);
    }
    if let Some(property) = compile_optional_property_ref(expression, path.clone(), plan, context)?
    {
        return Ok(ScalarExpression::Property(property));
    }
    compile_list_index_scalar_expression_in_mode(expression, path, mode, context)
}

fn compile_list_slice_scalar_expression_in_mode(
    expression: &Expression,
    path: impl Into<String>,
    mode: PredicateCompileMode<'_>,
    context: &CypherCompileContext,
) -> Result<ScalarExpression, CoreError> {
    let path = path.into();
    let plan = mode.static_metadata_plan();
    if let Some(expression) =
        compile_optional_path_list_slice_scalar_expression(expression, path.clone(), mode, context)?
    {
        return Ok(expression);
    }
    if let Some(expression) =
        compile_optional_static_list_scalar_expression(expression, path.clone(), plan, context)?
    {
        return Ok(expression);
    }
    Ok(ScalarExpression::LiteralList {
        literals: compile_literal_list(expression, path, context)?,
    })
}

fn compile_scalar_alias_expression(
    expression: &Expression,
    path: impl Into<String>,
    state: Option<&CypherCompileState>,
) -> Result<ScalarExpression, CoreError> {
    let path = path.into();
    compile_optional_scalar_alias_expression(expression, path.clone(), state)?.ok_or_else(|| {
        unsupported(
            path,
            "bare variables in scalar expressions must be in-scope WITH scalar aliases",
        )
    })
}

enum ProjectionLiteral {
    Scalar(Literal),
    List(Vec<Literal>),
}

fn compile_projection_literal(
    expression: &Expression,
    path: impl Into<String>,
    context: &CypherCompileContext,
) -> Result<ProjectionLiteral, CoreError> {
    let path = path.into();
    match expression {
        Expression::Parenthesized(inner) => compile_projection_literal(inner, path, context),
        Expression::Literal(CypherLiteral::List(list)) => {
            let literals = list
                .elements
                .iter()
                .enumerate()
                .map(|(index, expression)| {
                    compile_literal(expression, format!("{path}[{index}]"), context)
                })
                .collect::<Result<Vec<_>, _>>()?;
            validate_literal_list_projection(&literals, path)?;
            Ok(ProjectionLiteral::List(literals))
        }
        Expression::ListSlice { .. } => {
            let literals = compile_literal_list(expression, path.clone(), context)?;
            validate_literal_list_projection(&literals, path)?;
            Ok(ProjectionLiteral::List(literals))
        }
        Expression::Parameter(parameter) => {
            match context.parameter_value(parameter, path.clone())? {
                CypherParameterValue::Literal(value) => {
                    Ok(ProjectionLiteral::Scalar(value.clone()))
                }
                CypherParameterValue::List(values) => {
                    validate_literal_list_projection(values, path)?;
                    Ok(ProjectionLiteral::List(values.clone()))
                }
            }
        }
        _ => compile_literal(expression, path, context).map(ProjectionLiteral::Scalar),
    }
}

fn compile_id_projection(
    function: &FunctionInvocation,
    item: &ProjectionItem,
    path: impl Into<String>,
    plan: &GraphPlan,
    context: &CypherCompileContext,
) -> Result<Projection, CoreError> {
    let path = path.into();
    let alias = item
        .alias
        .as_ref()
        .map_or_else(|| "id".to_string(), variable_name);
    if let Some(value) = compile_optional_same_label_undirected_endpoint_function_argument(
        function,
        format!("{path}.expression.arguments"),
        plan,
        context,
    )? {
        return Ok(Projection::Expression {
            expression: same_label_undirected_endpoint_key_scalar_expression(value),
            alias,
        });
    }
    let value = compile_id_graph_value_ref(function, format!("{path}.expression"), plan, context)?;
    Ok(match value.presence_variable {
        Some(_) => Projection::Expression {
            expression: graph_value_key_scalar_expression(value),
            alias,
        },
        None => Projection::Key {
            variable: value.variable,
            alias,
        },
    })
}

fn compile_element_id_projection(
    function: &FunctionInvocation,
    item: &ProjectionItem,
    path: impl Into<String>,
    plan: &GraphPlan,
    context: &CypherCompileContext,
) -> Result<Projection, CoreError> {
    let path = path.into();
    let alias = item
        .alias
        .as_ref()
        .map_or_else(|| "elementId".to_string(), variable_name);
    if let Some(value) = compile_optional_same_label_undirected_endpoint_function_argument(
        function,
        format!("{path}.expression.arguments"),
        plan,
        context,
    )? {
        return Ok(Projection::Expression {
            expression: same_label_undirected_endpoint_element_id_scalar_expression(value),
            alias,
        });
    }
    let value =
        compile_element_id_graph_value_ref(function, format!("{path}.expression"), plan, context)?;
    Ok(match value.presence_variable {
        Some(_) => Projection::Expression {
            expression: graph_value_element_id_scalar_expression(value),
            alias,
        },
        None => Projection::ElementId {
            variable: value.variable,
            alias,
        },
    })
}

fn compile_internal_graph_identity_projection(
    function: &FunctionInvocation,
    item: &ProjectionItem,
    path: impl Into<String>,
    plan: &GraphPlan,
    context: &CypherCompileContext,
) -> Result<Projection, CoreError> {
    let path = path.into();
    let variable = compile_single_variable_function_argument(
        function,
        format!("{path}.expression.arguments"),
        "internal graph identity requires exactly one graph variable argument",
        context,
    )?;
    if !plan_uses_variable(plan, &variable) {
        return Err(unsupported(
            format!("{path}.expression.arguments[0]"),
            format!("internal graph identity argument '{variable}' is not a bound graph variable"),
        ));
    }
    Ok(Projection::Expression {
        expression: ScalarExpression::GraphIdentity { variable },
        alias: item
            .alias
            .as_ref()
            .map_or_else(|| "graphIdentity".to_string(), variable_name),
    })
}

fn compile_internal_graph_presence_projection(
    function: &FunctionInvocation,
    item: &ProjectionItem,
    path: impl Into<String>,
    plan: &GraphPlan,
    context: &CypherCompileContext,
) -> Result<Projection, CoreError> {
    let path = path.into();
    let variable = compile_single_variable_function_argument(
        function,
        format!("{path}.expression.arguments"),
        "internal graph presence requires exactly one graph variable argument",
        context,
    )?;
    if !plan_uses_variable(plan, &variable) {
        return Err(unsupported(
            format!("{path}.expression.arguments[0]"),
            format!("internal graph presence argument '{variable}' is not a bound graph variable"),
        ));
    }
    Ok(Projection::Expression {
        expression: ScalarExpression::GraphPresence { variable },
        alias: item
            .alias
            .as_ref()
            .map_or_else(|| "graphPresence".to_string(), variable_name),
    })
}

fn compile_type_projection(
    function: &FunctionInvocation,
    item: &ProjectionItem,
    path: impl Into<String>,
    plan: &GraphPlan,
    context: &CypherCompileContext,
) -> Result<Projection, CoreError> {
    let path = path.into();
    let variable = compile_single_variable_function_argument(
        function,
        format!("{path}.expression.arguments"),
        "type() supports exactly one relationship variable argument",
        context,
    )?;
    let relationship = plan
        .relationships
        .iter()
        .find(|relationship| relationship.variable.as_deref() == Some(variable.as_str()))
        .ok_or_else(|| {
            unsupported(
                format!("{path}.expression.arguments[0]"),
                format!("type() argument '{variable}' is not a named relationship variable"),
            )
        })?;
    Ok(Projection::RelationshipType {
        variable,
        relationship_type: relationship.relationship_type.clone(),
        alias: item
            .alias
            .as_ref()
            .map_or_else(|| "type".to_string(), variable_name),
    })
}

fn compile_labels_projection(
    function: &FunctionInvocation,
    item: &ProjectionItem,
    path: impl Into<String>,
    plan: &GraphPlan,
    context: &CypherCompileContext,
) -> Result<Projection, CoreError> {
    let path = path.into();
    if let Some(value) = compile_optional_same_label_undirected_endpoint_function_argument(
        function,
        format!("{path}.expression.arguments"),
        plan,
        context,
    )? {
        return Ok(Projection::Expression {
            expression: same_label_undirected_endpoint_labels_scalar_expression(value),
            alias: item
                .alias
                .as_ref()
                .map_or_else(|| "labels".to_string(), variable_name),
        });
    }
    let (value, label) = compile_node_function_target_ref(
        function,
        format!("{path}.expression.arguments"),
        "labels() supports exactly one node variable argument",
        plan,
        context,
    )?;
    if value.presence_variable.is_some() {
        return Ok(Projection::Expression {
            expression: graph_value_labels_scalar_expression(value, label),
            alias: item
                .alias
                .as_ref()
                .map_or_else(|| "labels".to_string(), variable_name),
        });
    }
    Ok(Projection::NodeLabels {
        variable: value.variable,
        label,
        alias: item
            .alias
            .as_ref()
            .map_or_else(|| "labels".to_string(), variable_name),
    })
}

fn compile_labels_order_expression(
    function: &FunctionInvocation,
    path: impl Into<String>,
    plan: &GraphPlan,
    context: &CypherCompileContext,
) -> Result<OrderExpression, CoreError> {
    let path = path.into();
    if let Some(value) = compile_optional_same_label_undirected_endpoint_function_argument(
        function,
        format!("{path}.arguments"),
        plan,
        context,
    )? {
        return Ok(OrderExpression::Scalar(
            same_label_undirected_endpoint_labels_scalar_expression(value),
        ));
    }
    let (value, label) = compile_node_function_target_ref(
        function,
        format!("{path}.arguments"),
        "labels() supports exactly one node variable argument",
        plan,
        context,
    )?;
    if value.presence_variable.is_some() {
        return Ok(OrderExpression::Scalar(
            graph_value_labels_scalar_expression(value, label),
        ));
    }
    Ok(OrderExpression::NodeLabels {
        variable: value.variable,
        label,
    })
}

fn compile_keys_order_expression(
    function: &FunctionInvocation,
    path: impl Into<String>,
    plan: &GraphPlan,
    context: &CypherCompileContext,
) -> Result<OrderExpression, CoreError> {
    let path = path.into();
    if let Some(value) = compile_optional_same_label_undirected_endpoint_function_argument(
        function,
        format!("{path}.arguments"),
        plan,
        context,
    )? {
        return Ok(OrderExpression::Scalar(
            same_label_undirected_endpoint_keys_scalar_expression(value),
        ));
    }
    let value = compile_single_graph_value_function_argument_ref(
        function,
        format!("{path}.arguments"),
        "keys() supports exactly one graph variable argument",
        plan,
        context,
    )?;
    if !plan_uses_variable(plan, &value.variable) {
        return Err(unsupported(
            format!("{path}.arguments[0]"),
            format!(
                "keys() argument '{}' is not a bound graph variable",
                value.variable
            ),
        ));
    }
    if value.presence_variable.is_some() {
        return Ok(OrderExpression::Scalar(graph_value_keys_scalar_expression(
            value,
        )));
    }
    Ok(OrderExpression::PropertyKeys {
        variable: value.variable,
    })
}

fn compile_arithmetic_order_expression(
    expression: &Expression,
    path: impl Into<String>,
    projections: &[Projection],
    plan: &GraphPlan,
    path_state: Option<&CypherCompileState>,
    context: &CypherCompileContext,
) -> Result<OrderExpression, CoreError> {
    let path = path.into();
    compile_scalar_order_expression(
        compile_scalar_expression_with_path_state(
            expression,
            path.clone(),
            plan,
            path_state,
            context,
        )?,
        projections,
        path,
    )
}

fn compile_binary_order_expression(
    expression: &Expression,
    path: impl Into<String>,
    projections: &[Projection],
    plan: &GraphPlan,
    state: &CypherCompileState,
    context: &CypherCompileContext,
) -> Result<OrderExpression, CoreError> {
    let path = path.into();
    if let Some(expression) = compile_optional_static_list_scalar_expression(
        expression,
        path.clone(),
        Some(plan),
        context,
    )? {
        return compile_scalar_order_expression(expression, projections, path);
    }
    if let Some(expression) =
        compile_optional_boolean_scalar_expression(expression, path.clone(), plan, context)?
    {
        return compile_scalar_order_expression(expression, projections, path);
    }
    compile_path_aware_arithmetic_order_expression(
        expression,
        path,
        projections,
        plan,
        state,
        context,
    )
}

fn compile_path_aware_arithmetic_order_expression(
    expression: &Expression,
    path: impl Into<String>,
    projections: &[Projection],
    plan: &GraphPlan,
    state: &CypherCompileState,
    context: &CypherCompileContext,
) -> Result<OrderExpression, CoreError> {
    compile_arithmetic_order_expression(expression, path, projections, plan, Some(state), context)
}

fn compile_case_order_expression(
    case: &CaseExpression,
    path: impl Into<String>,
    projections: &[Projection],
    plan: &GraphPlan,
    state: &CypherCompileState,
    context: &CypherCompileContext,
) -> Result<OrderExpression, CoreError> {
    let path = path.into();
    compile_scalar_order_expression(
        compile_case_scalar_expression_with_path_state(
            case,
            path.clone(),
            plan,
            Some(state),
            context,
        )?,
        projections,
        path,
    )
}

fn compile_optional_boolean_scalar_expression(
    expression: &Expression,
    path: impl Into<String>,
    plan: &GraphPlan,
    context: &CypherCompileContext,
) -> Result<Option<ScalarExpression>, CoreError> {
    let path = path.into();
    if is_boolean_scalar_expression(expression) {
        return compile_boolean_scalar_expression(expression, path, plan, context).map(Some);
    }
    Ok(None)
}

fn compile_boolean_scalar_expression(
    expression: &Expression,
    path: impl Into<String>,
    plan: &GraphPlan,
    context: &CypherCompileContext,
) -> Result<ScalarExpression, CoreError> {
    compile_predicate_expression(expression, path, plan, context)
        .map(|predicate| ScalarExpression::Predicate(Box::new(predicate)))
}

fn is_boolean_scalar_expression(expression: &Expression) -> bool {
    match expression {
        Expression::Parenthesized(inner) => is_boolean_scalar_expression(inner),
        Expression::BinaryOp {
            op: CypherBinaryOperator::And | CypherBinaryOperator::Or | CypherBinaryOperator::Xor,
            ..
        }
        | Expression::UnaryOp {
            op: UnaryOperator::Not,
            ..
        }
        | Expression::Comparison { .. }
        | Expression::In { .. }
        | Expression::IsNull { .. }
        | Expression::NodeLabels { .. }
        | Expression::Exists(_)
        | Expression::All(_)
        | Expression::Any(_)
        | Expression::None(_)
        | Expression::Single(_) => true,
        Expression::FunctionCall(function) => {
            is_exists_function(function)
                || is_empty_function(function)
                || collection_quantifier_function(function).is_some()
        }
        _ => false,
    }
}

fn compile_optional_predicate_scalar_expression(
    expression: &Expression,
    path: impl Into<String>,
    mode: PredicateCompileMode<'_>,
    context: &CypherCompileContext,
) -> Result<Option<ScalarExpression>, CoreError> {
    let path = path.into();
    let plan = mode.static_metadata_plan();
    if let Some(expression) =
        compile_optional_static_map_lookup_predicate_scalar(expression, &path, mode, context)?
    {
        return Ok(Some(expression));
    }
    match expression {
        Expression::Parenthesized(inner) => {
            compile_optional_predicate_scalar_expression(inner, path, mode, context)
        }
        Expression::ListIndex { .. } => {
            compile_optional_predicate_list_index_scalar_expression(expression, path, mode, context)
        }
        Expression::ListSlice { .. } => {
            compile_optional_predicate_list_slice_scalar_expression(expression, path, mode, context)
        }
        Expression::PropertyLookup { .. } => Ok(
            compile_optional_endpoint_property_scalar_expression(expression, path, plan, context)?
                .map(|(expression, _)| expression),
        ),
        Expression::Variable(_) => {
            compile_optional_scalar_alias_expression(expression, path, mode.scalar_alias_state())
        }
        Expression::BinaryOp { .. } => Ok(Some(compile_scalar_expression_in_predicate_mode(
            expression, path, mode, context,
        )?)),
        Expression::UnaryOp {
            op: UnaryOperator::Negate,
            operand,
            ..
        } if !is_literal_expression(operand) => Ok(Some(
            compile_scalar_expression_in_predicate_mode(expression, path, mode, context)?,
        )),
        Expression::Case(case) => Ok(Some(compile_case_scalar_expression_in_mode(
            case,
            path,
            PredicateCompileMode::CaseWhen { plan },
            context,
        )?)),
        Expression::CountSubquery(count) => Ok(Some(compile_count_subquery_scalar_expression(
            count, path, plan, context,
        )?)),
        Expression::FunctionCall(function) if is_id_function(function) => {
            let Some(plan) = plan else {
                return Ok(None);
            };
            let value = compile_id_graph_value_ref(function, path, plan, context)?;
            Ok(value
                .presence_variable
                .is_some()
                .then(|| graph_value_key_scalar_expression(value)))
        }
        Expression::FunctionCall(function) if is_element_id_function(function) => {
            let Some(plan) = plan else {
                return Ok(None);
            };
            let value = compile_element_id_graph_value_ref(function, path, plan, context)?;
            Ok(value
                .presence_variable
                .is_some()
                .then(|| graph_value_element_id_scalar_expression(value)))
        }
        Expression::FunctionCall(function)
            if is_start_node_function(function) || is_end_node_function(function) =>
        {
            let Some(plan) = plan else {
                return Ok(None);
            };
            let value = compile_relationship_endpoint_ref(function, path, plan, context)?;
            Ok(value
                .presence_variable
                .is_some()
                .then(|| graph_value_presence_scalar_expression(value)))
        }
        Expression::FunctionCall(function) if is_type_function(function) => Ok(None),
        Expression::FunctionCall(function) => {
            compile_scalar_function_expression_in_mode(function, path, mode, context)
        }
        _ => Ok(None),
    }
}

fn compile_optional_predicate_list_index_scalar_expression(
    expression: &Expression,
    path: impl Into<String>,
    mode: PredicateCompileMode<'_>,
    context: &CypherCompileContext,
) -> Result<Option<ScalarExpression>, CoreError> {
    let path = path.into();
    let Some(plan) = mode.static_metadata_plan() else {
        return Ok(None);
    };
    if let Some(expression) =
        compile_optional_path_list_index_scalar_expression(expression, path.clone(), mode, context)?
    {
        return Ok(Some(expression));
    }
    if let Some(expression) = compile_optional_metadata_list_index_scalar_expression(
        expression,
        path.clone(),
        plan,
        context,
    )? {
        return Ok(Some(expression));
    }
    compile_optional_static_list_index_scalar_expression(expression, path, Some(plan), context)
}

fn compile_optional_static_map_lookup_predicate_scalar(
    expression: &Expression,
    path: &str,
    mode: PredicateCompileMode<'_>,
    context: &CypherCompileContext,
) -> Result<Option<ScalarExpression>, CoreError> {
    compile_optional_non_literal_static_map_lookup_scalar_expression(
        expression,
        path.to_string(),
        mode,
        context,
    )
}

fn compile_optional_predicate_list_slice_scalar_expression(
    expression: &Expression,
    path: impl Into<String>,
    mode: PredicateCompileMode<'_>,
    context: &CypherCompileContext,
) -> Result<Option<ScalarExpression>, CoreError> {
    let path = path.into();
    let Some(plan) = mode.static_metadata_plan() else {
        return Ok(None);
    };
    if let Some(expression) =
        compile_optional_path_list_slice_scalar_expression(expression, path.clone(), mode, context)?
    {
        return Ok(Some(expression));
    }
    compile_optional_static_list_scalar_expression(expression, path, Some(plan), context)
}

fn compile_scalar_predicate_rhs(
    expression: &Expression,
    path: impl Into<String>,
    mode: PredicateCompileMode<'_>,
    context: &CypherCompileContext,
) -> Result<ScalarPredicateRhs, CoreError> {
    let path = path.into();
    if let Some(expression) =
        compile_optional_path_length_scalar_expression(expression, path.clone(), mode, context)?
    {
        return Ok(ScalarPredicateRhs::Expression(expression));
    }
    let plan = mode.static_metadata_plan();
    match expression {
        Expression::Parenthesized(inner) => {
            compile_scalar_predicate_rhs(inner, path, mode, context)
        }
        Expression::BinaryOp { .. }
        | Expression::UnaryOp {
            op: UnaryOperator::Negate,
            ..
        }
        | Expression::PropertyLookup { .. }
        | Expression::ListIndex { .. }
        | Expression::ListSlice { .. } => Ok(ScalarPredicateRhs::Expression(
            compile_scalar_expression_in_predicate_mode(expression, path, mode, context)?,
        )),
        Expression::Variable(_) => {
            let Some(expression) = compile_optional_scalar_alias_expression(
                expression,
                path.clone(),
                mode.scalar_alias_state(),
            )?
            else {
                return Err(unsupported(
                    path,
                    "scalar predicates can only use bare variables when they are in-scope WITH scalar aliases",
                ));
            };
            Ok(ScalarPredicateRhs::Expression(expression))
        }
        Expression::Case(case) => Ok(ScalarPredicateRhs::Expression(
            compile_case_scalar_expression_in_mode(case, path, mode, context)?,
        )),
        Expression::CountSubquery(count) => Ok(ScalarPredicateRhs::Expression(
            compile_count_subquery_scalar_expression(count, path, plan, context)?,
        )),
        Expression::FunctionCall(function) => {
            match compile_scalar_function_expression_in_mode(function, path.clone(), mode, context)?
            {
                Some(expression) => Ok(ScalarPredicateRhs::Expression(expression)),
                None => Err(unsupported(
                    path,
                    "scalar predicates support variable.property expressions, scalar literals, scalar parameters, arithmetic expressions, unary negation, nested coalesce(), nullIf(), toString(), toInteger(), toFloat(), toBoolean(), nullable scalar casts, toLower()/lower(), toUpper()/upper(), trim()/btrim(), lTrim(), rTrim(), replace(), head(), last(), tail(), size(), char_length(), character_length(), substring(), left(), right(), reverse(), abs(), ceil(), floor(), round(), sqrt(), sign(), exp(), log(), log10(), pi(), e(), sin(), cos(), tan(), cot(), asin(), acos(), atan(), atan2(), degrees(), radians(), or haversin() expressions",
                )),
            }
        }
        expression if is_literal_expression(expression) => Ok(ScalarPredicateRhs::Expression(
            ScalarExpression::Literal(compile_literal(expression, path, context)?),
        )),
        _ => Err(unsupported(
            path,
            "scalar predicates support variable.property expressions, scalar literals, scalar parameters, arithmetic expressions, unary negation, nested coalesce(), nullIf(), toString(), toInteger(), toFloat(), toBoolean(), nullable scalar casts, toLower()/lower(), toUpper()/upper(), trim()/btrim(), lTrim(), rTrim(), replace(), head(), last(), tail(), size(), char_length(), character_length(), substring(), left(), right(), reverse(), abs(), ceil(), floor(), round(), sqrt(), sign(), exp(), log(), log10(), pi(), e(), sin(), cos(), tan(), cot(), asin(), acos(), atan(), atan2(), degrees(), radians(), or haversin() expressions",
        )),
    }
}

fn compile_optional_path_length_scalar_expression(
    expression: &Expression,
    path: impl Into<String>,
    mode: PredicateCompileMode<'_>,
    context: &CypherCompileContext,
) -> Result<Option<ScalarExpression>, CoreError> {
    let path = path.into();
    let function = match expression {
        Expression::Parenthesized(inner) => {
            return compile_optional_path_length_scalar_expression(inner, path, mode, context);
        }
        Expression::FunctionCall(function) if is_length_function(function) => function,
        Expression::FunctionCall(function) if is_size_function(function) => {
            let Some(state) = mode.path_state() else {
                return Ok(None);
            };
            return compile_optional_size_path_length_scalar_expression(
                function,
                format!("{path}.arguments"),
                state,
                context,
            );
        }
        _ => return Ok(None),
    };
    let Some(state) = mode.path_state() else {
        return Ok(None);
    };
    let length = compile_path_length_scalar_expression(
        function,
        format!("{path}.arguments"),
        state,
        context,
    )?;
    Ok(Some(length))
}

fn compile_arithmetic_operator(
    operator: CypherBinaryOperator,
    path: impl Into<String>,
) -> Result<ArithmeticOperator, CoreError> {
    match operator {
        CypherBinaryOperator::Add => Ok(ArithmeticOperator::Add),
        CypherBinaryOperator::Subtract => Ok(ArithmeticOperator::Subtract),
        CypherBinaryOperator::Multiply => Ok(ArithmeticOperator::Multiply),
        CypherBinaryOperator::Divide => Ok(ArithmeticOperator::Divide),
        CypherBinaryOperator::Modulo => Ok(ArithmeticOperator::Modulo),
        CypherBinaryOperator::Power => Ok(ArithmeticOperator::Power),
        CypherBinaryOperator::And | CypherBinaryOperator::Or | CypherBinaryOperator::Xor => {
            Err(unsupported(
                path,
                "boolean operators are not scalar arithmetic expressions",
            ))
        }
    }
}

fn compile_case_scalar_expression_with_path_state(
    case: &CaseExpression,
    path: impl Into<String>,
    plan: &GraphPlan,
    path_state: Option<&CypherCompileState>,
    context: &CypherCompileContext,
) -> Result<ScalarExpression, CoreError> {
    compile_case_scalar_expression_in_mode(
        case,
        path,
        PredicateCompileMode::Graph { plan, path_state },
        context,
    )
}

fn compile_case_scalar_expression_in_mode(
    case: &CaseExpression,
    path: impl Into<String>,
    mode: PredicateCompileMode<'_>,
    context: &CypherCompileContext,
) -> Result<ScalarExpression, CoreError> {
    let path = path.into();
    if case.alternatives.is_empty() {
        return Err(unsupported(
            format!("{path}.alternatives"),
            "CASE expressions require at least one WHEN/THEN alternative",
        ));
    }

    if let Some(expression) =
        compile_optional_static_list_case_scalar_expression(case, path.clone(), mode, context)?
    {
        return Ok(expression);
    }

    let alternatives = case
        .alternatives
        .iter()
        .enumerate()
        .map(|(index, alternative)| {
            let when = if let Some(scrutinee) = &case.scrutinee {
                compile_binary_comparison(
                    scrutinee,
                    CypherComparisonOperator::Eq,
                    &alternative.when,
                    format!("{path}.alternatives[{index}].when"),
                    mode,
                    context,
                )?
            } else {
                compile_predicate_expression_in_mode(
                    &alternative.when,
                    format!("{path}.alternatives[{index}].when"),
                    mode,
                    context,
                )?
            };
            Ok(ScalarCaseAlternative {
                when,
                then: compile_scalar_expression_in_predicate_mode(
                    &alternative.then,
                    format!("{path}.alternatives[{index}].then"),
                    mode,
                    context,
                )?,
            })
        })
        .collect::<Result<Vec<_>, CoreError>>()?;
    let else_expression = case
        .default
        .as_ref()
        .map(|expression| {
            compile_scalar_expression_in_predicate_mode(
                expression,
                format!("{path}.default"),
                mode,
                context,
            )
            .map(Box::new)
        })
        .transpose()?;

    Ok(ScalarExpression::Case {
        alternatives,
        else_expression,
    })
}

fn compile_optional_static_list_case_scalar_expression(
    case: &CaseExpression,
    path: impl Into<String>,
    mode: PredicateCompileMode<'_>,
    context: &CypherCompileContext,
) -> Result<Option<ScalarExpression>, CoreError> {
    let path = path.into();
    let Some(parts) = compile_optional_static_list_case_parts(case, path.clone(), mode, context)?
    else {
        return Ok(None);
    };
    let element_type = require_static_list_case_element_type(&parts, path)?;

    Ok(Some(ScalarExpression::Case {
        alternatives: parts
            .alternatives
            .into_iter()
            .map(|(when, result)| ScalarCaseAlternative {
                when,
                then: static_list_case_result_scalar_expression(result, element_type),
            })
            .collect(),
        else_expression: parts.default.map(|result| {
            Box::new(static_list_case_result_scalar_expression(
                result,
                element_type,
            ))
        }),
    }))
}

struct StaticListCaseParts {
    alternatives: Vec<(PredicateExpression, StaticListCaseResult)>,
    default: Option<StaticListCaseResult>,
    element_type: Option<LiteralListElementType>,
}

fn require_static_list_case_element_type(
    parts: &StaticListCaseParts,
    path: impl Into<String>,
) -> Result<LiteralListElementType, CoreError> {
    parts.element_type.ok_or_else(|| {
        unsupported(
            format!("{}.alternatives", path.into()),
            "list-valued CASE result branches require at least one non-null list element type",
        )
    })
}

fn compile_static_list_case_alternative(
    case: &CaseExpression,
    index: usize,
    path: &str,
    mode: PredicateCompileMode<'_>,
    context: &CypherCompileContext,
) -> Result<(PredicateExpression, Option<StaticListCaseResult>), CoreError> {
    let alternative = case
        .alternatives
        .get(index)
        .ok_or_else(|| CoreError::internal("CASE alternative index out of bounds"))?;
    let when = if let Some(scrutinee) = &case.scrutinee {
        compile_binary_comparison(
            scrutinee,
            CypherComparisonOperator::Eq,
            &alternative.when,
            format!("{path}.alternatives[{index}].when"),
            mode,
            context,
        )?
    } else {
        compile_predicate_expression_in_mode(
            &alternative.when,
            format!("{path}.alternatives[{index}].when"),
            mode,
            context,
        )?
    };
    let result = compile_optional_static_list_case_result(
        &alternative.then,
        format!("{path}.alternatives[{index}].then"),
        mode.static_metadata_plan(),
        context,
    )?;
    Ok((when, result))
}

fn compile_optional_static_list_case_default(
    case: &CaseExpression,
    path: &str,
    mode: PredicateCompileMode<'_>,
    context: &CypherCompileContext,
) -> Result<Option<StaticListCaseResult>, CoreError> {
    case.default
        .as_ref()
        .map(|expression| {
            compile_optional_static_list_case_result(
                expression,
                format!("{path}.default"),
                mode.static_metadata_plan(),
                context,
            )
        })
        .transpose()
        .map(Option::flatten)
}

fn compile_optional_static_list_case_parts(
    case: &CaseExpression,
    path: impl Into<String>,
    mode: PredicateCompileMode<'_>,
    context: &CypherCompileContext,
) -> Result<Option<StaticListCaseParts>, CoreError> {
    let path = path.into();
    let mut saw_list_result = false;
    let mut saw_non_list_result = false;
    let mut element_type = None;
    let mut alternatives = Vec::with_capacity(case.alternatives.len());

    for index in 0..case.alternatives.len() {
        let (when, result) =
            compile_static_list_case_alternative(case, index, &path, mode, context)?;
        if let Some(result) = result.as_ref() {
            saw_list_result |= !matches!(result, StaticListCaseResult::Null);
            element_type = merge_static_list_case_result_element_type(
                element_type,
                result,
                &format!("{path}.alternatives[{index}].then"),
            )?;
        } else {
            saw_non_list_result = true;
        }
        alternatives.push((when, result));
    }

    let default = compile_optional_static_list_case_default(case, &path, mode, context)?;
    if let Some(default) = default.as_ref() {
        saw_list_result |= !matches!(default, StaticListCaseResult::Null);
        element_type = merge_static_list_case_result_element_type(
            element_type,
            default,
            &format!("{path}.default"),
        )?;
    } else if case.default.is_some() {
        saw_non_list_result = true;
    }

    if !saw_list_result {
        return Ok(None);
    }
    if saw_non_list_result {
        return Err(unsupported(
            format!("{path}.alternatives"),
            "list-valued CASE result branches require every non-null branch to be a static list",
        ));
    }
    let alternatives = alternatives
        .into_iter()
        .enumerate()
        .map(|(index, (when, result))| {
            let Some(result) = result else {
                return Err(unsupported(
                    format!("{path}.alternatives[{index}].then"),
                    "list-valued CASE result branches require every non-null branch to be a static list",
                ));
            };
            Ok((when, result))
        })
        .collect::<Result<Vec<_>, CoreError>>()?;

    Ok(Some(StaticListCaseParts {
        alternatives,
        default,
        element_type,
    }))
}

fn compile_keys_projection(
    function: &FunctionInvocation,
    item: &ProjectionItem,
    path: impl Into<String>,
    plan: &GraphPlan,
    context: &CypherCompileContext,
) -> Result<Projection, CoreError> {
    let path = path.into();
    if let Some(value) = compile_optional_same_label_undirected_endpoint_function_argument(
        function,
        format!("{path}.expression.arguments"),
        plan,
        context,
    )? {
        return Ok(Projection::Expression {
            expression: same_label_undirected_endpoint_keys_scalar_expression(value),
            alias: item
                .alias
                .as_ref()
                .map_or_else(|| "keys".to_string(), variable_name),
        });
    }
    let value = compile_single_graph_value_function_argument_ref(
        function,
        format!("{path}.expression.arguments"),
        "keys() supports exactly one graph variable argument",
        plan,
        context,
    )?;
    if !plan_uses_variable(plan, &value.variable) {
        return Err(unsupported(
            format!("{path}.expression.arguments[0]"),
            format!(
                "keys() argument '{}' is not a bound graph variable",
                value.variable
            ),
        ));
    }
    if value.presence_variable.is_some() {
        return Ok(Projection::Expression {
            expression: graph_value_keys_scalar_expression(value),
            alias: item
                .alias
                .as_ref()
                .map_or_else(|| "keys".to_string(), variable_name),
        });
    }
    Ok(Projection::PropertyKeys {
        variable: value.variable,
        alias: item
            .alias
            .as_ref()
            .map_or_else(|| "keys".to_string(), variable_name),
    })
}

fn compile_node_function_target_ref(
    function: &FunctionInvocation,
    path: impl Into<String>,
    message: &'static str,
    plan: &GraphPlan,
    context: &CypherCompileContext,
) -> Result<(GraphValueRef, String), CoreError> {
    let path = path.into();
    let value = compile_single_graph_value_function_argument_ref(
        function,
        path.clone(),
        message,
        plan,
        context,
    )?;
    let node = plan
        .nodes
        .iter()
        .find(|node| node.variable == value.variable)
        .ok_or_else(|| {
            unsupported(
                format!("{path}[0]"),
                format!(
                    "labels() argument '{}' is not a node variable",
                    value.variable
                ),
            )
        })?;
    Ok((value, node.label.clone()))
}

fn compile_single_graph_value_function_argument(
    function: &FunctionInvocation,
    path: impl Into<String>,
    message: &'static str,
    plan: &GraphPlan,
    context: &CypherCompileContext,
) -> Result<String, CoreError> {
    let path = path.into();
    let value = compile_single_graph_value_function_argument_ref(
        function,
        path.clone(),
        message,
        plan,
        context,
    )?;
    reject_optional_graph_value_ref(value, path)
}

fn compile_single_graph_value_function_argument_ref(
    function: &FunctionInvocation,
    path: impl Into<String>,
    message: &'static str,
    plan: &GraphPlan,
    context: &CypherCompileContext,
) -> Result<GraphValueRef, CoreError> {
    let path = path.into();
    match function.arguments.as_slice() {
        [argument] => compile_graph_value_expression_ref(
            argument,
            format!("{path}[0]"),
            message,
            plan,
            context,
        ),
        [] => {
            let variable = context
                .variable_function_argument(function)
                .map(str::to_string)
                .ok_or_else(|| unsupported(path.clone(), message))?;
            Ok(GraphValueRef {
                variable,
                presence_variable: None,
            })
        }
        _ => Err(unsupported(path, message)),
    }
}

fn compile_graph_value_expression_variable(
    expression: &Expression,
    path: impl Into<String>,
    message: &'static str,
    plan: &GraphPlan,
    context: &CypherCompileContext,
) -> Result<String, CoreError> {
    let path = path.into();
    let value =
        compile_graph_value_expression_ref(expression, path.clone(), message, plan, context)?;
    reject_optional_graph_value_ref(value, path)
}

fn compile_graph_value_expression_ref(
    expression: &Expression,
    path: impl Into<String>,
    message: &'static str,
    plan: &GraphPlan,
    context: &CypherCompileContext,
) -> Result<GraphValueRef, CoreError> {
    let path = path.into();
    match expression {
        Expression::Parenthesized(inner) => {
            compile_graph_value_expression_ref(inner, path, message, plan, context)
        }
        Expression::Variable(variable) => {
            let variable = variable_name(variable);
            Ok(GraphValueRef {
                variable,
                presence_variable: None,
            })
        }
        Expression::FunctionCall(function)
            if is_start_node_function(function) || is_end_node_function(function) =>
        {
            compile_relationship_endpoint_ref(function, path, plan, context)
        }
        _ => Err(unsupported(path, message)),
    }
}

fn reject_optional_graph_value_ref(
    value: GraphValueRef,
    path: impl Into<String>,
) -> Result<String, CoreError> {
    let path = path.into();
    if value.presence_variable.is_some() {
        return Err(unsupported(
            path,
            "relationship endpoint values from OPTIONAL MATCH are only supported in scalar projections, predicates, and ordering expressions",
        ));
    }
    Ok(value.variable)
}

fn compile_single_variable_function_argument(
    function: &FunctionInvocation,
    path: impl Into<String>,
    message: &'static str,
    context: &CypherCompileContext,
) -> Result<String, CoreError> {
    let path = path.into();
    if let Some(variable) = optional_single_variable_function_argument(function, context) {
        Ok(variable)
    } else if matches!(
        function.arguments.as_slice(),
        [Expression::Parenthesized(_)]
    ) {
        Err(unsupported(format!("{path}[0]"), message))
    } else {
        Err(unsupported(path, message))
    }
}

fn optional_single_variable_function_argument(
    function: &FunctionInvocation,
    context: &CypherCompileContext,
) -> Option<String> {
    match function.arguments.as_slice() {
        [Expression::Parenthesized(inner)] => match inner.as_ref() {
            Expression::Variable(variable) => Some(variable_name(variable)),
            _ => None,
        },
        [Expression::Variable(variable)] => Some(variable_name(variable)),
        [] => context
            .variable_function_argument(function)
            .map(str::to_string),
        _ => None,
    }
}

fn compile_aggregate_projection(
    function: &FunctionInvocation,
    item: &ProjectionItem,
    path: impl Into<String>,
    plan: &GraphPlan,
    context: &CypherCompileContext,
) -> Result<Projection, CoreError> {
    let path = path.into();
    let function_kind =
        compile_aggregate_function(function, &format!("{path}.expression"), context)?.ok_or_else(
            || {
                unsupported(
                    format!("{path}.expression"),
                    format!(
                        "RETURN function '{}' is not supported yet",
                        qualified_function_name(function)
                    ),
                )
            },
        )?;
    let target =
        compile_function_aggregate_target(function, function_kind, &path, Some(plan), context)?;
    Ok(Projection::Aggregate {
        function: function_kind,
        target,
        distinct: function.distinct,
        alias: item.alias.as_ref().map_or_else(
            || aggregate_function_name(function_kind).to_string(),
            variable_name,
        ),
    })
}

fn compile_function_aggregate_target(
    function: &FunctionInvocation,
    function_kind: AggregateFunction,
    path: &str,
    plan: Option<&GraphPlan>,
    context: &CypherCompileContext,
) -> Result<AggregateTarget, CoreError> {
    match function.arguments.as_slice() {
        [argument, _] if matches!(function_kind, AggregateFunction::PercentileCont { .. }) => {
            compile_aggregate_target(
                argument,
                format!("{path}.expression.arguments[0]"),
                plan,
                context,
            )
        }
        [argument] => compile_aggregate_target(
            argument,
            format!("{path}.expression.arguments[0]"),
            plan,
            context,
        ),
        [] if matches!(
            function_kind,
            AggregateFunction::Count | AggregateFunction::Collect
        ) =>
        {
            let variable = context
                .variable_function_argument(function)
                .ok_or_else(|| {
                    unsupported(
                        format!("{path}.expression.arguments"),
                        format!(
                            "{}() supports exactly one graph property or graph variable argument",
                            aggregate_function_name(function_kind)
                        ),
                    )
                })?;
            Ok(AggregateTarget::VariableKey {
                variable: variable.to_string(),
            })
        }
        _ => Err(unsupported(
            format!("{path}.expression.arguments"),
            format!(
                "{}() supports exactly one graph property argument",
                aggregate_function_name(function_kind)
            ),
        )),
    }
}

fn collect_variable_function_arguments(
    cypher: &str,
) -> BTreeMap<(usize, usize), VariableFunctionArgument> {
    // decypher's high-level AST currently drops variable-only function
    // arguments such as count(n), id(n), and type(r); the lossless CST keeps
    // them by span.
    let parse = decypher::parse_cst(cypher);
    let tree = parse.tree();
    tree.syntax()
        .descendants()
        .filter(|node| node.kind() == SyntaxKind::FUNCTION_INVOCATION)
        .filter_map(|node| variable_function_argument_from_cst(&node))
        .collect()
}

fn collect_function_argument_sources(
    cypher: &str,
) -> BTreeMap<(usize, usize), FunctionArgumentSources> {
    // decypher's high-level AST can omit variable-only function arguments.
    // Keep the lossless argument text available for static expression folders
    // that need to recover repeated item-variable arguments such as atan2(x, x).
    let parse = decypher::parse_cst(cypher);
    let tree = parse.tree();
    tree.syntax()
        .descendants()
        .filter(|node| node.kind() == SyntaxKind::FUNCTION_INVOCATION)
        .filter_map(|node| function_argument_sources_from_cst(&node))
        .collect()
}

fn collect_collection_filter_calls(cypher: &str) -> BTreeMap<(usize, usize), CollectionFilterCall> {
    // decypher's high-level AST currently lowers all/any/none/single(...)
    // filter expressions as normal function calls and drops the collection
    // expression. Recover the filter header from the lossless CST by span.
    let parse = decypher::parse_cst(cypher);
    let tree = parse.tree();
    tree.syntax()
        .descendants()
        .filter(|node| node.kind() == SyntaxKind::FUNCTION_INVOCATION)
        .filter_map(|node| collection_filter_call_from_cst(cypher, &node))
        .collect()
}

fn collect_list_comprehension_sources(
    cypher: &str,
) -> BTreeMap<(usize, usize), ListComprehensionSource> {
    // decypher's high-level AST currently drops the source collection from
    // list comprehensions. Recover the `variable IN collection` header from
    // the lossless CST by span, then keep lowering tied to the typed AST for
    // the optional filter and identity map expression.
    let parse = decypher::parse_cst(cypher);
    let tree = parse.tree();
    tree.syntax()
        .descendants()
        .filter(|node| node.kind() == SyntaxKind::LIST_COMPREHENSION)
        .filter_map(|node| list_comprehension_source_from_cst(cypher, &node))
        .collect()
}

fn collect_static_reduce_sources(cypher: &str) -> BTreeMap<(usize, usize), StaticReduceSource> {
    // decypher's high-level AST does not expose reduce(acc = init, x IN list | expr)
    // as three regular function arguments. Recover the header and reducer
    // expression from the lossless CST, then parse each expression fragment
    // through the normal expression compiler.
    let parse = decypher::parse_cst(cypher);
    let tree = parse.tree();
    tree.syntax()
        .descendants()
        .filter(|node| node.kind() == SyntaxKind::FUNCTION_INVOCATION)
        .filter_map(|node| static_reduce_source_from_cst(cypher, &node))
        .collect()
}

fn collect_unwind_expression_sources(cypher: &str) -> BTreeMap<(usize, usize), String> {
    // decypher's high-level AST can under-represent UNWIND expressions such as
    // `UNWIND ['a'] + $extra AS value`. Recover the full source expression from
    // the lossless CST and parse it through Coral's expression-fragment path.
    let parse = decypher::parse_cst(cypher);
    let tree = parse.tree();
    tree.syntax()
        .descendants()
        .filter(|node| node.kind() == SyntaxKind::UNWIND_CLAUSE)
        .filter_map(|node| unwind_expression_source_from_cst(cypher, &node))
        .collect()
}

fn collect_inline_property_value_sources(
    cypher: &str,
) -> BTreeMap<usize, InlinePropertyValueSource> {
    // decypher's high-level AST can under-represent map-entry values inside
    // pattern property maps, for example `source.team` may surface as only the
    // variable `source`. Recover the full value text from the lossless CST and
    // reparse it only when the typed AST span was truncated.
    let parse = decypher::parse_cst(cypher);
    let tree = parse.tree();
    tree.syntax()
        .descendants()
        .filter(|node| node.kind() == SyntaxKind::MAP_ENTRY)
        .filter_map(|node| inline_property_value_source_from_cst(cypher, &node))
        .collect()
}

fn inline_property_value_source_from_cst(
    cypher: &str,
    node: &SyntaxNode,
) -> Option<(usize, InlinePropertyValueSource)> {
    let range = node.text_range();
    let start: usize = range.start().into();
    let end: usize = range.end().into();
    let source = cypher.get(start..end)?;
    let colon = find_top_level_character(source, ':')?;
    let value_start = skip_ascii_whitespace(source, colon + 1);
    let value_end = trim_ascii_whitespace_end(source, source.len());
    if value_start >= value_end {
        return None;
    }
    let value = source.get(value_start..value_end)?;
    let absolute_value_start = start + value_start;
    let absolute_value_end = start + value_end;
    Some((
        absolute_value_start,
        InlinePropertyValueSource {
            source: value.to_string(),
            end: absolute_value_end,
        },
    ))
}

fn unwind_expression_source_from_cst(
    cypher: &str,
    node: &SyntaxNode,
) -> Option<((usize, usize), String)> {
    let range = node.text_range();
    let start: usize = range.start().into();
    let end: usize = range.end().into();
    let source = cypher.get(start..end)?;
    let expression = parse_unwind_expression_source(source)?;
    Some(((start, end), expression.to_string()))
}

fn parse_unwind_expression_source(source: &str) -> Option<&str> {
    const UNWIND_KEYWORD: &str = "UNWIND";
    let source = source.trim();
    if !source
        .get(..UNWIND_KEYWORD.len())
        .is_some_and(|value| value.eq_ignore_ascii_case(UNWIND_KEYWORD))
        || !keyword_has_boundaries(source, 0, UNWIND_KEYWORD.len())
    {
        return None;
    }
    let after_unwind = source.get(UNWIND_KEYWORD.len()..)?.trim();
    let as_index = find_top_level_keyword(after_unwind, "AS")?;
    let expression = after_unwind.get(..as_index)?.trim();
    (!expression.is_empty()).then_some(expression)
}

fn list_comprehension_source_from_cst(
    cypher: &str,
    node: &SyntaxNode,
) -> Option<((usize, usize), ListComprehensionSource)> {
    let range = node.text_range();
    let start: usize = range.start().into();
    let end: usize = range.end().into();
    let source = cypher.get(start..end)?;
    let value = parse_list_comprehension_source(source)?;
    Some(((start, end), value))
}

fn parse_list_comprehension_source(source: &str) -> Option<ListComprehensionSource> {
    let inner = source.strip_prefix('[')?.strip_suffix(']')?.trim();
    let in_index = find_top_level_keyword(inner, "IN")?;
    let variable = parse_collection_filter_variable(inner.get(..in_index)?.trim())?;
    let after_in = inner.get(in_index + "IN".len()..)?.trim();
    let where_index = find_top_level_keyword(after_in, "WHERE");
    let map_index = find_top_level_character(after_in, '|');
    let end_index = [where_index, map_index]
        .into_iter()
        .flatten()
        .min()
        .unwrap_or(after_in.len());
    let collection_source = after_in.get(..end_index)?.trim();
    if collection_source.is_empty() {
        return None;
    }
    let filter_source = where_index.and_then(|where_index| {
        let filter_end = map_index.unwrap_or(after_in.len());
        if where_index >= filter_end {
            return None;
        }
        after_in
            .get(where_index + "WHERE".len()..filter_end)
            .map(str::trim)
            .filter(|source| !source.is_empty())
            .map(str::to_string)
    });
    Some(ListComprehensionSource {
        variable,
        collection_source: collection_source.to_string(),
        filter_source,
        has_map: map_index.is_some(),
    })
}

fn collect_compact_exists_pattern_queries(cypher: &str) -> BTreeMap<(usize, usize), String> {
    // decypher's high-level AST treats `WHERE` inside `EXISTS { pattern WHERE ... }`
    // as a clause child, which makes the builder classify the expression as a
    // regular subquery and lose the compact pattern. Recover that compact form
    // from the lossless CST and lower it through the same scoped MATCH path as
    // `EXISTS { MATCH pattern WHERE ... }`.
    let parse = decypher::parse_cst(cypher);
    let tree = parse.tree();
    tree.syntax()
        .descendants()
        .filter(|node| node.kind() == SyntaxKind::EXISTS_SUBQUERY)
        .filter_map(|node| compact_exists_pattern_query_from_cst(cypher, &node))
        .collect()
}

#[derive(Debug)]
struct OrderNullPlacementNormalization<'a> {
    cypher: Cow<'a, str>,
    placements: Vec<Option<NullOrder>>,
}

fn normalize_order_null_placements(cypher: &str) -> OrderNullPlacementNormalization<'_> {
    let (placements, removals) = collect_order_null_placement_sites(cypher);
    if removals.is_empty() {
        return OrderNullPlacementNormalization {
            cypher: Cow::Borrowed(cypher),
            placements,
        };
    }

    let mut normalized = String::with_capacity(cypher.len());
    let mut cursor = 0usize;
    for (start, end) in removals {
        if let Some(prefix) = cypher.get(cursor..start) {
            normalized.push_str(prefix);
        }
        cursor = end;
    }
    if let Some(suffix) = cypher.get(cursor..) {
        normalized.push_str(suffix);
    }

    OrderNullPlacementNormalization {
        cypher: Cow::Owned(normalized),
        placements,
    }
}

fn collect_order_null_placement_sites(
    cypher: &str,
) -> (Vec<Option<NullOrder>>, Vec<(usize, usize)>) {
    const ORDER_KEYWORD: &str = "ORDER";
    const BY_KEYWORD: &str = "BY";

    let mut placements = Vec::new();
    let mut removals = Vec::new();
    let mut index = 0usize;
    let mut depth = 0usize;
    let mut in_string = false;
    let mut in_escaped_identifier = false;

    while index < cypher.len() {
        let Some(rest) = cypher.get(index..) else {
            break;
        };
        let Some(character) = rest.chars().next() else {
            break;
        };
        let character_len = character.len_utf8();

        if in_string {
            if character == '\'' {
                let next_index = index + character_len;
                if cypher
                    .get(next_index..)
                    .is_some_and(|value| value.starts_with('\''))
                {
                    index = next_index + '\''.len_utf8();
                    continue;
                }
                in_string = false;
            }
            index += character_len;
            continue;
        }

        if in_escaped_identifier {
            if character == '`' {
                let next_index = index + character_len;
                if cypher
                    .get(next_index..)
                    .is_some_and(|value| value.starts_with('`'))
                {
                    index = next_index + '`'.len_utf8();
                    continue;
                }
                in_escaped_identifier = false;
            }
            index += character_len;
            continue;
        }

        if keyword_at(cypher, index, ORDER_KEYWORD)
            && previous_non_whitespace(cypher, index) != Some('.')
        {
            let after_order = skip_ascii_whitespace(cypher, index + ORDER_KEYWORD.len());
            if keyword_at(cypher, after_order, BY_KEYWORD) {
                let after_by = skip_ascii_whitespace(cypher, after_order + BY_KEYWORD.len());
                index = collect_order_items_until_clause_end(
                    cypher,
                    after_by,
                    depth,
                    &mut placements,
                    &mut removals,
                );
                continue;
            }
        }

        match character {
            '\'' => in_string = true,
            '`' => in_escaped_identifier = true,
            '(' | '[' | '{' => depth += 1,
            ')' | ']' | '}' => depth = depth.saturating_sub(1),
            _ => {}
        }

        index += character_len;
    }

    (placements, removals)
}

fn collect_order_items_until_clause_end(
    cypher: &str,
    start: usize,
    baseline_depth: usize,
    placements: &mut Vec<Option<NullOrder>>,
    removals: &mut Vec<(usize, usize)>,
) -> usize {
    let mut item_start = skip_ascii_whitespace(cypher, start);
    let mut index = item_start;
    let mut depth = baseline_depth;
    let mut in_string = false;
    let mut in_escaped_identifier = false;

    while index < cypher.len() {
        let Some(rest) = cypher.get(index..) else {
            break;
        };
        let Some(character) = rest.chars().next() else {
            break;
        };
        let character_len = character.len_utf8();

        if in_string {
            if character == '\'' {
                let next_index = index + character_len;
                if cypher
                    .get(next_index..)
                    .is_some_and(|value| value.starts_with('\''))
                {
                    index = next_index + '\''.len_utf8();
                    continue;
                }
                in_string = false;
            }
            index += character_len;
            continue;
        }

        if in_escaped_identifier {
            if character == '`' {
                let next_index = index + character_len;
                if cypher
                    .get(next_index..)
                    .is_some_and(|value| value.starts_with('`'))
                {
                    index = next_index + '`'.len_utf8();
                    continue;
                }
                in_escaped_identifier = false;
            }
            index += character_len;
            continue;
        }

        if depth == baseline_depth {
            if matches!(character, ')' | ']' | '}') {
                push_order_null_placement_item(cypher, item_start, index, placements, removals);
                return index;
            }
            if character == ',' {
                push_order_null_placement_item(cypher, item_start, index, placements, removals);
                item_start = skip_ascii_whitespace(cypher, index + character_len);
                index = item_start;
                continue;
            }
            if order_clause_end_keyword_at(cypher, index) {
                push_order_null_placement_item(cypher, item_start, index, placements, removals);
                return index;
            }
        }

        match character {
            '\'' => in_string = true,
            '`' => in_escaped_identifier = true,
            '(' | '[' | '{' => depth += 1,
            ')' | ']' | '}' => depth = depth.saturating_sub(1),
            _ => {}
        }

        index += character_len;
    }

    push_order_null_placement_item(cypher, item_start, cypher.len(), placements, removals);
    cypher.len()
}

fn push_order_null_placement_item(
    cypher: &str,
    start: usize,
    end: usize,
    placements: &mut Vec<Option<NullOrder>>,
    removals: &mut Vec<(usize, usize)>,
) {
    let start = skip_ascii_whitespace(cypher, start);
    let end = trim_ascii_whitespace_end(cypher, end);
    if start >= end {
        return;
    }
    if let Some((remove_start, remove_end, nulls)) =
        find_order_item_null_placement(cypher, start, end)
    {
        placements.push(Some(nulls));
        removals.push((remove_start, remove_end));
    } else {
        placements.push(None);
    }
}

fn find_order_item_null_placement(
    cypher: &str,
    start: usize,
    end: usize,
) -> Option<(usize, usize, NullOrder)> {
    const NULLS_KEYWORD: &str = "NULLS";

    let mut index = start;
    let mut depth = 0usize;
    let mut in_string = false;
    let mut in_escaped_identifier = false;

    while index < end {
        let rest = cypher.get(index..end)?;
        let character = rest.chars().next()?;
        let character_len = character.len_utf8();

        if in_string {
            if character == '\'' {
                let next_index = index + character_len;
                if cypher
                    .get(next_index..end)
                    .is_some_and(|value| value.starts_with('\''))
                {
                    index = next_index + '\''.len_utf8();
                    continue;
                }
                in_string = false;
            }
            index += character_len;
            continue;
        }

        if in_escaped_identifier {
            if character == '`' {
                let next_index = index + character_len;
                if cypher
                    .get(next_index..end)
                    .is_some_and(|value| value.starts_with('`'))
                {
                    index = next_index + '`'.len_utf8();
                    continue;
                }
                in_escaped_identifier = false;
            }
            index += character_len;
            continue;
        }

        match character {
            '\'' => {
                in_string = true;
                index += character_len;
                continue;
            }
            '`' => {
                in_escaped_identifier = true;
                index += character_len;
                continue;
            }
            '(' | '[' | '{' => {
                depth += 1;
                index += character_len;
                continue;
            }
            ')' | ']' | '}' => {
                depth = depth.saturating_sub(1);
                index += character_len;
                continue;
            }
            _ => {}
        }

        if depth == 0
            && keyword_at(cypher, index, NULLS_KEYWORD)
            && previous_non_whitespace(cypher, index) != Some('.')
        {
            let after_nulls = skip_ascii_whitespace(cypher, index + NULLS_KEYWORD.len());
            if let Some((placement_end, nulls)) = parse_null_placement_keyword(cypher, after_nulls)
                && cypher
                    .get(placement_end..end)
                    .is_some_and(|tail| tail.trim().is_empty())
            {
                let remove_start = include_preceding_ascii_whitespace(cypher, start, index);
                return Some((remove_start, placement_end, nulls));
            }
        }

        index += character_len;
    }

    None
}

fn parse_null_placement_keyword(source: &str, index: usize) -> Option<(usize, NullOrder)> {
    const FIRST_KEYWORD: &str = "FIRST";
    const LAST_KEYWORD: &str = "LAST";

    if keyword_at(source, index, FIRST_KEYWORD) {
        Some((index + FIRST_KEYWORD.len(), NullOrder::First))
    } else if keyword_at(source, index, LAST_KEYWORD) {
        Some((index + LAST_KEYWORD.len(), NullOrder::Last))
    } else {
        None
    }
}

fn collect_order_null_placements_for_query(
    query: &Query,
    placements: &[Option<NullOrder>],
) -> Result<BTreeMap<(usize, usize), NullOrder>, CoreError> {
    #[derive(Default)]
    struct SortItemCollector<'ast> {
        items: Vec<&'ast SortItem>,
    }

    impl<'ast> visit::Visit<'ast> for SortItemCollector<'ast> {
        fn visit_sort_item(&mut self, node: &'ast SortItem) {
            self.items.push(node);
            visit::walk_sort_item(self, node);
        }
    }

    let mut collector = SortItemCollector::default();
    visit::Visit::visit_query(&mut collector, query);
    if collector.items.len() != placements.len() {
        if placements.iter().any(Option::is_some) {
            return Err(CoreError::internal(format!(
                "recovered {} Cypher ORDER BY null placements for {} parsed sort items",
                placements.len(),
                collector.items.len()
            )));
        }
        return Ok(BTreeMap::new());
    }

    let mut by_expression_span = BTreeMap::new();
    for (item, nulls) in collector.items.into_iter().zip(placements.iter().copied()) {
        let Some(nulls) = nulls else {
            continue;
        };
        let Some(span) = expression_span(&item.expression) else {
            return Err(unsupported(
                "order.nulls",
                "NULLS FIRST/LAST currently requires a sort expression with source span",
            ));
        };
        by_expression_span.insert((span.start, span.end), nulls);
    }
    Ok(by_expression_span)
}

fn expression_span(expression: &Expression) -> Option<decypher::error::Span> {
    match expression {
        Expression::Literal(literal) => literal_span(literal),
        Expression::Variable(variable) => Some(variable.name.span),
        Expression::Parameter(parameter) => Some(parameter.span),
        Expression::PropertyLookup { span, .. }
        | Expression::NodeLabels { span, .. }
        | Expression::BinaryOp { span, .. }
        | Expression::UnaryOp { span, .. }
        | Expression::Comparison { span, .. }
        | Expression::ListIndex { span, .. }
        | Expression::ListSlice { span, .. }
        | Expression::In { span, .. }
        | Expression::IsNull { span, .. }
        | Expression::CountStar { span } => Some(*span),
        Expression::FunctionCall(function) => Some(function.span),
        Expression::Case(case_expression) => Some(case_expression.span),
        Expression::ListComprehension(comprehension) => Some(comprehension.span),
        Expression::PatternComprehension(comprehension) => Some(comprehension.span),
        Expression::All(filter)
        | Expression::Any(filter)
        | Expression::None(filter)
        | Expression::Single(filter) => Some(filter.span),
        Expression::Parenthesized(inner) => expression_span(inner),
        Expression::Pattern(pattern) => Some(pattern.span),
        Expression::Exists(exists) => Some(exists.span),
        Expression::CountSubquery(count) => Some(count.span),
        Expression::CollectSubquery(collect) => Some(collect.span),
        Expression::MapProjection(projection) => Some(projection.span),
    }
}

fn literal_span(literal: &CypherLiteral) -> Option<decypher::error::Span> {
    match literal {
        CypherLiteral::String(string) => Some(string.span),
        CypherLiteral::List(list) => Some(list.span),
        CypherLiteral::Map(map) => Some(map.span),
        CypherLiteral::Number(_) | CypherLiteral::Boolean(_) | CypherLiteral::Null => None,
    }
}

fn normalize_compact_count_subqueries(cypher: &str) -> Cow<'_, str> {
    const COUNT_KEYWORD: &str = "COUNT";

    let mut rewrites = Vec::new();
    let mut index = 0usize;
    let mut in_string = false;
    let mut in_escaped_identifier = false;

    while index < cypher.len() {
        let Some(rest) = cypher.get(index..) else {
            break;
        };
        let Some(character) = rest.chars().next() else {
            break;
        };
        let character_len = character.len_utf8();

        if in_string {
            if character == '\'' {
                let next_index = index + character_len;
                if cypher
                    .get(next_index..)
                    .is_some_and(|value| value.starts_with('\''))
                {
                    index = next_index + '\''.len_utf8();
                    continue;
                }
                in_string = false;
            }
            index += character_len;
            continue;
        }

        if in_escaped_identifier {
            if character == '`' {
                let next_index = index + character_len;
                if cypher
                    .get(next_index..)
                    .is_some_and(|value| value.starts_with('`'))
                {
                    index = next_index + '`'.len_utf8();
                    continue;
                }
                in_escaped_identifier = false;
            }
            index += character_len;
            continue;
        }

        match character {
            '\'' => {
                in_string = true;
                index += character_len;
                continue;
            }
            '`' => {
                in_escaped_identifier = true;
                index += character_len;
                continue;
            }
            _ => {}
        }

        if rest
            .get(..COUNT_KEYWORD.len())
            .is_some_and(|candidate| candidate.eq_ignore_ascii_case(COUNT_KEYWORD))
            && keyword_has_boundaries(cypher, index, COUNT_KEYWORD.len())
        {
            let after_keyword = skip_ascii_whitespace(cypher, index + COUNT_KEYWORD.len());
            if cypher
                .get(after_keyword..)
                .is_some_and(|value| value.starts_with('{'))
                && let Some(close) = find_matching_brace(cypher, after_keyword)
            {
                let body_start = after_keyword + '{'.len_utf8();
                if let Some(body) = cypher.get(body_start..close)
                    && compact_count_body_should_normalize(body)
                {
                    rewrites.push((body_start, close, format!(" MATCH {} FINISH ", body.trim())));
                }
                index = close + '}'.len_utf8();
                continue;
            }
        }

        index += character_len;
    }

    if rewrites.is_empty() {
        return Cow::Borrowed(cypher);
    }

    let mut normalized = String::with_capacity(cypher.len() + rewrites.len() * 13);
    let mut cursor = 0usize;
    for (start, end, replacement) in rewrites {
        if let Some(prefix) = cypher.get(cursor..start) {
            normalized.push_str(prefix);
        }
        normalized.push_str(&replacement);
        cursor = end;
    }
    if let Some(suffix) = cypher.get(cursor..) {
        normalized.push_str(suffix);
    }
    Cow::Owned(normalized)
}

fn normalize_static_range_functions(cypher: &str) -> Cow<'_, str> {
    const RANGE_KEYWORD: &str = "range";

    let mut rewrites = Vec::new();
    let mut index = 0usize;
    let mut in_string = false;
    let mut in_escaped_identifier = false;

    while index < cypher.len() {
        let Some(rest) = cypher.get(index..) else {
            break;
        };
        let Some(character) = rest.chars().next() else {
            break;
        };
        let character_len = character.len_utf8();

        if in_string {
            if character == '\'' {
                let next_index = index + character_len;
                if cypher
                    .get(next_index..)
                    .is_some_and(|value| value.starts_with('\''))
                {
                    index = next_index + '\''.len_utf8();
                    continue;
                }
                in_string = false;
            }
            index += character_len;
            continue;
        }

        if in_escaped_identifier {
            if character == '`' {
                let next_index = index + character_len;
                if cypher
                    .get(next_index..)
                    .is_some_and(|value| value.starts_with('`'))
                {
                    index = next_index + '`'.len_utf8();
                    continue;
                }
                in_escaped_identifier = false;
            }
            index += character_len;
            continue;
        }

        match character {
            '\'' => {
                in_string = true;
                index += character_len;
                continue;
            }
            '`' => {
                in_escaped_identifier = true;
                index += character_len;
                continue;
            }
            _ => {}
        }

        if rest
            .get(..RANGE_KEYWORD.len())
            .is_some_and(|candidate| candidate.eq_ignore_ascii_case(RANGE_KEYWORD))
            && keyword_has_boundaries(cypher, index, RANGE_KEYWORD.len())
            && previous_non_whitespace(cypher, index) != Some('.')
        {
            let after_keyword = skip_ascii_whitespace(cypher, index + RANGE_KEYWORD.len());
            if cypher
                .get(after_keyword..)
                .is_some_and(|value| value.starts_with('('))
            {
                rewrites.push((index, index + RANGE_KEYWORD.len()));
                index = after_keyword + '('.len_utf8();
                continue;
            }
        }

        index += character_len;
    }

    if rewrites.is_empty() {
        return Cow::Borrowed(cypher);
    }

    let mut normalized =
        String::with_capacity(cypher.len() + rewrites.len() * INTERNAL_STATIC_RANGE_FUNCTION.len());
    let mut cursor = 0usize;
    for (start, end) in rewrites {
        if let Some(prefix) = cypher.get(cursor..start) {
            normalized.push_str(prefix);
        }
        normalized.push_str(INTERNAL_STATIC_RANGE_FUNCTION);
        cursor = end;
    }
    if let Some(suffix) = cypher.get(cursor..) {
        normalized.push_str(suffix);
    }
    Cow::Owned(normalized)
}

fn normalize_string_predicate_functions(cypher: &str) -> Cow<'_, str> {
    const FUNCTIONS: [(&str, &str); 3] = [
        ("contains", INTERNAL_STRING_CONTAINS_FUNCTION),
        ("startsWith", INTERNAL_STRING_STARTS_WITH_FUNCTION),
        ("endsWith", INTERNAL_STRING_ENDS_WITH_FUNCTION),
    ];

    let mut rewrites = Vec::new();
    let mut index = 0usize;
    let mut in_string = false;
    let mut in_escaped_identifier = false;

    while index < cypher.len() {
        let Some(rest) = cypher.get(index..) else {
            break;
        };
        let Some(character) = rest.chars().next() else {
            break;
        };
        let character_len = character.len_utf8();

        if in_string {
            if character == '\'' {
                let next_index = index + character_len;
                if cypher
                    .get(next_index..)
                    .is_some_and(|value| value.starts_with('\''))
                {
                    index = next_index + '\''.len_utf8();
                    continue;
                }
                in_string = false;
            }
            index += character_len;
            continue;
        }

        if in_escaped_identifier {
            if character == '`' {
                let next_index = index + character_len;
                if cypher
                    .get(next_index..)
                    .is_some_and(|value| value.starts_with('`'))
                {
                    index = next_index + '`'.len_utf8();
                    continue;
                }
                in_escaped_identifier = false;
            }
            index += character_len;
            continue;
        }

        match character {
            '\'' => {
                in_string = true;
                index += character_len;
                continue;
            }
            '`' => {
                in_escaped_identifier = true;
                index += character_len;
                continue;
            }
            _ => {}
        }

        let Some((keyword, replacement)) = FUNCTIONS.iter().find(|(keyword, _)| {
            rest.get(..keyword.len())
                .is_some_and(|candidate| candidate.eq_ignore_ascii_case(keyword))
                && keyword_has_boundaries(cypher, index, keyword.len())
                && previous_non_whitespace(cypher, index) != Some('.')
        }) else {
            index += character_len;
            continue;
        };

        let after_keyword = skip_ascii_whitespace(cypher, index + keyword.len());
        if cypher
            .get(after_keyword..)
            .is_some_and(|value| value.starts_with('('))
        {
            rewrites.push((index, index + keyword.len(), *replacement));
            index = after_keyword + '('.len_utf8();
            continue;
        }

        index += character_len;
    }

    if rewrites.is_empty() {
        return Cow::Borrowed(cypher);
    }

    let additional_capacity: usize = rewrites
        .iter()
        .map(|(start, end, replacement)| replacement.len().saturating_sub(end - start))
        .sum();
    let mut normalized = String::with_capacity(cypher.len() + additional_capacity);
    let mut cursor = 0usize;
    for (start, end, replacement) in rewrites {
        if let Some(prefix) = cypher.get(cursor..start) {
            normalized.push_str(prefix);
        }
        normalized.push_str(replacement);
        cursor = end;
    }
    if let Some(suffix) = cypher.get(cursor..) {
        normalized.push_str(suffix);
    }
    Cow::Owned(normalized)
}

fn compact_count_body_should_normalize(body: &str) -> bool {
    let trimmed = body.trim_start();
    if trimmed.starts_with('(') {
        return true;
    }
    let Some(equals_index) = find_top_level_character(trimmed, '=') else {
        return false;
    };
    let Some(path_variable) = trimmed.get(..equals_index).map(str::trim) else {
        return false;
    };
    if parse_collection_filter_variable(path_variable).is_none() {
        return false;
    }
    trimmed
        .get(equals_index + '='.len_utf8()..)
        .is_some_and(|pattern| pattern.trim_start().starts_with('('))
}

fn skip_ascii_whitespace(source: &str, mut index: usize) -> usize {
    while let Some(rest) = source.get(index..) {
        let Some(character) = rest.chars().next() else {
            return index;
        };
        if !character.is_ascii_whitespace() {
            return index;
        }
        index += character.len_utf8();
    }
    index
}

fn previous_non_whitespace(source: &str, index: usize) -> Option<char> {
    source
        .get(..index)?
        .chars()
        .rev()
        .find(|character| !character.is_whitespace())
}

fn find_matching_brace(source: &str, open: usize) -> Option<usize> {
    let mut depth = 0usize;
    let mut in_string = false;
    let mut in_escaped_identifier = false;
    let mut index = open;

    while index < source.len() {
        let rest = source.get(index..)?;
        let character = rest.chars().next()?;
        let character_len = character.len_utf8();

        if in_string {
            if character == '\'' {
                let next_index = index + character_len;
                if source.get(next_index..)?.starts_with('\'') {
                    index = next_index + '\''.len_utf8();
                    continue;
                }
                in_string = false;
            }
            index += character_len;
            continue;
        }

        if in_escaped_identifier {
            if character == '`' {
                let next_index = index + character_len;
                if source.get(next_index..)?.starts_with('`') {
                    index = next_index + '`'.len_utf8();
                    continue;
                }
                in_escaped_identifier = false;
            }
            index += character_len;
            continue;
        }

        match character {
            '\'' => in_string = true,
            '`' => in_escaped_identifier = true,
            '{' => depth += 1,
            '}' => {
                depth = depth.checked_sub(1)?;
                if depth == 0 {
                    return Some(index);
                }
            }
            _ => {}
        }

        index += character_len;
    }

    None
}

fn compact_exists_pattern_query_from_cst(
    cypher: &str,
    node: &SyntaxNode,
) -> Option<((usize, usize), String)> {
    let has_pattern = node
        .children()
        .any(|child| child.kind() == SyntaxKind::NODE_PATTERN);
    let has_where = node
        .children()
        .any(|child| child.kind() == SyntaxKind::WHERE_CLAUSE);
    if !has_pattern || !has_where {
        return None;
    }

    let range = node.text_range();
    let start: usize = range.start().into();
    let end: usize = range.end().into();
    let source = cypher.get(start..end)?;
    let inner = compact_exists_inner_source(source)?;
    let where_index = find_top_level_keyword(inner, "WHERE")?;
    let pattern_source = inner.get(..where_index)?.trim();
    let where_source = inner.get(where_index + "WHERE".len()..)?.trim();
    if pattern_source.is_empty() || where_source.is_empty() {
        return None;
    }
    Some((
        (start, end),
        format!("MATCH {pattern_source} WHERE {where_source} FINISH"),
    ))
}

fn compact_exists_inner_source(source: &str) -> Option<&str> {
    if let Some(open) = source.find('{') {
        let close = source.rfind('}')?;
        if close <= open {
            return None;
        }
        return source.get(open + 1..close).map(str::trim);
    }

    let exists_end = "EXISTS".len();
    let after_exists = source.get(exists_end..)?.trim_start();
    if !after_exists.starts_with('(') {
        return None;
    }
    let open = source.len() - after_exists.len();
    let close = source.rfind(')')?;
    if close <= open {
        return None;
    }
    source.get(open + 1..close).map(str::trim)
}

fn collection_filter_call_from_cst(
    cypher: &str,
    node: &SyntaxNode,
) -> Option<((usize, usize), CollectionFilterCall)> {
    let range = node.text_range();
    let start: usize = range.start().into();
    let end: usize = range.end().into();
    let source = cypher.get(start..end)?;
    let call = parse_collection_filter_call_source(source)?;
    Some(((start, end), call))
}

fn parse_collection_filter_call_source(source: &str) -> Option<CollectionFilterCall> {
    let open = source.find('(')?;
    let close = source.rfind(')')?;
    if close <= open {
        return None;
    }
    let function_name = source.get(..open)?.trim();
    if !matches!(
        function_name.to_ascii_lowercase().as_str(),
        "all" | "any" | "none" | "single"
    ) {
        return None;
    }

    let inner = source.get(open + 1..close)?.trim();
    let in_index = find_top_level_keyword(inner, "IN")?;
    let variable = parse_collection_filter_variable(inner.get(..in_index)?.trim())?;
    let after_in = inner.get(in_index + "IN".len()..)?.trim();
    let (collection_source, has_predicate) =
        if let Some(where_index) = find_top_level_keyword(after_in, "WHERE") {
            (after_in.get(..where_index)?.trim(), true)
        } else {
            (after_in, false)
        };
    if collection_source.is_empty() {
        return None;
    }
    Some(CollectionFilterCall {
        variable,
        collection_source: collection_source.to_string(),
        has_predicate,
    })
}

fn static_reduce_source_from_cst(
    cypher: &str,
    node: &SyntaxNode,
) -> Option<((usize, usize), StaticReduceSource)> {
    let range = node.text_range();
    let start: usize = range.start().into();
    let end: usize = range.end().into();
    let source = cypher.get(start..end)?;
    let reduce = parse_static_reduce_source(source)?;
    Some(((start, end), reduce))
}

fn parse_static_reduce_source(source: &str) -> Option<StaticReduceSource> {
    let open = source.find('(')?;
    let close = source.rfind(')')?;
    if close <= open {
        return None;
    }
    let function_name = source.get(..open)?.trim();
    if !function_name.eq_ignore_ascii_case("reduce") {
        return None;
    }

    let inner = source.get(open + 1..close)?.trim();
    let comma = find_top_level_character(inner, ',')?;
    let accumulator_source = inner.get(..comma)?.trim();
    let source_and_expression = inner.get(comma + 1..)?.trim();

    let equals = find_top_level_character(accumulator_source, '=')?;
    let accumulator_variable =
        parse_collection_filter_variable(accumulator_source.get(..equals)?.trim())?;
    let initial_source = accumulator_source.get(equals + 1..)?.trim();
    if initial_source.is_empty() {
        return None;
    }

    let pipe = find_top_level_character(source_and_expression, '|')?;
    let collection_header = source_and_expression.get(..pipe)?.trim();
    let expression_source = source_and_expression.get(pipe + 1..)?.trim();
    if expression_source.is_empty() {
        return None;
    }

    let in_index = find_top_level_keyword(collection_header, "IN")?;
    let item_variable =
        parse_collection_filter_variable(collection_header.get(..in_index)?.trim())?;
    let collection_source = collection_header.get(in_index + "IN".len()..)?.trim();
    if collection_source.is_empty() {
        return None;
    }

    Some(StaticReduceSource {
        accumulator_variable,
        initial_source: initial_source.to_string(),
        item_variable,
        collection_source: collection_source.to_string(),
        expression_source: expression_source.to_string(),
    })
}

fn parse_collection_filter_variable(source: &str) -> Option<String> {
    if source.is_empty() {
        return None;
    }
    if let Some(stripped) = source
        .strip_prefix('`')
        .and_then(|value| value.strip_suffix('`'))
    {
        return Some(stripped.replace("``", "`"));
    }
    let mut characters = source.chars();
    let first = characters.next()?;
    if matches!(
        source.to_ascii_lowercase().as_str(),
        "null" | "true" | "false"
    ) {
        return None;
    }
    (first == '_' || first.is_ascii_alphabetic())
        .then_some(())
        .filter(|()| {
            characters.all(|character| character == '_' || character.is_ascii_alphanumeric())
        })
        .map(|()| source.to_string())
}

fn split_top_level_arguments(source: &str) -> Option<Vec<&str>> {
    if source.trim().is_empty() {
        return Some(Vec::new());
    }

    let mut arguments = Vec::new();
    let mut depth = 0usize;
    let mut in_string = false;
    let mut in_escaped_identifier = false;
    let mut start = 0usize;
    let mut index = 0usize;

    while index < source.len() {
        let rest = source.get(index..)?;
        let character = rest.chars().next()?;
        let character_len = character.len_utf8();

        if in_string {
            if character == '\'' {
                let next_index = index + character_len;
                if source.get(next_index..)?.starts_with('\'') {
                    index = next_index + '\''.len_utf8();
                    continue;
                }
                in_string = false;
            }
            index += character_len;
            continue;
        }

        if in_escaped_identifier {
            if character == '`' {
                let next_index = index + character_len;
                if source.get(next_index..)?.starts_with('`') {
                    index = next_index + '`'.len_utf8();
                    continue;
                }
                in_escaped_identifier = false;
            }
            index += character_len;
            continue;
        }

        match character {
            '\'' => in_string = true,
            '`' => in_escaped_identifier = true,
            '(' | '[' | '{' => depth += 1,
            ')' | ']' | '}' => depth = depth.checked_sub(1)?,
            ',' if depth == 0 => {
                arguments.push(source.get(start..index)?.trim());
                start = index + character_len;
            }
            _ => {}
        }

        index += character_len;
    }

    if depth != 0 || in_string || in_escaped_identifier {
        return None;
    }

    arguments.push(source.get(start..)?.trim());
    arguments
        .iter()
        .all(|argument| !argument.is_empty())
        .then_some(arguments)
}

fn find_top_level_keyword(source: &str, keyword: &str) -> Option<usize> {
    let keyword_len = keyword.len();
    let mut depth = 0usize;
    let mut in_string = false;
    let mut in_escaped_identifier = false;
    let mut index = 0usize;

    while index < source.len() {
        let rest = source.get(index..)?;
        let character = rest.chars().next()?;
        let character_len = character.len_utf8();

        if in_string {
            if character == '\'' {
                let next_index = index + character_len;
                if source.get(next_index..)?.starts_with('\'') {
                    index = next_index + '\''.len_utf8();
                    continue;
                }
                in_string = false;
            }
            index += character_len;
            continue;
        }

        if in_escaped_identifier {
            if character == '`' {
                let next_index = index + character_len;
                if source.get(next_index..)?.starts_with('`') {
                    index = next_index + '`'.len_utf8();
                    continue;
                }
                in_escaped_identifier = false;
            }
            index += character_len;
            continue;
        }

        match character {
            '\'' => in_string = true,
            '`' => in_escaped_identifier = true,
            '(' | '[' | '{' => depth += 1,
            ')' | ']' | '}' => depth = depth.saturating_sub(1),
            _ => {}
        }

        if depth == 0
            && rest.len() >= keyword_len
            && rest
                .get(..keyword_len)
                .is_some_and(|candidate| candidate.eq_ignore_ascii_case(keyword))
            && keyword_has_boundaries(source, index, keyword_len)
        {
            return Some(index);
        }

        index += character_len;
    }
    None
}

fn find_top_level_character(source: &str, target: char) -> Option<usize> {
    let mut depth = 0usize;
    let mut in_string = false;
    let mut in_escaped_identifier = false;
    let mut index = 0usize;

    while index < source.len() {
        let rest = source.get(index..)?;
        let character = rest.chars().next()?;
        let character_len = character.len_utf8();

        if in_string {
            if character == '\'' {
                let next_index = index + character_len;
                if source.get(next_index..)?.starts_with('\'') {
                    index = next_index + '\''.len_utf8();
                    continue;
                }
                in_string = false;
            }
            index += character_len;
            continue;
        }

        if in_escaped_identifier {
            if character == '`' {
                let next_index = index + character_len;
                if source.get(next_index..)?.starts_with('`') {
                    index = next_index + '`'.len_utf8();
                    continue;
                }
                in_escaped_identifier = false;
            }
            index += character_len;
            continue;
        }

        match character {
            '\'' => in_string = true,
            '`' => in_escaped_identifier = true,
            '(' | '[' | '{' => depth += 1,
            ')' | ']' | '}' => depth = depth.saturating_sub(1),
            _ => {}
        }

        if depth == 0 && character == target {
            return Some(index);
        }

        index += character_len;
    }
    None
}

fn keyword_has_boundaries(source: &str, index: usize, keyword_len: usize) -> bool {
    let before = source
        .get(..index)
        .and_then(|prefix| prefix.chars().next_back());
    let after = source
        .get(index + keyword_len..)
        .and_then(|suffix| suffix.chars().next());
    !before.is_some_and(is_identifier_continue) && !after.is_some_and(is_identifier_continue)
}

fn keyword_at(source: &str, index: usize, keyword: &str) -> bool {
    source
        .get(index..index + keyword.len())
        .is_some_and(|candidate| candidate.eq_ignore_ascii_case(keyword))
        && keyword_has_boundaries(source, index, keyword.len())
}

fn order_clause_end_keyword_at(source: &str, index: usize) -> bool {
    const CLAUSE_END_KEYWORDS: &[&str] = &[
        "CALL", "CREATE", "DELETE", "FINISH", "LIMIT", "MATCH", "MERGE", "OPTIONAL", "REMOVE",
        "RETURN", "SET", "SKIP", "UNION", "UNWIND", "WHERE", "WITH",
    ];

    CLAUSE_END_KEYWORDS
        .iter()
        .any(|keyword| keyword_at(source, index, keyword))
}

fn trim_ascii_whitespace_end(source: &str, mut end: usize) -> usize {
    while let Some(prefix) = source.get(..end) {
        let Some(character) = prefix.chars().next_back() else {
            return end;
        };
        if !character.is_ascii_whitespace() {
            return end;
        }
        end -= character.len_utf8();
    }
    end
}

fn include_preceding_ascii_whitespace(source: &str, lower_bound: usize, mut index: usize) -> usize {
    while index > lower_bound {
        let Some(prefix) = source.get(lower_bound..index) else {
            return index;
        };
        let Some(character) = prefix.chars().next_back() else {
            return index;
        };
        if !character.is_ascii_whitespace() {
            return index;
        }
        index -= character.len_utf8();
    }
    index
}

fn is_identifier_continue(character: char) -> bool {
    character == '_' || character.is_ascii_alphanumeric()
}

fn variable_function_argument_from_cst(
    node: &SyntaxNode,
) -> Option<((usize, usize), VariableFunctionArgument)> {
    let range = node.text_range();
    let start: usize = range.start().into();
    let end: usize = range.end().into();
    let source = node.text().to_string();
    let open = source.find('(')?;
    let close = source.rfind(')')?;
    if close <= open {
        return variable_function_argument_from_children(node, start, end);
    }
    let Some(arguments) = split_top_level_arguments(source.get(open + 1..close)?) else {
        return variable_function_argument_from_children(node, start, end);
    };
    let mut variables = arguments
        .iter()
        .enumerate()
        .filter_map(|(index, argument)| {
            parse_variable_function_argument_source(argument).map(|variable| (index, variable))
        });
    let (index, variable) = variables.next()?;
    if variables.next().is_some() {
        return None;
    }
    Some((
        (start, end),
        VariableFunctionArgument {
            variable,
            index,
            count: arguments.len(),
        },
    ))
}

fn function_argument_sources_from_cst(
    node: &SyntaxNode,
) -> Option<((usize, usize), FunctionArgumentSources)> {
    let range = node.text_range();
    let start: usize = range.start().into();
    let end: usize = range.end().into();
    let source = node.text().to_string();
    let open = source.find('(')?;
    let close = source.rfind(')')?;
    if close <= open {
        return None;
    }
    let arguments = split_top_level_arguments(source.get(open + 1..close)?)?;
    Some((
        (start, end),
        FunctionArgumentSources {
            arguments: arguments.into_iter().map(str::to_string).collect(),
        },
    ))
}

fn parse_variable_function_argument_source(source: &str) -> Option<String> {
    let source = source.trim();
    let source = source
        .get(.."DISTINCT".len())
        .filter(|candidate| candidate.eq_ignore_ascii_case("DISTINCT"))
        .filter(|_| keyword_has_boundaries(source, 0, "DISTINCT".len()))
        .and_then(|_| source.get("DISTINCT".len()..))
        .map_or(source, str::trim_start);
    parse_collection_filter_variable(source)
}

fn variable_function_argument_from_children(
    node: &SyntaxNode,
    start: usize,
    end: usize,
) -> Option<((usize, usize), VariableFunctionArgument)> {
    let mut variables = node
        .children()
        .filter(|child| child.kind() == SyntaxKind::VARIABLE)
        .filter_map(|child| {
            let source = child.text().to_string();
            parse_collection_filter_variable(source.trim())
        });
    let variable = variables.next()?;
    if variables.next().is_some() {
        return None;
    }
    Some((
        (start, end),
        VariableFunctionArgument {
            variable,
            index: 0,
            count: 0,
        },
    ))
}

fn compile_aggregate_target(
    expression: &Expression,
    path: impl Into<String>,
    plan: Option<&GraphPlan>,
    context: &CypherCompileContext,
) -> Result<AggregateTarget, CoreError> {
    let path = path.into();
    match expression {
        Expression::Parenthesized(inner) => compile_aggregate_target(inner, path, plan, context),
        Expression::Variable(variable) => Ok(AggregateTarget::VariableKey {
            variable: variable_name(variable),
        }),
        Expression::FunctionCall(function)
            if is_start_node_function(function) || is_end_node_function(function) =>
        {
            let Some(plan) = plan else {
                return Err(unsupported(
                    path,
                    "relationship endpoint aggregate targets require graph context",
                ));
            };
            if let Some(value) = compile_optional_same_label_undirected_relationship_endpoint(
                expression,
                path.clone(),
                plan,
                context,
            )? {
                return Ok(AggregateTarget::Expression(
                    same_label_undirected_endpoint_key_scalar_expression(value),
                ));
            }
            let value = compile_relationship_endpoint_ref(function, path, plan, context)?;
            Ok(match value.presence_variable {
                Some(presence_variable) => AggregateTarget::PresenceGatedVariableKey {
                    variable: value.variable,
                    presence_variable,
                },
                None => AggregateTarget::VariableKey {
                    variable: value.variable,
                },
            })
        }
        Expression::PropertyLookup { .. } => {
            if let Some(target) = compile_optional_static_map_lookup_aggregate_target(
                expression,
                path.clone(),
                plan,
                context,
            )? {
                return Ok(target);
            }
            if let Some(plan) = plan
                && let Some((expression, _)) =
                    compile_optional_same_label_undirected_endpoint_property_scalar_expression(
                        expression,
                        path.clone(),
                        plan,
                        context,
                    )?
            {
                return Ok(AggregateTarget::Expression(expression));
            }
            if let Some(plan) = plan
                && let Some((property, presence_variable, _)) =
                    compile_optional_endpoint_property_ref(expression, path.clone(), plan, context)?
            {
                return Ok(AggregateTarget::PresenceGatedProperty {
                    property,
                    presence_variable,
                });
            }
            Ok(AggregateTarget::Property(compile_property_ref(
                expression, path, plan, context,
            )?))
        }
        _ => {
            let Some(plan) = plan else {
                return Ok(AggregateTarget::Property(compile_property_ref(
                    expression, path, plan, context,
                )?));
            };
            let expression = compile_aggregate_scalar_target_expression(
                expression,
                path.clone(),
                plan,
                context,
            )?;
            validate_aggregate_scalar_target_correlated_subqueries(&expression, path)?;
            Ok(AggregateTarget::Expression(expression))
        }
    }
}

fn compile_optional_static_map_lookup_aggregate_target(
    expression: &Expression,
    path: impl Into<String>,
    plan: Option<&GraphPlan>,
    context: &CypherCompileContext,
) -> Result<Option<AggregateTarget>, CoreError> {
    let path = path.into();
    let Some(expression) = compile_optional_static_map_lookup_scalar_expression(
        expression,
        path.clone(),
        PredicateCompileMode::CaseWhen { plan },
        context,
    )?
    else {
        return Ok(None);
    };
    validate_aggregate_scalar_target_correlated_subqueries(&expression, path)?;
    Ok(Some(match expression {
        ScalarExpression::Property(property) => AggregateTarget::Property(property),
        expression => AggregateTarget::Expression(expression),
    }))
}

fn compile_aggregate_scalar_target_expression(
    expression: &Expression,
    path: impl Into<String>,
    plan: &GraphPlan,
    context: &CypherCompileContext,
) -> Result<ScalarExpression, CoreError> {
    let path = path.into();
    if is_boolean_scalar_expression(expression) {
        return compile_boolean_scalar_expression(expression, path, plan, context);
    }
    compile_scalar_expression_with_path_state(expression, path, plan, None, context)
}

fn compile_aggregate_function(
    function: &FunctionInvocation,
    path: &str,
    context: &CypherCompileContext,
) -> Result<Option<AggregateFunction>, CoreError> {
    let [name] = function.name.as_slice() else {
        return Ok(None);
    };
    if name.name.eq_ignore_ascii_case("count") {
        Ok(Some(AggregateFunction::Count))
    } else if name.name.eq_ignore_ascii_case("collect")
        || name.name.eq_ignore_ascii_case("collect_list")
    {
        Ok(Some(AggregateFunction::Collect))
    } else if name.name.eq_ignore_ascii_case("sum") {
        Ok(Some(AggregateFunction::Sum))
    } else if name.name.eq_ignore_ascii_case("avg") {
        Ok(Some(AggregateFunction::Avg))
    } else if name.name.eq_ignore_ascii_case("median") {
        Ok(Some(AggregateFunction::Median))
    } else if name.name.eq_ignore_ascii_case("percentileCont")
        || name.name.eq_ignore_ascii_case("percentile_cont")
    {
        if function.distinct {
            return Err(unsupported(
                format!("{path}.distinct"),
                "percentileCont(DISTINCT ...) is not supported because DataFusion 53 cannot execute distinct percentile_cont aggregates",
            ));
        }
        Ok(Some(AggregateFunction::PercentileCont {
            percentile: compile_percentile_argument(function, path, context)?,
        }))
    } else if name.name.eq_ignore_ascii_case("stDev")
        || name.name.eq_ignore_ascii_case("stdev_samp")
    {
        Ok(Some(AggregateFunction::StdDev))
    } else if name.name.eq_ignore_ascii_case("stDevP")
        || name.name.eq_ignore_ascii_case("stdev_pop")
    {
        Ok(Some(AggregateFunction::StdDevP))
    } else if name.name.eq_ignore_ascii_case("min") {
        Ok(Some(AggregateFunction::Min))
    } else if name.name.eq_ignore_ascii_case("max") {
        Ok(Some(AggregateFunction::Max))
    } else {
        Ok(None)
    }
}

fn compile_percentile_argument(
    function: &FunctionInvocation,
    path: &str,
    context: &CypherCompileContext,
) -> Result<OrderedFloat<f64>, CoreError> {
    let [_, percentile] = function.arguments.as_slice() else {
        return Err(unsupported(
            format!("{path}.arguments"),
            "percentileCont() supports exactly two arguments: value and percentile",
        ));
    };
    let literal = compile_literal(percentile, format!("{path}.arguments[1]"), context)?;
    let value = match literal {
        Literal::Integer(0) => 0.0,
        Literal::Integer(1) => 1.0,
        Literal::Integer(_) => {
            return Err(unsupported(
                format!("{path}.arguments[1]"),
                "percentileCont() percentile must be between 0.0 and 1.0 inclusive",
            ));
        }
        Literal::Float(value) => value.into_inner(),
        _ => {
            return Err(unsupported(
                format!("{path}.arguments[1]"),
                "percentileCont() requires a numeric percentile literal",
            ));
        }
    };
    if !value.is_finite() || !(0.0..=1.0).contains(&value) {
        return Err(unsupported(
            format!("{path}.arguments[1]"),
            "percentileCont() percentile must be between 0.0 and 1.0 inclusive",
        ));
    }
    Ok(OrderedFloat(value))
}

fn is_aggregate_function_call(function: &FunctionInvocation) -> bool {
    aggregate_function_default_alias(function).is_some()
}

fn aggregate_function_default_alias(function: &FunctionInvocation) -> Option<&'static str> {
    let [name] = function.name.as_slice() else {
        return None;
    };
    if name.name.eq_ignore_ascii_case("count") {
        Some("count")
    } else if name.name.eq_ignore_ascii_case("collect")
        || name.name.eq_ignore_ascii_case("collect_list")
    {
        Some("collect")
    } else if name.name.eq_ignore_ascii_case("sum") {
        Some("sum")
    } else if name.name.eq_ignore_ascii_case("avg") {
        Some("avg")
    } else if name.name.eq_ignore_ascii_case("median") {
        Some("median")
    } else if name.name.eq_ignore_ascii_case("percentileCont")
        || name.name.eq_ignore_ascii_case("percentile_cont")
    {
        Some("percentileCont")
    } else if name.name.eq_ignore_ascii_case("stDev")
        || name.name.eq_ignore_ascii_case("stdev_samp")
    {
        Some("stDev")
    } else if name.name.eq_ignore_ascii_case("stDevP")
        || name.name.eq_ignore_ascii_case("stdev_pop")
    {
        Some("stDevP")
    } else if name.name.eq_ignore_ascii_case("min") {
        Some("min")
    } else if name.name.eq_ignore_ascii_case("max") {
        Some("max")
    } else {
        None
    }
}

fn aggregate_function_name(function: AggregateFunction) -> &'static str {
    match function {
        AggregateFunction::Count => "count",
        AggregateFunction::Collect => "collect",
        AggregateFunction::Sum => "sum",
        AggregateFunction::Avg => "avg",
        AggregateFunction::Median => "median",
        AggregateFunction::PercentileCont { .. } => "percentileCont",
        AggregateFunction::StdDev => "stDev",
        AggregateFunction::StdDevP => "stDevP",
        AggregateFunction::Min => "min",
        AggregateFunction::Max => "max",
    }
}

